INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'annual_bank_statement',
    'A. Finanzen & Rechnungen',
    'Jahreskontoauszug',
    'Der Jahreskontoauszug ist eine jährliche Zusammenfassung aller Transaktionen und Kontostände eines Bankkontos, typischerweise zum 31.12. eines Jahres. Er wird von Banken oder Sparkassen an Kontoinhaber versendet und dient als Nachweis für Kontostände, Zinserträge, Gebühren und steuerrelevante Kapitalerträge. Im Gegensatz zu monatlichen Kontoauszügen enthält er eine kompakte Jahresübersicht mit steuerrelevanten Daten wie Kapitalertragsteuer und Solidaritätszuschlag.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "annual_bank_statement", "description": "Jahreskontoauszug", "type": "object", "properties": {"kontoinhaber": {"type": "string"}, "iban": {"type": "string", "pattern": "^[A-Z]{2}\\d{2}[A-Z0-9]{11,30}$"}, "bank": {"type": "string"}, "jahr": {"type": "string", "pattern": "^\\d{4}$"}, "anfangssaldo_01_01": {"type": "string", "pattern": "^\\d{1,10}\\.\\d{2}$"}, "endsaldo_31_12": {"type": "string", "pattern": "^\\d{1,10}\\.\\d{2}$"}, "zinsen_haben": {"type": "string", "pattern": "^\\d{1,10}\\.\\d{2}$"}, "zinsen_soll": {"type": "string", "pattern": "^\\d{1,10}\\.\\d{2}$"}, "kontogebuehren_gesamt": {"type": "string", "pattern": "^\\d{1,10}\\.\\d{2}$"}, "freistellungsauftrag_betrag": {"type": "string", "pattern": "^\\d{1,10}\\.\\d{2}$", "nullable": true}, "kapitalertragsteuer": {"type": "string", "pattern": "^\\d{1,10}\\.\\d{2}$", "nullable": true}, "soli_kapitalertrag": {"type": "string", "pattern": "^\\d{1,10}\\.\\d{2}$", "nullable": true}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null]}, "steuerjahr": {"type": "string", "pattern": "^\\d{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "pattern": "^\\d{1,10}\\.\\d{2}$", "nullable": true}, "mwst_satz": {"type": "string", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}, "buchungen": {"type": "array", "description": "Zusammenfassung der Buchungen/Ums\u00e4tze des Jahres (soweit im Dokument aufgef\u00fchrt)", "items": {"type": "object", "properties": {"datum": {"type": "string"}, "text": {"type": "string"}, "betrag": {"type": "string"}, "saldo": {"type": "string"}}}}}, "required": ["kontoinhaber", "iban", "bank", "jahr", "anfangssaldo_01_01", "endsaldo_31_12", "zinsen_haben", "zinsen_soll", "kontogebuehren_gesamt", "_meta"]}',
    '"kontoinhaber, iban, bank, jahr, anfangssaldo_01_01, endsaldo_31_12, zinsen_haben, zinsen_soll, kontogebuehren_gesamt, freistellungsauftrag_betrag, kapitalertragsteuer, soli_kapitalertrag"',
    'Jahreskontoauszug, Jahresabschluss, Kontoauszug Jahresübersicht, Zinsbescheinigung, Kapitalerträge, Freistellungsauftrag, Kontogebühren, Anfangssaldo, Endsaldo, Habenzinsen, Sollzinsen, Kapitalertragsteuer, Soli, Solidaritätszuschlag, IBAN, Bank, Sparkasse, annual statement, interest statement, account fees, tax withheld, exemption order',
    'Banken, Sparkassen',
    '{"paragraphen": "§20 EStG (Kapitalerträge), §43 EStG (Kapitalertragsteuer), §43a EStG (Soli-Zuschlag)", "anlage": "Anlage KAP (Zeile 7-15 für Kapitalerträge, Zeile 24-26 für bereits abgeführte Steuern), Anlage N (Zeile 31-35 für Werbungskosten wie Kontogebühren)", "absetzbare_betraege": {"zinsen_haben": "Kapitalerträge müssen in Anlage KAP angegeben werden (ggf. nach Freistellungsauftrag).", "kontogebuehren_gesamt": "Können als Werbungskosten in Anlage N (Zeile 31-35) abgesetzt werden, sofern sie im Zusammenhang mit Einnahmen aus Kapitalvermögen stehen (z. B. Depotgebühren).", "kapitalertragsteuer": "Wird in Anlage KAP (Zeile 24-26) als bereits abgeführte Steuer eingetragen und auf die Einkommensteuer angerechnet."}}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
ON CONFLICT (id) DO UPDATE SET category=EXCLUDED.category, display_name=EXCLUDED.display_name, description=EXCLUDED.description, schema=EXCLUDED.schema, field_descriptions=EXCLUDED.field_descriptions, classify_keywords=EXCLUDED.classify_keywords, typical_senders=EXCLUDED.typical_senders, steuer_relevanz=EXCLUDED.steuer_relevanz, priority=EXCLUDED.priority, enabled=EXCLUDED.enabled, version=EXCLUDED.version, source=EXCLUDED.source, notes=EXCLUDED.notes;

INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'bank_statement',
    'A. Finanzen & Rechnungen',
    'Kontoauszug',
    'Ein Kontoauszug dokumentiert alle Kontobewegungen eines Bankkontos für einen bestimmten Zeitraum. Unterscheidet sich vom Jahreskontoauszug (annual_bank_statement) und von der Kreditkartenabrechnung (credit_card_statement).',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "Bank Statement", "description": "Schema f\u00fcr die Extraktion von Kontoausz\u00fcgen", "type": "object", "properties": {"kontoinhaber": {"type": "object", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort", "land"]}}, "required": ["name"]}, "iban": {"type": "string"}, "bic": {"type": "string"}, "bank": {"type": "string"}, "auszugsnummer": {"type": "string"}, "datum": {"type": "string", "format": "date"}, "anfangssaldo": {"type": "string"}, "endsaldo": {"type": "string"}, "buchungen": {"type": "array", "items": {"type": "object", "properties": {"datum": {"type": "string", "format": "date"}, "text": {"type": "string"}, "betrag": {"type": "string"}, "saldo": {"type": "string"}, "w\u00e4hrung": {"type": "string"}}, "required": ["datum", "text", "betrag", "saldo"]}}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^\\d{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "nullable": true}, "mwst_satz": {"type": "string", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}}, "required": ["kontoinhaber", "iban", "auszugsnummer", "datum", "anfangssaldo", "endsaldo", "buchungen", "_meta"]}',
    '"{\"kontoinhaber\": \"Name des Kontoinhabers\", \"iban\": \"IBAN ohne Leerzeichen\", \"bic\": \"BIC/SWIFT-Code\", \"bank\": \"Name der Bank\", \"auszugsnummer\": \"Laufende Nummer\", \"datum\": \"Erstellungsdatum YYYY-MM-DD\", \"anfangssaldo\": \"Saldo zu Beginn (''1234.56'')\", \"endsaldo\": \"Saldo am Ende\", \"buchungen\": \"Array: {datum, text, betrag, saldo}\"}"',
    'Kontoauszug,Kontobewegungen,Buchungen,Saldo,Anfangssaldo,Endsaldo,IBAN,BIC,Auszugsnummer,Kontonummer,Gutschrift,Lastschrift,Überweisung,Dauerauftrag',
    'Banken, Sparkassen',
    'Kontoauszüge sind Belege für steuerrelevante Zahlungen. Jahreskontoauszug enthält Zinsübersicht → Anlage KAP.',
    0,
    1,
    1,
    'mistral_batch',
    'Unterscheide: laufender Kontoauszug vs. Jahreskontoauszug (annual_bank_statement) vs. Kreditkartenabrechnung (credit_card_statement).'
)
ON CONFLICT (id) DO UPDATE SET category=EXCLUDED.category, display_name=EXCLUDED.display_name, description=EXCLUDED.description, schema=EXCLUDED.schema, field_descriptions=EXCLUDED.field_descriptions, classify_keywords=EXCLUDED.classify_keywords, typical_senders=EXCLUDED.typical_senders, steuer_relevanz=EXCLUDED.steuer_relevanz, priority=EXCLUDED.priority, enabled=EXCLUDED.enabled, version=EXCLUDED.version, source=EXCLUDED.source, notes=EXCLUDED.notes;

INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'building_savings_contract',
    'A. Finanzen & Rechnungen',
    'Bausparvertrag',
    'Ein Bausparvertrag ist ein Sparvertrag mit dem Ziel, ein zinsgünstiges Darlehen für wohnwirtschaftliche Zwecke (z. B. Hausbau, Kauf oder Modernisierung) zu erhalten. Er wird von Bausparkassen ausgegeben und kombiniert eine Sparphase mit einer späteren Darlehensphase. Im Gegensatz zu reinen Sparverträgen oder Darlehensverträgen ist der Bausparvertrag spezifisch auf die Finanzierung von Wohneigentum ausgerichtet und enthält sowohl Spar- als auch Darlehenskomponenten.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "building_savings_contract", "description": "Schema f\u00fcr Bausparvertrag-Dokumente", "type": "object", "properties": {"bausparer": {"type": "object", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort", "land"]}, "geburtsdatum": {"type": "string", "format": "date"}, "steuernummer": {"type": "string"}}, "required": ["name", "adresse"]}, "bausparnummer": {"type": "string"}, "bausparsumme": {"type": "string"}, "bausparkasse": {"type": "string"}, "abschlussdatum": {"type": "string", "format": "date"}, "sparbeitrag_monatlich": {"type": "string"}, "regelsparbeitrag": {"type": "string"}, "darlehenszins": {"type": "string"}, "abschlussgebuehr": {"type": "string"}, "zuteilungstermin_geschaetzt": {"type": "string", "format": "date"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^\\d{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "nullable": true}, "mwst_satz": {"type": "string", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant"]}, "konditionen": {"type": "array", "description": "Wesentliche Vertragskonditionen (Sparphase, Darlehensphase, Geb\u00fchren, etc.)", "items": {"type": "object", "properties": {"bezeichnung": {"type": "string"}, "wert": {"type": "string"}}}}}, "required": ["bausparer", "bausparnummer", "bausparsumme", "bausparkasse", "abschlussdatum", "_meta"]}',
    '"bausparer, bausparnummer, bausparsumme, bausparkasse, abschlussdatum, sparbeitrag_monatlich, regelsparbeitrag, darlehenszins, abschlussgebuehr, zuteilungstermin_geschaetzt"',
    'Bausparvertrag, Bausparsumme, Bausparer, Bausparnummer, Bausparkasse, Sparbeitrag, Regelsparbeitrag, monatlicher Sparbeitrag, Darlehenszins, Abschlussgebühr, Zuteilungstermin, wohnwirtschaftliche Verwendung, Bauspardarlehen, Ansparphase, Zuteilungsphase, Bausparurkunde, Vertragsabschluss, LBS, Schwäbisch Hall, Wüstenrot, BHW, Tarifvariante, Guthabenzins, Effektivzins',
    'Bausparkassen',
    '{"paragraphen": "§10 Abs. 1 Nr. 3 EStG (Vorsorgeaufwendungen), §35a EStG (haushaltsnahe Dienstleistungen/Handwerkerleistungen bei Modernisierung)", "anlage": "V (Vorsorgeaufwand), ggf. N (bei Handwerkerleistungen nach §35a)", "absetzbare_betraege": {"vorsorgeaufwendungen": "Sparbeiträge sind als Vorsorgeaufwendungen bis zu den Höchstbeträgen (2023: 25.639 € für Ledige, 51.278 € für Verheiratete) absetzbar, sofern sie nicht bereits durch andere Vorsorgeaufwendungen (z. B. Rentenversicherung) ausgeschöpft sind."}}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
ON CONFLICT (id) DO UPDATE SET category=EXCLUDED.category, display_name=EXCLUDED.display_name, description=EXCLUDED.description, schema=EXCLUDED.schema, field_descriptions=EXCLUDED.field_descriptions, classify_keywords=EXCLUDED.classify_keywords, typical_senders=EXCLUDED.typical_senders, steuer_relevanz=EXCLUDED.steuer_relevanz, priority=EXCLUDED.priority, enabled=EXCLUDED.enabled, version=EXCLUDED.version, source=EXCLUDED.source, notes=EXCLUDED.notes;

INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'building_savings_statement',
    'A. Finanzen & Rechnungen',
    'Bauspar-Kontoauszug',
    'Ein Bauspar-Kontoauszug ist ein periodischer Bericht einer Bausparkasse über den aktuellen Stand eines Bausparvertrags. Er wird typischerweise jährlich oder quartalsweise versendet und enthält Details zu Guthaben, Zinsen, Ansparsumme und Zuteilungsreife. Im Gegensatz zu einem regulären Sparkontoauszug oder einem Darlehenskontoauszug bezieht er sich spezifisch auf einen Bausparvertrag mit besonderen steuerlichen und förderrechtlichen Aspekten wie Wohnungsbauprämie oder vermögenswirksamen Leistungen.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "building_savings_statement", "description": "Bauspar-Kontoauszug", "type": "object", "properties": {"bausparer": {"type": "object", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort", "land"]}}, "required": ["name"]}, "bausparnummer": {"type": "string"}, "bausparsumme": {"type": "string"}, "bausparkasse": {"type": "string"}, "stichtag": {"type": "string", "format": "date"}, "ansparsumme": {"type": "string"}, "guthaben": {"type": "string"}, "zinsen": {"type": "string"}, "zuteilungsreif": {"type": "boolean"}, "vermoegenswirksame_leistungen": {"type": "array", "items": {"type": "object", "properties": {"betrag": {"type": "string"}, "datum": {"type": "string", "format": "date"}, "arbeitgeber": {"type": "string"}}, "required": ["betrag", "datum"]}}, "wohnungsbau_praemie_beantragt": {"type": "boolean"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^[0-9]{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "nullable": true}, "mwst_satz": {"type": "string", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}}, "required": ["bausparer", "bausparnummer", "bausparsumme", "bausparkasse", "stichtag", "ansparsumme", "guthaben", "zinsen", "_meta"]}',
    '"bausparer, bausparnummer, bausparsumme, bausparkasse, stichtag, ansparsumme, guthaben, zinsen, zuteilungsreif, vermoegenswirksame_leistungen, wohnungsbau_praemie_beantragt"',
    'Bausparvertrag, Bausparkonto, Bausparsumme, Ansparsumme, Guthaben, Zinsen, Zuteilungsreif, Zuteilung, Wohnungsbauprämie, vermögenswirksame Leistungen, VL, Bausparkasse, Schwäbisch Hall, Wüstenrot, LBS, Bausparer, Vertragsnummer, Stichtag, Bausparurkunde, Sparphase, Darlehensphase, staatliche Förderung, Arbeitgeberzulage, prämienbegünstigt, saving contract, building savings, home savings, allocation maturity',
    'Bausparkassen (Schwäbisch Hall, Wüstenrot, LBS, etc.)',
    '{"paragraphen": "§10a EStG (Wohnungsbauprämie), §3 Nr. 39 EStG (vermögenswirksame Leistungen), §4 WoPG (Wohnungsbau-Prämiengesetz)", "anlage": "Anlage N (Werbungskosten bei vermögenswirksamen Leistungen), Anlage Vorsorgeaufwand (falls Beiträge als Altersvorsorge absetzbar), ggf. separate Bescheinigung für Wohnungsbauprämie", "absetzbare_betraege": {"wohnungsbau_praemie": "Bis zu 70 € (Alleinstehende) bzw. 140 € (Verheiratete) pro Jahr bei Einhaltung der Einkommensgrenzen (35.000 € bzw. 70.000 € zu versteuerndes Einkommen)."}}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
ON CONFLICT (id) DO UPDATE SET category=EXCLUDED.category, display_name=EXCLUDED.display_name, description=EXCLUDED.description, schema=EXCLUDED.schema, field_descriptions=EXCLUDED.field_descriptions, classify_keywords=EXCLUDED.classify_keywords, typical_senders=EXCLUDED.typical_senders, steuer_relevanz=EXCLUDED.steuer_relevanz, priority=EXCLUDED.priority, enabled=EXCLUDED.enabled, version=EXCLUDED.version, source=EXCLUDED.source, notes=EXCLUDED.notes;

INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'claim',
    'A. Finanzen & Rechnungen',
    'Forderung/Forderungsaufstellung',
    'Eine Forderungsaufstellung ist ein Dokument, das von einem Gläubiger an einen Schuldner gesendet wird, um offene Forderungen detailliert aufzuschlüsseln. Es listet einzelne Positionen wie Hauptforderung, Zinsen, Mahnkosten oder Gebühren auf und gibt die Gesamtsumme sowie die Fälligkeit an. Im Gegensatz zu einer einfachen Rechnung oder Mahnung enthält es oft rechtliche Hinweise (z. B. Verzug, Vertragsverletzung) und dient als Grundlage für weitere rechtliche Schritte wie Mahnbescheide oder Vollstreckungen.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "claim", "description": "Forderung/Forderungsaufstellung", "type": "object", "properties": {"glaeubiger": {"type": "object", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort", "land"]}, "kontakt": {"type": "object", "properties": {"telefon": {"type": "string"}, "email": {"type": "string"}}}, "steuernummer": {"type": "string"}, "ust_id": {"type": "string"}}, "required": ["name", "adresse"]}, "schuldner": {"type": "object", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort", "land"]}, "kontakt": {"type": "object", "properties": {"telefon": {"type": "string"}, "email": {"type": "string"}}}}, "required": ["name", "adresse"]}, "positionen": {"type": "array", "items": {"type": "object", "properties": {"beschreibung": {"type": "string"}, "menge": {"type": "number"}, "einzelpreis": {"type": "string"}, "gesamtpreis": {"type": "string"}, "steuersatz": {"type": "string"}, "steuerbetrag": {"type": "string"}}, "required": ["beschreibung", "gesamtpreis"]}}, "gesamtforderung": {"type": "string"}, "faellig_seit": {"type": "string", "format": "date"}, "rechtsgrundlage": {"type": "string"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^\\d{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "nullable": true}, "mwst_satz": {"type": "string", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}}, "required": ["glaeubiger", "schuldner", "gesamtforderung"]}',
    '"{\"glaeubiger\": \"Name und Anschrift des Gl\u00e4ubigers (Person oder Unternehmen), der die Forderung geltend macht. Wichtig f\u00fcr die steuerliche Zuordnung (z. B. bei beruflicher Veranlassung oder Erbschaft). Beispiel: ''Muster GmbH, Musterstra\u00dfe 1, 12345 Berlin''.\", \"schuldner\": \"Name und Anschrift des Schuldners, gegen den die Forderung besteht. Relevant f\u00fcr die steuerliche Absetzbarkeit (z. B. bei Forderungsausf\u00e4llen im Betriebsverm\u00f6gen). Beispiel: ''Max Mustermann, Beispielweg 2, 54321 K\u00f6ln''.\"}"',
    'Forderung, Forderungsaufstellung, Gläubiger, Schuldner, Gesamtforderung, fällig seit, Verzug, Zinsen, Mahnkosten, Rechtsgrundlage, Anspruch, Hauptforderung, Nebenforderungen, Rechnungsnummer, Vertragsnummer, Inkassokosten, Erbengemeinschaft, Nachlassverbindlichkeit, Zahlungsaufforderung, offene Posten, Frist, gerichtliches Mahnverfahren, claim, outstanding amount, default interest, collection costs, legal basis',
    'Gläubiger, Erbengemeinschaften',
    '{"einkommensteuer": {"paragraphen": ["§ 9 EStG (Werbungskosten)", "§ 4 Abs. 4 EStG (Betriebsausgaben)", "§ 22 Nr. 3 EStG (Sonstige Einkünfte)"], "anlage": "Je nach Kontext: Anlage N (selbstständige Tätigkeit), Anlage S (Freiberufler), Anlage V (Vermietung), oder als außergewöhnliche Belastung (§ 33 EStG) in der Haupterklärung", "hinweise": "Forderungsausfälle können unter bestimmten Bedingungen als Werbungskosten/Betriebsausgaben abgesetzt werden (z. B. bei beruflicher Veranlassung). Zinsen oder Mahnkosten sind nur absetzbar, wenn sie im Zusammenhang mit steuerpflichtigen Einkünften stehen. Bei Erbengemeinschaften: Nachlassverbindlichkeiten können die Erbschaftsteuer mindern (§ 10 ErbStG)."}, "erbschaftsteuer": {"paragraphen": ["§ 10 ErbStG (Nachlassverbindlichkeiten)"], "anlage": null, "hinweise": "Forderungen gegen den Nachlass können als Nachlassverbindlichkeiten die Erbschaftsteuer mindern, sofern sie nachgewiesen werden (z. B. durch Forderungsaufstellung)."}}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
ON CONFLICT (id) DO UPDATE SET category=EXCLUDED.category, display_name=EXCLUDED.display_name, description=EXCLUDED.description, schema=EXCLUDED.schema, field_descriptions=EXCLUDED.field_descriptions, classify_keywords=EXCLUDED.classify_keywords, typical_senders=EXCLUDED.typical_senders, steuer_relevanz=EXCLUDED.steuer_relevanz, priority=EXCLUDED.priority, enabled=EXCLUDED.enabled, version=EXCLUDED.version, source=EXCLUDED.source, notes=EXCLUDED.notes;

INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'cost_statement',
    'A. Finanzen & Rechnungen',
    'Kostenaufstellung',
    'Eine Kostenaufstellung ist eine detaillierte Auflistung von Ausgaben oder Kosten, die in einem bestimmten Zeitraum angefallen sind. Sie wird häufig von Dienstleistern, Handwerkern oder Unternehmen erstellt, um geleistete Arbeiten oder gelieferte Waren transparent abzurechnen. Im Gegensatz zu einer Rechnung enthält sie oft keine Umsatzsteuerangaben oder Zahlungsaufforderungen, sondern dient primär der Übersicht und Dokumentation.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "cost_statement", "description": "Kostenaufstellung", "type": "object", "properties": {"ersteller": {"type": "object", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort", "land"]}, "telefon": {"type": "string"}, "email": {"type": "string", "format": "email"}}, "required": ["name"]}, "zeitraum": {"type": "object", "properties": {"von": {"type": "string", "format": "date"}, "bis": {"type": "string", "format": "date"}}, "required": ["von", "bis"]}, "positionen": {"type": "array", "items": {"type": "object", "properties": {"beschreibung": {"type": "string"}, "betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}, "w\u00e4hrung": {"type": "string", "pattern": "^[A-Z]{3}$"}, "kategorie": {"type": "string"}, "datum": {"type": "string", "format": "date"}, "belegnummer": {"type": "string"}, "mwst_satz": {"type": "string", "pattern": "^\\d+(\\.\\d{1,2})?$"}, "mwst_betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}}, "required": ["beschreibung", "betrag", "w\u00e4hrung"]}}, "gesamtbetrag": {"type": "object", "properties": {"netto": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}, "brutto": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}, "w\u00e4hrung": {"type": "string", "pattern": "^[A-Z]{3}$"}, "mwst_betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}}, "required": ["netto", "brutto", "w\u00e4hrung"]}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^\\d{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$", "nullable": true}, "mwst_satz": {"type": "string", "pattern": "^\\d+(\\.\\d{1,2})?$", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}}, "required": ["ersteller", "zeitraum", "positionen", "gesamtbetrag", "_meta"]}',
    '"{\"ersteller\": \"Name oder Firma des Ausstellers der Kostenaufstellung, z. B. ''Malerbetrieb Schmidt GmbH''. Wichtig f\u00fcr die Zuordnung der Ausgaben und ggf. f\u00fcr die Steuererkl\u00e4rung (Nachweis des Leistungserbringers).\", \"zeitraum\": \"Der Zeitraum, f\u00fcr den die Kosten aufgelistet werden, z. B. ''01.01.2023 - 31.01.2023'' oder ''Q2 2023''. Format: Meist TT.MM.JJJJ - TT.MM.JJJJ oder Monats-/Quartalsangabe. Relevant f\u00fcr die zeitliche Zuordnung in der Steuererkl\u00e4rung.\", \"positionen\": \"Detaillierte Auflistung der einzelnen Kostenpunkte, oft als Array mit Unterfeldern wie ''beschreibung'', ''menge'', ''einzelpreis'', ''gesamtpreis''. Beispiel: [{''beschreibung'': ''Farbe (wei\u00df)'', ''menge'': 10, ''einheit'': ''Liter'', ''einzelpreis'': 15.00, ''gesamtpreis'': 150.00}]. Wichtig f\u00fcr die Aufschl\u00fcsselung der absetzbaren Betr\u00e4ge (z. B. Material vs. Arbeitskosten bei \u00a735a EStG).\"}"',
    'Kostenaufstellung, Kostenübersicht, Aufstellung, Ausgaben, Positionen, Gesamtbetrag, Zeitraum, netto, brutto, Materialkosten, Arbeitskosten, Dienstleistung, Aufwand, Spesen, Kostenaufschlüsselung, cost statement, expense report, itemized costs, summary, period, total amount',
    'Diverse',
    '{"einordnung": "Abhängig vom Kontext: Bei beruflicher Veranlassung (z. B. Handwerkerrechnungen, Dienstleistungen) können Kosten als Betriebsausgaben (§4 Abs. 4 EStG) oder Werbungskosten (§9 EStG) abgesetzt werden. Bei haushaltsnahen Dienstleistungen oder Handwerkerleistungen greift §35a EStG (Anlage Haushaltsnahe Aufwendungen). Bei privaten Ausgaben (z. B. Umzugskosten) ggf. §33 EStG (außergewöhnliche Belastungen).", "anlage": "N (bei Werbungskosten), S (bei §35a EStG), Vorsorgeaufwand (falls zutreffend), oder Anlage EÜR (bei Selbstständigen)", "absetzbare_beträge": "§35a EStG: Bis zu 20% der Arbeitskosten (max. 1.200 €/Jahr für Handwerkerleistungen, 4.000 €/Jahr für haushaltsnahe Dienstleistungen). Bei außergewöhnlichen Belastungen (§33 EStG) nur der Teil, der die zumutbare Belastung übersteigt."}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
ON CONFLICT (id) DO UPDATE SET category=EXCLUDED.category, display_name=EXCLUDED.display_name, description=EXCLUDED.description, schema=EXCLUDED.schema, field_descriptions=EXCLUDED.field_descriptions, classify_keywords=EXCLUDED.classify_keywords, typical_senders=EXCLUDED.typical_senders, steuer_relevanz=EXCLUDED.steuer_relevanz, priority=EXCLUDED.priority, enabled=EXCLUDED.enabled, version=EXCLUDED.version, source=EXCLUDED.source, notes=EXCLUDED.notes;

INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'craftsman_bill',
    'A. Finanzen & Rechnungen',
    'Handwerkerrechnung',
    'Eine Handwerkerrechnung dokumentiert erbrachte handwerkliche Leistungen und Materialkosten durch einen Handwerksbetrieb. Sie wird nach Abschluss von Reparatur-, Wartungs- oder Installationsarbeiten ausgestellt und enthält detaillierte Aufschlüsselungen von Arbeitszeiten, Materialverbrauch und Kosten. Im Gegensatz zu reinen Materialrechnungen oder Dienstleistungsverträgen kombiniert sie Arbeits- und Materialkosten und ist oft nach §35a EStG steuerlich begünstigt.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "craftsman_bill", "description": "Handwerkerrechnung", "type": "object", "properties": {"handwerker": {"type": "object", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "default": "DE"}}, "required": ["strasse", "plz", "ort"]}, "steuernummer": {"type": "string"}, "ust_id": {"type": "string"}, "telefon": {"type": "string"}, "email": {"type": "string", "format": "email"}}, "required": ["name"]}, "gewerk": {"type": "string", "enum": ["elektro", "sanitaer", "heizung", "maler", "schreiner", "dachdecker", "fliesenleger", "rohrreinigung", "schornsteinfeger", "garten", "schluessel", "klima", "sonstiges"]}, "auftragsnummer": {"type": "string"}, "kundenauftrag_stichwort": {"type": "string"}, "leistungsdatum": {"type": "string", "format": "date"}, "objekt_adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "default": "DE"}}, "required": ["strasse", "plz", "ort"]}, "arbeitskraefte": {"type": "array", "items": {"type": "object", "properties": {"qualifikation": {"type": "string", "enum": ["meister", "geselle", "fachkraft", "lehrling", "helfer", "monteur"]}, "stunden": {"type": "number", "minimum": 0}, "stundensatz": {"type": "string"}, "betrag": {"type": "string"}, "einheit": {"type": "string", "description": "Einheit der Arbeitszeit (z.B. h, Std)"}}, "required": ["qualifikation", "stunden", "stundensatz", "betrag"]}}, "materialkosten_positionen": {"type": "array", "items": {"type": "object", "properties": {"beschreibung": {"type": "string"}, "menge": {"type": "number", "minimum": 0}, "einzelpreis": {"type": "string"}, "betrag": {"type": "string"}, "einheit": {"type": "string", "description": "Einheit (z.B. m2, Stk, lfm, kg)"}}, "required": ["beschreibung", "menge", "einzelpreis", "betrag"]}}, "fahrtkosten": {"type": "string"}, "anfahrt_km": {"type": "number", "minimum": 0}, "maschinenkosten": {"type": "string"}, "entsorgungskosten": {"type": "string"}, "netto": {"type": "string"}, "mwst": {"type": "string"}, "brutto": {"type": "string"}, "lohnanteil_netto": {"type": "string"}, "materialanteil_netto": {"type": "string"}, "arbeitsstunden_gesamt": {"type": "number", "minimum": 0}, "steuerhinweis_35a": {"type": "string"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean", "default": true}, "steuerrelevanz_hinweis": {"type": "string"}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "default": "handwerkerleistungen"}, "steuerjahr": {"type": "string", "pattern": "^\\d{4}$"}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string"}, "mwst_satz": {"type": "string"}, "aktenzeichen": {"type": "string"}, "dokumenten_id": {"type": "string"}}, "required": ["steuerrelevant", "steuer_kategorie"]}, "waehrung": {"type": "string", "default": "EUR", "description": "Waehrung ISO 4217 (EUR, USD, etc.)"}}, "required": ["handwerker", "gewerk", "leistungsdatum", "objekt_adresse", "netto", "brutto", "lohnanteil_netto", "materialanteil_netto", "_meta"]}',
    '"{\"handwerker\": \"Name und Anschrift des ausf\u00fchrenden Handwerksbetriebs. Wichtig f\u00fcr die Zuordnung der Rechnung und steuerliche Nachweispflicht. Beispiel: ''Malermeister Schmidt GmbH, Musterstra\u00dfe 1, 12345 Berlin''.\", \"gewerk\": \"Art des ausgef\u00fchrten Handwerks (z. B. ''Elektro'', ''Sanit\u00e4r'', ''Heizung'', ''Maler''). Wichtig f\u00fcr die Klassifizierung der Leistung und steuerliche Einordnung. Beispiel: ''Sanit\u00e4r''.\", \"auftragsnummer\": \"Interne Nummer des Handwerksbetriebs zur Identifikation des Auftrags. Format: alphanumerisch, oft mit Pr\u00e4fix oder Bindestrichen. Beispiel: ''2023-4711''.\", \"kundenauftrag_stichwort\": \"Kurzbeschreibung oder Stichwort des Kundenauftrags, oft vom Kunden vorgegeben. Beispiel: ''Heizungswartung EG''.\", \"leistungsdatum\": \"Datum der Leistungserbringung (Format: YYYY-MM-DD). Wichtig f\u00fcr die zeitliche Zuordnung in der Steuererkl\u00e4rung. Beispiel: ''2023-10-15''.\", \"objekt_adresse\": \"Adresse, an der die Leistung erbracht wurde. Muss mit der eigenen Haushaltsadresse \u00fcbereinstimmen, um \u00a735a EStG geltend zu machen. Beispiel: ''Musterweg 42, 12345 Berlin''.\", \"arbeitskraefte\": \"Array mit Details zu den eingesetzten Arbeitskr\u00e4ften. Enth\u00e4lt Qualifikation, geleistete Stunden, Stundensatz und Gesamtbetrag. Beispiel: [{''qualifikation'': ''Meister'', ''stunden'': 5, ''stundensatz'': 65.00, ''betrag'': 325.00}]. Wichtig f\u00fcr die Berechnung des absetzbaren Lohnanteils.\"}"',
    'Handwerkerrechnung, Rechnung, Arbeitsstunden, Materialkosten, Lohnanteil, Fahrtkosten, Meisterstunden, Gesellenstunden, Nettobetrag, Bruttobetrag, Mehrwertsteuer, §35a EStG, Handwerkerleistung, Gewerk, Auftragsnummer, Leistungsdatum, Stundenlohn, Monteur, Sanitär, Elektro, Heizung, Malerarbeiten, Dachdecker, Fliesenleger, Schornsteinfeger, Rohrreinigung, Gartenarbeiten, Handwerkerbonus, invoice, craftsman, labor costs, material costs',
    'Handwerksbetriebe (Elektriker, Sanitär, Heizung, Maler, Schreiner, Dachdecker, Fliesenleger, Rohrreinigung, Schornsteinfeger, Gärtner, Schlüsseldienst, etc.)',
    '{"paragraph": "§35a Abs. 3 EStG (Handwerkerleistungen für Renovierung, Erhaltung, Modernisierung)", "anlage": "Haushaltsnahe Dienstleistungen (Anlage „Haushaltsnahe Aufwendungen“ in der Steuererklärung)", "absetzbar": "20% der Arbeitskosten (Lohnanteil_netto + Fahrtkosten + Maschinenkosten), maximal 1.200 € pro Jahr. Materialkosten sind nicht absetzbar.", "hinweis": "Der Steuerbonus gilt nur für Leistungen im eigenen Haushalt (inkl. Garten, Balkon, Terrasse) und muss durch Rechnung und Banküberweisung nachgewiesen werden."}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
ON CONFLICT (id) DO UPDATE SET category=EXCLUDED.category, display_name=EXCLUDED.display_name, description=EXCLUDED.description, schema=EXCLUDED.schema, field_descriptions=EXCLUDED.field_descriptions, classify_keywords=EXCLUDED.classify_keywords, typical_senders=EXCLUDED.typical_senders, steuer_relevanz=EXCLUDED.steuer_relevanz, priority=EXCLUDED.priority, enabled=EXCLUDED.enabled, version=EXCLUDED.version, source=EXCLUDED.source, notes=EXCLUDED.notes;

INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'credit_card_statement',
    'A. Finanzen & Rechnungen',
    'Kreditkartenabrechnung',
    'Eine Kreditkartenabrechnung ist die monatliche Übersicht über alle getätigten Umsätze mit einer Kreditkarte, inklusive Gebühren, Zinsen und Fälligkeitsterminen. Sie wird von der kartenausgebenden Bank oder dem Finanzinstitut erstellt und dient als Nachweis für Zahlungen, Abrechnungszeitraum und offene Salden. Im Gegensatz zu Kontoauszügen listet sie ausschließlich Kreditkartentransaktionen auf, oft mit detaillierten Händlerinformationen und Währungsumrechnungen.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "credit_card_statement", "description": "Kreditkartenabrechnung", "type": "object", "properties": {"karteninhaber": {"type": "string", "description": "Name des Kreditkarteninhabers"}, "kartennummer_letzte_4": {"type": "string", "description": "Letzte 4 Ziffern der Kreditkartennummer", "pattern": "^[0-9]{4}$"}, "abrechnungszeitraum": {"type": "object", "properties": {"von": {"type": "string", "format": "date", "description": "Startdatum des Abrechnungszeitraums (YYYY-MM-DD)"}, "bis": {"type": "string", "format": "date", "description": "Enddatum des Abrechnungszeitraums (YYYY-MM-DD)"}}, "required": ["von", "bis"]}, "umsaetze": {"type": "array", "items": {"type": "object", "properties": {"datum": {"type": "string", "format": "date", "description": "Datum der Transaktion (YYYY-MM-DD)"}, "haendler": {"type": "string", "description": "Name des H\u00e4ndlers"}, "ort": {"type": "string", "description": "Ort der Transaktion"}, "waehrung": {"type": "string", "description": "W\u00e4hrung der Transaktion (ISO 4217)", "pattern": "^[A-Z]{3}$"}, "betrag_original": {"type": "string", "description": "Betrag in Originalw\u00e4hrung (z.B. 49.99)", "pattern": "^[0-9]+\\.[0-9]{2}$"}, "betrag_eur": {"type": "string", "description": "Betrag in EUR (z.B. 49.99)", "pattern": "^[0-9]+\\.[0-9]{2}$"}}, "required": ["datum", "haendler", "waehrung", "betrag_original", "betrag_eur"]}}, "gesamtbetrag": {"type": "string", "description": "Gesamtbetrag der Abrechnung in EUR (z.B. 49.99)", "pattern": "^[0-9]+\\.[0-9]{2}$"}, "faellig_am": {"type": "string", "format": "date", "description": "F\u00e4lligkeitsdatum der Zahlung (YYYY-MM-DD)"}, "teilzahlung_minimum": {"type": "string", "description": "Mindestbetrag f\u00fcr Teilzahlung in EUR (z.B. 49.99)", "pattern": "^[0-9]+\\.[0-9]{2}$", "nullable": true}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean", "description": "Gibt an, ob das Dokument steuerrelevant ist"}, "steuerrelevanz_hinweis": {"type": "string", "description": "Hinweis zur Steuerrelevanz", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "description": "Kategorie der Steuerrelevanz", "nullable": true}, "steuerjahr": {"type": "string", "description": "Steuerjahr (YYYY)", "pattern": "^[0-9]{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean", "description": "Gibt an, ob Mehrwertsteuer ausgewiesen ist"}, "mwst_betrag": {"type": "string", "description": "Mehrwertsteuerbetrag (z.B. 49.99)", "pattern": "^[0-9]+\\.[0-9]{2}$", "nullable": true}, "mwst_satz": {"type": "string", "description": "Mehrwertsteuersatz (z.B. 19.00)", "pattern": "^[0-9]+\\.[0-9]{2}$", "nullable": true}, "aktenzeichen": {"type": "string", "description": "Aktenzeichen", "nullable": true}, "dokumenten_id": {"type": "string", "description": "Eindeutige Dokumenten-ID", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}}, "required": ["karteninhaber", "kartennummer_letzte_4", "abrechnungszeitraum", "umsaetze", "gesamtbetrag", "faellig_am", "_meta"]}',
    '"{\"karteninhaber\": \"Name des Kreditkarteninhabers, wie auf der Karte angegeben. Wichtig f\u00fcr die Zuordnung zur richtigen Person im Haushalt, z. B. ''Max Mustermann''.\", \"kartennummer_letzte_4\": \"Die letzten vier Ziffern der Kreditkartennummer, z. B. ''1234''. Dient der Identifikation der Karte bei mehreren Karten desselben Inhabers.\", \"abrechnungszeitraum\": \"Zeitraum, f\u00fcr den die Ums\u00e4tze abgerechnet werden, typischerweise im Format ''01.01.2023 - 31.01.2023''. Relevant f\u00fcr die zeitliche Zuordnung der Transaktionen in der Steuererkl\u00e4rung.\", \"umsaetze\": {\"datum\": \"Datum der Transaktion, z. B. ''15.01.2023''. Wichtig f\u00fcr die zeitliche Einordnung und ggf. steuerliche Absetzbarkeit (z. B. bei beruflichen Ausgaben).\", \"haendler\": \"Name des H\u00e4ndlers oder Dienstleisters, z. B. ''Amazon.de'' oder ''Deutsche Bahn''. Wichtig f\u00fcr die Kategorisierung der Ausgabe (beruflich/privat).\", \"ort\": \"Ort der Transaktion, oft inkl. Land, z. B. ''Berlin, DE'' oder ''New York, US''. Relevant f\u00fcr die Pr\u00fcfung von Auslandsgeb\u00fchren oder beruflichen Reisen.\", \"waehrung\": \"Originalw\u00e4hrung der Transaktion, z. B. ''USD'' oder ''EUR''. Wichtig f\u00fcr die Umrechnung in Euro bei steuerrelevanten Posten.\", \"betrag_original\": \"Betrag in der Originalw\u00e4hrung, z. B. ''49.99''. Wird f\u00fcr die Umrechnung in Euro ben\u00f6tigt, falls absetzbar.\"}}"',
    'Kreditkartenabrechnung, Credit Card Statement, Umsätze, Transaktionen, Abrechnungszeitraum, Fällig am, Gesamtbetrag, Teilzahlung, Mindestbetrag, Kartennummer, Karteninhaber, Händler, Ort, Währung, Betrag EUR, Barclays, American Express, Amex, Visa, Mastercard, Rechnungsnummer, Valuta, Buchungstext, Fremdwährung, Zinsen, Gebühren',
    'Banken, Barclays, Amex, etc.',
    '{"allgemein": "Relevant für §4 Abs. 4 EStG (Betriebsausgaben) oder §9 EStG (Werbungskosten), wenn Umsätze beruflich veranlasst sind. Private Umsätze sind nicht absetzbar, außer bei außergewöhnlichen Belastungen (§33 EStG) oder haushaltsnahen Dienstleistungen (§35a EStG).", "anlage": {"beruflich": "Anlage N (Zeile 46: Werbungskosten) oder Anlage EÜR (bei Selbstständigen)", "privat": "Anlage Vorsorgeaufwand (nur bei steuerrelevanten Versicherungen über Kreditkarte) oder Anlage Haushaltsnahe Dienstleistungen (§35a EStG)"}, "hinweise": "Einzelne Umsätze müssen manuell auf berufliche/private Nutzung geprüft werden. Belege für absetzbare Posten (z. B. Fachliteratur, Bewirtung) separat sammeln. Fremdwährungsbeträge sind mit dem offiziellen Umrechnungskurs des Abrechnungstags anzusetzen (§60 EStDV)."}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
