INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'credit_note',
    'A. Finanzen & Rechnungen',
    'Gutschrift',
    'Eine Gutschrift ist ein Dokument, das von einem Verkäufer oder Dienstleister ausgestellt wird, um einen zuvor in Rechnung gestellten Betrag ganz oder teilweise zurückzuerstatten. Sie kommt vor bei Rücksendungen, Preisnachlässen, Stornierungen oder nachträglichen Korrekturen. Im Gegensatz zu einer Rechnung reduziert eine Gutschrift die ursprüngliche Forderung und kann als Ausgleich oder Teilrückzahlung dienen.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "credit_note", "description": "Schema für Gutschriften", "type": "object", "properties": {"gutschriftsnummer": {"type": "string", "description": "Eindeutige Nummer der Gutschrift"}, "bezug_rechnung": {"type": "string", "description": "Rechnungsnummer der ursprünglichen Rechnung, auf die sich die Gutschrift bezieht", "nullable": true}, "positionen": {"type": "array", "description": "Liste der Positionen in der Gutschrift", "items": {"type": "object", "properties": {"beschreibung": {"type": "string", "description": "Beschreibung der Position"}, "menge": {"type": "number", "description": "Menge der Position"}, "einzelpreis": {"type": "string", "description": "Einzelpreis der Position (z.B. ''49.99'')", "pattern": "^\\d+\\.\\d{2}$"}, "gesamtpreis": {"type": "string", "description": "Gesamtpreis der Position (z.B. ''49.99'')", "pattern": "^\\d+\\.\\d{2}$"}, "steuersatz": {"type": "string", "description": "Steuersatz der Position (z.B. ''19.00'')", "pattern": "^\\d+\\.\\d{2}$", "nullable": true}}, "required": ["beschreibung", "menge", "einzelpreis", "gesamtpreis"]}}, "betrag": {"type": "object", "description": "Gesamtbetrag der Gutschrift", "properties": {"netto": {"type": "string", "description": "Nettogesamtbetrag (z.B. ''49.99'')", "pattern": "^\\d+\\.\\d{2}$"}, "brutto": {"type": "string", "description": "Bruttogesamtbetrag (z.B. ''49.99'')", "pattern": "^\\d+\\.\\d{2}$"}, "währung": {"type": "string", "description": "Währung nach ISO 4217 (z.B. ''EUR'')"}, "steuerbetrag": {"type": "string", "description": "Steuerbetrag (z.B. ''9.49'')", "pattern": "^\\d+\\.\\d{2}$", "nullable": true}}, "required": ["netto", "brutto", "währung"]}, "gutscheincode": {"type": "string", "description": "Gutscheincode, falls zutreffend", "nullable": true}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean", "description": "Gibt an, ob das Dokument steuerrelevant ist"}, "steuerrelevanz_hinweis": {"type": "string", "description": "Hinweis zur Steuerrelevanz", "nullable": true}, "steuer_kategorie": {"type": "string", "description": "Kategorie der Steuerrelevanz", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "nullable": true}, "steuerjahr": {"type": "string", "description": "Steuerjahr im Format YYYY", "pattern": "^\\d{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean", "description": "Gibt an, ob Mehrwertsteuer ausgewiesen ist"}, "mwst_betrag": {"type": "string", "description": "Mehrwertsteuerbetrag (z.B. ''9.49'')", "pattern": "^\\d+\\.\\d{2}$", "nullable": true}, "mwst_satz": {"type": "string", "description": "Mehrwertsteuersatz (z.B. ''19.00'')", "pattern": "^\\d+\\.\\d{2}$", "nullable": true}, "aktenzeichen": {"type": "string", "description": "Aktenzeichen, falls zutreffend", "nullable": true}, "dokumenten_id": {"type": "string", "description": "Eindeutige Dokumenten-ID", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}, "waehrung": {"type": "string", "default": "EUR", "description": "Waehrung ISO 4217 (EUR, USD, etc.)"}}, "required": ["gutschriftsnummer", "positionen", "betrag", "_meta"]}',
    '"{\"gutschriftsnummer\": \"Eindeutige Identifikationsnummer der Gutschrift, oft alphanumerisch. Wichtig f\u00fcr die Zuordnung und Archivierung, z. B. ''GU-2023-4711''. Bei steuerrelevanten Vorg\u00e4ngen (z. B. berufliche Anschaffungen) zur Dokumentation der Korrektur.\", \"bezug_rechnung\": \"Rechnungsnummer der urspr\u00fcnglichen Rechnung, auf die sich die Gutschrift bezieht. Format z. B. ''RE-2023-1234''. Wichtig f\u00fcr die Nachvollziehbarkeit der Korrektur und steuerliche Dokumentation.\", \"positionen\": \"Liste der Artikel oder Dienstleistungen, die gutgeschrieben werden, inkl. Menge, Einzelpreis und Gesamtpreis. Beispiel: ''[{\\\"beschreibung\\\": \\\"B\u00fcrostuhl\\\", \\\"menge\\\": 1, \\\"einzelpreis\\\": 199.99, \\\"gesamtpreis\\\": 199.99}]''. Bei beruflichen Ausgaben relevant f\u00fcr die korrekte Erfassung in der Steuererkl\u00e4rung (z. B. Anlage N).\", \"betrag\": \"Gesamtbetrag der Gutschrift, inkl. Umsatzsteuer. Format: Dezimalzahl mit zwei Nachkommastellen, z. B. 199.99. Wichtig f\u00fcr die steuerliche Korrektur des urspr\u00fcnglichen Rechnungsbetrags.\"}"',
    'Gutschrift, Gutschriftsnummer, Erstattung, Rückerstattung, Stornorechnung, Korrekturrechnung, credit note, refund, reimbursement, Rückgabe, Preisnachlass, Gutgeschrieben, Bezugsrechnung, Rechnungsnummer, Betrag, Positionen, Gutscheincode, Minderung, Ausgleich',
    'Shops, Dienstleister',
    '{"einkommensteuer": {"paragraph": "§17 UStG (Umsatzsteuergesetz), §14 UStG (Berichtigung der Bemessungsgrundlage)", "anlage": null, "hinweis": "Gutschriften mindern den ursprünglichen Rechnungsbetrag und damit die umsatzsteuerliche Bemessungsgrundlage. Der korrigierte Betrag muss in der Umsatzsteuer-Voranmeldung bzw. Jahreserklärung berücksichtigt werden. Bei privaten Endverbrauchern ist die Gutschrift meist nicht direkt steuerrelevant, kann aber bei nachträglichen Werbungskosten (z. B. berufliche Anschaffungen) oder außergewöhnlichen Belastungen (§33 EStG) relevant sein."}}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
ON CONFLICT (id) DO UPDATE SET category=EXCLUDED.category, display_name=EXCLUDED.display_name, description=EXCLUDED.description, schema=EXCLUDED.schema, field_descriptions=EXCLUDED.field_descriptions, classify_keywords=EXCLUDED.classify_keywords, typical_senders=EXCLUDED.typical_senders, steuer_relevanz=EXCLUDED.steuer_relevanz, priority=EXCLUDED.priority, enabled=EXCLUDED.enabled, version=EXCLUDED.version, source=EXCLUDED.source, notes=EXCLUDED.notes;

INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'dunning_notice',
    'A. Finanzen & Rechnungen',
    'Mahnung',
    'Eine Mahnung ist ein formelles Schreiben, das einen Schuldner zur Zahlung einer ausstehenden Rechnung auffordert. Sie wird typischerweise nach Ablauf der ursprünglichen Zahlungsfrist versendet und enthält zusätzliche Mahngebühren sowie eine neue Frist. Im Gegensatz zu einer einfachen Rechnung oder Zahlungserinnerung enthält eine Mahnung explizit rechtliche Konsequenzen bei Nichtzahlung und ist oft in mehrere Mahnstufen unterteilt.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "Dunning Notice", "description": "Schema for extracting data from dunning notices", "type": "object", "properties": {"rechnungsnummer": {"description": "Original invoice number", "type": "string"}, "mahnungsnummer": {"description": "Unique dunning notice number", "type": "string"}, "mahnstufe": {"description": "Dunning level (e.g., 1, 2, 3)", "type": "integer"}, "ursprungsbetrag": {"description": "Original amount before dunning fees", "type": "string"}, "mahngebuehr": {"description": "Dunning fee amount", "type": "string"}, "gesamtbetrag": {"description": "Total amount due including dunning fees", "type": "string"}, "zahlungsfrist": {"description": "Payment deadline (YYYY-MM-DD)", "type": "string", "format": "date"}, "iban": {"description": "IBAN for payment", "type": "string"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean", "default": false}, "steuerrelevanz_hinweis": {"type": "string", "default": null}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "default": null}, "steuerjahr": {"type": "string", "pattern": "^[0-9]{4}$", "default": null}, "mwst_ausgewiesen": {"type": "boolean", "default": false}, "mwst_betrag": {"type": "string", "default": null}, "mwst_satz": {"type": "string", "default": null}, "aktenzeichen": {"type": "string", "default": null}, "dokumenten_id": {"type": "string", "default": null}}, "additionalProperties": false}, "positionen": {"type": "array", "description": "Einzelpositionen der Mahnung (ursprüngliche Forderung, Mahngebühren, Verzugszinsen, etc.)", "items": {"type": "object", "properties": {"beschreibung": {"type": "string"}, "betrag": {"type": "string"}, "faellig_am": {"type": "string"}}}}, "waehrung": {"type": "string", "default": "EUR", "description": "Waehrung ISO 4217 (EUR, USD, etc.)"}}, "required": ["rechnungsnummer", "mahnungsnummer", "mahnstufe", "ursprungsbetrag", "gesamtbetrag", "zahlungsfrist", "iban"], "additionalProperties": false}',
    '"{\"rechnungsnummer\": \"Die Nummer der urspr\u00fcnglichen Rechnung, auf die sich die Mahnung bezieht. Wichtig f\u00fcr die Zuordnung der Zahlung und als Nachweis in der Buchhaltung. Format: Alphanumerisch, z. B. ''RE-2023-4711''.\", \"mahnungsnummer\": \"Eindeutige Nummer der Mahnung, oft fortlaufend oder mit Pr\u00e4fix. Wichtig f\u00fcr die Dokumentation des Mahnverfahrens. Format: Alphanumerisch, z. B. ''MAH-2023-0012''.\", \"mahnstufe\": \"Gibt an, um die wievielte Mahnung es sich handelt (z. B. 1, 2, 3). Wichtig f\u00fcr die Einsch\u00e4tzung der Dringlichkeit und rechtlicher Schritte. Format: Numerisch oder als Text (z. B. ''Erste Mahnung'').\", \"ursprungsbetrag\": \"Der urspr\u00fcngliche Rechnungsbetrag ohne Mahngeb\u00fchren. Wichtig f\u00fcr die steuerliche Erfassung der urspr\u00fcnglichen Forderung. Format: Dezimalzahl mit W\u00e4hrung, z. B. ''120,50 \u20ac''.\", \"mahngebuehr\": \"Zus\u00e4tzliche Geb\u00fchr f\u00fcr die Mahnung, die dem Schuldner in Rechnung gestellt wird. Meist nicht steuerlich absetzbar, aber relevant f\u00fcr die Gesamtzahlung. Format: Dezimalzahl mit W\u00e4hrung, z. B. ''5,00 \u20ac''.\", \"gesamtbetrag\": \"Summe aus ursprungsbetrag und mahngebuehr, die bis zum Fristende zu zahlen ist. Wichtig f\u00fcr die Zahlungsabwicklung und als Nachweis der Gesamtforderung. Format: Dezimalzahl mit W\u00e4hrung, z. B. ''125,50 \u20ac''.\", \"zahlungsfrist\": \"Datum, bis zu dem die Zahlung sp\u00e4testens erfolgen muss, um weitere Schritte zu vermeiden. Wichtig f\u00fcr die Fristen\u00fcberwachung und rechtliche Konsequenzen. Format: Datum (TT.MM.JJJJ oder JJJJ-MM-TT).\"}"',
    'Mahnung, Zahlungserinnerung, Mahngebühr, Mahnstufe, letzte Frist, Verzug, Säumnis, Zahlungsaufforderung, Inkassoverfahren, Fälligkeit, Rechnungsnummer, Mahnungsnummer, Gesamtbetrag, IBAN, Überfälligkeit, reminder, dunning notice, late payment, collection procedure, default, due date',
    'Versorger, Versicherungen, Shops',
    '{"relevanz": "teilweise", "hinweise": "Mahngebühren sind in der Regel nicht steuerlich absetzbar, da sie als Verzugsschaden gelten. Der ursprungsbetrag (die ursprüngliche Rechnung) kann jedoch steuerrelevant sein, abhängig vom Kontext (z. B. §4 Abs. 4 EStG für Betriebsausgaben, §9 EStG für Werbungskosten oder §33 EStG für außergewöhnliche Belastungen). Bei privaten Haushalten ist die Relevanz meist auf die Anlage N (Werbungskosten) oder Anlage V (Vermietung) beschränkt. Die Mahnung selbst dient als Nachweis für die Fälligkeit und Höhe der Schuld.", "anlagen": ["N", "V", "EÜR (bei Selbstständigen)"], "paragraphen": ["§4 Abs. 4 EStG", "§9 EStG", "§33 EStG"]}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
