INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'electricity_bill',
    'A. Finanzen & Rechnungen',
    'Stromrechnung',
    'Eine Stromrechnung dokumentiert den Energieverbrauch eines Haushalts über einen bestimmten Abrechnungszeitraum, inklusive Kostenaufschlüsselung (Arbeitspreis, Grundpreis) und ggf. Nachzahlungen oder Guthaben. Sie wird typischerweise jährlich oder halbjährlich vom Stromanbieter versendet und dient als Nachweis für gezahlte Energiekosten, die teilweise steuerlich absetzbar sind. Im Gegensatz zu Gasrechnungen oder Wasserrechnungen bezieht sie sich ausschließlich auf elektrischen Strom und enthält spezifische Felder wie Zählernummer und kWh-Verbrauch.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "electricity_bill", "description": "Schema für Stromrechnungen", "type": "object", "properties": {"anbieter": {"type": "object", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "pattern": "^[A-Z]{2}$"}}, "required": ["strasse", "plz", "ort", "land"]}, "kundenservice_telefon": {"type": "string", "pattern": "^\\+[0-9]{11,15}$"}, "kundenservice_email": {"type": "string", "format": "email"}}, "required": ["name"]}, "kundennummer": {"type": "string"}, "zaehlernummer": {"type": "string"}, "verbrauch_kwh": {"type": "number", "minimum": 0}, "zeitraum": {"type": "object", "properties": {"von": {"type": "string", "format": "date"}, "bis": {"type": "string", "format": "date"}}, "required": ["von", "bis"]}, "arbeitspreis_ct_kwh": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$"}, "grundpreis": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$"}, "abschlag_monatlich": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$"}, "nachzahlung_guthaben": {"type": "string", "pattern": "^(-?[0-9]+\\.[0-9]{2})$"}, "neuer_abschlag": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "enum": [null, "Haushaltsnahe Dienstleistungen"], "default": null}, "steuer_kategorie": {"type": "string", "enum": ["haushaltsnahe_dienstleistungen", null], "default": null}, "steuerjahr": {"type": "string", "pattern": "^[0-9]{4}$", "default": null}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$", "default": null}, "mwst_satz": {"type": "string", "pattern": "^[0-9]+(\\.[0-9]{1,2})?$", "default": null}, "aktenzeichen": {"type": "string", "default": null}, "dokumenten_id": {"type": "string", "default": null}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}, "positionen": {"type": "array", "description": "Einzelpositionen der Stromrechnung (Arbeitspreis, Grundpreis, Netzentgelte, Abgaben, etc.)", "items": {"type": "object", "properties": {"beschreibung": {"type": "string"}, "menge": {"type": "string"}, "einzelpreis": {"type": "string"}, "betrag": {"type": "string"}, "einheit": {"type": "string", "description": "Einheit (z.B. kWh, Stk, Monat)"}}}}, "objekt_adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "default": "DE"}}, "description": "Verbrauchsstelle/Liegenschaft des Stromzaehlers"}, "waehrung": {"type": "string", "default": "EUR", "description": "Waehrung ISO 4217 (EUR, USD, etc.)"}, "verbrauch_einheit": {"type": "string", "description": "Einheit des Verbrauchs (z.B. kWh)"}}, "required": ["anbieter", "kundennummer", "zaehlernummer", "verbrauch_kwh", "zeitraum", "arbeitspreis_ct_kwh", "grundpreis", "_meta"]}',
    '"anbieter, kundennummer, zaehlernummer, verbrauch_kwh, zeitraum, arbeitspreis_ct_kwh, grundpreis, abschlag_monatlich, nachzahlung_guthaben, neuer_abschlag"',
    'Stromrechnung, Stromabrechnung, Energieabrechnung, kWh, Verbrauch, Arbeitspreis, Grundpreis, Abschlag, Nachzahlung, Guthaben, Zählernummer, Kundennummer, Netzbetreiber, Stromanbieter, EEG-Umlage, Stromsteuer, electricity bill, consumption, base price, energy charge, meter number, advance payment, final settlement',
    'NEW, Stadtwerke, E.ON, Vattenfall, etc.',
    '{"paragraphen": ["§35a EStG (haushaltsnahe Dienstleistungen)", "§9 EStG (Werbungskosten bei Homeoffice)"], "anlage": "N (bei Homeoffice), sonst null"}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
