    'E-Auto Laderechnung',
    'Laderechnung fuer Elektrofahrzeuge',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "ev_charging", "description": "Schema fuer E-Auto Laderechnungen", "type": "object", "properties": {"anbieter": {"type": "string"}, "ladesaeule_id": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "pattern": "^[A-Z]{2}$"}}}, "datum": {"type": "string", "format": "date"}, "energie_kwh": {"type": "string"}, "preis_pro_kwh": {"type": "string"}, "ladedauer_minuten": {"type": "string"}, "gesamtbetrag": {"type": "string"}, "waehrung": {"type": "string", "default": "EUR"}, "kennzeichen": {"type": "string"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "default": null}, "steuer_kategorie": {"type": "string", "default": null}, "steuerjahr": {"type": "string", "pattern": "^[0-9]{4}$", "default": null}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "default": null}, "mwst_satz": {"type": "string", "default": null}, "aktenzeichen": {"type": "string", "default": null}, "dokumenten_id": {"type": "string", "default": null}, "absender": {"type": "string"}, "empfaenger": {"type": "string"}, "datum": {"type": "string", "format": "date"}, "betreff": {"type": "string"}}}}}',
