    'Tankquittung oder Kraftstoff-Rechnung',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "fuel_receipt", "description": "Schema fuer Tankquittungen", "type": "object", "properties": {"tankstelle": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "pattern": "^[A-Z]{2}$"}}}, "datum": {"type": "string", "format": "date"}, "kraftstoffart": {"type": "string", "description": "Super E10, Super E5, Diesel, AdBlue, Strom"}, "menge_liter": {"type": "string"}, "preis_pro_liter": {"type": "string"}, "gesamtbetrag": {"type": "string"}, "waehrung": {"type": "string", "default": "EUR"}, "km_stand": {"type": "string", "description": "Kilometerstand wenn angegeben"}, "kennzeichen": {"type": "string"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "default": null}, "steuer_kategorie": {"type": "string", "default": null}, "steuerjahr": {"type": "string", "pattern": "^[0-9]{4}$", "default": null}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "default": null}, "mwst_satz": {"type": "string", "default": null}, "aktenzeichen": {"type": "string", "default": null}, "dokumenten_id": {"type": "string", "default": null}, "absender": {"type": "string"}, "empfaenger": {"type": "string"}, "datum": {"type": "string", "format": "date"}, "betreff": {"type": "string"}}}}}',
