INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'gas_bill',
    'A. Finanzen & Rechnungen',
    'Gasrechnung',
    'Eine Gasrechnung dokumentiert den Verbrauch von Erdgas in einem Haushalt über einen bestimmten Abrechnungszeitraum. Sie wird typischerweise jährlich oder halbjährlich vom Gasversorger ausgestellt und enthält Details zu Verbrauch, Preisen, Abschlägen und einer eventuellen Nachzahlung oder Gutschrift. Im Gegensatz zu Stromrechnungen bezieht sie sich ausschließlich auf den Gasverbrauch und enthält spezifische Angaben wie die CO₂-Abgabe und den Arbeitspreis pro kWh für Gas.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "Gasrechnung", "description": "Schema für die Extraktion von Daten aus einer Gasrechnung", "type": "object", "properties": {"anbieter": {"type": "object", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "pattern": "^[A-Z]{2}$"}}, "required": ["strasse", "plz", "ort", "land"]}, "kundenservice_telefon": {"type": "string", "pattern": "^\\+[0-9]{11,15}$"}, "kundenservice_email": {"type": "string", "format": "email"}}, "required": ["name", "adresse"]}, "kundennummer": {"type": "string"}, "zaehlernummer": {"type": "string"}, "verbrauch_kwh": {"type": "number", "minimum": 0}, "zeitraum": {"type": "object", "properties": {"von": {"type": "string", "format": "date"}, "bis": {"type": "string", "format": "date"}}, "required": ["von", "bis"]}, "arbeitspreis_ct_kwh": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$"}, "grundpreis": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$"}, "abschlag_monatlich": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$"}, "nachzahlung_guthaben": {"type": "string", "pattern": "^-?[0-9]+\\.[0-9]{2}$"}, "neuer_abschlag": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$"}, "co2_abgabe": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$"}, "rechnungsbetrag": {"type": "object", "properties": {"netto": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$"}, "brutto": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$"}, "währung": {"type": "string", "pattern": "^[A-Z]{3}$"}}, "required": ["netto", "brutto", "währung"]}, "zahlungsinformationen": {"type": "object", "properties": {"iban": {"type": "string", "pattern": "^[A-Z]{2}[0-9]{2}[A-Z0-9]{11,30}$"}, "bic": {"type": "string", "pattern": "^[A-Z]{6}[A-Z0-9]{2}([A-Z0-9]{3})?$"}, "zahlungsziel": {"type": "string", "format": "date"}}, "required": ["iban"]}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^[0-9]{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$", "nullable": true}, "mwst_satz": {"type": "string", "pattern": "^[0-9]+(\\.[0-9]{1,2})?$", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}, "positionen": {"type": "array", "description": "Einzelpositionen der Gasrechnung (Arbeitspreis, Grundpreis, CO2-Abgabe, Netzentgelte, etc.)", "items": {"type": "object", "properties": {"beschreibung": {"type": "string"}, "menge": {"type": "string"}, "einzelpreis": {"type": "string"}, "betrag": {"type": "string"}, "einheit": {"type": "string", "description": "Einheit (z.B. kWh, m3, Monat)"}}}}, "objekt_adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "default": "DE"}}, "description": "Verbrauchsstelle/Liegenschaft des Gaszaehlers"}, "waehrung": {"type": "string", "default": "EUR", "description": "Waehrung ISO 4217 (EUR, USD, etc.)"}, "verbrauch_einheit": {"type": "string", "description": "Einheit des Verbrauchs (kWh oder m3)"}}, "required": ["anbieter", "kundennummer", "zaehlernummer", "verbrauch_kwh", "zeitraum", "arbeitspreis_ct_kwh", "grundpreis", "_meta"]}',
    '"anbieter, kundennummer, zaehlernummer, verbrauch_kwh, zeitraum, arbeitspreis_ct_kwh, grundpreis, abschlag_monatlich, nachzahlung_guthaben, neuer_abschlag, co2_abgabe"',
    'Gasrechnung, Erdgasverbrauch, Gasabrechnung, kWh, Zählernummer, Arbeitspreis, Grundpreis, Abschlag, Nachzahlung, Gutschrift, CO₂-Abgabe, Gasversorger, Stadtwerke, Jahresverbrauch, Verbrauchszeitraum, Rechnungsbetrag, gas bill, gas consumption, meter number, base price, energy charge, advance payment, carbon dioxide levy',
    'NEW, Stadtwerke, Gasversorger',
    '{"paragraphen": "§35a EStG (haushaltsnahe Dienstleistungen), §9b EStG (energetische Sanierung)", "anlage": "Haushaltsnahe Dienstleistungen (Anlage N, Zeile 73-78)", "absetzbare_betraege": {"beschreibung": "Anteil der Arbeitskosten (z. B. für Ablesung oder Wartung) und CO₂-Abgabe können unter bestimmten Bedingungen abgesetzt werden."}}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
