INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'heating_bill',
    'A. Finanzen & Rechnungen',
    'Heizkostenabrechnung',
    'Die Heizkostenabrechnung ist ein jährliches Dokument, das die Kosten für Heizung und Warmwasser in Mietobjekten detailliert auflistet. Sie wird vom Vermieter oder einem beauftragten Dienstleister (z. B. Techem, ista) erstellt und enthält Verbrauchs- und Grundkostenanteile sowie Vorauszahlungen und eine mögliche Nachzahlung oder Gutschrift. Im Gegensatz zu reinen Energieabrechnungen (z. B. Strom oder Gas) bezieht sich die Heizkostenabrechnung spezifisch auf die Umlage der Heiz- und Warmwasserkosten in Mehrparteienhäusern nach der Heizkostenverordnung (HeizkostenV).',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "Heating Bill", "description": "Schema for extracting data from a heating cost statement", "type": "object", "properties": {"objekt": {"type": "object", "properties": {"bezeichnung": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "default": "DE"}}, "required": ["strasse", "plz", "ort"]}, "einheit": {"type": "string"}}, "required": ["adresse"]}, "abrechnungszeitraum": {"type": "object", "properties": {"von": {"type": "string", "format": "date"}, "bis": {"type": "string", "format": "date"}}, "required": ["von", "bis"]}, "heizkosten_gesamt": {"type": "string"}, "warmwasser_gesamt": {"type": "string"}, "verbrauchsanteil": {"type": "object", "properties": {"betrag": {"type": "string"}, "anteil_prozent": {"type": "string"}}, "required": ["betrag"]}, "grundkostenanteil": {"type": "object", "properties": {"betrag": {"type": "string"}, "anteil_prozent": {"type": "string"}}, "required": ["betrag"]}, "eigenanteil": {"type": "string"}, "vorauszahlungen": {"type": "array", "items": {"type": "object", "properties": {"betrag": {"type": "string"}, "zeitraum": {"type": "object", "properties": {"von": {"type": "string", "format": "date"}, "bis": {"type": "string", "format": "date"}}, "required": ["von", "bis"]}}, "required": ["betrag", "zeitraum"]}}, "nachzahlung_guthaben": {"type": "object", "properties": {"betrag": {"type": "string"}, "faelligkeitsdatum": {"type": "string", "format": "date"}, "typ": {"type": "string", "enum": ["nachzahlung", "guthaben"]}}, "required": ["betrag", "typ"]}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean", "default": false}, "steuerrelevanz_hinweis": {"type": "string", "default": null}, "steuer_kategorie": {"type": "string", "enum": ["haushaltsnahe_dienstleistungen", null], "default": null}, "steuerjahr": {"type": "string", "pattern": "^\\d{4}$", "default": null}, "mwst_ausgewiesen": {"type": "boolean", "default": false}, "mwst_betrag": {"type": "string", "default": null}, "mwst_satz": {"type": "string", "default": null}, "aktenzeichen": {"type": "string", "default": null}, "dokumenten_id": {"type": "string", "default": null}}, "required": ["steuerrelevant"]}, "positionen": {"type": "array", "description": "Einzelpositionen der Heizkostenabrechnung (Heizung, Warmwasser, Grundkosten, Verbrauchskosten, etc.)", "items": {"type": "object", "properties": {"kostenart": {"type": "string"}, "gesamtkosten": {"type": "string"}, "anteil": {"type": "string"}, "verteilungsschluessel": {"type": "string"}, "einheit": {"type": "string", "description": "Einheit des Verteilungsschluessels (z.B. m2, kWh, Personen)"}}}}, "objekt_adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "default": "DE"}}, "description": "Objekt/Liegenschaft der Heizkostenabrechnung"}, "waehrung": {"type": "string", "default": "EUR", "description": "Waehrung ISO 4217 (EUR, USD, etc.)"}, "verbrauch_einheit": {"type": "string", "description": "Einheit des Verbrauchs (z.B. kWh, m2)"}}, "required": ["objekt", "abrechnungszeitraum", "heizkosten_gesamt", "eigenanteil", "nachzahlung_guthaben", "_meta"]}',
    '"objekt, abrechnungszeitraum, heizkosten_gesamt, warmwasser_gesamt, verbrauchsanteil, grundkostenanteil, eigenanteil, vorauszahlungen, nachzahlung_guthaben"',
    'Heizkostenabrechnung, Heizkostenverordnung, HeizkostenV, Warmwasserkosten, Verbrauchsanteil, Grundkostenanteil, Vorauszahlungen, Nachzahlung, Guthaben, Umlage, Techem, ista, Vermieter, Mietnebenkosten, Betriebskostenabrechnung, heating costs, hot water costs, consumption share, basic costs, advance payments, refund, utility bill, Nebenkostenabrechnung',
    'Techem, ista, Vermieter',
    '{"paragraphen": "§ 35a EStG (haushaltsnahe Dienstleistungen), § 9b EStG (anteilige Absetzung von Handwerkerleistungen für Heizungswartung)", "anlage": "Anlage N (Zeile 5 oder 7 für haushaltsnahe Dienstleistungen/Handwerkerleistungen)", "absetzbare_betraege": {"haushaltsnahe_dienstleistungen": "20% der Arbeitskosten (max. 4.000 € pro Jahr)"}}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
