INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'internet_bill',
    'A. Finanzen & Rechnungen',
    'Internet/Breitband-Rechnung',
    'Dieses Dokument ist eine Rechnung für Internet- oder Breitband-Dienstleistungen, die monatlich oder in anderen Abrechnungszeiträumen von Telekommunikationsanbietern ausgestellt wird. Es enthält Details zum Vertrag, den monatlichen Gebühren und zusätzlichen Leistungen. Im Gegensatz zu Mobilfunkrechnungen bezieht es sich spezifisch auf Festnetz-Internetanschlüsse und deren Nutzung.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "Internet/Breitband-Rechnung", "type": "object", "properties": {"anbieter": {"type": "string", "description": "Name des Internetanbieters"}, "kundennummer": {"type": "string", "description": "Kundennummer beim Anbieter"}, "vertragsnummer": {"type": "string", "description": "Vertragsnummer des Internetvertrags"}, "tarif": {"type": "string", "description": "Name des gebuchten Tarifs"}, "bandbreite": {"type": "string", "description": "Vertraglich vereinbarte Bandbreite (z.B. ''100 Mbit/s'')"}, "grundgebuehr": {"type": "string", "description": "Monatliche Grundgebühr (Betrag mit 2 Dezimalstellen)", "pattern": "^\\d+\\.\\d{2}$"}, "zusatzleistungen": {"type": "array", "description": "Liste der zusätzlichen Leistungen", "items": {"type": "object", "properties": {"bezeichnung": {"type": "string", "description": "Name der Zusatzleistung"}, "betrag": {"type": "string", "description": "Kosten der Zusatzleistung (Betrag mit 2 Dezimalstellen)", "pattern": "^\\d+\\.\\d{2}$"}}, "required": ["bezeichnung", "betrag"]}}, "gesamtbetrag": {"type": "string", "description": "Gesamtbetrag der Rechnung (Betrag mit 2 Dezimalstellen)", "pattern": "^\\d+\\.\\d{2}$"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean", "description": "Gibt an, ob das Dokument steuerrelevant ist"}, "steuerrelevanz_hinweis": {"type": "string", "description": "Hinweis zur Steuerrelevanz", "nullable": true}, "steuer_kategorie": {"type": "string", "description": "Kategorie der Steuerrelevanz", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "nullable": true}, "steuerjahr": {"type": "string", "description": "Steuerjahr im Format YYYY", "pattern": "^\\d{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean", "description": "Gibt an, ob Mehrwertsteuer ausgewiesen ist"}, "mwst_betrag": {"type": "string", "description": "Ausgewiesener Mehrwertsteuerbetrag (Betrag mit 2 Dezimalstellen)", "pattern": "^\\d+\\.\\d{2}$", "nullable": true}, "mwst_satz": {"type": "string", "description": "Mehrwertsteuersatz (z.B. ''19.00'')", "nullable": true}, "aktenzeichen": {"type": "string", "description": "Aktenzeichen für steuerliche Zwecke", "nullable": true}, "dokumenten_id": {"type": "string", "description": "Eindeutige Dokumenten-ID", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}, "positionen": {"type": "array", "description": "Einzelpositionen der Internetrechnung (Grundgebühr, Hardware-Miete, Optionen, etc.)", "items": {"type": "object", "properties": {"beschreibung": {"type": "string"}, "menge": {"type": "string"}, "einzelpreis": {"type": "string"}, "betrag": {"type": "string"}}}}, "waehrung": {"type": "string", "default": "EUR", "description": "Waehrung ISO 4217 (EUR, USD, etc.)"}}, "required": ["anbieter", "kundennummer", "vertragsnummer", "tarif", "grundgebuehr", "gesamtbetrag", "_meta"]}',
    '"{\"anbieter\": \"Name des Internetdienstanbieters (z. B. Telekom, Vodafone). Wichtig f\u00fcr die Zuordnung der Rechnung und ggf. steuerliche Dokumentation.\", \"kundennummer\": \"Eindeutige Identifikationsnummer des Kunden beim Anbieter. Format: alphanumerisch, z. B. ''123456789''. Wichtig f\u00fcr die Zuordnung der Rechnung zum Vertrag.\", \"vertragsnummer\": \"Eindeutige Nummer des Vertrags. Format: alphanumerisch, z. B. ''V123456789''. Wichtig f\u00fcr die Identifikation des spezifischen Vertrags und ggf. steuerliche Nachweise.\", \"tarif\": \"Name oder Bezeichnung des gebuchten Tarifs (z. B. ''MagentaZuhause M''). Wichtig f\u00fcr die \u00dcberpr\u00fcfung der Vertragskonditionen und ggf. steuerliche Absetzbarkeit.\", \"bandbreite\": \"Angegebene Download- und Upload-Geschwindigkeit des Internetanschlusses (z. B. ''100 Mbit/s Download, 40 Mbit/s Upload''). Format: numerisch mit Einheit (Mbit/s, Gbit/s). Wichtig f\u00fcr die \u00dcberpr\u00fcfung der Leistung und ggf. berufliche Nutzung.\", \"grundgebuehr\": \"Monatliche Grundgeb\u00fchr f\u00fcr den Internetanschluss. Format: numerisch mit W\u00e4hrung (z. B. 39,99 \u20ac). Wichtig f\u00fcr die steuerliche Absetzbarkeit bei beruflicher Nutzung (anteilig).\", \"zusatzleistungen[]\": \"Liste zus\u00e4tzlicher Leistungen oder Geb\u00fchren (z. B. Router-Miete, Telefon-Flatrate, TV-Pakete). Jeder Eintrag enth\u00e4lt Beschreibung und Betrag. Wichtig f\u00fcr die \u00dcberpr\u00fcfung der Gesamtkosten und ggf. steuerliche Absetzbarkeit einzelner Posten.\"}"',
    'Internetrechnung, Breitbandrechnung, DSL-Rechnung, Grundgebühr, monatliche Gebühren, Vertragsnummer, Kundennummer, Download-Geschwindigkeit, Upload-Geschwindigkeit, Router-Miete, Telekom, Vodafone, 1&1, IONOS, Internetanschluss, Flatrate, bandwidth, monthly fee, contract number, customer number, internet service provider, ISP bill',
    'Telekom, Vodafone, 1&1, IONOS',
    '{"einordnung": "§4 Abs. 4 EStG (Werbungskosten bei Homeoffice), §9 EStG (beruflich veranlasste Aufwendungen)", "anlage": "N (bei beruflicher Nutzung), Vorsorgeaufwand (falls privat, aber nur anteilig bei gemischter Nutzung)", "absetzbar": "Anteilige Kosten bei beruflicher Nutzung (z. B. Homeoffice-Pauschale oder tatsächliche Kosten). Maximal 1.260 € pro Jahr (Homeoffice-Pauschale, §4 Abs. 5a EStG) oder anteilige Kosten bei Nachweis der beruflichen Nutzung (z. B. 50% der Grundgebühr)."}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
ON CONFLICT (id) DO UPDATE SET category=EXCLUDED.category, display_name=EXCLUDED.display_name, description=EXCLUDED.description, schema=EXCLUDED.schema, field_descriptions=EXCLUDED.field_descriptions, classify_keywords=EXCLUDED.classify_keywords, typical_senders=EXCLUDED.typical_senders, steuer_relevanz=EXCLUDED.steuer_relevanz, priority=EXCLUDED.priority, enabled=EXCLUDED.enabled, version=EXCLUDED.version, source=EXCLUDED.source, notes=EXCLUDED.notes;

INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'invoice',
    'A. Finanzen & Rechnungen',
    'Rechnung',
    'Generische Rechnung für Waren oder Dienstleistungen. Für spezialisierte Rechnungen eigene Templates nutzen: craftsman_bill (Handwerker §35a), supplier_invoice (Lieferant mit PO), electricity_bill/gas_bill/telecom_bill (Versorger), lawyer_invoice (Anwalt RVG).',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "invoice", "description": "Schema für Rechnungsdokumente", "type": "object", "properties": {"rechnungsnummer": {"type": "string", "description": "Eindeutige Rechnungsnummer"}, "datum": {"type": "string", "format": "date", "description": "Rechnungsdatum im Format YYYY-MM-DD"}, "positionen": {"type": "array", "items": {"type": "object", "properties": {"beschreibung": {"type": "string", "description": "Beschreibung der Position"}, "menge": {"type": "number", "description": "Menge der Position"}, "einzelpreis": {"type": "string", "pattern": "^\\d+\\.\\d{2}$", "description": "Einzelpreis der Position mit 2 Dezimalstellen"}, "gesamtpreis": {"type": "string", "pattern": "^\\d+\\.\\d{2}$", "description": "Gesamtpreis der Position mit 2 Dezimalstellen"}, "einheit": {"type": "string", "description": "Einheit (z.B. Stk, h, m2, kg)"}}, "required": ["beschreibung", "menge", "einzelpreis", "gesamtpreis"]}}, "netto": {"type": "string", "pattern": "^\\d+\\.\\d{2}$", "description": "Nettosumme der Rechnung mit 2 Dezimalstellen"}, "mwst": {"type": "string", "pattern": "^\\d+\\.\\d{2}$", "description": "Mehrwertsteuerbetrag mit 2 Dezimalstellen"}, "brutto": {"type": "string", "pattern": "^\\d+\\.\\d{2}$", "description": "Bruttosumme der Rechnung mit 2 Dezimalstellen"}, "iban": {"type": "string", "pattern": "^[A-Z]{2}\\d{2}[A-Z0-9]{11,30}$", "description": "IBAN für die Zahlung ohne Leerzeichen"}, "zahlungsfrist": {"type": "string", "format": "date", "description": "Fälligkeitsdatum im Format YYYY-MM-DD"}, "bestellnummer": {"type": "string", "description": "Bestellnummer des Kunden"}, "kundennummer": {"type": "string", "description": "Kundennummer"}, "projektnummer": {"type": "string", "description": "Projektnummer"}, "po_nummer": {"type": "string", "description": "Purchase Order Nummer"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean", "description": "Gibt an, ob das Dokument steuerrelevant ist"}, "steuerrelevanz_hinweis": {"type": "string", "description": "Hinweis zur Steuerrelevanz", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "description": "Kategorie der Steuerrelevanz", "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^\\d{4}$", "description": "Steuerjahr im Format YYYY", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean", "description": "Gibt an, ob die Mehrwertsteuer ausgewiesen ist"}, "mwst_betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$", "description": "Mehrwertsteuerbetrag mit 2 Dezimalstellen", "nullable": true}, "mwst_satz": {"type": "string", "pattern": "^\\d+(\\.\\d{1,2})?$", "description": "Mehrwertsteuersatz (z.B. 19 oder 7.0)", "nullable": true}, "aktenzeichen": {"type": "string", "description": "Aktenzeichen", "nullable": true}, "dokumenten_id": {"type": "string", "description": "Eindeutige Dokumenten-ID", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}, "waehrung": {"type": "string", "default": "EUR", "description": "Waehrung ISO 4217 (EUR, USD, etc.)"}}, "required": ["rechnungsnummer", "datum", "positionen", "netto", "brutto", "_meta"]}',
    '"{\"rechnungsnummer\": \"Eindeutige Rechnungsnummer\", \"datum\": \"YYYY-MM-DD\", \"positionen\": \"Array: {beschreibung, menge, einzelpreis, betrag}\", \"netto\": \"Nettobetrag\", \"mwst\": \"MwSt-Betrag\", \"brutto\": \"Bruttobetrag\", \"iban\": \"IBAN f\u00fcr \u00dcberweisung\", \"zahlungsfrist\": \"Zahlungsziel YYYY-MM-DD\", \"bestellnummer\": \"Referenz Bestellung\", \"kundennummer\": \"Kundennr beim Aussteller\", \"projektnummer\": \"Projektreferenz\", \"po_nummer\": \"Purchase Order Nr\"}"',
    'Rechnung,Invoice,Rechnungsnummer,Rechnungsdatum,Nettobetrag,Bruttobetrag,MwSt,Mehrwertsteuer,Umsatzsteuer,Zahlungsziel,IBAN,Positionen,Bestellnummer',
    'Shops, Dienstleister, Handwerker',
    'MwSt ausgewiesen → Beleg aufbewahren. Berufliche Nutzung: Werbungskosten Anlage N. Vermietung: Anlage V. Vorsteuerabzug nur für Gewerbetreibende.',
    0,
    1,
    1,
    'mistral_batch',
    'Generisches Template — prüfe ob spezialisiertes besser passt: craftsman_bill, supplier_invoice, electricity_bill, lawyer_invoice etc.'
)
ON CONFLICT (id) DO UPDATE SET category=EXCLUDED.category, display_name=EXCLUDED.display_name, description=EXCLUDED.description, schema=EXCLUDED.schema, field_descriptions=EXCLUDED.field_descriptions, classify_keywords=EXCLUDED.classify_keywords, typical_senders=EXCLUDED.typical_senders, steuer_relevanz=EXCLUDED.steuer_relevanz, priority=EXCLUDED.priority, enabled=EXCLUDED.enabled, version=EXCLUDED.version, source=EXCLUDED.source, notes=EXCLUDED.notes;

INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'loan_statement',
    'A. Finanzen & Rechnungen',
    'Darlehens-Kontoauszug',
    'Ein Darlehens-Kontoauszug ist ein periodisches Dokument von Banken oder Bausparkassen, das den aktuellen Stand eines Darlehens (z. B. Immobilienkredit, Bausparvertrag) zusammenfasst. Es enthält Details wie Restschuld, gezahlte Zinsen und Tilgung im aktuellen Jahr sowie zukünftige Raten. Im Gegensatz zu einem normalen Bankkontoauszug bezieht es sich ausschließlich auf Darlehenskonten und enthält spezifische Kreditdaten wie Zinsbindung oder Sondertilgungsoptionen.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "loan_statement", "description": "Darlehens-Kontoauszug", "type": "object", "properties": {"darlehensnehmer": {"type": "object", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort", "land"]}}, "required": ["name", "adresse"]}, "darlehensnummer": {"type": "string"}, "bank": {"type": "object", "properties": {"name": {"type": "string"}, "iban": {"type": "string"}, "bic": {"type": "string"}}, "required": ["name"]}, "stichtag": {"type": "string", "format": "date"}, "ursprungsbetrag": {"type": "string"}, "restschuld": {"type": "string"}, "zinsen_bezahlt_jahr": {"type": "string"}, "tilgung_bezahlt_jahr": {"type": "string"}, "annuitaet": {"type": "string"}, "naechste_rate": {"type": "object", "properties": {"faelligkeitsdatum": {"type": "string", "format": "date"}, "betrag": {"type": "string"}}, "required": ["faelligkeitsdatum", "betrag"]}, "zinsbindung_bis": {"type": "string", "format": "date"}, "sondertilgung_moeglich": {"type": "boolean"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^\\d{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "nullable": true}, "mwst_satz": {"type": "string", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}, "buchungen": {"type": "array", "description": "Tilgungs- und Zinsbuchungen des Darlehens", "items": {"type": "object", "properties": {"datum": {"type": "string"}, "tilgung": {"type": "string"}, "zinsen": {"type": "string"}, "rate": {"type": "string"}, "restschuld": {"type": "string"}}}}}, "required": ["darlehensnehmer", "darlehensnummer", "bank", "stichtag", "ursprungsbetrag", "restschuld", "_meta"]}',
    '"darlehensnehmer, darlehensnummer, bank, stichtag, ursprungsbetrag, restschuld, zinsen_bezahlt_jahr, tilgung_bezahlt_jahr, annuitaet, naechste_rate, zinsbindung_bis, sondertilgung_moeglich"',
    'Darlehenskontoauszug, Darlehenskonto, Kreditkontoauszug, Restschuld, Ursprungskapital, Zinsen p.a., Tilgung, Annuität, Zinsbindung, Sondertilgung, Darlehensnummer, Bausparvertrag, loan statement, remaining balance, interest paid, principal repayment, next installment, fixed interest rate, early repayment',
    'Banken, Bausparkassen',
    '{"paragraphen": ["§10e EStG (Altfälle)", "§35a EStG (Handwerkerleistungen bei Modernisierung)", "§9 EStG (Werbungskosten bei vermieteten Immobilien)"], "anlage": "V (bei vermieteten Immobilien), N (bei selbstgenutztem Wohneigentum in Altfällen), Vorsorgeaufwand (nur in Ausnahmefällen)", "absetzbare_betraege": {"zinsen_bezahlt_jahr": "Bei vermieteten Immobilien als Werbungskosten (Anlage V) absetzbar. Bei selbstgenutztem Wohneigentum nur in Altfällen (§10e EStG) oder bei energetischen Sanierungen (§35a EStG). Maximalbeträge je nach Fall."}}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
ON CONFLICT (id) DO UPDATE SET category=EXCLUDED.category, display_name=EXCLUDED.display_name, description=EXCLUDED.description, schema=EXCLUDED.schema, field_descriptions=EXCLUDED.field_descriptions, classify_keywords=EXCLUDED.classify_keywords, typical_senders=EXCLUDED.typical_senders, steuer_relevanz=EXCLUDED.steuer_relevanz, priority=EXCLUDED.priority, enabled=EXCLUDED.enabled, version=EXCLUDED.version, source=EXCLUDED.source, notes=EXCLUDED.notes;

INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'payment_demand',
    'A. Finanzen & Rechnungen',
    'Zahlungsaufforderung',
    'Eine Zahlungsaufforderung ist ein formelles Schreiben eines Gläubigers, Inkassounternehmens oder Anwalts, das den Schuldner zur Begleichung einer offenen Forderung auffordert. Sie enthält detaillierte Angaben zur Forderung, Zinsen, Kosten und eine Zahlungsfrist. Im Gegensatz zu einer einfachen Rechnung oder Mahnung ist sie oft rechtlich präziser formuliert und kann bereits mit Inkassokosten oder Anwaltsgebühren verbunden sein, was sie von regulären Rechnungen unterscheidet.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "payment_demand", "description": "Zahlungsaufforderung", "type": "object", "properties": {"glaeubiger": {"type": "object", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort", "land"]}, "steuernummer": {"type": "string"}, "ust_id": {"type": "string"}}, "required": ["name", "adresse"]}, "schuldner": {"type": "object", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort", "land"]}}, "required": ["name", "adresse"]}, "forderungsbetrag": {"type": "object", "properties": {"betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}, "waehrung": {"type": "string", "pattern": "^[A-Z]{3}$"}}, "required": ["betrag", "waehrung"]}, "ursprungsforderung": {"type": "object", "properties": {"betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}, "waehrung": {"type": "string", "pattern": "^[A-Z]{3}$"}, "datum": {"type": "string", "format": "date"}, "referenz": {"type": "string"}}, "required": ["betrag", "waehrung", "datum"]}, "zinsen": {"type": "array", "items": {"type": "object", "properties": {"betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}, "waehrung": {"type": "string", "pattern": "^[A-Z]{3}$"}, "satz": {"type": "string", "pattern": "^\\d+(\\.\\d{1,4})?%$"}, "zeitraum": {"type": "object", "properties": {"von": {"type": "string", "format": "date"}, "bis": {"type": "string", "format": "date"}}, "required": ["von", "bis"]}}, "required": ["betrag", "waehrung", "satz", "zeitraum"]}}, "kosten": {"type": "array", "items": {"type": "object", "properties": {"betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}, "waehrung": {"type": "string", "pattern": "^[A-Z]{3}$"}, "beschreibung": {"type": "string"}}, "required": ["betrag", "waehrung", "beschreibung"]}}, "zahlungsfrist": {"type": "string", "format": "date"}, "iban": {"type": "string", "pattern": "^[A-Z]{2}\\d{2}[A-Z0-9]{11,30}$"}, "aktenzeichen": {"type": "string"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^\\d{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$", "nullable": true}, "mwst_satz": {"type": "string", "pattern": "^\\d+(\\.\\d{1,4})?%$", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant", "steuerrelevanz_hinweis", "steuer_kategorie", "steuerjahr", "mwst_ausgewiesen", "mwst_betrag", "mwst_satz", "aktenzeichen", "dokumenten_id"]}, "positionen": {"type": "array", "description": "Einzelpositionen der Zahlungsaufforderung (Hauptforderung, Zinsen, Kosten, etc.)", "items": {"type": "object", "properties": {"beschreibung": {"type": "string"}, "betrag": {"type": "string"}}}}}, "required": ["glaeubiger", "schuldner", "forderungsbetrag", "ursprungsforderung", "zahlungsfrist", "iban", "_meta"]}',
    '"glaeubiger, schuldner, forderungsbetrag, ursprungsforderung, zinsen, kosten, zahlungsfrist, iban, aktenzeichen"',
    'Zahlungsaufforderung, Mahnung, Forderung, Inkasso, Gläubiger, Schuldner, Zahlungsfrist, Verzug, Zinsen, Kosten, Aktenzeichen, IBAN, Rechnungsbetrag, offene Forderung, Zahlungserinnerung, payment demand, collection, creditor, debtor, default interest, file reference, due date',
    'Gläubiger, Inkasso, Anwälte',
    '{"allgemein": "Zahlungsaufforderungen selbst sind nicht direkt steuerrelevant, da sie keine Einnahmen oder Ausgaben darstellen. Allerdings können die zugrundeliegenden Forderungen oder Kosten (z. B. Inkassogebühren) in bestimmten Fällen steuerlich geltend gemacht werden.", "ausnahmen": {"§33 EStG": "Falls die Forderung oder Inkassokosten im Zusammenhang mit außergewöhnlichen Belastungen stehen (z. B. Krankheitskosten), können diese unter Umständen abgesetzt werden. Die Kosten müssen jedoch nachgewiesen und die Voraussetzungen des §33 EStG erfüllt sein.", "§4 Abs. 4 EStG (Betriebsausgaben)": "Für Selbstständige oder Unternehmen können Inkassokosten oder Zinsen als Betriebsausgaben abgesetzt werden, sofern die Forderung betrieblich veranlasst war."}}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
ON CONFLICT (id) DO UPDATE SET category=EXCLUDED.category, display_name=EXCLUDED.display_name, description=EXCLUDED.description, schema=EXCLUDED.schema, field_descriptions=EXCLUDED.field_descriptions, classify_keywords=EXCLUDED.classify_keywords, typical_senders=EXCLUDED.typical_senders, steuer_relevanz=EXCLUDED.steuer_relevanz, priority=EXCLUDED.priority, enabled=EXCLUDED.enabled, version=EXCLUDED.version, source=EXCLUDED.source, notes=EXCLUDED.notes;

INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'purchase_order',
    'A. Finanzen & Rechnungen',
    'Bestellung/Auftragsbestätigung',
    'Eine Bestellung oder Auftragsbestätigung dokumentiert die verbindliche Vereinbarung zwischen Käufer und Verkäufer über den Kauf von Waren oder Dienstleistungen. Sie wird typischerweise nach einer Anfrage oder einem Angebot erstellt und enthält Details wie Artikel, Mengen, Preise und Lieferbedingungen. Im Gegensatz zu einer Rechnung ist sie kein Zahlungsbeleg, sondern bestätigt lediglich die Bestellung und dient als Grundlage für die spätere Lieferung und Rechnungsstellung.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "purchase_order", "description": "Schema f\u00fcr Bestellungen und Auftragsbest\u00e4tigungen", "type": "object", "properties": {"bestellnummer": {"type": "string", "description": "Interne Bestellnummer des K\u00e4ufers"}, "po_nummer": {"type": "string", "description": "Purchase Order Nummer des K\u00e4ufers (falls abweichend von bestellnummer)"}, "datum": {"type": "string", "format": "date", "description": "Bestelldatum im Format YYYY-MM-DD"}, "lieferant": {"type": "object", "description": "Informationen zum Lieferanten", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort", "land"]}, "steuernummer": {"type": "string"}, "ust_id": {"type": "string"}, "kontakt": {"type": "object", "properties": {"name": {"type": "string"}, "telefon": {"type": "string"}, "email": {"type": "string", "format": "email"}}}}, "required": ["name"]}, "besteller": {"type": "object", "description": "Informationen zum Besteller", "properties": {"name": {"type": "string"}, "abteilung": {"type": "string"}, "kostenstelle": {"type": "string"}, "kontakt": {"type": "object", "properties": {"telefon": {"type": "string"}, "email": {"type": "string", "format": "email"}}}}, "required": ["name"]}, "projektnummer": {"type": "string", "description": "Projektnummer falls zutreffend"}, "positionen": {"type": "array", "description": "Liste der bestellten Positionen", "items": {"type": "object", "properties": {"artikelnr": {"type": "string"}, "beschreibung": {"type": "string"}, "menge": {"type": "number", "minimum": 0}, "einzelpreis": {"type": "string", "pattern": "^\\d+\\.\\d{2}$", "description": "Einzelpreis als String mit 2 Dezimalstellen"}, "w\u00e4hrung": {"type": "string", "description": "W\u00e4hrung nach ISO 4217"}, "steuersatz": {"type": "string", "description": "Steuersatz in Prozent (z.B. ''19.00'')"}}, "required": ["artikelnr", "beschreibung", "menge", "einzelpreis"]}}, "liefertermin": {"type": "string", "format": "date", "description": "Geplantes Lieferdatum im Format YYYY-MM-DD"}, "lieferadresse": {"type": "object", "description": "Lieferadresse falls abweichend von Rechnungsadresse", "properties": {"name": {"type": "string"}, "strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort", "land"]}, "gesamtbetrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$", "description": "Gesamtbetrag der Bestellung als String mit 2 Dezimalstellen"}, "w\u00e4hrung": {"type": "string", "description": "W\u00e4hrung nach ISO 4217"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^\\d{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$", "nullable": true}, "mwst_satz": {"type": "string", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}}, "required": ["bestellnummer", "datum", "lieferant", "positionen", "gesamtbetrag", "_meta"]}',
    '"{\"bestellnummer\": \"Eindeutige Identifikationsnummer der Bestellung, oft alphanumerisch (z. B. ''B-2023-4711''). Wichtig f\u00fcr die sp\u00e4tere Zuordnung von Lieferungen und Rechnungen, aber nicht direkt steuerrelevant.\", \"po_nummer\": \"Englische Bezeichnung f\u00fcr Bestellnummer (''Purchase Order Number''), oft in internationalen Gesch\u00e4ften verwendet. Format wie bei ''bestellnummer''.\", \"datum\": \"Datum der Bestellung oder Auftragsbest\u00e4tigung im Format TT.MM.JJJJ (z. B. ''15.10.2023''). Relevant f\u00fcr die zeitliche Einordnung, aber nicht f\u00fcr die Steuererkl\u00e4rung.\", \"lieferant\": \"Name und Adresse des Verk\u00e4ufers/Lieferanten (z. B. ''Muster GmbH, Musterstra\u00dfe 1, 12345 Berlin''). Wichtig f\u00fcr die sp\u00e4tere Rechnungspr\u00fcfung, aber nicht steuerrelevant.\", \"besteller\": \"Name und ggf. Kontaktdaten des K\u00e4ufers (z. B. ''Max Mustermann, Privatadresse''). Kann bei privaten Bestellungen identisch mit der Lieferadresse sein.\", \"projektnummer\": \"Falls zutreffend: Projektnummer, auf die die Bestellung gebucht wird (z. B. ''P-2023-001''). Nur relevant, wenn die Bestellung im Rahmen eines steuerlich absetzbaren Projekts erfolgt (z. B. Homeoffice-Ausstattung).\", \"positionen\": \"Liste der bestellten Artikel mit Details: ''artikelnr'' (Artikelnummer, z. B. ''A12345''), ''beschreibung'' (Artikelbezeichnung, z. B. ''B\u00fcrostuhl Ergonomisch''), ''menge'' (Anzahl, z. B. 2), ''einzelpreis'' (Preis pro Einheit, z. B. 199.99). Wichtig f\u00fcr die sp\u00e4tere Rechnungspr\u00fcfung, aber nicht direkt steuerrelevant.\", \"liefertermin\": \"Geplantes Lieferdatum im Format TT.MM.JJJJ (z. B. ''30.10.2023''). Kann bei Verz\u00f6gerungen f\u00fcr Mahnungen relevant sein, aber nicht steuerrelevant.\", \"lieferadresse\": \"Adresse, an die die Ware geliefert werden soll (z. B. ''Max Mustermann, Musterweg 2, 12345 Berlin''). Kann von der Rechnungsadresse abweichen.\", \"gesamtbetrag\": \"Gesamtsumme der Bestellung inkl. MwSt. (z. B. 475.98). Wichtig f\u00fcr die sp\u00e4tere Rechnungspr\u00fcfung, aber nicht direkt steuerrelevant, da die Rechnung den offiziellen Zahlungsbeleg darstellt.\"}"',
    'Bestellung, Auftragsbestätigung, Purchase Order, PO, Bestellnummer, po_nummer, Liefertermin, Lieferadresse, Artikelnummer, Menge, Einzelpreis, Gesamtbetrag, Projektnummer, Besteller, Lieferant, Warenkorb, Versandkosten, Zahlungsbedingungen, order confirmation, delivery date, unit price, total amount, project number',
    'Lieferanten, Shops',
    NULL,
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
