INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'quote',
    'A. Finanzen & Rechnungen',
    'Angebot/Kostenvoranschlag',
    'Angebot oder Kostenvoranschlag. Enthält Positionen mit Preisen, Gültigkeitsdauer, Zahlungsbedingungen. Wird zum Vertrag bei Annahme. Nicht verwechseln mit purchase_order (Bestellung) oder invoice (Rechnung).',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "quote", "description": "Angebot/Kostenvoranschlag", "type": "object", "properties": {"angebotsnummer": {"type": "string"}, "datum": {"type": "string", "format": "date"}, "gueltig_bis": {"type": "string", "format": "date"}, "anbieter": {"type": "object", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort", "land"]}, "telefon": {"type": "string"}, "email": {"type": "string", "format": "email"}, "ust_id": {"type": "string"}}, "required": ["name"]}, "empfaenger": {"type": "object", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort", "land"]}, "kundennummer": {"type": "string"}}, "required": ["name"]}, "kundennummer": {"type": "string"}, "projektnummer": {"type": "string"}, "betreff_stichwort": {"type": "string"}, "positionen": {"type": "array", "items": {"type": "object", "properties": {"artikelnr": {"type": "string"}, "beschreibung": {"type": "string"}, "menge": {"type": "number"}, "einheit": {"type": "string"}, "einzelpreis": {"type": "string"}, "betrag": {"type": "string"}}, "required": ["beschreibung", "menge", "einzelpreis", "betrag"]}}, "netto": {"type": "string"}, "mwst": {"type": "string"}, "brutto": {"type": "string"}, "lieferzeit": {"type": "string"}, "zahlungsbedingungen": {"type": "string"}, "bindefrist": {"type": "string"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^[0-9]{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "nullable": true}, "mwst_satz": {"type": "string", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}}, "required": ["angebotsnummer", "datum", "anbieter", "empfaenger", "positionen", "netto", "brutto", "_meta"]}',
    '"{\"angebotsnummer\": \"Eindeutige Angebotsnummer\", \"datum\": \"YYYY-MM-DD\", \"gueltig_bis\": \"G\u00fcltigkeitsdatum\", \"anbieter\": \"Ersteller\", \"empfaenger\": \"Empf\u00e4nger\", \"betreff_stichwort\": \"Worum geht es\", \"positionen\": \"Array: {artikelnr, beschreibung, menge, einheit, einzelpreis, betrag}\", \"bindefrist\": \"Wie lange bindend\"}"',
    'Angebot,Kostenvoranschlag,Offerte,Quote,Angebotsnummer,gültig bis,Bindefrist,Lieferzeit,unverbindlich,freibleibend,Positionen',
    'Lieferanten, Handwerker, Dienstleister',
    'Angebot selbst nicht steuerrelevant. Bei Annahme und Rechnungsstellung gelten Steuerregeln der Rechnung.',
    0,
    1,
    1,
    'mistral_batch',
    'Verwechslungsgefahr: Angebot vs. Auftragsbestätigung (purchase_order) vs. Rechnung (invoice). Angebot hat immer ''gültig bis''.'
)
