INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'receipt',
    'A. Finanzen & Rechnungen',
    'Quittung',
    'Eine Quittung ist ein Beleg über den Erhalt einer Zahlung, typischerweise ausgestellt von Geschäften, Restaurants oder Dienstleistern nach Barzahlung oder Kartenzahlung. Im Gegensatz zu einer Rechnung enthält eine Quittung oft weniger Details, dient aber als Nachweis für getätigte Ausgaben, z. B. für Garantieansprüche oder steuerliche Zwecke. Sie unterscheidet sich von einem Kassenbon durch die explizite Bestätigung der Zahlungsannahme (z. B. mit Unterschrift oder Stempel).',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "Quittung", "description": "Schema für die Extraktion von Quittungsdaten", "type": "object", "properties": {"geschaeft": {"type": "object", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort"]}, "steuernummer": {"type": "string"}, "ust_id": {"type": "string"}, "telefon": {"type": "string"}, "email": {"type": "string", "format": "email"}}, "required": ["name"]}, "datum": {"type": "string", "format": "date"}, "positionen": {"type": "array", "items": {"type": "object", "properties": {"beschreibung": {"type": "string"}, "menge": {"type": "number"}, "einzelpreis": {"type": "string"}, "gesamtpreis": {"type": "string"}, "mwst_satz": {"type": "string"}, "mwst_betrag": {"type": "string"}, "einheit": {"type": "string", "description": "Einheit (z.B. Stk, kg, l)"}}, "required": ["beschreibung", "gesamtpreis"]}}, "gesamtbetrag": {"type": "string"}, "zahlungsmethode": {"type": "string", "enum": ["bar", "karte", "ueberweisung", "paypal", "sonstige"]}, "währung": {"type": "string", "default": "EUR"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^[0-9]{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "nullable": true}, "mwst_satz": {"type": "string", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}, "waehrung": {"type": "string", "default": "EUR", "description": "Waehrung ISO 4217 (EUR, USD, etc.)"}}, "required": ["geschaeft", "datum", "positionen", "gesamtbetrag", "zahlungsmethode", "_meta"]}',
    '"{\"geschaeft\": \"Name und ggf. Adresse des ausstellenden Gesch\u00e4fts oder Dienstleisters. Wichtig f\u00fcr die Zuordnung der Ausgabe (z. B. berufliche vs. private Nutzung) und f\u00fcr die Steuererkl\u00e4rung (z. B. bei Handwerkerleistungen oder haushaltsnahen Dienstleistungen). Beispiel: ''M\u00fcller Elektrohandwerk GmbH, Musterstra\u00dfe 1, 12345 Berlin''.\", \"datum\": \"Datum der Zahlung im Format TT.MM.JJJJ oder JJJJ-MM-TT. Relevant f\u00fcr die zeitliche Zuordnung der Ausgabe im Steuerjahr. Beispiel: ''15.03.2023''.\", \"positionen\": \"Liste der gekauften Artikel oder Dienstleistungen mit Einzelpreisen, Mengen und ggf. Steuers\u00e4tzen. Wichtig f\u00fcr die Aufschl\u00fcsselung der Ausgaben, z. B. bei gemischten beruflichen/privaten K\u00e4ufen oder f\u00fcr die Vorsteuerabzugsberechtigung (bei Rechnungen mit USt-ID). Beispiel: ''[{\\\"artikel\\\": \\\"B\u00fcromaterial\\\", \\\"menge\\\": 1, \\\"einzelpreis\\\": 12.99, \\\"steuersatz\\\": 19}, {\\\"artikel\\\": \\\"Druckerpapier\\\", \\\"menge\\\": 2, \\\"einzelpreis\\\": 5.50, \\\"steuersatz\\\": 19}]''.\", \"gesamtbetrag\": \"Endbetrag inkl. Steuern und ggf. Rabatten, meist in Euro (\u20ac). Wichtig f\u00fcr die steuerliche Erfassung des Gesamtaufwands. Beispiel: 23.99.\", \"zahlungsmethode\": \"Art der Zahlung, z. B. ''Bar'', ''EC-Karte'', ''Kreditkarte'', ''PayPal''. Relevant f\u00fcr die Nachweispflicht bei hohen Barzahlungen (\u00a710 GwG) oder f\u00fcr die Zuordnung zu bestimmten Steuerregelungen (z. B. \u00a735a EStG, wo nur unbare Zahlungen absetzbar sind). Beispiel: ''Bar''.\"}"',
    'Quittung, Beleg, Zahlungsbestätigung, erhalten, bar, Barzahlung, Kartenzahlung, EC, Kreditkarte, Unterschrift, Stempel, Betrag, Summe, Datum, Geschäft, Restaurant, Empfangsbestätigung, receipt, payment confirmation, cash, card payment, total amount, signature, stamp',
    'Geschäfte, Restaurants',
    '{"paragraphen": "§4 Abs. 4 EStG (Betriebsausgaben), §9 EStG (Werbungskosten), §33 EStG (außergewöhnliche Belastungen), §35a EStG (haushaltsnahe Dienstleistungen)", "anlage": "N (bei Werbungskosten), V (bei Vermietung), Kind (bei Kinderbetreuungskosten), Vorsorge (bei Handwerkerleistungen)", "hinweise": "Quittungen können als Nachweis für absetzbare Ausgaben dienen, z. B. für berufliche Aufwendungen (Werbungskosten), Handwerkerleistungen (§35a EStG, max. 6.000 €/Jahr) oder haushaltsnahe Dienstleistungen (max. 20.000 €/Jahr). Bei Barzahlungen über 10.000 € (ab 2024: 3.000 €) ist ein Nachweis der Herkunft der Mittel erforderlich (§10 GwG)."}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
ON CONFLICT (id) DO UPDATE SET category=EXCLUDED.category, display_name=EXCLUDED.display_name, description=EXCLUDED.description, schema=EXCLUDED.schema, field_descriptions=EXCLUDED.field_descriptions, classify_keywords=EXCLUDED.classify_keywords, typical_senders=EXCLUDED.typical_senders, steuer_relevanz=EXCLUDED.steuer_relevanz, priority=EXCLUDED.priority, enabled=EXCLUDED.enabled, version=EXCLUDED.version, source=EXCLUDED.source, notes=EXCLUDED.notes;

INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'savings_exemption',
    'A. Finanzen & Rechnungen',
    'Freistellungsauftrag',
    'Ein Freistellungsauftrag ist ein Dokument, mit dem Bankkunden ihren Sparer-Pauschbetrag (aktuell 1.000 € pro Person/Jahr) für Kapitalerträge wie Zinsen oder Dividenden bei ihrer Bank geltend machen. Es wird typischerweise bei Kontoeröffnung oder auf Anfrage von der Bank ausgestellt und gilt bis auf Widerruf oder bis zu einem festgelegten Datum. Im Gegensatz zu einer Steuerbescheinigung, die bereits erzielte Erträge dokumentiert, dient der Freistellungsauftrag der vorab festgelegten Steuerfreistellung zukünftiger Erträge.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "savings_exemption", "description": "Freistellungsauftrag f\u00fcr Kapitalertr\u00e4ge", "type": "object", "properties": {"kontoinhaber": {"type": "object", "properties": {"name": {"type": "string"}, "vorname": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "pattern": "^[A-Z]{2}$"}}, "required": ["strasse", "plz", "ort", "land"]}}, "required": ["name", "vorname", "adresse"]}, "steuer_id": {"type": "string", "description": "Steueridentifikationsnummer des Kontoinhabers"}, "bank": {"type": "object", "properties": {"name": {"type": "string"}, "bic": {"type": "string"}, "iban": {"type": "string", "pattern": "^[A-Z]{2}\\d{2}[A-Z0-9]{11,30}$"}}, "required": ["name", "bic", "iban"]}, "gueltig_ab": {"type": "string", "format": "date", "description": "G\u00fcltigkeitsbeginn im Format YYYY-MM-DD"}, "gueltig_bis": {"type": "string", "format": "date", "description": "G\u00fcltigkeitsende im Format YYYY-MM-DD"}, "freistellungsbetrag": {"type": "string", "pattern": "^\\d{1,10}\\.\\d{2}$", "description": "Freistellungsbetrag in Euro mit 2 Dezimalstellen"}, "einzeln_oder_gemeinsam": {"type": "string", "enum": ["einzeln", "gemeinsam"]}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean", "const": true}, "steuerrelevanz_hinweis": {"type": "string", "const": "Freistellungsauftrag f\u00fcr Kapitalertr\u00e4ge"}, "steuer_kategorie": {"type": "string", "const": "kapitalertraege"}, "steuerjahr": {"type": "string", "pattern": "^\\d{4}$", "description": "Jahr, f\u00fcr das der Freistellungsauftrag gilt"}, "mwst_ausgewiesen": {"type": "boolean", "const": false}, "mwst_betrag": {"type": "null"}, "mwst_satz": {"type": "null"}, "aktenzeichen": {"type": "null"}, "dokumenten_id": {"type": "string"}}, "required": ["steuerrelevant", "steuerrelevanz_hinweis", "steuer_kategorie", "mwst_ausgewiesen"]}, "freistellungen": {"type": "array", "description": "Einzelne Freistellungsauftr\u00e4ge bei verschiedenen Instituten", "items": {"type": "object", "properties": {"institut": {"type": "string"}, "betrag": {"type": "string"}, "gueltig_ab": {"type": "string"}}}}}, "required": ["kontoinhaber", "steuer_id", "bank", "gueltig_ab", "freistellungsbetrag", "einzeln_oder_gemeinsam", "_meta"]}',
    '"kontoinhaber, steuer_id, bank, gueltig_ab, gueltig_bis, freistellungsbetrag, einzeln_oder_gemeinsam"',
    'Freistellungsauftrag, Sparer-Pauschbetrag, Kapitalerträge, Steuerfreistellung, Freistellungsvolumen, Freistellungsbetrag, Zinserträge, Dividenden, Nichtveranlagungsbescheinigung, NV-Bescheinigung, Steuer-ID, Kontoinhaber, gemeinsam, einzeln, gültig ab, gültig bis, Bank, Sparkasse, Volksbank, Raiffeisenbank, comdirect, ING, DKB, Sparerfreibetrag, §44a EStG, §20 EStG, exemption order, tax exemption, capital gains',
    'Banken',
    '{"paragraphen": "§20 Abs. 9 EStG (Sparer-Pauschbetrag), §44a EStG (Freistellungsauftrag)", "anlage": "KAP (Zeile 15-17 für Freistellungsauftrag, Zeile 7-14 für Kapitalerträge)", "betraege": "Aktuell 1.000 € pro Person/Jahr (Stand 2024). Bei Ehegatten/Lebenspartnern: 2.000 €, wenn gemeinsam veranlagt. Der Freistellungsbetrag kann auf mehrere Banken aufgeteilt werden, die Summe darf den Pauschbetrag jedoch nicht überschreiten."}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
ON CONFLICT (id) DO UPDATE SET category=EXCLUDED.category, display_name=EXCLUDED.display_name, description=EXCLUDED.description, schema=EXCLUDED.schema, field_descriptions=EXCLUDED.field_descriptions, classify_keywords=EXCLUDED.classify_keywords, typical_senders=EXCLUDED.typical_senders, steuer_relevanz=EXCLUDED.steuer_relevanz, priority=EXCLUDED.priority, enabled=EXCLUDED.enabled, version=EXCLUDED.version, source=EXCLUDED.source, notes=EXCLUDED.notes;

INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'securities_statement',
    'A. Finanzen & Rechnungen',
    'Depotauszug/Wertpapierabrechnung',
    'Ein Depotauszug oder eine Wertpapierabrechnung dokumentiert den Bestand und die Wertentwicklung von Wertpapieren in einem Depot zu einem bestimmten Stichtag. Er wird typischerweise quartalsweise oder jährlich von Banken oder Brokern versendet und enthält detaillierte Informationen zu einzelnen Positionen wie Aktien, Anleihen oder Fonds. Im Gegensatz zu Kauf-/Verkaufsabrechnungen zeigt er den Gesamtbestand und nicht einzelne Transaktionen.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "securities_statement", "description": "Depotauszug/Wertpapierabrechnung", "type": "object", "properties": {"depotinhaber": {"type": "string", "description": "Name des Depotinhabers"}, "depotnummer": {"type": "string", "description": "Depotnummer"}, "bank": {"type": "string", "description": "Name der Bank"}, "stichtag": {"type": "string", "format": "date", "description": "Stichtag im Format YYYY-MM-DD"}, "positionen": {"type": "array", "items": {"type": "object", "properties": {"wkn_isin": {"type": "string", "description": "WKN oder ISIN der Wertpapierposition"}, "bezeichnung": {"type": "string", "description": "Bezeichnung der Wertpapierposition"}, "stueck": {"type": "number", "description": "Anzahl der St\u00fccke"}, "kurs": {"type": "string", "description": "Kurswert pro St\u00fcck (mit 2 Dezimalstellen)"}, "kurswert": {"type": "string", "description": "Gesamtkurswert der Position (mit 2 Dezimalstellen)"}}, "required": ["wkn_isin", "bezeichnung", "stueck", "kurs", "kurswert"]}}, "depotwert_gesamt": {"type": "string", "description": "Gesamtwert des Depots (mit 2 Dezimalstellen)"}, "veraenderung_zeitraum": {"type": "string", "description": "Ver\u00e4nderung des Depotwerts im Zeitraum (mit 2 Dezimalstellen)"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^[0-9]{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "nullable": true}, "mwst_satz": {"type": "string", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}}, "required": ["depotinhaber", "depotnummer", "bank", "stichtag", "positionen", "depotwert_gesamt"]}',
    '"depotinhaber, depotnummer, bank, stichtag, positionen[] (wkn_isin, bezeichnung, stueck, kurs, kurswert), depotwert_gesamt, veraenderung_zeitraum"',
    'Depotauszug, Wertpapierabrechnung, Depotbestand, Stichtag, WKN, ISIN, Stück, Kurs, Kurswert, Depotwert, Gesamtwert, Veränderung, Performance, Bank, Broker, Wertpapier, Aktien, Fonds, Anleihen, securities statement, portfolio statement, holdings, valuation date, market value',
    'Banken, Broker',
    '{"paragraphen": "§20 EStG (Kapitalerträge), §43 EStG (Kapitalertragsteuer), §43a EStG (Steuersatz)", "anlage": "KAP (Einkünfte aus Kapitalvermögen), Anlage SO (Sonstige Angaben)"}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
