INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'securities_transaction',
    'A. Finanzen & Rechnungen',
    'Wertpapierkauf/-verkauf',
    'Dieses Dokument ist eine Abrechnung über den Kauf oder Verkauf von Wertpapieren (Aktien, Anleihen, Fonds etc.), die von Banken oder Brokern an den Depotinhaber gesendet wird. Es enthält detaillierte Informationen zur Transaktion wie Stückzahl, Kurs, Gebühren und Ausführungsdatum. Im Gegensatz zu Dividendenabrechnungen oder Depotauszügen liegt der Fokus hier auf der einzelnen Kauf- oder Verkaufstransaktion mit allen abrechnungsrelevanten Daten.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "securities_transaction", "description": "Wertpapierkauf/-verkauf", "type": "object", "properties": {"depotinhaber": {"type": "string"}, "depotnummer": {"type": "string"}, "transaktion": {"type": "string", "enum": ["kauf", "verkauf"]}, "wkn_isin": {"type": "string"}, "bezeichnung": {"type": "string"}, "stueck": {"type": "string"}, "kurs": {"type": "string"}, "kurswert": {"type": "string"}, "provision": {"type": "string"}, "boersenplatz": {"type": "string"}, "ausfuehrungsdatum": {"type": "string", "format": "date"}, "abrechnungsbetrag": {"type": "string"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["kapitalertraege", null], "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^[0-9]{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "nullable": true}, "mwst_satz": {"type": "string", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"], "additionalProperties": false}, "positionen": {"type": "array", "description": "Einzelne Wertpapiertransaktionen (K\u00e4ufe, Verk\u00e4ufe, Dividenden)", "items": {"type": "object", "properties": {"wertpapier": {"type": "string"}, "isin": {"type": "string"}, "stueck": {"type": "string"}, "kurs": {"type": "string"}, "betrag": {"type": "string"}}}}}, "required": ["depotinhaber", "depotnummer", "transaktion", "wkn_isin", "bezeichnung", "stueck", "kurs", "kurswert", "ausfuehrungsdatum", "abrechnungsbetrag"], "additionalProperties": false}',
    '"depotinhaber, depotnummer, transaktion (kauf/verkauf), wkn_isin, bezeichnung, stueck, kurs, kurswert, provision, boersenplatz, ausfuehrungsdatum, abrechnungsbetrag"',
    'Wertpapierabrechnung, Kaufabrechnung, Verkaufsabrechnung, Transaktionsbestätigung, Orderausführung, WKN, ISIN, Stück, Kurs, Provision, Börsenplatz, Ausführungsdatum, Abrechnungsbetrag, Broker, Depotnummer, securities transaction, trade confirmation, buy order, sell order, commission, execution date, settlement amount',
    'Banken, Broker',
    '{"paragraphen": "§20 EStG (Kapitalerträge), §23 EStG (private Veräußerungsgeschäfte)", "anlage": "SO (Sonstige Angaben, für Verlustverrechnung), KAP (Kapitalerträge)"}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
