INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'supplier_invoice',
    'A. Finanzen & Rechnungen',
    'Lieferantenrechnung',
    'Eine Lieferantenrechnung ist eine Rechnung, die von einem Lieferanten oder Großhändler an einen Kunden für gelieferte Waren oder erbrachte Dienstleistungen ausgestellt wird. Sie enthält detaillierte Positionen, Preise, Steuern und Zahlungsmodalitäten. Im Gegensatz zu einer Quittung oder einem Kassenbon dokumentiert sie eine offene Forderung und dient als Grundlage für die Buchhaltung und ggf. Vorsteuerabzug.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "supplier_invoice", "description": "Lieferantenrechnung", "type": "object", "properties": {"rechnungsnummer": {"type": "string"}, "lieferant": {"type": "object", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort", "land"]}, "steuernummer": {"type": "string"}, "ust_id": {"type": "string"}, "telefon": {"type": "string"}, "email": {"type": "string", "format": "email"}}, "required": ["name"]}, "kundennummer": {"type": "string"}, "bestellnummer": {"type": "string"}, "po_nummer": {"type": "string"}, "projektnummer": {"type": "string"}, "kundenauftrag": {"type": "string"}, "lieferscheinnummer": {"type": "string"}, "rechnungsdatum": {"type": "string", "format": "date"}, "lieferdatum": {"type": "string", "format": "date"}, "fälligkeitsdatum": {"type": "string", "format": "date"}, "positionen": {"type": "array", "items": {"type": "object", "properties": {"artikelnr": {"type": "string"}, "beschreibung": {"type": "string"}, "menge": {"type": "number"}, "einheit": {"type": "string"}, "einzelpreis": {"type": "string"}, "betrag": {"type": "string"}}, "required": ["beschreibung", "menge", "betrag"]}}, "netto": {"type": "string"}, "mwst": {"type": "string"}, "brutto": {"type": "string"}, "zahlungsbedingungen": {"type": "string"}, "skonto_frist": {"type": "string", "format": "date"}, "skonto_prozent": {"type": "string"}, "iban": {"type": "string"}, "lohnanteil_netto": {"type": "string"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string"}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null]}, "steuerjahr": {"type": "string"}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string"}, "mwst_satz": {"type": "string"}, "aktenzeichen": {"type": "string"}, "dokumenten_id": {"type": "string"}}, "required": ["steuerrelevant"]}, "waehrung": {"type": "string", "default": "EUR", "description": "Waehrung ISO 4217 (EUR, USD, etc.)"}}, "required": ["rechnungsnummer", "lieferant", "netto", "brutto", "_meta"]}',
    '"rechnungsnummer, lieferant, kundennummer, bestellnummer, po_nummer, projektnummer, kundenauftrag, lieferscheinnummer, positionen[] (artikelnr, beschreibung, menge, einheit, einzelpreis, betrag), netto, mwst, brutto, zahlungsbedingungen, skonto_frist, skonto_prozent, iban, lohnanteil_netto (wenn Dienstleistung enthalten)"',
    'Rechnung, Rechnungsnummer, Lieferant, Kundennummer, Bestellnummer, PO-Nummer, Lieferscheinnummer, Artikelnummer, Menge, Einzelpreis, Nettobetrag, Mehrwertsteuer, MwSt, Bruttobetrag, Zahlungsbedingungen, Skonto, IBAN, Fälligkeitsdatum, Rechnungsdatum, Lieferdatum, Position, USt, VAT, invoice, supplier, order number, delivery note, payment terms, due date',
    'Lieferanten, Großhändler',
    '{"vorsteuerabzug": "§15 UStG (Vorsteuerabzug), sofern Rechnung alle Pflichtangaben nach §14 UStG enthält. Relevant für Anlage EÜR (Einnahmen-Überschuss-Rechnung) oder Anlage G (Gewerbebetrieb) bzw. S (selbstständige Arbeit).", "abzugsfähige_betriebsausgaben": "§4 Abs. 4 EStG (Betriebsausgaben), sofern die Rechnung betrieblich veranlasst ist. Nettobetrag + ggf. Lohnanteil (bei gemischten Leistungen) sind abzugsfähig.", "lohnanteil": "Falls die Rechnung Dienstleistungen mit Lohnanteil enthält (z.B. Handwerkerrechnungen), kann der Lohnanteil unter §35a EStG (haushaltsnahe Dienstleistungen) absetzbar sein (bis zu 20% der Aufwendungen, max. 4.000 € pro Jahr)."}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
