INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'tax_cert_bank',
    'A. Finanzen & Rechnungen',
    'Jahressteuerbescheinigung Bank',
    'Die Jahressteuerbescheinigung einer Bank dokumentiert die im Steuerjahr erzielten Kapitalerträge sowie die darauf entrichteten Steuern (Kapitalertragsteuer, Solidaritätszuschlag, Kirchensteuer). Sie wird von Banken an Kontoinhaber ausgestellt und dient als Nachweis für die Steuererklärung, insbesondere zur Anrechnung bereits gezahlter Steuern oder zur Verlustverrechnung. Im Gegensatz zu Dividendenabrechnungen oder Zinsbescheinigungen fasst sie alle Kapitalerträge eines Kontos/Depots für das gesamte Jahr zusammen.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "tax_cert_bank", "description": "Jahressteuerbescheinigung Bank", "type": "object", "properties": {"kontoinhaber": {"type": "object", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort", "land"]}}, "required": ["name", "adresse"]}, "steuer_id": {"type": "string"}, "bank": {"type": "object", "properties": {"name": {"type": "string"}, "bic": {"type": "string"}, "iban": {"type": "string"}}, "required": ["name"]}, "steuerjahr": {"type": "string"}, "kapitalertraege": {"type": "string"}, "verlustverrechnung": {"type": "string"}, "kapitalertragsteuer": {"type": "string"}, "soli": {"type": "string"}, "kirchensteuer": {"type": "string"}, "freistellungsauftrag_genutzt": {"type": "boolean"}, "anrechenbare_quellensteuer": {"type": "string"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null]}, "steuerjahr": {"type": "string", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "nullable": true}, "mwst_satz": {"type": "string", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant", "steuer_kategorie", "mwst_ausgewiesen"]}, "positionen": {"type": "array", "description": "Einzelpositionen der Steuerbescheinigung (Kapitalertr\u00e4ge, KESt, Soli, Verlustverrechnungst\u00f6pfe, etc.)", "items": {"type": "object", "properties": {"bezeichnung": {"type": "string"}, "betrag": {"type": "string"}, "zeile_anlage_kap": {"type": "string"}}}}}, "required": ["kontoinhaber", "steuer_id", "bank", "steuerjahr", "kapitalertraege", "kapitalertragsteuer", "_meta"]}',
    '"kontoinhaber, steuer_id, bank, steuerjahr, kapitalertraege, verlustverrechnung, kapitalertragsteuer, soli, kirchensteuer, freistellungsauftrag_genutzt, anrechenbare_quellensteuer"',
    'Jahressteuerbescheinigung, Kapitalerträge, Kapitalertragsteuer, Soli, Solidaritätszuschlag, Kirchensteuer, Freistellungsauftrag, Verlustverrechnung, Quellensteuer, Steuer-ID, Steuerbescheinigung, Bank, Depot, Erträgnisaufstellung, §20 EStG, §43 EStG, tax certificate, investment income, withholding tax, church tax, loss offset, exemption order',
    'Banken',
    '{"paragraphen": "§20 EStG (Kapitalerträge), §32d EStG (Abgeltungsteuer), §43 EStG (Kapitalertragsteuer), §43a EStG (Steuersatz), §44a EStG (Freistellungsauftrag), §51a EStG (Kirchensteuer)", "anlage": "Anlage KAP (Zeilen 7-15 für Kapitalerträge, Zeilen 24-33 für anrechenbare Steuern), ggf. Anlage SO (Verlustverrechnung)", "absetzbar": {"kapitalertragsteuer": "Anrechnung auf Einkommensteuer (Anlage KAP, Zeile 24)", "soli": "Anrechnung (Anlage KAP, Zeile 25)", "kirchensteuer": "Anrechnung (Anlage KAP, Zeile 26)", "anrechenbare_quellensteuer": "Anrechnung (Anlage KAP, Zeile 31-33)"}}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
