INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'telecom_bill',
    'A. Finanzen & Rechnungen',
    'Telefonrechnung',
    'Eine Telefonrechnung ist die monatliche oder quartalsweise Abrechnung eines Telekommunikationsanbieters für Mobilfunk- oder Festnetzdienste. Sie enthält detaillierte Kostenaufstellungen für Grundgebühren, Gespräche, SMS, Datenvolumen sowie zusätzliche Gebühren wie Roaming oder Drittanbieterleistungen. Im Gegensatz zu Internet- oder TV-Rechnungen liegt der Fokus auf Sprach- und Datendiensten sowie mobilen Kommunikationskosten.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "Telecom Bill", "description": "Schema für die Extraktion von Telefonrechnungen", "type": "object", "properties": {"anbieter": {"type": "string", "description": "Name des Telekommunikationsanbieters"}, "kundennummer": {"type": "string", "description": "Kundennummer beim Anbieter"}, "rufnummer": {"type": "string", "description": "Telefonnummer im E.164-Format", "pattern": "^\\+[0-9]{11,15}$"}, "abrechnungszeitraum": {"type": "object", "properties": {"von": {"type": "string", "format": "date", "description": "Startdatum des Abrechnungszeitraums (YYYY-MM-DD)"}, "bis": {"type": "string", "format": "date", "description": "Enddatum des Abrechnungszeitraums (YYYY-MM-DD)"}}, "required": ["von", "bis"]}, "grundgebuehr": {"type": "string", "description": "Grundgebühr als Betrag mit 2 Dezimalstellen", "pattern": "^[0-9]+\\.[0-9]{2}$"}, "verbindungskosten": {"type": "string", "description": "Kosten für Verbindungen als Betrag mit 2 Dezimalstellen", "pattern": "^[0-9]+\\.[0-9]{2}$"}, "sms_kosten": {"type": "string", "description": "Kosten für SMS als Betrag mit 2 Dezimalstellen", "pattern": "^[0-9]+\\.[0-9]{2}$"}, "datenvolumen": {"type": "object", "properties": {"inklusive": {"type": "string", "description": "Im Tarif inkludiertes Datenvolumen (z.B. ''10 GB'')"}, "verbraucht": {"type": "string", "description": "Tatsächlich verbrauchtes Datenvolumen (z.B. ''8.5 GB'')"}, "kosten": {"type": "string", "description": "Kosten für zusätzliches Datenvolumen als Betrag mit 2 Dezimalstellen", "pattern": "^[0-9]+\\.[0-9]{2}$"}}}, "roaming": {"type": "object", "properties": {"kosten": {"type": "string", "description": "Kosten für Roaming als Betrag mit 2 Dezimalstellen", "pattern": "^[0-9]+\\.[0-9]{2}$"}, "laender": {"type": "array", "items": {"type": "string", "description": "Ländercode (ISO 3166-1 alpha-2) der Roaming-Nutzung"}}}}, "drittanbieter": {"type": "array", "items": {"type": "object", "properties": {"anbieter": {"type": "string", "description": "Name des Drittanbieters"}, "dienst": {"type": "string", "description": "Beschreibung des Dienstes"}, "kosten": {"type": "string", "description": "Kosten als Betrag mit 2 Dezimalstellen", "pattern": "^[0-9]+\\.[0-9]{2}$"}}, "required": ["anbieter", "kosten"]}}, "gesamtbetrag": {"type": "string", "description": "Gesamtbetrag der Rechnung als Betrag mit 2 Dezimalstellen", "pattern": "^[0-9]+\\.[0-9]{2}$"}, "waehrung": {"type": "string", "description": "Währungscode (ISO 4217)", "default": "EUR"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean", "default": true}, "steuerrelevanz_hinweis": {"type": "string", "default": "Telefonkosten können als Werbungskosten oder Betriebsausgaben abgesetzt werden."}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "default": "werbungskosten"}, "steuerjahr": {"type": "string", "pattern": "^[0-9]{4}$", "description": "Steuerjahr der Rechnung (YYYY)"}, "mwst_ausgewiesen": {"type": "boolean", "default": true}, "mwst_betrag": {"type": "string", "description": "Ausgewiesener Mehrwertsteuerbetrag als Betrag mit 2 Dezimalstellen", "pattern": "^[0-9]+\\.[0-9]{2}$"}, "mwst_satz": {"type": "string", "description": "Mehrwertsteuersatz (z.B. ''19.00'')", "pattern": "^[0-9]+\\.[0-9]{2}$"}, "aktenzeichen": {"type": "string", "description": "Aktenzeichen für steuerliche Zwecke"}, "dokumenten_id": {"type": "string", "description": "Eindeutige ID des Dokuments"}}, "required": ["steuerrelevant"]}, "positionen": {"type": "array", "description": "Einzelpositionen der Rechnung (Grundgebühr, Verbindungskosten, Optionen, etc.)", "items": {"type": "object", "properties": {"beschreibung": {"type": "string"}, "menge": {"type": "string"}, "einzelpreis": {"type": "string"}, "betrag": {"type": "string"}, "einheit": {"type": "string", "description": "Einheit (z.B. Stk, Min, GB)"}}}}, "datenvolumen_einheit": {"type": "string", "description": "Einheit des Datenvolumens (z.B. GB, MB)"}}, "required": ["anbieter", "rufnummer", "abrechnungszeitraum", "gesamtbetrag", "_meta"]}',
    '"anbieter, kundennummer, rufnummer, abrechnungszeitraum, grundgebuehr, verbindungskosten, sms_kosten, datenvolumen, roaming, drittanbieter, gesamtbetrag"',
    'Telefonrechnung, Mobilfunkrechnung, Festnetzrechnung, Grundgebühr, Verbindungskosten, SMS-Kosten, Datenvolumen, Roaming, Drittanbieter, Gesamtbetrag, Abrechnungszeitraum, Rufnummer, Kundennummer, Telekom, Vodafone, O2, 1&1, call charges, data usage, monthly bill, mobile services, telecommunication invoice',
    'Telekom, Vodafone, O2, 1&1',
    '{"privat": {"beschreibung": "Teilweise absetzbar als Werbungskosten (§9 EStG) oder außergewöhnliche Belastungen (§33 EStG), wenn berufliche Nutzung nachgewiesen wird. Private Nutzung ist nicht absetzbar.", "voraussetzungen": "Nachweis der beruflichen Nutzung (z. B. durch Einzelverbindungsnachweis oder Arbeitsvertrag).", "anlage": "Anlage N (Zeile 46: Werbungskosten) oder Anlage Vorsorgeaufwand (falls berufliche Nutzung).", "grenzen": "Pauschale von 1.000 € für Werbungskosten (Arbeitnehmer-Pauschbetrag) oder tatsächliche Kosten bei Nachweis. Bei außergewöhnlichen Belastungen: zumutbare Belastung nach §33 EStG."}, "selbststaendig": {"beschreibung": "Voll absetzbar als Betriebsausgabe (§4 Abs. 4 EStG), wenn berufliche Nutzung nachgewiesen wird. Private Nutzung muss herausgerechnet werden (z. B. 30% privat, 70% beruflich).", "voraussetzungen": "Nachweis der beruflichen Nutzung (z. B. durch Einzelverbindungsnachweis oder betriebliche Nutzungserklärung).", "anlage": "Anlage EÜR (Einnahmen-Überschuss-Rechnung) oder Anlage G/S (Gewerbebetrieb/Selbstständige)."}}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
