INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'tv_radio_bill',
    'A. Finanzen & Rechnungen',
    'Rundfunk/Kabel/Streaming',
    'Dieses Dokument ist eine Rechnung oder Beitragsbescheinigung für Rundfunkgebühren (ARD/ZDF), Kabelanschluss oder Streaming-Dienste. Es wird typischerweise monatlich oder jährlich versendet und enthält die Zahlungsinformationen für Mediennutzungsentgelte. Im Gegensatz zu anderen Rechnungen (z. B. für Internet oder Telefon) bezieht es sich spezifisch auf öffentlich-rechtliche oder private Medienabos und ist oft durch eine Beitragsnummer oder Kundennummer gekennzeichnet.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "TV_Radio_Bill", "description": "Schema für Rundfunk-, Kabel- und Streaming-Rechnungen", "type": "object", "properties": {"anbieter": {"type": "string", "description": "Name des Anbieters (z.B. ARD ZDF Deutschlandradio Beitragsservice)"}, "beitragsnummer": {"type": "string", "description": "Individuelle Beitragsnummer des Kunden"}, "zeitraum": {"type": "object", "description": "Zeitraum, für den der Beitrag erhoben wird", "properties": {"von": {"type": "string", "format": "date", "description": "Startdatum des Beitragszeitraums (YYYY-MM-DD)"}, "bis": {"type": "string", "format": "date", "description": "Enddatum des Beitragszeitraums (YYYY-MM-DD)"}}, "required": ["von", "bis"]}, "betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$", "description": "Beitragsbetrag in Euro (z.B. 17.50)"}, "zahlungsweise": {"type": "string", "enum": ["einmalig", "monatlich", "vierteljährlich", "halbjährlich", "jährlich"], "description": "Häufigkeit der Zahlung"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean", "description": "Gibt an, ob das Dokument steuerrelevant ist"}, "steuerrelevanz_hinweis": {"type": "string", "description": "Hinweis zur Steuerrelevanz", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "description": "Kategorie der Steuerrelevanz", "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^\\d{4}$", "description": "Steuerjahr, für das das Dokument relevant ist (YYYY)", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean", "description": "Gibt an, ob Mehrwertsteuer ausgewiesen ist"}, "mwst_betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$", "description": "Mehrwertsteuerbetrag in Euro (z.B. 1.50)", "nullable": true}, "mwst_satz": {"type": "string", "pattern": "^\\d+(\\.\\d{1,2})?$", "description": "Mehrwertsteuersatz in Prozent (z.B. 7.0 oder 19.0)", "nullable": true}, "aktenzeichen": {"type": "string", "description": "Aktenzeichen für steuerliche Zwecke", "nullable": true}, "dokumenten_id": {"type": "string", "description": "Eindeutige Dokumenten-ID", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}, "positionen": {"type": "array", "description": "Einzelpositionen der TV/Radio-Rechnung (Pakete, Zusatzoptionen, Hardware, etc.)", "items": {"type": "object", "properties": {"beschreibung": {"type": "string"}, "menge": {"type": "string"}, "einzelpreis": {"type": "string"}, "betrag": {"type": "string"}}}}, "waehrung": {"type": "string", "default": "EUR", "description": "Waehrung ISO 4217 (EUR, USD, etc.)"}}, "required": ["anbieter", "beitragsnummer", "zeitraum", "betrag", "zahlungsweise"]}',
    '"{\"anbieter\": \"Name des Anbieters, z. B. ''ARD ZDF Deutschlandradio Beitragsservice'', ''Sky Deutschland'', ''Netflix''. Wichtig f\u00fcr die Zuordnung der Rechnung und ggf. steuerliche Abgrenzung (beruflich/privat).\", \"beitragsnummer\": \"Eindeutige Identifikationsnummer des Beitragskontos, z. B. ''DE123456789''. Wird f\u00fcr R\u00fcckfragen oder Zahlungszuordnung ben\u00f6tigt. Bei ARD/ZDF oft als ''Beitragsnummer'' oder ''Kundennummer'' bezeichnet.\", \"zeitraum\": \"Zeitraum, f\u00fcr den die Geb\u00fchren erhoben werden, z. B. ''01.01.2023 - 31.12.2023'' oder ''Januar 2024''. Wichtig f\u00fcr die zeitliche Zuordnung der Zahlung, besonders bei steuerlicher Geltendmachung.\", \"betrag\": \"H\u00f6he des zu zahlenden Betrags, z. B. ''18,36 \u20ac'' (monatlich) oder ''220,32 \u20ac'' (j\u00e4hrlich). Bei beruflicher Nutzung relevant f\u00fcr die Berechnung des absetzbaren Anteils (\u00a735a EStG).\"}"',
    'Rundfunkbeitrag, Rundfunkgebühren, ARD ZDF, Beitragsservice, Kabelanschluss, Streaming-Abo, Netflix, Sky, Beitragsnummer, Rechnung, Zahlungsaufforderung, Medienentgelt, GEZ, monatlicher Beitrag, Jahresrechnung, Kundennummer, Vertragsnummer, Zahlungsweise, Lastschrift, Überweisung, Beitragskonto',
    'ARD/ZDF, Sky, Netflix, etc.',
    '{"allgemein": "Grundsätzlich nicht steuerlich absetzbar, da private Lebenshaltungskosten (§12 EStG).", "ausnahme": {"beschreibung": "Nur in Ausnahmefällen als haushaltsnahe Dienstleistung (§35a EStG) absetzbar, wenn der Kabelanschluss oder Streaming-Dienst beruflich genutzt wird (z. B. bei Heimarbeit oder freiberuflicher Tätigkeit).", "voraussetzung": "Nachweis der beruflichen Nutzung (z. B. durch Arbeitsvertrag oder Bescheinigung des Arbeitgebers).", "anlage": "Anlage N (bei beruflicher Nutzung), sonst keine Relevanz.", "betrag": "Maximal 20% der Kosten, höchstens 4.000 € pro Jahr (§35a Abs. 2 EStG)."}}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
ON CONFLICT (id) DO UPDATE SET category=EXCLUDED.category, display_name=EXCLUDED.display_name, description=EXCLUDED.description, schema=EXCLUDED.schema, field_descriptions=EXCLUDED.field_descriptions, classify_keywords=EXCLUDED.classify_keywords, typical_senders=EXCLUDED.typical_senders, steuer_relevanz=EXCLUDED.steuer_relevanz, priority=EXCLUDED.priority, enabled=EXCLUDED.enabled, version=EXCLUDED.version, source=EXCLUDED.source, notes=EXCLUDED.notes;

INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'waste_bill',
    'A. Finanzen & Rechnungen',
    'Müllgebühren',
    'Die Müllgebührenabrechnung ist eine jährliche oder quartalsweise Rechnung der kommunalen Entsorgungsbetriebe oder Stadtwerke für die Entsorgung von Hausmüll, Bioabfall, Papier und anderen Abfallfraktionen. Sie unterscheidet sich von anderen Gebührenbescheiden durch die spezifische Aufschlüsselung nach Tonnengrößen, Leerungsintervallen und getrennten Grund- und Leistungsgebühren. Typisch sind Angaben zum Grundstück und Abrechnungszeitraum.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "waste_bill", "description": "Müllgebührenabrechnung", "type": "object", "properties": {"grundstueck": {"type": "object", "properties": {"strasse": {"type": "string"}, "hausnummer": {"type": "string"}, "plz": {"type": "string", "pattern": "^[0-9]{5}$"}, "ort": {"type": "string"}, "grundstuecksnummer": {"type": "string"}}, "required": ["strasse", "hausnummer", "plz", "ort"]}, "zeitraum": {"type": "object", "properties": {"von": {"type": "string", "format": "date"}, "bis": {"type": "string", "format": "date"}}, "required": ["von", "bis"]}, "tonnengroesse": {"type": "array", "items": {"type": "object", "properties": {"art": {"type": "string", "enum": ["restmuell", "bio", "papier", "gelber_sack", "glas"]}, "groesse_liter": {"type": "integer"}, "einheit": {"type": "string", "description": "Einheit der Tonnengroesse (z.B. Liter)"}}, "required": ["art", "groesse_liter"]}}, "leerungen": {"type": "array", "items": {"type": "object", "properties": {"tonnenart": {"type": "string", "enum": ["restmuell", "bio", "papier", "gelber_sack", "glas"]}, "datum": {"type": "string", "format": "date"}, "anzahl": {"type": "integer"}}, "required": ["tonnenart", "datum", "anzahl"]}}, "grundgebuehr": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$"}, "leistungsgebuehr": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$"}, "gesamtbetrag": {"type": "object", "properties": {"betrag": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$"}, "waehrung": {"type": "string", "pattern": "^[A-Z]{3}$"}}, "required": ["betrag", "waehrung"]}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "enum": [null], "default": null}, "steuer_kategorie": {"type": "string", "enum": [null], "default": null}, "steuerjahr": {"type": "string", "pattern": "^[0-9]{4}$", "enum": [null]}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$", "enum": [null]}, "mwst_satz": {"type": "string", "enum": [null]}, "aktenzeichen": {"type": "string", "enum": [null]}, "dokumenten_id": {"type": "string"}}, "required": ["steuerrelevant", "mwst_ausgewiesen", "dokumenten_id"]}, "positionen": {"type": "array", "description": "Einzelpositionen der Abfallgebührenrechnung (Restmüll, Biomüll, Papier, Sperrmüll, etc.)", "items": {"type": "object", "properties": {"beschreibung": {"type": "string"}, "menge": {"type": "string"}, "einzelpreis": {"type": "string"}, "betrag": {"type": "string"}, "einheit": {"type": "string", "description": "Einheit (z.B. Liter, Stk, Leerung)"}}}}, "objekt_adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "default": "DE"}}, "description": "Grundstueck/Liegenschaft der Muellgebuehren"}, "waehrung": {"type": "string", "default": "EUR", "description": "Waehrung ISO 4217 (EUR, USD, etc.)"}}, "required": ["grundstueck", "zeitraum", "tonnengroesse", "leerungen", "grundgebuehr", "leistungsgebuehr", "gesamtbetrag", "_meta"]}',
    '"{\"grundstueck\": \"Angabe des Grundst\u00fccks, f\u00fcr das die M\u00fcllgeb\u00fchren abgerechnet werden. Typischerweise eine Grundst\u00fccksnummer, Adresse oder Kundennummer. Format: alphanumerisch, z. B. ''Grundst\u00fcck Nr. 12345'' oder ''Kunden-Nr. 67890''. Wichtig f\u00fcr die Zuordnung der Rechnung zum richtigen Haushalt.\", \"zeitraum\": \"Abrechnungszeitraum der M\u00fcllgeb\u00fchren, meist ein Kalenderjahr oder Quartal. Format: Datumsbereich, z. B. ''01.01.2023 - 31.12.2023'' oder ''01.04.2023 - 30.06.2023''. Wichtig f\u00fcr die zeitliche Einordnung der Kosten.\", \"tonnengroesse\": \"Gr\u00f6\u00dfe der genutzten M\u00fclltonnen (z. B. Restm\u00fcll, Bioabfall, Papier) in Litern oder Kubikmetern. Format: numerisch mit Einheit, z. B. ''240 Liter'', ''1,1 m\u00b3''. Wichtig f\u00fcr die Berechnung der Leistungsgeb\u00fchr.\", \"leerungen\": \"Anzahl der Leerungen pro Abrechnungszeitraum f\u00fcr jede Tonnenart. Format: numerisch, z. B. ''52 Leerungen (w\u00f6chentlich)''. Wichtig f\u00fcr die Berechnung der Leistungsgeb\u00fchr.\", \"grundgebuehr\": \"Feste Grundgeb\u00fchr f\u00fcr die Bereitstellung der M\u00fclltonnen und Entsorgungsinfrastruktur. Format: W\u00e4hrungsbetrag, z. B. ''60,00 \u20ac''. Wird unabh\u00e4ngig von der tats\u00e4chlichen Nutzung f\u00e4llig.\", \"leistungsgebuehr\": \"Variable Geb\u00fchr basierend auf Tonnengr\u00f6\u00dfe und Anzahl der Leerungen. Format: W\u00e4hrungsbetrag, z. B. ''120,50 \u20ac''. Kann nach Abfallfraktionen (Restm\u00fcll, Bio, Papier) aufgeschl\u00fcsselt sein.\", \"gesamtbetrag\": \"Gesamtsumme der M\u00fcllgeb\u00fchren (Grundgeb\u00fchr + Leistungsgeb\u00fchr). Format: W\u00e4hrungsbetrag, z. B. ''180,50 \u20ac''. Wichtig f\u00fcr die Haushaltsbuchf\u00fchrung und Kostenkontrolle.\"}"',
    'Müllgebühren, Abfallgebühren, Entsorgungsgebühren, Restmülltonne, Biotonne, Papiertonne, Gelber Sack, Leerungen, Grundgebühr, Leistungsgebühr, Gesamtbetrag, Abrechnungszeitraum, Grundstücksnummer, mags, AWA, BSR, AWB, Entsorgungsbetrieb, Kommune, Stadtwerke, Abfallwirtschaft, Tonnengröße, m³, Liter, Jahresabrechnung, Quartalsabrechnung, waste management, waste disposal fees',
    'mags (Mönchengladbach), Kommune, Entsorgungsbetriebe',
    NULL,
    0,
    1,
    1,
    'mistral_batch',
    'Häufige Verwechslungen: Müllgebührenabrechnungen werden oft mit Wasser- oder Abwassergebühren verwechselt, da diese ebenfalls von kommunalen Betrieben stammen. Achte auf die spezifischen Begriffe wie ''Tonnengröße'', ''Leerungen'' oder ''Abfallfraktionen''. Sonderfälle: Manche Kommunen berechnen separate Gebühren für Sondermüll oder Sperrmüll, die nicht in diesem Template abgebildet sind. In einigen Fällen sind Müllgebühren in den Nebenkostenabrechnungen des Vermieters enthalten – hier ist eine separate Rechnung nicht zu erwarten.'
)
ON CONFLICT (id) DO UPDATE SET category=EXCLUDED.category, display_name=EXCLUDED.display_name, description=EXCLUDED.description, schema=EXCLUDED.schema, field_descriptions=EXCLUDED.field_descriptions, classify_keywords=EXCLUDED.classify_keywords, typical_senders=EXCLUDED.typical_senders, steuer_relevanz=EXCLUDED.steuer_relevanz, priority=EXCLUDED.priority, enabled=EXCLUDED.enabled, version=EXCLUDED.version, source=EXCLUDED.source, notes=EXCLUDED.notes;

INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'water_bill',
    'A. Finanzen & Rechnungen',
    'Wasserrechnung',
    'Die Wasserrechnung ist eine regelmäßige Abrechnung für die Lieferung von Trinkwasser und die Entsorgung von Abwasser durch kommunale oder private Versorger. Sie kommt typischerweise quartalsweise oder jährlich vor und enthält detaillierte Angaben zum Verbrauch, Gebühren und Zählerständen. Im Gegensatz zu anderen Nebenkostenabrechnungen (z. B. Heizung oder Strom) bezieht sie sich spezifisch auf Wasserverbrauch und Abwasserentsorgung, oft inklusive Niederschlagsgebühr für Regenwasserableitung.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "water_bill", "description": "Schema für die Extraktion von Daten aus einer Wasserrechnung", "type": "object", "properties": {"anbieter": {"type": "object", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort", "land"]}, "kontakt": {"type": "object", "properties": {"telefon": {"type": "string"}, "email": {"type": "string"}}}}, "required": ["name"]}, "kundennummer": {"type": "string"}, "zaehlernummer": {"type": "string"}, "verbrauch_m3": {"type": "number"}, "zeitraum": {"type": "object", "properties": {"von": {"type": "string", "format": "date"}, "bis": {"type": "string", "format": "date"}}, "required": ["von", "bis"]}, "wasserpreis": {"type": "object", "properties": {"betrag": {"type": "string"}, "waehrung": {"type": "string"}}, "required": ["betrag", "waehrung"]}, "abwasserpreis": {"type": "object", "properties": {"betrag": {"type": "string"}, "waehrung": {"type": "string"}}, "required": ["betrag", "waehrung"]}, "niederschlagsgebuehr": {"type": "object", "properties": {"betrag": {"type": "string"}, "waehrung": {"type": "string"}}, "required": ["betrag", "waehrung"]}, "grundgebuehr": {"type": "object", "properties": {"betrag": {"type": "string"}, "waehrung": {"type": "string"}}, "required": ["betrag", "waehrung"]}, "gesamtbetrag": {"type": "object", "properties": {"betrag": {"type": "string"}, "waehrung": {"type": "string"}}, "required": ["betrag", "waehrung"]}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^[0-9]{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "nullable": true}, "mwst_satz": {"type": "string", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}, "positionen": {"type": "array", "description": "Einzelpositionen der Wasserrechnung (Frischwasser, Abwasser, Grundgebühr, Zählergebühr, etc.)", "items": {"type": "object", "properties": {"beschreibung": {"type": "string"}, "menge": {"type": "string"}, "einzelpreis": {"type": "string"}, "betrag": {"type": "string"}, "einheit": {"type": "string", "description": "Einheit (z.B. m3, Stk, Monat)"}}}}, "objekt_adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "default": "DE"}}, "description": "Verbrauchsstelle/Liegenschaft des Wasserzaehlers"}, "waehrung": {"type": "string", "default": "EUR", "description": "Waehrung ISO 4217 (EUR, USD, etc.)"}, "verbrauch_einheit": {"type": "string", "description": "Einheit des Verbrauchs (z.B. m3)"}}, "required": ["anbieter", "kundennummer", "zaehlernummer", "verbrauch_m3", "zeitraum", "wasserpreis", "abwasserpreis", "grundgebuehr", "gesamtbetrag", "_meta"]}',
    '"{\"anbieter\": \"Name des Wasserversorgers oder der Stadtwerke, z. B. ''Stadtwerke M\u00fcnchen''. Wichtig f\u00fcr die Zuordnung der Rechnung und ggf. steuerliche Nachweise.\", \"kundennummer\": \"Eindeutige Identifikationsnummer des Kunden beim Anbieter, z. B. ''KD-12345678''. Wichtig f\u00fcr die Zuordnung und bei R\u00fcckfragen.\", \"zaehlernummer\": \"Nummer des Wasserz\u00e4hlers, z. B. ''WZ-98765432''. Wichtig f\u00fcr die Verbrauchsermittlung und bei Z\u00e4hlerwechsel.\", \"verbrauch_m3\": \"Wassermenge in Kubikmetern (m\u00b3) f\u00fcr den Abrechnungszeitraum, z. B. ''50,5''. Wichtig f\u00fcr die Berechnung der Kosten und ggf. steuerliche Aufteilung bei beruflicher Nutzung.\", \"zeitraum\": \"Abrechnungszeitraum im Format ''TT.MM.JJJJ - TT.MM.JJJJ'', z. B. ''01.01.2023 - 31.12.2023''. Wichtig f\u00fcr die zeitliche Zuordnung und steuerliche Abgrenzung.\", \"wasserpreis\": \"Preis pro Kubikmeter Trinkwasser in Euro, z. B. ''2,10 \u20ac/m\u00b3''. Wichtig f\u00fcr die Berechnung der Gesamtkosten und ggf. steuerliche Aufteilung.\", \"abwasserpreis\": \"Preis pro Kubikmeter Abwasserentsorgung in Euro, z. B. ''1,80 \u20ac/m\u00b3''. Oft steuerrelevant f\u00fcr \u00a735a EStG (haushaltsnahe Dienstleistungen).\", \"niederschlagsgebuehr\": \"Geb\u00fchr f\u00fcr die Ableitung von Regenwasser, oft in Euro pro m\u00b2 versiegelter Fl\u00e4che oder pauschal, z. B. ''25,00 \u20ac''. Kann steuerrelevant sein, wenn sie als Dienstleistung gilt.\", \"grundgebuehr\": \"Feste Grundgeb\u00fchr f\u00fcr den Wasseranschluss, z. B. ''60,00 \u20ac pro Jahr''. Wichtig f\u00fcr die Gesamtkostenberechnung.\"}"',
    'Wasserrechnung, Wasserverbrauch, Abwassergebühr, Niederschlagswasser, Trinkwasser, Zählernummer, m³, Kubikmeter, Grundgebühr, Stadtwerke, Wasserversorgung, sewage, water supply, consumption, meter number, wastewater, rainwater fee, annual statement, Verbrauchsabrechnung',
    'NEW, Stadtwerke, Kommune',
    '{"einordnung": "Teilweise relevant für §35a EStG (haushaltsnahe Dienstleistungen) oder bei beruflicher Nutzung (z. B. Homeoffice).", "anlage": "Keine direkte Anlage, aber Belege für §35a EStG (Anlage Haushaltsnahe Aufwendungen) oder bei Arbeitszimmer (Anlage N).", "absetzbar": {"haushaltsnah": "20% der Arbeitskosten (z. B. Abwasserentsorgung) bis max. 4.000 € (§35a Abs. 2 EStG).", "beruflich": "Anteilige Kosten bei Homeoffice oder betrieblicher Nutzung (Anlage N oder EÜR)."}}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
