INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'cancellation_letter',
    'B. Verträge & Vereinbarungen',
    'Kündigung',
    'Ein Kündigungsschreiben ist ein formelles Dokument zur Beendigung eines Vertragsverhältnisses, das entweder vom Kunden oder Anbieter versendet wird. Es kommt typischerweise bei Abonnements, Mitgliedschaften, Versicherungen oder Dienstleistungsverträgen vor und enthält spezifische Angaben zum Vertrag sowie das gewünschte Kündigungsdatum. Im Gegensatz zu einer Rechnung oder Mahnung dient es nicht der Zahlungsaufforderung, sondern der rechtlichen Beendigung einer Vereinbarung.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "cancellation_letter", "description": "Schema f\u00fcr K\u00fcndigungsschreiben", "type": "object", "properties": {"vertragspartner": {"type": "object", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort"]}, "kontakt": {"type": "object", "properties": {"telefon": {"type": "string"}, "email": {"type": "string", "format": "email"}}}}, "required": ["name"]}, "vertragsnummer": {"type": "string"}, "kuendigungsdatum": {"type": "string", "format": "date"}, "wirksam_zum": {"type": "string", "format": "date"}, "kuendigungsgrund": {"type": "string"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^[0-9]{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$", "nullable": true}, "mwst_satz": {"type": "string", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}}, "required": ["vertragspartner", "vertragsnummer", "kuendigungsdatum"]}',
    '"{\"vertragspartner\": \"Name und Adresse des Vertragspartners (z. B. Unternehmen oder Person), an den die K\u00fcndigung gerichtet ist. Wichtig f\u00fcr die Identifikation des Vertragsverh\u00e4ltnisses. Beispiel: ''Musterfirma GmbH, Musterstra\u00dfe 1, 12345 Musterstadt''.\", \"vertragsnummer\": \"Eindeutige Nummer des zu k\u00fcndigenden Vertrags. Wird ben\u00f6tigt, um die K\u00fcndigung dem richtigen Vertrag zuzuordnen. Beispiel: ''VN-2023-45678''.\", \"kuendigungsdatum\": \"Datum, an dem die K\u00fcndigung verfasst oder versendet wurde. Wichtig f\u00fcr die Einhaltung von Fristen. Format: TT.MM.JJJJ. Beispiel: ''15.10.2023''.\", \"wirksam_zum\": \"Datum, zu dem die K\u00fcndigung wirksam werden soll (Ende des Vertragsverh\u00e4ltnisses). Oft identisch mit dem Ende der Vertragslaufzeit oder einer K\u00fcndigungsfrist. Format: TT.MM.JJJJ. Beispiel: ''31.12.2023''.\", \"kuendigungsgrund\": \"Optional angegebener Grund f\u00fcr die K\u00fcndigung (z. B. Umzug, Unzufriedenheit, Vertragsende). Kann f\u00fcr die Dokumentation oder bei Streitf\u00e4llen relevant sein. Beispiel: ''Umzug ins Ausland''.\"}"',
    'Kündigung, Kündigungsschreiben, Vertragskündigung, Beendigung, fristgerecht, außerordentlich, Vertragsnummer, Kündigungsdatum, wirksam zum, Kündigungsgrund, kündigen, Vertragspartner, Mitgliedschaft beenden, Abonnement kündigen, cancellation, termination, notice period, contract number, effective date, termination reason',
    'Kunde oder Anbieter',
    NULL,
    0,
    1,
    1,
    'mistral_batch',
    'Häufige Verwechslungen: Kündigungen werden oft mit Mahnungen oder Vertragsänderungen verwechselt, da sie ähnliche Felder wie Vertragsnummern enthalten. Achte auf Formulierungen wie ''hiermit kündige ich'' oder ''wir bestätigen die Kündigung''. Sonderfälle: Bei außerordentlichen Kündigungen (z. B. aus wichtigem Grund) fehlt oft das Feld ''wirksam_zum'', da die Kündigung sofort wirksam wird. Tipp: Kündigungen sind oft kurz und prägnant, während Vertragsänderungen oder -verlängerungen detailliertere Bedingungen enthalten.'
)
ON CONFLICT (id) DO UPDATE SET category=EXCLUDED.category, display_name=EXCLUDED.display_name, description=EXCLUDED.description, schema=EXCLUDED.schema, field_descriptions=EXCLUDED.field_descriptions, classify_keywords=EXCLUDED.classify_keywords, typical_senders=EXCLUDED.typical_senders, steuer_relevanz=EXCLUDED.steuer_relevanz, priority=EXCLUDED.priority, enabled=EXCLUDED.enabled, version=EXCLUDED.version, source=EXCLUDED.source, notes=EXCLUDED.notes;

INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'contract',
    'B. Verträge & Vereinbarungen',
    'Vertrag',
    'Ein Vertrag ist eine rechtlich bindende Vereinbarung zwischen zwei oder mehr Parteien, die Rechte und Pflichten regelt. Er kommt in vielfältigen Kontexten vor, z. B. Mietverträge, Arbeitsverträge, Kaufverträge oder Dienstleistungsverträge. Im Gegensatz zu einseitigen Dokumenten wie Rechnungen oder Bescheiden enthält ein Vertrag stets wechselseitige Verpflichtungen und ist oft durch Unterschriften der Parteien gekennzeichnet.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "contract", "description": "Schema f\u00fcr Vertragsdokumente", "type": "object", "properties": {"vertragsparteien": {"type": "array", "items": {"type": "object", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort", "land"]}, "kontakt": {"type": "object", "properties": {"telefon": {"type": "string"}, "email": {"type": "string", "format": "email"}}}, "rolle": {"type": "string", "enum": ["auftraggeber", "auftragnehmer", "vermieter", "mieter", "k\u00e4ufer", "verk\u00e4ufer"]}}, "required": ["name", "adresse"]}}, "gegenstand": {"type": "string"}, "laufzeit": {"type": "object", "properties": {"beginn": {"type": "string", "format": "date"}, "ende": {"type": "string", "format": "date"}, "unbefristet": {"type": "boolean"}}, "anyOf": [{"required": ["beginn", "ende"]}, {"required": ["unbefristet"]}]}, "kuendigungsfrist": {"type": "object", "properties": {"frist": {"type": "string"}, "einheit": {"type": "string", "enum": ["tage", "wochen", "monate", "jahre"]}, "kuendigungstermin": {"type": "string"}}, "required": ["frist", "einheit"]}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^[0-9]{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$", "nullable": true}, "mwst_satz": {"type": "string", "pattern": "^[0-9]+(\\.[0-9]{1,2})?$", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}, "klauseln": {"type": "array", "description": "Wesentliche Vertragsklauseln und Bedingungen", "items": {"type": "object", "properties": {"paragraph": {"type": "string"}, "titel": {"type": "string"}, "inhalt": {"type": "string"}}}}}, "required": ["vertragsparteien", "gegenstand", "_meta"]}',
    '"{\"vertragsparteien\": \"Namen und Adressen der beteiligten Vertragsparteien (z. B. Mieter/Vermieter, Arbeitgeber/Arbeitnehmer). Format: Liste von Objekten mit ''name'' und ''adresse''. Beispiel: [{''name'': ''Max Mustermann'', ''adresse'': ''Musterstra\u00dfe 1, 12345 Musterstadt''}, {''name'': ''Musterfirma GmbH'', ''adresse'': ''Firmenweg 2, 54321 Beispielstadt''}]. Wichtig f\u00fcr die Identifikation der Vertragspartner und ggf. f\u00fcr steuerliche Zuordnungen (z. B. bei Mietvertr\u00e4gen).\", \"gegenstand\": \"Beschreibung des Vertragsgegenstands (z. B. ''Vermietung einer Wohnung'', ''Erbringung von IT-Dienstleistungen''). Format: Freitext. Beispiel: ''Vermietung der Wohnung im 2. OG, Musterstra\u00dfe 1, 12345 Musterstadt''. Relevant f\u00fcr die Einordnung des Vertragstyps und ggf. f\u00fcr steuerliche Zwecke (z. B. bei gewerblichen Mietvertr\u00e4gen).\", \"laufzeit\": \"Angabe der Vertragslaufzeit, inkl. Start- und Enddatum (falls zutreffend). Format: Objekt mit ''beginn'' (Datum) und ''ende'' (Datum oder ''unbefristet''). Beispiel: {''beginn'': ''2023-01-01'', ''ende'': ''2025-12-31''}. Wichtig f\u00fcr die Dokumentation von Fristen und ggf. f\u00fcr steuerliche Abschreibungen (z. B. bei Leasingvertr\u00e4gen).\", \"kuendigungsfrist\": \"Regelungen zur K\u00fcndigung des Vertrags, inkl. Fristen und Modalit\u00e4ten. Format: Freitext oder strukturiert (z. B. ''3 Monate zum Monatsende''). Beispiel: ''Der Vertrag kann mit einer Frist von 3 Monaten zum Quartalsende gek\u00fcndigt werden.''. Relevant f\u00fcr die Einhaltung von Fristen und ggf. f\u00fcr die steuerliche Bewertung von Vertragsverh\u00e4ltnissen.\"}"',
    'Vertrag, Vereinbarung, Vertragsparteien, §, Paragraph, Laufzeit, Kündigungsfrist, Gegenstand, Unterschrift, Datum, Pflichten, Rechte, Mietvertrag, Arbeitsvertrag, Kaufvertrag, Dienstleistungsvertrag, Vertragsbeginn, Vertragsende, clause, parties, term, termination, agreement, signature',
    'Diverse',
    NULL,
    0,
    1,
    1,
    'mistral_batch',
    'Häufige Verwechslungen: Verträge können mit anderen rechtlichen Dokumenten wie AGBs, Angeboten oder Bestätigungen verwechselt werden. Verträge zeichnen sich jedoch durch wechselseitige Verpflichtungen und Unterschriften aus. Sonderfälle: Bei befristeten Verträgen kann das Enddatum fehlen (z. B. ''bis auf weiteres''). Bei Mietverträgen oder Arbeitsverträgen sind oft zusätzliche Felder wie ''Mietzins'' oder ''Gehaltsangaben'' relevant, die in diesem generischen Template nicht abgebildet sind. Tipp: Achte auf Formulierungen wie ''hiermit vereinbaren'' oder ''verpflichten sich'' sowie auf Unterschriftenfelder.'
)
