INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'employment_contract',
    'B. Verträge & Vereinbarungen',
    'Arbeitsvertrag',
    'Ein Arbeitsvertrag ist die schriftliche Vereinbarung zwischen Arbeitgeber und Arbeitnehmer, die die Bedingungen des Beschäftigungsverhältnisses regelt. Er kommt bei der Einstellung oder Änderung von Arbeitsbedingungen zustande und unterscheidet sich von anderen Verträgen (z. B. Dienstverträgen) durch die spezifischen Regelungen zu Arbeitszeit, Gehalt, Kündigungsfristen und Sozialleistungen. Typisch sind detaillierte Angaben zu Position, Probezeit und Urlaubsanspruch.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "employment_contract", "description": "Schema f\u00fcr die Extraktion von Daten aus einem Arbeitsvertrag", "type": "object", "properties": {"arbeitnehmer": {"type": "object", "properties": {"name": {"type": "string"}, "vorname": {"type": "string"}, "geburtsdatum": {"type": "string", "format": "date"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort", "land"]}, "steuer_id": {"type": "string"}, "sozialversicherungsnummer": {"type": "string"}, "iban": {"type": "string"}, "telefon": {"type": "string"}, "email": {"type": "string", "format": "email"}}, "required": ["name", "vorname", "adresse"]}, "arbeitgeber": {"type": "object", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort", "land"]}, "steuernummer": {"type": "string"}, "betriebsnummer": {"type": "string"}, "telefon": {"type": "string"}, "email": {"type": "string", "format": "email"}, "ansprechpartner": {"type": "string"}}, "required": ["name", "adresse"]}, "position": {"type": "object", "properties": {"bezeichnung": {"type": "string"}, "abteilung": {"type": "string"}, "beginn": {"type": "string", "format": "date"}, "befristet_bis": {"type": "string", "format": "date", "nullable": true}, "taetigkeitsbeschreibung": {"type": "string"}}, "required": ["bezeichnung", "beginn"]}, "gehalt": {"type": "object", "properties": {"brutto": {"type": "string"}, "waehrung": {"type": "string"}, "zahlungsweise": {"type": "string", "enum": ["monatlich", "woechentlich", "jaehrlich", "einmalig"]}, "zulagen": {"type": "array", "items": {"type": "object", "properties": {"bezeichnung": {"type": "string"}, "betrag": {"type": "string"}, "waehrung": {"type": "string"}}, "required": ["bezeichnung", "betrag", "waehrung"]}}, "sonderzahlungen": {"type": "array", "items": {"type": "object", "properties": {"bezeichnung": {"type": "string"}, "betrag": {"type": "string"}, "waehrung": {"type": "string"}, "zeitpunkt": {"type": "string"}}, "required": ["bezeichnung", "betrag", "waehrung"]}}}, "required": ["brutto", "waehrung", "zahlungsweise"]}, "arbeitszeit": {"type": "object", "properties": {"wochenstunden": {"type": "number"}, "verteilung": {"type": "string"}, "gleitzeit": {"type": "boolean"}, "kernarbeitszeit": {"type": "string", "nullable": true}, "pausenregelung": {"type": "string"}}, "required": ["wochenstunden"]}, "urlaub": {"type": "object", "properties": {"tage_pro_jahr": {"type": "number"}, "regelung": {"type": "string"}, "zusatzurlaub": {"type": "array", "items": {"type": "object", "properties": {"grund": {"type": "string"}, "tage": {"type": "number"}}, "required": ["grund", "tage"]}}}, "required": ["tage_pro_jahr"]}, "kuendigungsfrist": {"type": "object", "properties": {"arbeitnehmer": {"type": "string"}, "arbeitgeber": {"type": "string"}, "regelung": {"type": "string"}}, "required": ["arbeitnehmer", "arbeitgeber"]}, "probezeit": {"type": "object", "properties": {"dauer": {"type": "string"}, "kuendigungsfrist": {"type": "string"}}, "required": ["dauer"]}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^[0-9]{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "nullable": true}, "mwst_satz": {"type": "string", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant"]}, "klauseln": {"type": "array", "description": "Wesentliche Vertragsklauseln (Wettbewerbsverbot, Geheimhaltung, Nebent\u00e4tigkeit, etc.)", "items": {"type": "object", "properties": {"paragraph": {"type": "string"}, "titel": {"type": "string"}, "inhalt": {"type": "string"}}}}}, "required": ["arbeitnehmer", "arbeitgeber", "position", "gehalt", "arbeitszeit", "urlaub", "kuendigungsfrist", "_meta"]}',
    '"{\"arbeitnehmer\": \"Name und Adresse des Arbeitnehmers (Vorname, Nachname, Stra\u00dfe, PLZ, Ort). Wichtig f\u00fcr die Identifikation der steuerpflichtigen Person in der Anlage N.\", \"arbeitgeber\": \"Name und Adresse des Arbeitgebers (Firma, Stra\u00dfe, PLZ, Ort). Relevant f\u00fcr die Zuordnung der Lohnsteuerbescheinigung und ggf. Werbungskosten (z. B. Entfernungspauschale).\", \"position\": \"Bezeichnung der Stelle oder T\u00e4tigkeit (z. B. ''Softwareentwickler'', ''Vertriebsmitarbeiter''). Kann f\u00fcr die Einordnung von Werbungskosten (z. B. Fortbildungskosten) oder au\u00dfergew\u00f6hnlichen Belastungen relevant sein.\", \"gehalt\": \"Bruttogehalt pro Jahr oder Monat (z. B. ''50.000 \u20ac p.a.'' oder ''4.166 \u20ac monatlich''). Wichtigster Wert f\u00fcr die Berechnung der Eink\u00fcnfte in der Anlage N. Achte auf Zusatzangaben wie ''zzgl. Bonus'' oder ''inkl. Weihnachtsgeld''.\", \"arbeitszeit\": \"Vereinbarte Wochen- oder Monatsarbeitszeit (z. B. ''40 Stunden/Woche'' oder ''173 Stunden/Monat''). Kann f\u00fcr die Berechnung von Teilzeitverh\u00e4ltnissen oder \u00dcberstunden relevant sein, die steuerlich ggf. als sonstige Eink\u00fcnfte (\u00a7 22 EStG) erfasst werden.\", \"urlaub\": \"Anzahl der vereinbarten Urlaubstage pro Jahr (z. B. ''30 Tage''). Nicht direkt steuerrelevant, aber wichtig f\u00fcr die Dokumentation von Anspr\u00fcchen (z. B. bei K\u00fcndigung).\", \"kuendigungsfrist\": \"Vereinbarte Frist f\u00fcr die K\u00fcndigung des Arbeitsverh\u00e4ltnisses (z. B. ''4 Wochen zum Monatsende''). Relevant f\u00fcr die steuerliche Behandlung von Abfindungen (\u00a7 34 EStG) oder Arbeitslosengeld.\"}"',
    'Arbeitsvertrag, Arbeitsverhältnis, Anstellung, Beschäftigungsvertrag, Position, Gehalt, Bruttogehalt, Arbeitszeit, Urlaubstage, Kündigungsfrist, Probezeit, Arbeitnehmer, Arbeitgeber, Vertragsparteien, employment contract, probation period, notice period, salary, working hours, annual leave',
    'Arbeitgeber',
    '{"paragraphen": "§ 2 EStG (Einkünfte aus nichtselbstständiger Arbeit), § 38 EStG (Lohnsteuerabzug), § 41 EStG (Elektronische Lohnsteuerabzugsmerkmale)", "anlage": "Anlage N (Einkünfte aus nichtselbstständiger Arbeit)", "hinweise": "Das Gehalt ist als Bruttobetrag anzugeben und fließt in die Einkommensteuererklärung ein. Arbeitsverträge können auch Hinweise auf steuerfreie Zuschüsse (z. B. für Homeoffice) oder Werbungskosten (z. B. Dienstwagen) enthalten, die in der Anlage N geltend gemacht werden."}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
ON CONFLICT (id) DO UPDATE SET category=EXCLUDED.category, display_name=EXCLUDED.display_name, description=EXCLUDED.description, schema=EXCLUDED.schema, field_descriptions=EXCLUDED.field_descriptions, classify_keywords=EXCLUDED.classify_keywords, typical_senders=EXCLUDED.typical_senders, steuer_relevanz=EXCLUDED.steuer_relevanz, priority=EXCLUDED.priority, enabled=EXCLUDED.enabled, version=EXCLUDED.version, source=EXCLUDED.source, notes=EXCLUDED.notes;

INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'energy_contract',
    'B. Verträge & Vereinbarungen',
    'Energievertrag',
    'Ein Energievertrag regelt die Lieferung von Strom oder Gas zwischen einem Energieversorger und einem Privathaushalt. Er enthält Details wie Tarif, Preise, Vertragslaufzeit und Kündigungsfristen. Im Gegensatz zu Rechnungen oder Abrechnungen handelt es sich um den grundlegenden Vertragstext, der die Rahmenbedingungen der Energieversorgung festlegt.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "energy_contract", "description": "Schema f\u00fcr Energievertr\u00e4ge", "type": "object", "properties": {"anbieter": {"type": "string", "description": "Name des Energieanbieters"}, "zaehlernummer": {"type": "string", "description": "Z\u00e4hlernummer des Strom-/Gasanschlusses"}, "tarif": {"type": "string", "description": "Name des gew\u00e4hlten Tarifs"}, "grundpreis": {"type": "string", "description": "Grundpreis pro Monat (z.B. ''4.99'')", "pattern": "^\\d+\\.\\d{2}$"}, "arbeitspreis": {"type": "string", "description": "Arbeitspreis pro kWh (z.B. ''0.29'')", "pattern": "^\\d+\\.\\d{2}$"}, "vertragsbeginn": {"type": "string", "description": "Vertragsbeginn (YYYY-MM-DD)", "format": "date"}, "kuendigungsfrist": {"type": "string", "description": "K\u00fcndigungsfrist in Tagen oder als Datum (YYYY-MM-DD)", "oneOf": [{"type": "string", "pattern": "^\\d+$"}, {"type": "string", "format": "date"}]}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean", "default": false}, "steuerrelevanz_hinweis": {"type": "string", "default": null}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "default": null}, "steuerjahr": {"type": "string", "pattern": "^\\d{4}$", "default": null}, "mwst_ausgewiesen": {"type": "boolean", "default": false}, "mwst_betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$", "default": null}, "mwst_satz": {"type": "string", "pattern": "^\\d+(\\.\\d{1,2})?$", "default": null}, "aktenzeichen": {"type": "string", "default": null}, "dokumenten_id": {"type": "string", "default": null}}, "additionalProperties": false}, "klauseln": {"type": "array", "description": "Wesentliche Vertragsklauseln (Preisanpassung, Laufzeit, K\u00fcndigungsfristen, etc.)", "items": {"type": "object", "properties": {"paragraph": {"type": "string"}, "titel": {"type": "string"}, "inhalt": {"type": "string"}}}}}, "required": ["anbieter", "zaehlernummer", "tarif", "grundpreis", "arbeitspreis", "vertragsbeginn"], "additionalProperties": false}',
    '"{\"anbieter\": \"Name des Energieversorgers, der den Vertrag ausstellt (z. B. ''Stadtwerke M\u00fcnchen''). Wichtig f\u00fcr die Identifikation des Vertragspartners, aber nicht direkt steuerrelevant.\", \"zaehlernummer\": \"Eindeutige Nummer des Strom- oder Gasz\u00e4hlers (z. B. ''12345678''). Wird zur Identifikation des Messpunkts ben\u00f6tigt, aber nicht steuerrelevant.\", \"tarif\": \"Name oder Bezeichnung des gew\u00e4hlten Tarifs (z. B. ''\u00d6kostrom Classic''). Kann f\u00fcr die Unterscheidung von Vertragsmodellen relevant sein, aber nicht steuerrelevant.\", \"grundpreis\": \"Monatlicher oder j\u00e4hrlicher Grundpreis in Euro (z. B. ''8,50 \u20ac/Monat''). Wird in der Regel nicht steuerlich abgesetzt, kann aber bei gewerblicher Nutzung relevant sein.\", \"arbeitspreis\": \"Preis pro verbrauchter Kilowattstunde (kWh) in Euro (z. B. ''0,30 \u20ac/kWh''). Wird in der Regel nicht steuerlich abgesetzt, kann aber bei gewerblicher Nutzung relevant sein.\", \"vertragsbeginn\": \"Datum, an dem der Vertrag in Kraft tritt (Format: YYYY-MM-DD, z. B. ''2023-01-01''). Wichtig f\u00fcr die Vertragslaufzeit, aber nicht steuerrelevant.\", \"kuendigungsfrist\": \"Zeitraum, innerhalb dessen der Vertrag gek\u00fcndigt werden kann (z. B. ''6 Wochen zum Vertragsende''). Wichtig f\u00fcr die Planung einer Vertragsbeendigung, aber nicht steuerrelevant.\"}"',
    'Energievertrag, Stromvertrag, Gasvertrag, Versorgungsvertrag, Tarif, Grundpreis, Arbeitspreis, Vertragsbeginn, Kündigungsfrist, Zählernummer, Lieferbedingungen, Preisgarantie, Vertragslaufzeit, Netzbetreiber, Stadtwerke, Energieversorger, supply agreement, electricity contract, gas contract, meter number, basic fee, energy price',
    'Stadtwerke, Versorger',
    NULL,
    0,
    1,
    1,
    'mistral_batch',
    'Häufige Verwechslungen treten mit Energieabrechnungen oder -rechnungen auf, die jedoch konkrete Verbrauchsdaten und Kostenaufstellungen enthalten. Energieverträge sind oft längerfristige Dokumente mit allgemeinen Bedingungen, während Rechnungen monatlich oder jährlich ausgestellt werden. Achte auf Formulierungen wie ''Vertragsbedingungen'', ''Liefervertrag'' oder ''Allgemeine Geschäftsbedingungen (AGB)'' zur Unterscheidung.'
)
