INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'loan_contract',
    'B. Verträge & Vereinbarungen',
    'Darlehensvertrag',
    'Ein Darlehensvertrag ist ein rechtsverbindliches Dokument zwischen einem Darlehensnehmer und einer Bank oder Bausparkasse, das die Konditionen eines Kredits regelt. Typischerweise tritt es bei Immobilienfinanzierungen, Autokrediten oder privaten Darlehen auf. Im Gegensatz zu einem Kreditvertrag (der oft standardisierter ist) enthält ein Darlehensvertrag detaillierte Angaben zu Zinsen, Tilgung, Laufzeit und Sicherheiten, die für die steuerliche und finanzielle Planung relevant sind.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "loan_contract", "description": "Darlehensvertrag", "type": "object", "properties": {"darlehensnehmer": {"type": "object", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort", "land"]}, "geburtsdatum": {"type": "string", "format": "date"}, "steuer_id": {"type": "string"}}, "required": ["name", "adresse"]}, "darlehensnummer": {"type": "string"}, "bank": {"type": "object", "properties": {"name": {"type": "string"}, "iban": {"type": "string"}, "bic": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort", "land"]}}, "required": ["name", "iban", "adresse"]}, "darlehensbetrag": {"type": "string"}, "auszahlungsdatum": {"type": "string", "format": "date"}, "zinssatz_nominal": {"type": "string"}, "zinssatz_effektiv": {"type": "string"}, "zinsbindung_bis": {"type": "string", "format": "date"}, "laufzeit": {"type": "integer"}, "monatliche_rate": {"type": "string"}, "tilgungssatz": {"type": "string"}, "sondertilgung_prozent": {"type": "string"}, "sondertilgung_max": {"type": "string"}, "bereitstellungszinsen": {"type": "string"}, "sicherheiten": {"type": "array", "items": {"type": "object", "properties": {"art": {"type": "string"}, "beschreibung": {"type": "string"}, "wert": {"type": "string"}}, "required": ["art", "beschreibung"]}}, "verwendungszweck": {"type": "string"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^\\d{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "nullable": true}, "mwst_satz": {"type": "string", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant"]}, "klauseln": {"type": "array", "description": "Wesentliche Vertragsklauseln (Sondertilgung, Vorf\u00e4lligkeitsentsch\u00e4digung, Zinsbindung, etc.)", "items": {"type": "object", "properties": {"paragraph": {"type": "string"}, "titel": {"type": "string"}, "inhalt": {"type": "string"}}}}}, "required": ["darlehensnehmer", "darlehensnummer", "bank", "darlehensbetrag", "auszahlungsdatum", "_meta"]}',
    '"darlehensnehmer, darlehensnummer, bank, darlehensbetrag, auszahlungsdatum, zinssatz_nominal, zinssatz_effektiv, zinsbindung_bis, laufzeit, monatliche_rate, tilgungssatz, sondertilgung_prozent, sondertilgung_max, bereitstellungszinsen, sicherheiten, verwendungszweck"',
    'Darlehensvertrag, Darlehensnehmer, Darlehensnummer, Zinssatz, nominal, effektiv, Zinsbindung, Laufzeit, monatliche Rate, Tilgungssatz, Sondertilgung, Bereitstellungszinsen, Sicherheiten, Verwendungszweck, Auszahlungsdatum, loan agreement, interest rate, repayment, collateral, purpose of loan, disbursement date, fixed interest period',
    'Banken, Bausparkassen',
    '{"paragraphen": "§4 Abs. 4 EStG (Betriebsausgaben), §9 Abs. 1 EStG (Werbungskosten), §10e EStG (Eigenheimzulage, historisch), §35a EStG (Handwerkerleistungen bei Modernisierung), §21 EStG (Einkünfte aus Vermietung und Verpachtung)", "anlage": "V (bei Vermietung), N (bei selbstgenutztem Wohneigentum, z. B. Handwerkerleistungen), Vorsorgeaufwand (falls Zinsen für vermietete Immobilien)", "absetzbare_betrage": {"zinsen": "Schuldzinsen als Werbungskosten bei vermieteten Immobilien (Anlage V), ggf. anteilig bei gemischter Nutzung. Bei selbstgenutztem Wohneigentum nur in Ausnahmefällen (z. B. §35a EStG für energetische Maßnahmen).", "tilgung": "Nicht absetzbar, da es sich um eine Rückzahlung des Darlehens handelt (keine Ausgabe).", "sondertilgung": "Keine direkte steuerliche Auswirkung, aber kann Zinsbelastung reduzieren (indirekt relevant für Werbungskosten)."}}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
