INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'rental_contract',
    'B. Verträge & Vereinbarungen',
    'Mietvertrag',
    'Ein Mietvertrag regelt die rechtliche Beziehung zwischen Vermieter und Mieter für die Überlassung einer Wohnung oder eines Hauses. Er kommt bei Neuvermietung, Vertragsverlängerung oder -änderung vor und enthält alle wesentlichen Konditionen wie Mietpreis, Nebenkosten und Kündigungsfristen. Im Gegensatz zu einem Untermietvertrag oder Mietkaufvertrag handelt es sich um einen klassischen Wohnraummietvertrag ohne Kaufoption oder Zwischenvermietung.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "rental_contract", "description": "Mietvertrag", "type": "object", "properties": {"vermieter": {"type": "object", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort", "land"]}, "telefon": {"type": "string"}, "email": {"type": "string", "format": "email"}}, "required": ["name", "adresse"]}, "mieter": {"type": "object", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort", "land"]}, "telefon": {"type": "string"}, "email": {"type": "string", "format": "email"}}, "required": ["name", "adresse"]}, "objekt_adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort", "land"]}, "kaltmiete": {"type": "string", "description": "Betrag in EUR mit 2 Dezimalstellen"}, "nebenkosten": {"type": "string", "description": "Betrag in EUR mit 2 Dezimalstellen"}, "warmmiete": {"type": "string", "description": "Betrag in EUR mit 2 Dezimalstellen"}, "kaution": {"type": "string", "description": "Betrag in EUR mit 2 Dezimalstellen"}, "mietbeginn": {"type": "string", "format": "date", "description": "Datum im Format YYYY-MM-DD"}, "kuendigungsfrist": {"type": "string", "description": "Angabe der K\u00fcndigungsfrist (z.B. ''3 Monate zum Monatsende'')"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^[0-9]{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "nullable": true}, "mwst_satz": {"type": "string", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}, "klauseln": {"type": "array", "description": "Wesentliche Vertragsklauseln und Sondervereinbarungen", "items": {"type": "object", "properties": {"paragraph": {"type": "string"}, "titel": {"type": "string"}, "inhalt": {"type": "string"}}}}}, "required": ["vermieter", "mieter", "objekt_adresse", "kaltmiete", "mietbeginn", "_meta"]}',
    '"vermieter, mieter, objekt_adresse, kaltmiete, nebenkosten, warmmiete, kaution, mietbeginn, kuendigungsfrist"',
    'Mietvertrag, Mietverhältnis, Vermieter, Mieter, Kaltmiete, Warmmiete, Nebenkosten, Kaution, Mietbeginn, Kündigungsfrist, §535 BGB, Wohnraummiete, Mietdauer, Mieterhöhung, Betriebskosten, Nettokaltmiete, Bruttokaltmiete, Mietobjekt, Vertragsparteien, rental agreement, lease contract',
    'Vermieter',
    '{"einkommensteuer": {"paragraphen": ["§9 EStG (Werbungskosten)", "§21 EStG (Einkünfte aus Vermietung und Verpachtung)", "§35a EStG (haushaltsnahe Dienstleistungen)"], "anlagen": ["Anlage V (Einkünfte aus Vermietung und Verpachtung)", "Anlage N (Werbungskosten bei Arbeitnehmern als Mieter)"], "absetzbar": {"vermieter": {"kaltmiete": "Einnahmen (zu versteuern)", "nebenkosten": "Teilweise als Werbungskosten absetzbar (z.B. Grundsteuer, Versicherungen)", "kaution": "Keine direkte steuerliche Relevanz, aber bei Rückzahlung ggf. Zinserträge (§20 EStG)"}, "mieter": {"kaltmiete": "Nur bei doppelter Haushaltsführung (§9 EStG) oder Homeoffice (§4 Abs. 5 EStG) anteilig absetzbar", "nebenkosten": "Nur bei beruflicher Nutzung (z.B. Homeoffice) anteilig absetzbar"}}}}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
