INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'subscription',
    'B. Verträge & Vereinbarungen',
    'Abo/Mitgliedschaft',
    'Dieses Dokument repräsentiert einen Vertrag oder eine Vereinbarung für ein Abonnement oder eine Mitgliedschaft, typischerweise von Streaming-Diensten, Zeitschriften oder Vereinen. Es enthält Details wie Kosten, Zahlungsintervalle und Kündigungsfristen. Im Gegensatz zu einmaligen Kaufverträgen oder Dienstleistungsverträgen handelt es sich hier um wiederkehrende Zahlungsverpflichtungen mit automatischer Verlängerung, falls nicht gekündigt wird.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "Subscription", "description": "Abo- oder Mitgliedschaftsdokument", "type": "object", "properties": {"anbieter": {"type": "string", "description": "Name des Anbieters"}, "abo_name": {"type": "string", "description": "Name des Abonnements oder der Mitgliedschaft"}, "preis": {"type": "string", "pattern": "^\\d+\\.\\d{2}$", "description": "Preis des Abonnements (z.B. 19.99)"}, "intervall": {"type": "string", "enum": ["monatlich", "viertelj\u00e4hrlich", "halbj\u00e4hrlich", "j\u00e4hrlich", "einmalig"], "description": "Zahlungsintervall"}, "beginn": {"type": "string", "format": "date", "description": "Startdatum des Abonnements (YYYY-MM-DD)"}, "naechste_zahlung": {"type": "string", "format": "date", "description": "Datum der n\u00e4chsten Zahlung (YYYY-MM-DD)"}, "kuendigungsfrist": {"type": "object", "description": "K\u00fcndigungsfristdetails", "properties": {"frist": {"type": "string", "description": "K\u00fcndigungsfrist (z.B. 1 Monat)"}, "frist_ende": {"type": "string", "format": "date", "description": "Ende der K\u00fcndigungsfrist (YYYY-MM-DD)"}}, "required": ["frist"]}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^\\d{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$", "nullable": true}, "mwst_satz": {"type": "string", "pattern": "^\\d+(\\.\\d{1,2})?$", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}, "klauseln": {"type": "array", "description": "Wesentliche Abo-Bedingungen (Laufzeit, K\u00fcndigungsfrist, Preisanpassung, etc.)", "items": {"type": "object", "properties": {"titel": {"type": "string"}, "inhalt": {"type": "string"}}}}}, "required": ["anbieter", "abo_name", "preis", "intervall"]}',
    '"anbieter, abo_name, preis, intervall, beginn, naechste_zahlung, kuendigungsfrist"',
    'Abonnement, Mitgliedschaft, Subscription, Vertrag, monatlich, jährlich, Kündigung, Kündigungsfrist, Zahlungstermin, Preis, Anbieter, Streaming, Zeitschrift, Verein, automatische Verlängerung, next payment, Vertragsbeginn, Laufzeit, Abo-Name, Gebühr, Beitrag',
    'Streaming, Zeitschriften, Vereine',
    '{"privat": {"§10 EStG": {"beschreibung": "Abonnements oder Mitgliedschaften können unter bestimmten Voraussetzungen als Vorsorgeaufwendungen oder Sonderausgaben abgesetzt werden, z. B. wenn sie beruflich veranlasst sind (z. B. Fachzeitschriften).", "anlage": "V (Vorsorgeaufwand) oder N (Sonstige Angaben)", "betrag": "Nur der beruflich veranlasste Anteil ist absetzbar, private Anteile nicht."}, "§35a EStG": {"beschreibung": "Falls das Abo Dienstleistungen im Haushalt betrifft (z. B. Reinigungsdienst-Abo), könnte eine Steuerermäßigung für haushaltsnahe Dienstleistungen in Frage kommen.", "anlage": "Haushaltsnahe Dienstleistungen (Anlage N)", "betrag": "20% der Aufwendungen, max. 4.000 € pro Jahr."}}, "beruflich": {"§4 Abs. 4 EStG": {"beschreibung": "Beruflich veranlasste Abos (z. B. Fachzeitschriften, Software-Lizenzen) sind als Betriebsausgaben absetzbar.", "anlage": "Anlage EÜR oder S (bei Selbstständigen)"}}}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
ON CONFLICT (id) DO UPDATE SET category=EXCLUDED.category, display_name=EXCLUDED.display_name, description=EXCLUDED.description, schema=EXCLUDED.schema, field_descriptions=EXCLUDED.field_descriptions, classify_keywords=EXCLUDED.classify_keywords, typical_senders=EXCLUDED.typical_senders, steuer_relevanz=EXCLUDED.steuer_relevanz, priority=EXCLUDED.priority, enabled=EXCLUDED.enabled, version=EXCLUDED.version, source=EXCLUDED.source, notes=EXCLUDED.notes;

INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'benefit_notification',
    'C. Versicherungen',
    'Leistungsmitteilung',
    'Eine Leistungsmitteilung informiert Versicherte über erbrachte Leistungen durch ihre Versicherung oder Krankenkasse, z.B. Erstattungen für Arztbesuche, Medikamente oder Therapien. Sie dient als Nachweis für erhaltene Zahlungen und unterscheidet sich von Rechnungen oder Beitragsbescheiden durch den Fokus auf ausgezahlte oder verrechnete Leistungen innerhalb eines bestimmten Zeitraums. Typisch für gesetzliche und private Krankenversicherungen sowie andere Leistungsversicherungen (z. B. Pflege-, Unfallversicherung).',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "benefit_notification", "description": "Schema f\u00fcr Leistungsmitteilungen", "type": "object", "properties": {"versicherungsnummer": {"type": "string", "description": "Versicherungsnummer des Versicherten"}, "leistungsart": {"type": "string", "description": "Art der Leistung (z.B. Krankengeld, Mutterschaftsgeld)"}, "betrag": {"type": "string", "pattern": "^\\d{1,10}\\.\\d{2}$", "description": "Gesamtbetrag der Leistung"}, "zeitraum": {"type": "object", "properties": {"von": {"type": "string", "format": "date", "description": "Startdatum des Leistungszeitraums (YYYY-MM-DD)"}, "bis": {"type": "string", "format": "date", "description": "Enddatum des Leistungszeitraums (YYYY-MM-DD)"}}, "required": ["von", "bis"]}, "abrechnungspositionen": {"type": "array", "items": {"type": "object", "properties": {"position": {"type": "string", "description": "Bezeichnung der Abrechnungsposition"}, "betrag": {"type": "string", "pattern": "^\\d{1,10}\\.\\d{2}$", "description": "Betrag der Abrechnungsposition"}, "anzahl_tage": {"type": "integer", "description": "Anzahl der Tage f\u00fcr diese Position (falls zutreffend)"}, "tagessatz": {"type": "string", "pattern": "^\\d{1,10}\\.\\d{2}$", "description": "Tagessatz f\u00fcr diese Position (falls zutreffend)"}}, "required": ["position", "betrag"]}}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^\\d{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "pattern": "^\\d{1,10}\\.\\d{2}$", "nullable": true}, "mwst_satz": {"type": "string", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}}, "required": ["versicherungsnummer", "leistungsart", "betrag", "zeitraum"]}',
    '"versicherungsnummer, leistungsart, betrag, zeitraum, abrechnungspositionen"',
    'Leistungsmitteilung, Leistungsbescheid, Erstattung, Kostenerstattung, Abrechnung, Versicherungsleistung, Krankenkasse, Versicherung, Rechnungsbetrag, gezahlter Betrag, Zeitraum, Abrechnungspositionen, Versicherungsnummer, Leistungsart, Erstattungsbetrag, Verrechnung, Beleg, Nachweis, health insurance reimbursement, benefit notification, payment confirmation',
    'Versicherungen, Krankenkassen',
    '{"einkommensteuer": {"paragraphen": "§10 Abs. 1 Nr. 3 EStG (Vorsorgeaufwendungen), §33 EStG (außergewöhnliche Belastungen)", "anlage": "V (Vorsorgeaufwand), ggf. Anlage N (bei Werbungskosten) oder Hauptvordruck (außergewöhnliche Belastungen)"}}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
