INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'insurance_claim',
    'C. Versicherungen',
    'Schadensmeldung',
    'Eine Schadensmeldung ist ein Dokument, das von einem Versicherungsnehmer an seine Versicherung gesendet wird, um einen Schaden zu melden und eine Regulierung zu beantragen. Es enthält Details zum Schadensereignis wie Datum, Ort, Beschreibung und geschätzte Schadenshöhe. Im Gegensatz zu einer Police oder Beitragsrechnung dient dieses Dokument ausschließlich der Schadensabwicklung und ist oft der erste Schritt im Leistungsprozess der Versicherung.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "insurance_claim", "description": "Schadensmeldung für Versicherungsansprüche", "type": "object", "properties": {"schadennummer": {"description": "Eindeutige Nummer des Schadensfalls", "type": "string"}, "datum": {"description": "Datum des Schadensereignisses (YYYY-MM-DD)", "type": "string", "format": "date"}, "ort": {"description": "Ort des Schadensereignisses", "type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "default": "DE"}}, "required": ["strasse", "plz", "ort"]}, "beschreibung": {"description": "Beschreibung des Schadenshergangs", "type": "string"}, "schadenshoehe": {"description": "Höhe des Schadens (Betrag mit 2 Dezimalstellen)", "type": "string", "pattern": "^\\d+\\.\\d{2}$"}, "zeugen": {"description": "Liste der Zeugen", "type": "array", "items": {"type": "object", "properties": {"name": {"type": "string"}, "kontakt": {"type": "string", "description": "Telefonnummer im E.164-Format"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "default": "DE"}}, "required": ["strasse", "plz", "ort"]}}, "required": ["name"]}}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean", "default": false}, "steuerrelevanz_hinweis": {"type": "string", "default": null}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "default": null}, "steuerjahr": {"type": "string", "pattern": "^\\d{4}$", "default": null}, "mwst_ausgewiesen": {"type": "boolean", "default": false}, "mwst_betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$", "default": null}, "mwst_satz": {"type": "string", "default": null}, "aktenzeichen": {"type": "string", "default": null}, "dokumenten_id": {"type": "string", "default": null}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}, "positionen": {"type": "array", "description": "Einzelne Schadenspositionen des Versicherungsfalls", "items": {"type": "object", "properties": {"beschreibung": {"type": "string"}, "betrag": {"type": "string"}}}}, "objekt_adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "default": "DE"}}, "description": "Schadenort/Liegenschaft"}}, "required": ["schadennummer", "datum", "ort", "beschreibung"]}',
    '"{\"schadennummer\": \"Eindeutige Identifikationsnummer des Schadensfalls, vergeben von der Versicherung oder dem Versicherungsnehmer. Format: Alphanumerisch, oft mit Pr\u00e4fix (z.B. ''S-2023-45678''). Wichtig f\u00fcr die Zuordnung des Schadens in der Steuererkl\u00e4rung, falls Kosten geltend gemacht werden.\", \"datum\": \"Datum des Schadensereignisses im Format TT.MM.JJJJ oder JJJJ-MM-TT. Relevant f\u00fcr die zeitliche Einordnung des Schadens und ggf. f\u00fcr die steuerliche Ber\u00fccksichtigung im richtigen Veranlagungszeitraum.\", \"ort\": \"Ort des Schadensereignisses, inkl. Adresse oder geografischer Beschreibung (z.B. ''Autobahn A3, km 123''). Wichtig f\u00fcr die Pr\u00fcfung der Versicherungsdeckung (z.B. regionale Einschr\u00e4nkungen).\", \"beschreibung\": \"Detaillierte Beschreibung des Schadenshergangs und der Sch\u00e4den (z.B. ''Unfall mit Fremdfahrzeug, Heckaufprall, Besch\u00e4digung der Sto\u00dfstange und R\u00fcckleuchten''). Wichtig f\u00fcr die steuerliche Bewertung, ob der Schaden als au\u00dfergew\u00f6hnliche Belastung geltend gemacht werden kann.\", \"schadenshoehe\": \"Gesch\u00e4tzte oder tats\u00e4chliche Schadensh\u00f6he in Euro (z.B. ''1.250,00 \u20ac''). Format: Dezimalzahl mit zwei Nachkommastellen. Relevant f\u00fcr die steuerliche Ber\u00fccksichtigung, falls der Schaden nicht vollst\u00e4ndig erstattet wird und als au\u00dfergew\u00f6hnliche Belastung geltend gemacht werden soll.\"}"',
    'Schadensmeldung, Schadenmeldung, Schadensfall, Schadensnummer, Schadensdatum, Schadensort, Schadensbeschreibung, Schadenshöhe, Zeugen, Versicherung, Regulierung, claim, damage report, incident report, insurance claim, witness, damage amount, policy number, Versicherungsnummer, Unfallbericht, Leistungsantrag',
    'Versicherungsnehmer',
    '{"einkommensteuer": {"paragraph": "§33 EStG (außergewöhnliche Belastungen)", "anlage": "Anlage Vorsorgeaufwand (nur bei bestimmten Versicherungsarten wie Kranken- oder Pflegeversicherung) oder ggf. als außergewöhnliche Belastung in der Haupterklärung", "hinweis": "Nur relevant, wenn der Schaden nicht vollständig von der Versicherung erstattet wird und der verbleibende Betrag als außergewöhnliche Belastung geltend gemacht werden kann. Die Schadenshöhe selbst ist nicht direkt absetzbar, aber ggf. entstandene Kosten (z.B. Reparaturkosten) können unter bestimmten Bedingungen berücksichtigt werden. Maximal abziehbarer Betrag richtet sich nach der zumutbaren Belastung (§33 Abs. 3 EStG)."}}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
