INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'insurance_policy',
    'C. Versicherungen',
    'Versicherungspolice/-schein',
    'Eine Versicherungspolice oder ein Versicherungsschein ist das zentrale Dokument eines Versicherungsvertrags, das die vertraglichen Vereinbarungen zwischen Versicherungsnehmer und Versicherer festhält. Es wird bei Abschluss einer neuen Versicherung oder bei Änderungen (z. B. Tarifanpassungen) ausgestellt. Im Gegensatz zu Rechnungen oder Schadensmeldungen enthält die Police keine Zahlungsaufforderungen oder Leistungsanträge, sondern die grundlegenden Vertragsdetails wie Laufzeit, Beitrag und Leistungsumfang.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "insurance_policy", "description": "Versicherungspolice/-schein", "type": "object", "properties": {"versicherungsnummer": {"type": "string", "description": "Eindeutige Nummer der Versicherungspolice"}, "nehmer": {"type": "object", "description": "Versicherungsnehmer", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort", "land"]}, "geburtsdatum": {"type": "string", "format": "date"}, "steuernummer": {"type": "string", "description": "Steuernummer des Versicherungsnehmers, falls relevant"}}, "required": ["name", "adresse"]}, "gesellschaft": {"type": "object", "description": "Versicherungsgesellschaft", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort", "land"]}}, "required": ["name", "adresse"]}, "tarif": {"type": "string", "description": "Name oder Bezeichnung des Tarifs"}, "beitrag": {"type": "object", "description": "Beitragsinformationen", "properties": {"betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}, "waehrung": {"type": "string", "pattern": "^[A-Z]{3}$"}, "zahlungsweise": {"type": "string", "enum": ["monatlich", "vierteljaehrlich", "halbjaehrlich", "jaehrlich"]}}, "required": ["betrag", "waehrung"]}, "leistungsumfang": {"type": "array", "description": "Beschreibung der Leistungen", "items": {"type": "object", "properties": {"leistungsart": {"type": "string"}, "beschreibung": {"type": "string"}, "betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}, "waehrung": {"type": "string", "pattern": "^[A-Z]{3}$"}}, "required": ["leistungsart"]}}, "beginn": {"type": "string", "format": "date", "description": "Beginn der Versicherung"}, "ende": {"type": "string", "format": "date", "description": "Ende der Versicherung"}, "kuendigungsfrist": {"type": "string", "description": "Kündigungsfrist in Tagen oder als Datum"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "vorsorgeaufwendungen", null], "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^\\d{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$", "nullable": true}, "mwst_satz": {"type": "string", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}, "objekt_adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "default": "DE"}}, "description": "Versichertes Objekt/Risikoadresse (bei Gebaeude/Hausrat)"}}, "required": ["versicherungsnummer", "nehmer", "gesellschaft", "tarif", "beitrag", "beginn", "_meta"]}',
    '"versicherungsnummer, nehmer, gesellschaft, tarif, beitrag, leistungsumfang, beginn, ende, kuendigungsfrist"',
    'Versicherungspolice, Versicherungsschein, Police, Versicherungsvertrag, Vertragsnummer, Versicherungsnummer, Beitrag, Prämie, Tarif, Leistungsumfang, Laufzeit, Kündigungsfrist, Versicherungsnehmer, Versicherungsgesellschaft, Beginn, Ende, insurance policy, policy number, premium, coverage, term, insurer, policyholder',
    'Versicherungen',
    '{"private_haushalte": {"haftpflicht": {"relevanz": "teilweise", "paragraphen": "§10 Abs. 1 Nr. 3a EStG (Vorsorgeaufwendungen)", "anlage": "Vorsorgeaufwand (Anlage Vorsorgeaufwand)", "grenzen": "Bis zu 2.800 € (Selbstständige: 2.400 €) als Sonderausgaben absetzbar, sofern nicht bereits durch andere Vorsorgeaufwendungen ausgeschöpft."}, "risikolebensversicherung": {"relevanz": "teilweise", "paragraphen": "§10 Abs. 1 Nr. 3a EStG (Vorsorgeaufwendungen)", "anlage": "Vorsorgeaufwand (Anlage Vorsorgeaufwand)", "grenzen": "Wie Haftpflicht, aber nur der Risikoanteil (nicht der Sparanteil) ist absetzbar."}, "berufsunfaehigkeitsversicherung": {"relevanz": "ja", "paragraphen": "§10 Abs. 1 Nr. 3a EStG (Vorsorgeaufwendungen)", "anlage": "Vorsorgeaufwand (Anlage Vorsorgeaufwand)", "grenzen": "Volle Absetzbarkeit im Rahmen der Vorsorgeaufwendungen (2.800 €/2.400 € Grenze)."}, "krankenversicherung": {"relevanz": "ja", "paragraphen": "§10 Abs. 1 Nr. 3 EStG (Vorsorgeaufwendungen)", "anlage": "Vorsorgeaufwand (Anlage Vorsorgeaufwand)", "grenzen": "Grundsätzlich voll absetzbar, aber mit komplexen Regelungen für Basiskranken- und Pflegepflichtversicherung (vorrangig vor anderen Vorsorgeaufwendungen)."}, "unfallversicherung": {"relevanz": "nein", "hinweis": "Nur absetzbar, wenn sie berufliche Risiken abdeckt (z. B. für Selbstständige)."}, "hausratversicherung": {"relevanz": "nein"}, "kfz_versicherung": {"relevanz": "teilweise", "paragraphen": "§4 Abs. 4 EStG (bei beruflicher Nutzung), §9 Abs. 1 Satz 3 Nr. 2 EStG (Werbungskosten)", "anlage": "Anlage N (bei beruflicher Nutzung), sonst nicht absetzbar"}}}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
ON CONFLICT (id) DO UPDATE SET category=EXCLUDED.category, display_name=EXCLUDED.display_name, description=EXCLUDED.description, schema=EXCLUDED.schema, field_descriptions=EXCLUDED.field_descriptions, classify_keywords=EXCLUDED.classify_keywords, typical_senders=EXCLUDED.typical_senders, steuer_relevanz=EXCLUDED.steuer_relevanz, priority=EXCLUDED.priority, enabled=EXCLUDED.enabled, version=EXCLUDED.version, source=EXCLUDED.source, notes=EXCLUDED.notes;

INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'reimbursement_notice',
    'C. Versicherungen',
    'Beihilfebescheid',
    'Ein Beihilfebescheid ist die Erstattungsmitteilung einer Beihilfestelle (Bund, Land, Kommune) für Gesundheitskosten von Beamten und deren Angehörigen. Enthält Antragsnummer, Beihilfenummer, einzelne Positionen mit Beihilfesatz und Erstattungsbetrag. Nicht verwechseln mit Leistungsmitteilung einer Krankenkasse (benefit_notification) oder einer Arztrechnung (invoice).',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "reimbursement_notice", "description": "Beihilfebescheid f\u00fcr Erstattungen", "type": "object", "properties": {"aktenzeichen": {"type": "string", "description": "Aktenzeichen des Bescheids"}, "beihilfenummer": {"type": "string", "description": "Nummer der Beihilfe"}, "antragsdatum": {"type": "string", "format": "date", "description": "Datum des Antrags (YYYY-MM-DD)"}, "positionen": {"type": "array", "description": "Liste der Positionen im Bescheid", "items": {"type": "object", "properties": {"leistungsart": {"type": "string", "description": "Art der Leistung"}, "betrag_brutto": {"type": "string", "pattern": "^\\d+\\.\\d{2}$", "description": "Bruttobetrag der Position (z.B. 49.99)"}, "beihilfefaehiger_anteil": {"type": "string", "pattern": "^\\d+\\.\\d{2}$", "description": "Beihilfef\u00e4higer Anteil der Position (z.B. 49.99)"}, "erstattungsbetrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$", "description": "Erstattungsbetrag der Position (z.B. 49.99)"}, "mwst_betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$", "description": "Mehrwertsteuerbetrag der Position (z.B. 49.99)"}, "mwst_satz": {"type": "string", "description": "Mehrwertsteuersatz der Position (z.B. 19%)"}}, "required": ["leistungsart", "betrag_brutto"]}}, "erstattungsbetrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$", "description": "Gesamter Erstattungsbetrag (z.B. 49.99)"}, "eigenanteil": {"type": "string", "pattern": "^\\d+\\.\\d{2}$", "description": "Eigenanteil des Antragstellers (z.B. 49.99)"}, "beihilfesatz": {"type": "string", "description": "Beihilfesatz in Prozent (z.B. 50%)"}, "rechtsmittelbelehrung": {"type": "string", "description": "Text der Rechtsmittelbelehrung"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean", "description": "Gibt an, ob das Dokument steuerrelevant ist"}, "steuerrelevanz_hinweis": {"type": "string", "description": "Hinweis zur Steuerrelevanz", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "description": "Kategorie der Steuerrelevanz", "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^\\d{4}$", "description": "Steuerjahr (YYYY)", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean", "description": "Gibt an, ob Mehrwertsteuer ausgewiesen ist"}, "mwst_betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$", "description": "Gesamtbetrag der Mehrwertsteuer (z.B. 49.99)", "nullable": true}, "mwst_satz": {"type": "string", "description": "Mehrwertsteuersatz (z.B. 19%)", "nullable": true}, "aktenzeichen": {"type": "string", "description": "Aktenzeichen des Dokuments", "nullable": true}, "dokumenten_id": {"type": "string", "description": "Eindeutige ID des Dokuments", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}}, "required": ["aktenzeichen", "beihilfenummer", "antragsdatum", "erstattungsbetrag", "_meta"]}',
    '"{\"aktenzeichen\": \"Eindeutige Referenznummer des Bescheids, oft im Format ''Jahr-Nummer'' (z.B. ''2023-12345''). Wichtig f\u00fcr die Zuordnung und Nachverfolgung des Bescheids, z.B. bei R\u00fcckfragen oder Widerspr\u00fcchen.\", \"beihilfenummer\": \"Pers\u00f6nliche Identifikationsnummer des Beihilfeempf\u00e4ngers, oft lebenslang g\u00fcltig. Wichtig f\u00fcr die Identifikation des Empf\u00e4ngers und die Zuordnung zu weiteren Beihilfeantr\u00e4gen.\", \"antragsdatum\": \"Datum, an dem der Beihilfeantrag gestellt wurde (Format: TT.MM.JJJJ oder JJJJ-MM-TT). Relevant f\u00fcr die zeitliche Zuordnung der erstatteten Kosten und die Pr\u00fcfung von Fristen.\", \"positionen\": \"Liste der erstatteten Positionen mit Details wie Datum der Leistung, Art der Leistung (z.B. Arztbesuch, Medikamente), Rechnungsbetrag, erstatteter Betrag und ggf. Grund f\u00fcr K\u00fcrzungen. Wichtig f\u00fcr die steuerliche Erfassung der Eigenanteile und die \u00dcberpr\u00fcfung der Erstattung.\", \"erstattungsbetrag\": \"Gesamtsumme, die von der Beihilfestelle erstattet wird (Format: W\u00e4hrung, z.B. ''123,45 EUR''). Wichtig f\u00fcr die Gegen\u00fcberstellung mit den tats\u00e4chlichen Ausgaben und die Ermittlung des steuerrelevanten Eigenanteils.\", \"eigenanteil\": \"Gesamtsumme, die vom Beihilfeempf\u00e4nger selbst getragen werden muss (Format: W\u00e4hrung, z.B. ''50,00 EUR''). Dieser Betrag ist steuerrelevant und kann als au\u00dfergew\u00f6hnliche Belastung geltend gemacht werden.\", \"beihilfesatz\": \"Prozentualer Anteil, zu dem die Beihilfe die Kosten \u00fcbernimmt (z.B. ''50%'', ''70%''). Wichtig f\u00fcr die Berechnung des Eigenanteils und die Pr\u00fcfung der korrekten Erstattung.\"}"',
    'Beihilfebescheid,Beihilfe,Beihilfenummer,Antragsnummer,Beihilfefestsetzung,BVO NRW,Beihilfestelle,CC Beihilfe,beihilfefähig,Eigenanteil,Beihilfesatz,Erstattungsbetrag,Heilbehandlung,ärztlich verordnet,Aufwendungen,Bemessungssatz,Festsetzung,Landeshauptstadt Düsseldorf Amt für Zentrale Dienste',
    'Beihilfestelle',
    '{"paragraphen": "§33 EStG (außergewöhnliche Belastungen)", "anlage": "Keine direkte Anlage, aber relevant für die Ermittlung der abziehbaren außergewöhnlichen Belastungen in der Hauptsteuererklärung (Anlage „Außergewöhnliche Belastungen“).", "hinweise": "Der Eigenanteil (nicht erstatteter Betrag) kann unter bestimmten Voraussetzungen als außergewöhnliche Belastung nach §33 EStG geltend gemacht werden. Die Summe der Eigenanteile aus allen Beihilfebescheiden des Jahres ist relevant. Maximal abziehbar sind die Aufwendungen, die die zumutbare Belastung nach §33 Abs. 3 EStG übersteigen."}',
    10,
    1,
    1,
    'mistral_batch',
    NULL
)
ON CONFLICT (id) DO UPDATE SET category=EXCLUDED.category, display_name=EXCLUDED.display_name, description=EXCLUDED.description, schema=EXCLUDED.schema, field_descriptions=EXCLUDED.field_descriptions, classify_keywords=EXCLUDED.classify_keywords, typical_senders=EXCLUDED.typical_senders, steuer_relevanz=EXCLUDED.steuer_relevanz, priority=EXCLUDED.priority, enabled=EXCLUDED.enabled, version=EXCLUDED.version, source=EXCLUDED.source, notes=EXCLUDED.notes;

INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'application',
    'D. Steuern & Behörden',
    'Antrag',
    'Ein Antrag ist ein formelles Schreiben eines Bürgers an eine Behörde, um eine bestimmte Leistung, Genehmigung oder Entscheidung zu beantragen. Dies kann z.B. ein Antrag auf Kindergeld, Wohngeld, BAföG, Elterngeld oder eine Baugenehmigung sein. Im Gegensatz zu Bescheiden oder Bescheinigungen wird hier aktiv eine behördliche Handlung oder Entscheidung erbeten, und das Dokument ist vom Antragsteller verfasst.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "application", "description": "Schema f\u00fcr Antragsdokumente", "type": "object", "properties": {"antragsteller": {"type": "object", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort"]}, "geburtsdatum": {"type": "string", "format": "date"}, "telefon": {"type": "string"}, "email": {"type": "string", "format": "email"}}, "required": ["name"]}, "behoerde": {"type": "object", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort"]}, "aktenzeichen": {"type": "string"}}, "required": ["name"]}, "antragsgegenstand": {"type": "string"}, "datum": {"type": "string", "format": "date"}, "aktenzeichen": {"type": "string"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^[0-9]{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$", "nullable": true}, "mwst_satz": {"type": "string", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}}, "required": ["antragsteller", "behoerde", "antragsgegenstand", "datum"]}',
    '"{\"antragsteller\": \"Name und Adresse der Person, die den Antrag stellt. Wichtig f\u00fcr die Zuordnung des Antrags zur richtigen Person, z.B. bei sp\u00e4teren R\u00fcckfragen oder Bescheiden. Format: Vorname Nachname, Stra\u00dfe Hausnummer, PLZ Ort. Beispiel: Max Mustermann, Musterstra\u00dfe 1, 12345 Musterstadt.\", \"behoerde\": \"Name und Adresse der Beh\u00f6rde, an die der Antrag gerichtet ist. Wichtig f\u00fcr die korrekte Zuordnung und Weiterleitung des Antrags. Format: Bezeichnung der Beh\u00f6rde, ggf. Abteilung, Stra\u00dfe Hausnummer, PLZ Ort. Beispiel: Stadt Musterstadt, Amt f\u00fcr Soziales, Rathausplatz 1, 12345 Musterstadt.\", \"antragsgegenstand\": \"Kurze Beschreibung des Antragsgegenstands, z.B. ''Antrag auf Kindergeld'' oder ''Antrag auf Baugenehmigung''. Wichtig f\u00fcr die inhaltliche Einordnung und sp\u00e4tere Bearbeitung. Format: Freitext, oft fett oder unterstrichen hervorgehoben. Beispiel: Antrag auf Gew\u00e4hrung von Elterngeld ab dem 01.01.2024.\", \"datum\": \"Datum, an dem der Antrag gestellt oder unterschrieben wurde. Wichtig f\u00fcr Fristen und die zeitliche Einordnung des Antrags. Format: TT.MM.JJJJ. Beispiel: 15.03.2024.\", \"aktenzeichen\": \"Aktenzeichen oder Gesch\u00e4ftszeichen der Beh\u00f6rde, falls bereits vorhanden. Wichtig f\u00fcr die sp\u00e4tere Zuordnung und Bearbeitung des Antrags. Format: Kombination aus Buchstaben und Zahlen, oft mit Schr\u00e4gstrichen oder Bindestrichen. Beispiel: 55.12-012345/2024.\"}"',
    'Antrag, Antragsteller, Behörde, Antragsgegenstand, Aktenzeichen, hiermit beantrage ich, Antrag auf, Genehmigung, Bewilligung, Antragsformular, Unterschrift, Antragsdatum, Antragseingang, Antrag auf Gewährung, Antrag auf Leistungen, Antrag auf Erstattung, application, request, authority, subject, file reference',
    'Bürger → Behörde',
    NULL,
    0,
    1,
    1,
    'mistral_batch',
    'Häufige Verwechslungen: Anträge können mit Bescheiden (z.B. Bewilligungsbescheid) oder Bescheinigungen (z.B. Steuerbescheinigung) verwechselt werden, da diese oft ähnliche Inhalte haben. Ein Antrag ist jedoch immer vom Bürger verfasst und richtet sich an eine Behörde, während Bescheide und Bescheinigungen von Behörden an Bürger gerichtet sind. Tipp: Achte auf Formulierungen wie ''hiermit beantrage ich'' oder ''ich stelle Antrag auf'', die typisch für Anträge sind.'
)
