INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'court_decision',
    'D. Steuern & Behörden',
    'Gerichtsbeschluss',
    'Ein Gerichtsbeschluss ist eine Entscheidung eines Gerichts in einem rechtlichen Verfahren, die formal festgehalten wird. Er kommt in verschiedenen Rechtsbereichen vor, z. B. im Zivil-, Straf- oder Verwaltungsrecht, und enthält verbindliche Anordnungen oder Urteile. Im Gegensatz zu einem Urteil ist ein Beschluss oft kürzer gefasst und kann ohne mündliche Verhandlung ergehen, z. B. in Eilverfahren oder bei Zwischenentscheidungen.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "court_decision", "description": "Gerichtsbeschluss", "type": "object", "properties": {"gericht": {"type": "string", "description": "Name des Gerichts"}, "aktenzeichen": {"type": "string", "description": "Aktenzeichen des Verfahrens"}, "datum": {"type": "string", "format": "date", "description": "Datum des Beschlusses (YYYY-MM-DD)"}, "beteiligte": {"type": "array", "description": "Liste der beteiligten Parteien", "items": {"type": "object", "properties": {"name": {"type": "string", "description": "Name der Partei"}, "rolle": {"type": "string", "description": "Rolle der Partei (z.B. Kl\u00e4ger, Beklagter, Antragsteller)"}, "adresse": {"type": "object", "description": "Adresse der Partei", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "description": "L\u00e4ndercode (ISO 3166-1 alpha-2)"}}, "required": ["strasse", "plz", "ort"]}}, "required": ["name", "rolle"]}}, "tenor": {"type": "string", "description": "Tenor des Beschlusses"}, "rechtsmittelbelehrung": {"type": "string", "description": "Rechtsmittelbelehrung"}, "rechtsmittelfrist": {"type": "string", "description": "Frist f\u00fcr Rechtsmittel (z.B. ''1 Monat ab Zustellung'')"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^[0-9]{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$", "nullable": true}, "mwst_satz": {"type": "string", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}}, "required": ["gericht", "aktenzeichen", "datum", "_meta"]}',
    '"{\"gericht\": \"Name und Sitz des Gerichts, das den Beschluss erlassen hat, z. B. ''Amtsgericht M\u00fcnchen''. Wichtig f\u00fcr die Zuordnung des Dokuments und ggf. f\u00fcr die Einordnung der Zust\u00e4ndigkeit.\", \"aktenzeichen\": \"Eindeutige Kennung des Verfahrens, z. B. ''42 C 1234/23''. Wichtig f\u00fcr die Identifikation des Falls und ggf. f\u00fcr Nachweise in weiteren rechtlichen oder steuerlichen Angelegenheiten.\", \"datum\": \"Datum, an dem der Beschluss erlassen wurde, im Format TT.MM.JJJJ. Relevant f\u00fcr die Fristenberechnung (z. B. Rechtsmittelfrist) und f\u00fcr die zeitliche Einordnung des Dokuments.\", \"beteiligte[]\": \"Liste der am Verfahren beteiligten Parteien, z. B. Kl\u00e4ger, Beklagte, Antragsteller oder Beigeladene. Enth\u00e4lt Namen und ggf. Rollen im Verfahren. Wichtig f\u00fcr die Identifikation der Betroffenen und f\u00fcr Nachweise in weiteren Verfahren.\", \"tenor\": \"Kernaussage des Beschlusses, z. B. ''Der Antrag wird abgelehnt.'' oder ''Die Beschwerde wird zur\u00fcckgewiesen.''. Enth\u00e4lt die verbindliche Entscheidung des Gerichts. Wichtig f\u00fcr die inhaltliche Bewertung des Dokuments.\", \"rechtsmittelbelehrung\": \"Hinweis des Gerichts, ob und wie gegen den Beschluss Rechtsmittel eingelegt werden k\u00f6nnen, z. B. ''Gegen diesen Beschluss kann binnen zwei Wochen Beschwerde eingelegt werden.''. Wichtig f\u00fcr die Fristenwahrung und weitere rechtliche Schritte.\", \"rechtsmittelfrist\": \"Frist, innerhalb derer Rechtsmittel eingelegt werden k\u00f6nnen, z. B. ''2 Wochen ab Zustellung''. Wichtig f\u00fcr die Einhaltung rechtlicher Fristen und ggf. f\u00fcr die Dokumentation in weiteren Verfahren.\"}"',
    'Gerichtsbeschluss, Beschluss, Tenor, Aktenzeichen, Rechtsmittelbelehrung, Rechtsmittelfrist, Gericht, Beteiligte, Entscheidung, Urteil, §329 ZPO, §567 ZPO, §128 VwGO, court decision, order, judgment, case number, appeal, deadline, parties involved',
    'Gerichte',
    'null (Grundsätzlich nicht direkt steuerrelevant, kann aber in Einzelfällen für Nachweise im Rahmen von Steuerstreitigkeiten oder außergewöhnlichen Belastungen (§33 EStG) relevant sein, z. B. bei Prozesskosten oder Schadensersatzforderungen mit steuerlicher Auswirkung.)',
    0,
    1,
    1,
    'mistral_batch',
    'Häufige Verwechslungen: Gerichtsbeschlüsse können mit Urteilen verwechselt werden, sind aber oft kürzer und ohne mündliche Verhandlung ergangen. Auch Vergleiche oder Verfügungen können ähnlich aussehen, enthalten aber keine verbindliche Entscheidung. Sonderfälle: Beschlüsse in Eilverfahren (z. B. einstweilige Anordnungen) oder Zwischenentscheidungen (z. B. Beweisbeschlüsse) haben oft spezifische Formulierungen. Tipp: Achten Sie auf die Begriffe ''Beschluss'', ''Tenor'' und ''Rechtsmittelbelehrung'' zur eindeutigen Identifikation.'
)
ON CONFLICT (id) DO UPDATE SET category=EXCLUDED.category, display_name=EXCLUDED.display_name, description=EXCLUDED.description, schema=EXCLUDED.schema, field_descriptions=EXCLUDED.field_descriptions, classify_keywords=EXCLUDED.classify_keywords, typical_senders=EXCLUDED.typical_senders, steuer_relevanz=EXCLUDED.steuer_relevanz, priority=EXCLUDED.priority, enabled=EXCLUDED.enabled, version=EXCLUDED.version, source=EXCLUDED.source, notes=EXCLUDED.notes;

INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'court_judgment',
    'D. Steuern & Behörden',
    'Urteil',
    'Ein gerichtliches Urteil ist die offizielle Entscheidung eines Gerichts in einem Rechtsstreit, die den Sachverhalt feststellt und rechtliche Konsequenzen ausspricht. Es kommt nach Abschluss eines Gerichtsverfahrens vor und unterscheidet sich von anderen behördlichen Dokumenten wie Bescheiden oder Beschlüssen durch seine bindende Wirkung und detaillierte rechtliche Begründung. Urteile sind besonders relevant bei zivilrechtlichen, arbeitsrechtlichen oder steuerrechtlichen Streitigkeiten.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "court_judgment", "description": "Schema f\u00fcr die Extraktion von Gerichtsurteilen", "type": "object", "properties": {"gericht": {"type": "string", "description": "Name des Gerichts"}, "aktenzeichen": {"type": "string", "description": "Aktenzeichen des Verfahrens"}, "datum": {"type": "string", "format": "date", "description": "Datum des Urteils im Format YYYY-MM-DD"}, "klaeger": {"type": "object", "description": "Informationen zum Kl\u00e4ger", "properties": {"name": {"type": "string", "description": "Name des Kl\u00e4gers"}, "adresse": {"type": "object", "description": "Adresse des Kl\u00e4gers", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "description": "L\u00e4ndercode nach ISO 3166-1 alpha-2"}}, "required": ["strasse", "plz", "ort"]}, "vertreter": {"type": "string", "description": "Name des Vertreters (z.B. Anwalt)"}}, "required": ["name"]}, "beklagter": {"type": "object", "description": "Informationen zum Beklagten", "properties": {"name": {"type": "string", "description": "Name des Beklagten"}, "adresse": {"type": "object", "description": "Adresse des Beklagten", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "description": "L\u00e4ndercode nach ISO 3166-1 alpha-2"}}, "required": ["strasse", "plz", "ort"]}, "vertreter": {"type": "string", "description": "Name des Vertreters (z.B. Anwalt)"}}, "required": ["name"]}, "streitwert": {"type": "string", "description": "Streitwert in Euro mit 2 Dezimalstellen (z.B. 1500.00)"}, "tenor": {"type": "string", "description": "Urteilstenor (Entscheidung des Gerichts)"}, "tatbestand_zusammenfassung": {"type": "string", "description": "Zusammenfassung des Tatbestands"}, "gruende_zusammenfassung": {"type": "string", "description": "Zusammenfassung der Urteilsgr\u00fcnde"}, "rechtsmittelbelehrung": {"type": "string", "description": "Rechtsmittelbelehrung"}, "rechtskraeftig": {"type": "boolean", "description": "Gibt an, ob das Urteil rechtskr\u00e4ftig ist"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^[0-9]{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "nullable": true}, "mwst_satz": {"type": "string", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}, "entscheidungspunkte": {"type": "array", "description": "Einzelne Entscheidungspunkte / Tenor des Urteils", "items": {"type": "object", "properties": {"punkt_nr": {"type": "string"}, "inhalt": {"type": "string"}}}}}, "required": ["gericht", "aktenzeichen", "datum", "klaeger", "beklagter", "tenor", "rechtskraeftig", "_meta"]}',
    '"gericht, aktenzeichen, datum, klaeger, beklagter, streitwert, tenor, tatbestand_zusammenfassung, gruende_zusammenfassung, rechtsmittelbelehrung, rechtskraeftig"',
    'Urteil, Gericht, Aktenzeichen, Tenor, Tatbestand, Entscheidungsgründe, Rechtskraft, Rechtsmittelbelehrung, Kläger, Beklagter, Streitwert, gerichtliche Entscheidung, judgment, court decision, plaintiff, defendant, legal force, appeal, reasons for decision, case number',
    'Gerichte',
    '{"relevanz": "teilweise", "details": {"§33 EStG": {"beschreibung": "Außergewöhnliche Belastungen: Prozesskosten können unter bestimmten Voraussetzungen als außergewöhnliche Belastungen abgesetzt werden, wenn sie zwangsläufig entstanden sind (z.B. bei existenziellen Rechtsstreitigkeiten).", "anlage": "Anlage N (Zeile 67-70)", "hinweis": "Nur absetzbar, wenn der Streitwert oder die Kosten nicht von der Gegenseite erstattet werden und der Rechtsstreit nicht mutwillig geführt wurde."}, "§4 Abs. 4 EStG": {"beschreibung": "Betriebsausgaben: Prozesskosten im Zusammenhang mit betrieblichen Einkünften (z.B. Arbeitsrecht, Handelsrecht) können als Betriebsausgaben abgesetzt werden.", "anlage": "Anlage EÜR oder Anlage G/S (je nach Einkunftsart)"}, "§9 EStG": {"beschreibung": "Werbungskosten: Prozesskosten im Zusammenhang mit nichtselbstständiger Arbeit (z.B. Kündigungsschutzklage) können als Werbungskosten abgesetzt werden."}}}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
ON CONFLICT (id) DO UPDATE SET category=EXCLUDED.category, display_name=EXCLUDED.display_name, description=EXCLUDED.description, schema=EXCLUDED.schema, field_descriptions=EXCLUDED.field_descriptions, classify_keywords=EXCLUDED.classify_keywords, typical_senders=EXCLUDED.typical_senders, steuer_relevanz=EXCLUDED.steuer_relevanz, priority=EXCLUDED.priority, enabled=EXCLUDED.enabled, version=EXCLUDED.version, source=EXCLUDED.source, notes=EXCLUDED.notes;

INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'court_order',
    'D. Steuern & Behörden',
    'Mahnbescheid',
    'Ein gerichtlicher Mahnbescheid des Amtsgerichts im Mahnverfahren. Fordert den Antragsgegner zur Zahlung auf. 14-tägige Widerspruchsfrist nach Zustellung. Nicht verwechseln mit außergerichtlicher Mahnung (dunning_notice) oder Vollstreckungsbescheid (enforcement_order).',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "court_order", "description": "Mahnbescheid", "type": "object", "properties": {"gericht": {"type": "object", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "default": "DE"}}, "required": ["strasse", "plz", "ort"]}}, "required": ["name", "adresse"]}, "aktenzeichen": {"type": "string"}, "antragsteller": {"type": "object", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "default": "DE"}}, "required": ["strasse", "plz", "ort"]}, "vertreter": {"type": "object", "properties": {"name": {"type": "string"}, "kanzlei": {"type": "string"}}, "required": ["name"]}}, "required": ["name", "adresse"]}, "antragsgegner": {"type": "object", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "default": "DE"}}, "required": ["strasse", "plz", "ort"]}}, "required": ["name", "adresse"]}, "hauptforderung": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}, "zinsen": {"type": "object", "properties": {"betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}, "satz": {"type": "string"}, "zeitraum": {"type": "object", "properties": {"von": {"type": "string", "format": "date"}, "bis": {"type": "string", "format": "date"}}, "required": ["von", "bis"]}}, "required": ["betrag"]}, "kosten": {"type": "object", "properties": {"gerichtskosten": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}, "anwaltskosten": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}, "sonstige_kosten": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}}}, "gesamtforderung": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}, "zugestellt_am": {"type": "string", "format": "date"}, "widerspruchsfrist": {"type": "string", "format": "date"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean", "default": false}, "steuerrelevanz_hinweis": {"type": "string", "default": null}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "default": null}, "steuerjahr": {"type": "string", "pattern": "^\\d{4}$", "default": null}, "mwst_ausgewiesen": {"type": "boolean", "default": false}, "mwst_betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$", "default": null}, "mwst_satz": {"type": "string", "default": null}, "aktenzeichen": {"type": "string", "default": null}, "dokumenten_id": {"type": "string", "default": null}}, "required": ["steuerrelevant", "steuerrelevanz_hinweis", "steuer_kategorie", "steuerjahr", "mwst_ausgewiesen", "mwst_betrag", "mwst_satz"]}, "anordnungen": {"type": "array", "description": "Einzelne Anordnungen des Beschlusses", "items": {"type": "object", "properties": {"punkt_nr": {"type": "string"}, "inhalt": {"type": "string"}}}}}, "required": ["gericht", "aktenzeichen", "antragsteller", "antragsgegner", "hauptforderung", "gesamtforderung", "zugestellt_am", "widerspruchsfrist", "_meta"]}',
    '"{\"gericht\": \"Zust\u00e4ndiges Amtsgericht\", \"aktenzeichen\": \"Aktenzeichen des Mahnverfahrens\", \"antragsteller\": \"Gl\u00e4ubiger\", \"antragsgegner\": \"Schuldner\", \"hauptforderung\": \"Betrag Hauptforderung\", \"zinsen\": \"Zinsforderung\", \"kosten\": \"Gerichts-/Anwaltskosten\", \"gesamtforderung\": \"Summe\", \"zugestellt_am\": \"Ab hier l\u00e4uft Widerspruchsfrist\", \"widerspruchsfrist\": \"i.d.R. 14 Tage\"}"',
    'Mahnbescheid,Amtsgericht,Mahnverfahren,Antragsteller,Antragsgegner,Hauptforderung,Widerspruch,Widerspruchsfrist,Zustellung,gerichtlich',
    'Amtsgericht',
    'Gerichtskosten ggf. als Werbungskosten absetzbar bei beruflichem Bezug. Zinsen auf Forderungen sind Kapitalerträge → Anlage KAP.',
    0,
    1,
    1,
    'mistral_batch',
    'ACHTUNG: Widerspruchsfrist beachten! Nach Ablauf → Vollstreckungsbescheid. Verwechslungsgefahr: dunning_notice (außergerichtlich), enforcement_order (nach Fristablauf).'
)
