INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'court_summons',
    'D. Steuern & Behörden',
    'Ladung/Terminbestimmung',
    'Eine Ladung oder Terminbestimmung ist eine offizielle Aufforderung eines Gerichts, zu einem bestimmten Termin zu erscheinen. Sie kommt in Zivil-, Straf-, Familien- oder Verwaltungsgerichtsverfahren vor und enthält konkrete Angaben zum Gericht, Aktenzeichen, Datum, Uhrzeit und Ort der Verhandlung. Im Gegensatz zu bloßen Benachrichtigungen oder Anhörungseinladungen anderer Behörden ist sie rechtlich bindend und mit Fristen sowie möglichen Konsequenzen bei Nichterscheinen verbunden.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "court_summons", "description": "Schema f\u00fcr eine gerichtliche Ladung/Terminbestimmung", "type": "object", "properties": {"gericht": {"type": "string", "description": "Name des Gerichts"}, "aktenzeichen": {"type": "string", "description": "Aktenzeichen der Rechtssache"}, "termin_datum": {"type": "string", "format": "date", "description": "Datum des Termins im Format YYYY-MM-DD"}, "termin_uhrzeit": {"type": "string", "pattern": "^([01]?[0-9]|2[0-3]):[0-5][0-9]$", "description": "Uhrzeit des Termins im Format HH:MM"}, "saal": {"type": "string", "description": "Saal oder Raum des Termins"}, "parteien": {"type": "array", "items": {"type": "object", "properties": {"name": {"type": "string", "description": "Name der Partei"}, "rolle": {"type": "string", "description": "Rolle der Partei (z.B. Kl\u00e4ger, Beklagter, Zeuge)", "enum": ["kl\u00e4ger", "beklagter", "zeuge", "sachverst\u00e4ndiger", "vertreter", "sonstige"]}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "default": "DE"}}, "required": ["strasse", "plz", "ort"]}}, "required": ["name", "rolle"]}}, "gegenstand": {"type": "string", "description": "Gegenstand der Verhandlung"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean", "default": false}, "steuerrelevanz_hinweis": {"type": "string", "default": null}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "default": null}, "steuerjahr": {"type": "string", "pattern": "^[0-9]{4}$", "default": null}, "mwst_ausgewiesen": {"type": "boolean", "default": false}, "mwst_betrag": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$", "default": null}, "mwst_satz": {"type": "string", "default": null}, "aktenzeichen": {"type": "string", "default": null}, "dokumenten_id": {"type": "string", "default": null}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}}, "required": ["gericht", "aktenzeichen", "termin_datum", "gegenstand"]}',
    '"{\"gericht\": \"Name und Sitz des Gerichts (z. B. ''Amtsgericht M\u00fcnchen''). Wichtig f\u00fcr die Identifikation der zust\u00e4ndigen Instanz und ggf. sp\u00e4tere Korrespondenz.\", \"aktenzeichen\": \"Eindeutige Kennung des Verfahrens (z. B. ''123 C 456/24''). Wird f\u00fcr alle weiteren Schrifts\u00e4tze und Anfragen ben\u00f6tigt, um das Verfahren zuzuordnen.\", \"termin_datum\": \"Datum des Gerichtstermins im Format TT.MM.JJJJ (z. B. ''15.10.2024''). Entscheidend f\u00fcr die Einhaltung der Ladungsfrist und Planung.\", \"termin_uhrzeit\": \"Uhrzeit des Termins im Format HH:MM (z. B. ''10:00''). Wichtig f\u00fcr die p\u00fcnktliche Wahrnehmung des Termins.\", \"saal\": \"Bezeichnung des Verhandlungssaals oder Raums (z. B. ''Saal 301''). Hilft bei der Orientierung im Gerichtsgeb\u00e4ude.\", \"parteien[]\": \"Liste der beteiligten Parteien (Kl\u00e4ger, Beklagte, Antragsteller, Antragsgegner etc.), oft mit Namen und Rollen. Wichtig f\u00fcr die Identifikation der eigenen Position im Verfahren und der Gegenseite.\", \"gegenstand\": \"Kurze Beschreibung des Verfahrensgegenstands (z. B. ''Klage auf Zahlung von Mietr\u00fcckst\u00e4nden''). Gibt Aufschluss \u00fcber den Grund der Ladung und den Verfahrensstand.\"}"',
    'Ladung, Terminbestimmung, Gerichtstermin, Vorladung, gerichtliche Ladung, court summons, hearing notice, Aktenzeichen, Termin, Saal, Parteien, Verhandlungstermin, Zustellungsurkunde, §214 ZPO, §216 ZPO, Ladungsfrist, Rechtsstreit, Klageverfahren, Hauptverhandlung, mündliche Verhandlung',
    'Gerichte',
    NULL,
    0,
    1,
    1,
    'mistral_batch',
    'Häufige Verwechslungen: 1) Mit bloßen Anhörungseinladungen von Behörden (z. B. Finanzamt, Ordnungsamt), die keine rechtliche Bindung haben. 2) Mit Fristsetzungen oder Aufforderungen zur Stellungnahme, die keine mündliche Verhandlung vorsehen. 3) Mit Strafbefehlen oder Urteilen, die bereits eine Entscheidung enthalten. Tipp: Ladungen enthalten immer ein konkretes Datum, eine Uhrzeit und einen Ort für eine mündliche Verhandlung sowie das Wort ''Ladung'' oder ''Terminbestimmung''. Bei Unsicherheit über die Rechtsfolgen eines Nichterscheinens sollte rechtlicher Rat eingeholt werden.'
)
