INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'enforcement_order',
    'D. Steuern & Behörden',
    'Vollstreckungsbescheid',
    'Ein Vollstreckungsbescheid ist ein gerichtlicher Beschluss, der die Zwangsvollstreckung aus einem bereits titulierten Anspruch (z. B. einem Mahnbescheid) ermöglicht. Er wird vom Amtsgericht erlassen, wenn der Schuldner nach Erhalt eines Mahnbescheids nicht widersprochen oder gezahlt hat. Im Gegensatz zum Mahnbescheid ist der Vollstreckungsbescheid ein vollstreckbarer Titel, der direkte Maßnahmen wie Pfändungen ermöglicht.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "Vollstreckungsbescheid", "description": "Schema f\u00fcr die Extraktion von Daten aus einem Vollstreckungsbescheid", "type": "object", "properties": {"gericht": {"type": "object", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "default": "DE"}}, "required": ["strasse", "plz", "ort"]}}, "required": ["name"]}, "aktenzeichen": {"type": "string"}, "glaeubiger": {"type": "object", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "default": "DE"}}, "required": ["strasse", "plz", "ort"]}, "kontakt": {"type": "object", "properties": {"telefon": {"type": "string"}, "email": {"type": "string", "format": "email"}}}}, "required": ["name"]}, "schuldner": {"type": "object", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "default": "DE"}}, "required": ["strasse", "plz", "ort"]}, "geburtsdatum": {"type": "string", "format": "date"}, "kontakt": {"type": "object", "properties": {"telefon": {"type": "string"}, "email": {"type": "string", "format": "email"}}}}, "required": ["name"]}, "titel_betrag": {"type": "object", "properties": {"betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}, "waehrung": {"type": "string", "default": "EUR"}, "urspruenglicher_betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}, "zinsen": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}, "kosten": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}}, "required": ["betrag", "waehrung"]}, "vollstreckbar_seit": {"type": "string", "format": "date"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean", "default": false}, "steuerrelevanz_hinweis": {"type": "string", "default": null}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "default": null}, "steuerjahr": {"type": "string", "pattern": "^\\d{4}$", "default": null}, "mwst_ausgewiesen": {"type": "boolean", "default": false}, "mwst_betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$", "default": null}, "mwst_satz": {"type": "string", "default": null}, "aktenzeichen": {"type": "string", "default": null}, "dokumenten_id": {"type": "string", "default": null}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}}, "required": ["gericht", "aktenzeichen", "glaeubiger", "schuldner", "titel_betrag", "vollstreckbar_seit", "_meta"]}',
    '"{\"gericht\": \"Name des Amtsgerichts, das den Vollstreckungsbescheid erlassen hat. Beispiel: ''Amtsgericht M\u00fcnchen''. Wichtig f\u00fcr die Identifikation des zust\u00e4ndigen Gerichts bei weiteren Schritten.\", \"aktenzeichen\": \"Eindeutige Kennung des Verfahrens beim Gericht. Beispiel: ''12 M 12345/23''. Wird f\u00fcr alle weiteren Korrespondenzen und Vollstreckungsma\u00dfnahmen ben\u00f6tigt.\", \"glaeubiger\": \"Name und Adresse der Person oder Institution, die den Anspruch geltend macht. Beispiel: ''Finanzamt Berlin, Musterstra\u00dfe 1, 10115 Berlin''. Wichtig f\u00fcr die Kl\u00e4rung der Forderungsherkunft.\", \"schuldner\": \"Name und Adresse der Person, gegen die der Vollstreckungsbescheid erlassen wurde. Beispiel: ''Max Mustermann, Musterweg 2, 80331 M\u00fcnchen''. Wichtig f\u00fcr die Zuordnung des Dokuments zum Haushalt.\", \"titel_betrag\": \"Der im Vollstreckungsbescheid festgelegte Geldbetrag, der vollstreckt werden soll. Format: W\u00e4hrung und Betrag (z. B. ''1.234,56 EUR''). Wichtig f\u00fcr die H\u00f6he der Forderung und m\u00f6gliche Ratenzahlungsvereinbarungen.\", \"vollstreckbar_seit\": \"Datum, ab dem der Vollstreckungsbescheid vollstreckbar ist. Format: TT.MM.JJJJ (z. B. ''15.05.2024''). Wichtig f\u00fcr Fristen und m\u00f6gliche Rechtsmittel.\"}"',
    'Vollstreckungsbescheid, Zwangsvollstreckung, Amtsgericht, vollstreckbarer Titel, Mahnverfahren, Gläubiger, Schuldner, Aktenzeichen, Titelbetrag, Vollstreckung, Gerichtsvollzieher, Pfändung, § 699 ZPO, § 700 ZPO, enforcement order, enforcement notice, court order, debt collection, bailiff',
    'Amtsgericht',
    NULL,
    0,
    1,
    1,
    'mistral_batch',
    'Häufig wird der Vollstreckungsbescheid mit einem Mahnbescheid verwechselt. Der entscheidende Unterschied ist, dass der Vollstreckungsbescheid bereits ein vollstreckbarer Titel ist, während der Mahnbescheid erst nach Widerspruch oder Fristablauf zum Vollstreckungsbescheid wird. Achten Sie auf Formulierungen wie ''Vollstreckungsbescheid'' oder ''vollstreckbarer Titel'' im Dokument. Bei Erhalt sollte umgehend gehandelt werden, da sonst Pfändungen oder andere Zwangsmaßnahmen drohen. Im Zweifel rechtlichen Rat einholen.'
)
ON CONFLICT (id) DO UPDATE SET category=EXCLUDED.category, display_name=EXCLUDED.display_name, description=EXCLUDED.description, schema=EXCLUDED.schema, field_descriptions=EXCLUDED.field_descriptions, classify_keywords=EXCLUDED.classify_keywords, typical_senders=EXCLUDED.typical_senders, steuer_relevanz=EXCLUDED.steuer_relevanz, priority=EXCLUDED.priority, enabled=EXCLUDED.enabled, version=EXCLUDED.version, source=EXCLUDED.source, notes=EXCLUDED.notes;

INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'enforcement_title',
    'D. Steuern & Behörden',
    'Vollstreckbarer Titel',
    'Ein vollstreckbarer Titel ist ein amtliches Dokument, das einen Anspruch rechtskräftig feststellt und die Grundlage für Zwangsvollstreckungsmaßnahmen bildet. Es wird von Gerichten oder Notaren ausgestellt, nachdem ein gerichtliches Verfahren abgeschlossen oder ein notarieller Vergleich geschlossen wurde. Im Gegensatz zu einfachen Rechnungen oder Mahnbescheiden ermöglicht dieses Dokument direkte Vollstreckungshandlungen wie Pfändungen oder Zwangsversteigerungen.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "enforcement_title", "description": "Vollstreckbarer Titel", "type": "object", "properties": {"gericht": {"type": "string", "description": "Name des Gerichts, das den Titel ausgestellt hat"}, "aktenzeichen": {"type": "string", "description": "Aktenzeichen des Titels"}, "glaeubiger": {"type": "object", "description": "Informationen zum Gl\u00e4ubiger", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort"]}, "kontakt": {"type": "object", "properties": {"telefon": {"type": "string"}, "email": {"type": "string", "format": "email"}}}}, "required": ["name"]}, "schuldner": {"type": "object", "description": "Informationen zum Schuldner", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort"]}, "geburtsdatum": {"type": "string", "format": "date"}, "kontakt": {"type": "object", "properties": {"telefon": {"type": "string"}, "email": {"type": "string", "format": "email"}}}}, "required": ["name"]}, "titel_art": {"type": "string", "description": "Art des Titels (z.B. Urteil, Vollstreckungsbescheid, Vergleich)"}, "betrag": {"type": "string", "description": "Vollstreckungsbetrag mit 2 Dezimalstellen", "pattern": "^\\d+\\.\\d{2}$"}, "waehrung": {"type": "string", "description": "W\u00e4hrung des Betrags (ISO 4217)", "pattern": "^[A-Z]{3}$"}, "vollstreckungsklausel": {"type": "boolean", "description": "Gibt an, ob eine Vollstreckungsklausel vorhanden ist"}, "datum": {"type": "string", "format": "date", "description": "Datum des Titels (YYYY-MM-DD)"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^\\d{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$", "nullable": true}, "mwst_satz": {"type": "string", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}}, "required": ["gericht", "aktenzeichen", "glaeubiger", "schuldner", "titel_art", "betrag", "vollstreckungsklausel", "datum", "_meta"]}',
    '"{\"gericht\": \"Name des Gerichts oder der notariellen Stelle, die den Titel ausgestellt hat. Beispiel: ''Amtsgericht M\u00fcnchen''. Wichtig f\u00fcr die Identifikation der ausstellenden Beh\u00f6rde und ggf. f\u00fcr sp\u00e4tere rechtliche Schritte.\", \"aktenzeichen\": \"Eindeutige Kennung des Verfahrens beim Gericht oder Notar. Beispiel: ''42 C 1234/23''. Wichtig f\u00fcr die Zuordnung des Titels zu einem spezifischen Verfahren und f\u00fcr Vollstreckungsma\u00dfnahmen.\", \"glaeubiger\": \"Name und Adresse der Person oder Institution, die den Anspruch geltend macht. Beispiel: ''Max Mustermann, Musterstra\u00dfe 1, 12345 Berlin''. Relevant f\u00fcr die Identifikation des Anspruchsberechtigten.\", \"schuldner\": \"Name und Adresse der Person oder Institution, gegen die der Anspruch besteht. Beispiel: ''Erika Musterfrau, Beispielweg 2, 54321 K\u00f6ln''. Relevant f\u00fcr die Identifikation des Vollstreckungsschuldners.\", \"titel_art\": \"Art des Titels, z.B. ''Urteil'', ''Vergleich'', ''Vollstreckungsbescheid'' oder ''notarielle Urkunde''. Beispiel: ''Urteil''. Wichtig f\u00fcr die rechtliche Einordnung und die Art der m\u00f6glichen Vollstreckungsma\u00dfnahmen.\", \"betrag\": \"Der festgestellte Geldbetrag, der vollstreckt werden soll. Beispiel: ''5000.00''. Wichtig f\u00fcr die H\u00f6he der Forderung und ggf. f\u00fcr die Berechnung von Zinsen oder Kosten.\", \"waehrung\": \"W\u00e4hrung des festgestellten Betrags. Beispiel: ''EUR''. Wichtig f\u00fcr die korrekte Angabe des Forderungsbetrags, insbesondere bei internationalen Titeln.\", \"vollstreckungsklausel\": \"Best\u00e4tigung, dass der Titel vollstreckbar ist. Beispiel: ''Vorstehende Ausfertigung wird dem Gl\u00e4ubiger zum Zwecke der Zwangsvollstreckung erteilt.''. Wichtig f\u00fcr die Legitimation von Vollstreckungsma\u00dfnahmen.\", \"datum\": \"Datum der Ausstellung des Titels oder der Vollstreckungsklausel. Beispiel: ''2023-10-15''. Relevant f\u00fcr die Fristenberechnung und die G\u00fcltigkeit des Titels.\"}"',
    'Vollstreckungstitel, vollstreckbarer Titel, Vollstreckungsklausel, Zwangsvollstreckung, Gericht, Notar, Aktenzeichen, Gläubiger, Schuldner, Titelart, Urteil, Vergleich, Vollstreckungsbescheid, Pfändung, §794 ZPO, enforcement order, enforcement title, writ of execution, court order, enforcement clause',
    'Gericht, Notar',
    NULL,
    0,
    1,
    1,
    'mistral_batch',
    'Häufige Verwechslungen können mit Mahnbescheiden oder einfachen Rechnungen auftreten, die jedoch keine Vollstreckungsklausel enthalten. Ein vollstreckbarer Titel ist erst mit der Vollstreckungsklausel wirksam. Achten Sie auf Formulierungen wie ''zum Zwecke der Zwangsvollstreckung'' oder ''Vollstreckungsklausel''. Sonderfälle sind Titel aus dem Ausland, die ggf. einer Vollstreckbarerklärung in Deutschland bedürfen.'
)
