INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'fee_notice',
    'D. Steuern & Behörden',
    'Gebührenbescheid',
    'Ein Gebührenbescheid ist ein behördliches Dokument, das die Erhebung von Gebühren für öffentliche Leistungen oder Verwaltungsakte (z. B. Ausstellung von Dokumenten, Genehmigungen, Bußgelder) formal ankündigt oder bestätigt. Er unterscheidet sich von Steuerbescheiden durch die direkte Zuordnung zu einer konkreten Leistung oder Handlung der Behörde und enthält typischerweise eine Rechtsgrundlage (z. B. Gebührensatzung). Im Gegensatz zu Rechnungen privater Dienstleister ist er hoheitlich und mit Fristen für Widerspruch oder Zahlung versehen.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "fee_notice", "description": "Geb\u00fchrenbescheid", "type": "object", "properties": {"aktenzeichen": {"type": "string", "description": "Aktenzeichen des Geb\u00fchrenbescheids"}, "gebuehrenart": {"type": "string", "description": "Art der Geb\u00fchr (z.B. Verwaltungsgeb\u00fchr, Bearbeitungsgeb\u00fchr)"}, "betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$", "description": "Geb\u00fchrenbetrag in Euro mit zwei Dezimalstellen"}, "faellig_am": {"type": "string", "format": "date", "description": "F\u00e4lligkeitsdatum der Geb\u00fchr (YYYY-MM-DD)"}, "rechtsgrundlage": {"type": "string", "description": "Rechtsgrundlage der Geb\u00fchrenerhebung"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean", "description": "Gibt an, ob das Dokument steuerrelevant ist"}, "steuerrelevanz_hinweis": {"type": "string", "description": "Hinweis zur Steuerrelevanz", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "description": "Steuerkategorie des Dokuments", "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^\\d{4}$", "description": "Steuerjahr (YYYY)", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean", "description": "Gibt an, ob Mehrwertsteuer ausgewiesen ist"}, "mwst_betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$", "description": "Mehrwertsteuerbetrag in Euro mit zwei Dezimalstellen", "nullable": true}, "mwst_satz": {"type": "string", "description": "Mehrwertsteuersatz (z.B. ''19'')", "nullable": true}, "aktenzeichen": {"type": "string", "description": "Aktenzeichen des Dokuments", "nullable": true}, "dokumenten_id": {"type": "string", "description": "Eindeutige ID des Dokuments", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}, "positionen": {"type": "array", "description": "Einzelpositionen des Geb\u00fchrenbescheids (Verwaltungsgeb\u00fchr, Auslagen, etc.)", "items": {"type": "object", "properties": {"beschreibung": {"type": "string"}, "betrag": {"type": "string"}, "rechtsgrundlage": {"type": "string"}}}}}, "required": ["aktenzeichen", "gebuehrenart", "betrag", "faellig_am", "_meta"]}',
    '"{\"aktenzeichen\": {\"beschreibung\": \"Eindeutige Referenznummer des Bescheids, oft alphanumerisch (z. B. ''4711/2023''). Wichtig f\u00fcr R\u00fcckfragen oder Widerspruch bei der Beh\u00f6rde. Format: Meist 5\u201315 Zeichen, kann Schr\u00e4gstriche oder Bindestriche enthalten.\", \"beispiel\": \"2023-012345/KA\"}}"',
    'Gebührenbescheid, Gebührenrechnung, Kostenbescheid, Verwaltungsgebühr, Benutzungsgebühr, aktenzeichen, rechtsgrundlage, fällig am, zahlbar bis, Widerspruchsfrist, Gebührensatzung, Kommunalabgabe, Bescheid, Behörde, Gemeinde, Stadt, Landkreis, Bußgeld, Ordnungsamt, fee notice, administrative fee, due date, legal basis, file reference',
    'Kommunen, Behörden',
    '{"allgemein": "Gebührenbescheide sind in der Regel **nicht direkt steuerlich absetzbar**, da es sich um Gegenleistungen für behördliche Leistungen handelt. Ausnahmen:", "ausnahmen": [{"fall": "Gebühren für berufliche Zwecke (z. B. Gewerbeanmeldung, Berufsausübungserlaubnis)", "paragraph": "§ 4 Abs. 4 EStG (Betriebsausgaben) oder § 9 EStG (Werbungskosten)", "anlage": "Anlage N (Zeile 46: ''Sonstige Werbungskosten'') oder Anlage EÜR (bei Selbstständigen)", "hinweis": "Nachweis der beruflichen Veranlassung erforderlich (z. B. durch Berufsbezeichnung oder Tätigkeitsbeschreibung)."}, {"fall": "Gebühren im Zusammenhang mit haushaltsnahen Dienstleistungen oder Handwerkerleistungen (z. B. Baugenehmigung für Modernisierung)", "paragraph": "§ 35a EStG (Steuerermäßigung für Handwerkerleistungen)", "anlage": "Anlage Haushaltsnahe Aufwendungen (Zeile 5–7)", "grenze": "Maximal 1.200 € pro Jahr (20 % von 6.000 € Handwerkerleistungen), nur Arbeitskosten (keine Materialkosten).", "hinweis": "Gebühr muss direkt mit der Leistung verknüpft sein (z. B. Genehmigung für Dachsanierung)."}, {"fall": "Gebühren für außergewöhnliche Belastungen (z. B. Behindertenausweis, Pflegegrad-Bescheid)", "paragraph": "§ 33 EStG (Außergewöhnliche Belastungen)", "anlage": "Anlage Außergewöhnliche Belastungen (Zeile 6–44)", "hinweis": "Nur absetzbar, wenn die Gebühr zwangsläufig und notwendig war (z. B. für medizinische Hilfsmittel)."}], "nicht_absetzbar": "Gebühren für private Zwecke (z. B. Kfz-Zulassung, Personalausweis, Hundesteuer, Bußgelder)."}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
