INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'fine_notice',
    'D. Steuern & Behörden',
    'Bußgeldbescheid/Knöllchen',
    'Ein Bußgeldbescheid (umgangssprachlich ''Knöllchen'') ist ein amtliches Dokument, das bei Verstößen gegen die Straßenverkehrsordnung (StVO) oder andere Ordnungswidrigkeiten ausgestellt wird. Es enthält die Details des Verstoßes, das festgesetzte Bußgeld sowie mögliche Punkte in Flensburg. Im Gegensatz zu einer Verwarnung ist ein Bußgeldbescheid mit höheren Kosten und oft mit Punkten verbunden, während ein Strafbefehl schwerwiegendere Verstöße betrifft.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "fine_notice", "description": "Schema f\u00fcr die Extraktion von Daten aus einem Bu\u00dfgeldbescheid/Kn\u00f6llchen", "type": "object", "properties": {"aktenzeichen": {"type": "string", "description": "Aktenzeichen des Bu\u00dfgeldbescheids"}, "datum_versto\u00df": {"type": "string", "format": "date", "description": "Datum des Versto\u00dfes im Format YYYY-MM-DD"}, "ort": {"type": "string", "description": "Ort des Versto\u00dfes"}, "versto\u00df": {"type": "string", "description": "Beschreibung des Versto\u00dfes"}, "bu\u00dfgeld": {"type": "string", "pattern": "^\\d+\\.\\d{2}$", "description": "Bu\u00dfgeldbetrag als String mit zwei Dezimalstellen"}, "punkte": {"type": "integer", "description": "Anzahl der Punkte in Flensburg"}, "einspruchsfrist": {"type": "string", "format": "date", "description": "Frist f\u00fcr den Einspruch im Format YYYY-MM-DD"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean", "description": "Gibt an, ob das Dokument steuerrelevant ist"}, "steuerrelevanz_hinweis": {"type": "string", "description": "Hinweis zur Steuerrelevanz", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^\\d{4}$", "description": "Steuerjahr im Format YYYY", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean", "description": "Gibt an, ob Mehrwertsteuer ausgewiesen ist"}, "mwst_betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$", "description": "Mehrwertsteuerbetrag als String mit zwei Dezimalstellen", "nullable": true}, "mwst_satz": {"type": "string", "description": "Mehrwertsteuersatz", "nullable": true}, "aktenzeichen": {"type": "string", "description": "Aktenzeichen des Dokuments", "nullable": true}, "dokumenten_id": {"type": "string", "description": "Eindeutige ID des Dokuments", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"], "additionalProperties": false}, "positionen": {"type": "array", "description": "Einzelpositionen des Bu\u00dfgeldbescheids (Bu\u00dfgeld, Geb\u00fchren, Auslagen, etc.)", "items": {"type": "object", "properties": {"beschreibung": {"type": "string"}, "betrag": {"type": "string"}}}}}, "required": ["aktenzeichen", "datum_versto\u00df", "ort", "versto\u00df", "bu\u00dfgeld", "_meta"], "additionalProperties": false}',
    '"{\"aktenzeichen\": \"Amtliches Aktenzeichen des Bu\u00dfgeldbescheids, meist alphanumerisch (z. B. ''OWi 12345/2023''). Wichtig f\u00fcr Einspr\u00fcche oder Nachfragen beim Absender. Format: String.\", \"datum_versto\u00df\": \"Datum, an dem der Versto\u00df begangen wurde. Format: ISO-8601 (YYYY-MM-DD). Relevant f\u00fcr die Fristberechnung (Einspruchsfrist beginnt mit Zustellung, nicht mit Versto\u00dfdatum).\", \"ort\": \"Ort des Versto\u00dfes, oft mit Stra\u00dfe, Hausnummer oder Kilometerangabe (z. B. ''A5, km 123,4''). Format: String. Wichtig f\u00fcr die Pr\u00fcfung der Zust\u00e4ndigkeit des ausstellenden Amtes.\", \"versto\u00df\": \"Beschreibung des Versto\u00dfes (z. B. ''Geschwindigkeit \u00fcberschritten: 25 km/h innerorts''). Format: String. Enth\u00e4lt oft den genauen Tatbestand nach StVO oder anderen Gesetzen (z. B. ''\u00a741 Abs. 1 i. V. m. Anlage 2 StVO'').\", \"bu\u00dfgeld\": \"H\u00f6he des festgesetzten Bu\u00dfgelds in Euro (z. B. 100.00). Format: Number (Dezimaltrennzeichen: Punkt). Bei beruflicher Veranlassung m\u00f6glicherweise teilweise steuerrelevant (siehe ''steuer_relevanz'').\", \"punkte\": \"Anzahl der Punkte im Fahreignungsregister (Flensburg), die f\u00fcr den Versto\u00df vergeben werden (z. B. 1, 2 oder 3). Format: Integer. Relevant f\u00fcr die Fahrerlaubnis (z. B. drohender Entzug ab 8 Punkten).\"}"',
    'Bußgeldbescheid, Knöllchen, Ordnungswidrigkeit, Verstoß, Straßenverkehrsordnung, StVO, Bußgeld, Punkte, Flensburg, aktenzeichen, einspruchsfrist, datum verstoß, ort, gebührenpflichtig, Verwarnungsgeld, Polizei, Ordnungsamt, Fahrverbot, Anhörungsbogen, fine notice, penalty notice, traffic violation, driving offense',
    'Ordnungsamt, Polizei',
    '{"einordnung": "Grundsätzlich nicht steuerlich absetzbar (§12 Nr. 4 EStG), da Bußgelder als nicht abziehbare Aufwendungen gelten. Ausnahme: Bei beruflich veranlassten Verstößen (z. B. Dienstfahrten) kann unter bestimmten Umständen eine teilweise Anerkennung als Betriebsausgabe/Werbungskosten möglich sein (§4 Abs. 4 EStG), sofern der Verstoß nicht grob fahrlässig war. Dokumentation im Einzelfall erforderlich.", "anlage": null, "hinweis": "Nur in seltenen Fällen (z. B. bei beruflicher Veranlassung) relevant. Im Zweifel mit Steuerberater klären."}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
ON CONFLICT (id) DO UPDATE SET category=EXCLUDED.category, display_name=EXCLUDED.display_name, description=EXCLUDED.description, schema=EXCLUDED.schema, field_descriptions=EXCLUDED.field_descriptions, classify_keywords=EXCLUDED.classify_keywords, typical_senders=EXCLUDED.typical_senders, steuer_relevanz=EXCLUDED.steuer_relevanz, priority=EXCLUDED.priority, enabled=EXCLUDED.enabled, version=EXCLUDED.version, source=EXCLUDED.source, notes=EXCLUDED.notes;

INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'garnishment_order',
    'D. Steuern & Behörden',
    'Pfändungsbeschluss',
    'Ein Pfändungsbeschluss ist eine behördliche oder gerichtliche Anordnung zur Pfändung von Vermögenswerten (z. B. Lohn, Konten) eines Schuldners zugunsten eines Gläubigers. Er wird typischerweise vom Amtsgericht oder Finanzamt ausgestellt, wenn offene Forderungen nicht beglichen werden. Im Gegensatz zu Mahnbescheiden oder Vollstreckungsbescheiden ist der Pfändungsbeschluss bereits ein konkreter Vollstreckungstitel mit Angaben zu Gläubiger, Schuldner, Pfändungsbetrag und Drittschuldner (z. B. Arbeitgeber oder Bank).',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "garnishment_order", "description": "Pf\u00e4ndungsbeschluss", "type": "object", "properties": {"glaeubiger": {"type": "object", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort"]}, "kontakt": {"type": "object", "properties": {"telefon": {"type": "string"}, "email": {"type": "string", "format": "email"}}}}, "required": ["name", "adresse"]}, "schuldner": {"type": "object", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort"]}, "geburtsdatum": {"type": "string", "format": "date"}, "steuer_id": {"type": "string"}}, "required": ["name", "adresse"]}, "pfaendungsbetrag": {"type": "object", "properties": {"betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}, "waehrung": {"type": "string", "pattern": "^[A-Z]{3}$"}}, "required": ["betrag", "waehrung"]}, "gericht": {"type": "object", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort"]}}, "required": ["name", "adresse"]}, "aktenzeichen": {"type": "string"}, "zugestellt_am": {"type": "string", "format": "date"}, "drittschuldner": {"type": "object", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort"]}, "iban": {"type": "string"}, "bic": {"type": "string"}}, "required": ["name", "adresse"]}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^\\d{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$", "nullable": true}, "mwst_satz": {"type": "string", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}}, "required": ["glaeubiger", "schuldner", "pfaendungsbetrag", "gericht", "aktenzeichen", "zugestellt_am", "_meta"]}',
    '"{\"glaeubiger\": \"Name und Anschrift des Gl\u00e4ubigers, der die Pf\u00e4ndung veranlasst hat (z. B. Finanzamt, Inkassounternehmen, Privatperson). Wichtig f\u00fcr die Dokumentation, falls der Schuldner die Rechtm\u00e4\u00dfigkeit pr\u00fcfen oder steuerliche Auswirkungen (z. B. bei Schuldzinsen) nachweisen muss.\", \"schuldner\": \"Name und Anschrift des Schuldners, gegen den die Pf\u00e4ndung gerichtet ist. Muss mit den pers\u00f6nlichen Daten des Empf\u00e4ngers \u00fcbereinstimmen, um die G\u00fcltigkeit des Beschlusses zu best\u00e4tigen.\", \"pfaendungsbetrag\": \"Der genaue Betrag, der gepf\u00e4ndet wird (in Euro, z. B. ''1.250,00 \u20ac''). Wichtig f\u00fcr die Finanzplanung und ggf. f\u00fcr Nachweise bei Sozialleistungen oder Schuldenberatung.\", \"gericht\": \"Das ausstellende Gericht (z. B. ''Amtsgericht M\u00fcnchen'') oder die Beh\u00f6rde (z. B. ''Finanzamt Berlin''). Relevant f\u00fcr m\u00f6gliche Rechtsmittel oder Anfragen zur Pf\u00e4ndung.\", \"aktenzeichen\": \"Eindeutige Referenznummer des Pf\u00e4ndungsbeschlusses (z. B. ''M 1234/23''). Wird f\u00fcr alle weiteren Korrespondenzen mit Gericht oder Gl\u00e4ubiger ben\u00f6tigt.\", \"zugestellt_am\": \"Datum der Zustellung des Beschlusses (Format: TT.MM.JJJJ, z. B. ''15.05.2024''). Ab diesem Datum beginnt die Pf\u00e4ndung zu wirken; wichtig f\u00fcr Fristen (z. B. Widerspruch).\", \"drittschuldner\": \"Name und Anschrift des Drittschuldners (z. B. Arbeitgeber, Bank), bei dem die Pf\u00e4ndung vollstreckt wird (z. B. ''Deutsche Bank AG, Filiale Hamburg''). Entscheidend f\u00fcr die Umsetzung der Pf\u00e4ndung, da dieser den Betrag einbeh\u00e4lt und an den Gl\u00e4ubiger \u00fcberweist.\"}"',
    'Pfändungsbeschluss, Pfändung, Vollstreckung, Drittschuldner, Gläubiger, Schuldner, Pfändungsbetrag, Amtsgericht, Aktenzeichen, Zustellungsdatum, Lohnpfändung, Kontopfändung, Zwangsvollstreckung, enforcement order, garnishment, third-party debtor, court order, Finanzamt, Gerichtsvollzieher',
    'Gericht, Finanzamt',
    NULL,
    0,
    1,
    1,
    'mistral_batch',
    'Häufige Verwechslungen: Pfändungsbeschlüsse werden oft mit Mahnbescheiden oder Vollstreckungsbescheiden verwechselt – letztere sind jedoch Vorstufen und enthalten keine konkrete Pfändungsanordnung. Sonderfälle: Bei Lohnpfändungen muss der Arbeitgeber als Drittschuldner informiert werden; bei Kontopfändungen die Bank. Tipp: Pfändungsbeschlüsse sind immer an den Schuldner **und** den Drittschuldner adressiert. Bei Unklarheiten sollte umgehend eine Schuldnerberatung oder ein Anwalt kontaktiert werden, da Fristen für Widersprüche kurz sein können.'
)
