INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'lawyer_invoice',
    'D. Steuern & Behörden',
    'Anwaltsrechnung',
    'Eine Anwaltsrechnung ist eine detaillierte Kostenaufstellung für juristische Dienstleistungen, die von einer Anwaltskanzlei an ihren Mandanten gesendet wird. Sie enthält typischerweise Gebühren nach dem Rechtsanwaltsvergütungsgesetz (RVG), Auslagen und Mehrwertsteuer. Im Gegensatz zu allgemeinen Rechnungen oder Honorarnoten anderer Dienstleister sind Anwaltsrechnungen durch die spezifischen RVG-Gebührenposten und das Aktenzeichen klar identifizierbar.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "Anwaltsrechnung", "description": "Schema für die Extraktion von Daten aus Anwaltsrechnungen", "type": "object", "properties": {"anwalt": {"type": "object", "properties": {"name": {"type": "string"}, "titel": {"type": "string", "nullable": true}, "fachanwalt": {"type": "string", "nullable": true}}, "required": ["name"]}, "kanzlei": {"type": "object", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "default": "DE"}}, "required": ["strasse", "plz", "ort"]}, "telefon": {"type": "string", "nullable": true}, "fax": {"type": "string", "nullable": true}, "email": {"type": "string", "format": "email", "nullable": true}, "website": {"type": "string", "format": "uri", "nullable": true}, "steuernummer": {"type": "string", "nullable": true}, "umsatzsteuer_id": {"type": "string", "nullable": true}}, "required": ["name", "adresse"]}, "mandant": {"type": "object", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "default": "DE"}}, "required": ["strasse", "plz", "ort"]}, "kundennummer": {"type": "string", "nullable": true}}, "required": ["name", "adresse"]}, "aktenzeichen": {"type": "string"}, "rechnungsdatum": {"type": "string", "format": "date"}, "rechnungsnummer": {"type": "string"}, "gegenstandswert": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$"}, "gebuehren_nach_rvg": {"type": "array", "items": {"type": "object", "properties": {"vorgang": {"type": "string"}, "ziffer": {"type": "string"}, "beschreibung": {"type": "string"}, "einzelbetrag": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$"}, "menge": {"type": "number", "minimum": 0}, "gesamtbetrag": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$"}}, "required": ["vorgang", "ziffer", "beschreibung", "einzelbetrag", "gesamtbetrag"]}}, "auslagen": {"type": "array", "items": {"type": "object", "properties": {"beschreibung": {"type": "string"}, "betrag": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$"}, "belegnummer": {"type": "string", "nullable": true}}, "required": ["beschreibung", "betrag"]}}, "mwst": {"type": "object", "properties": {"betrag": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$"}, "satz": {"type": "string", "pattern": "^[0-9]+(\\.[0-9]{1,2})?$"}}, "required": ["betrag", "satz"]}, "gesamtbetrag": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$"}, "zahlungsbedingungen": {"type": "object", "properties": {"faelligkeitsdatum": {"type": "string", "format": "date", "nullable": true}, "zahlungsziel_tage": {"type": "integer", "minimum": 0, "nullable": true}, "skonto": {"type": "object", "properties": {"prozent": {"type": "string", "pattern": "^[0-9]+(\\.[0-9]{1,2})?$", "nullable": true}, "tage": {"type": "integer", "minimum": 0, "nullable": true}, "betrag": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$", "nullable": true}}, "nullable": true}}, "nullable": true}, "bankverbindung": {"type": "object", "properties": {"kontoinhaber": {"type": "string"}, "iban": {"type": "string", "pattern": "^[A-Z]{2}[0-9]{2}[A-Z0-9]{11,30}$"}, "bic": {"type": "string", "pattern": "^[A-Z]{6}[A-Z0-9]{2}([A-Z0-9]{3})?$", "nullable": true}, "bankname": {"type": "string"}}, "required": ["kontoinhaber", "iban", "bankname"], "nullable": true}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean", "default": true}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "default": "werbungskosten"}, "steuerjahr": {"type": "string", "pattern": "^[0-9]{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean", "default": true}, "mwst_betrag": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$", "nullable": true}, "mwst_satz": {"type": "string", "pattern": "^[0-9]+(\\.[0-9]{1,2})?$", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}, "waehrung": {"type": "string", "default": "EUR", "description": "Waehrung ISO 4217 (EUR, USD, etc.)"}}, "required": ["anwalt", "kanzlei", "mandant", "aktenzeichen", "rechnungsdatum", "rechnungsnummer", "gegenstandswert", "gebuehren_nach_rvg", "mwst", "gesamtbetrag", "_meta"]}',
    '"{\"anwalt\": \"Name des beauftragten Rechtsanwalts oder der Rechtsanw\u00e4ltin, z.B. ''Dr. Max Mustermann''. Wichtig f\u00fcr die Zuordnung der Dienstleistung und ggf. f\u00fcr die steuerliche Dokumentation.\", \"kanzlei\": \"Name und Adresse der Anwaltskanzlei, z.B. ''Mustermann & Partner Rechtsanw\u00e4lte, Musterstra\u00dfe 1, 10115 Berlin''. Relevant f\u00fcr die Identifikation des Rechnungsstellers und steuerliche Nachweispflicht.\", \"mandant\": \"Name und Adresse des Mandanten, an den die Rechnung gerichtet ist. Wichtig f\u00fcr die Zuordnung der Kosten zu einer Person oder einem Unternehmen, insbesondere bei steuerlicher Relevanz.\", \"aktenzeichen\": \"Eindeutige Kennung des Falls, z.B. ''AZ 2023-4711''. Wichtig f\u00fcr die Nachverfolgbarkeit des Mandats und die Zuordnung zu einem konkreten Rechtsfall, besonders bei mehreren Rechnungen.\", \"rechnungsdatum\": \"Datum der Rechnungsstellung im Format TT.MM.JJJJ, z.B. ''15.10.2023''. Relevant f\u00fcr die Fristenberechnung (Zahlungsziel) und die steuerliche Zuordnung zum richtigen Veranlagungszeitraum.\", \"rechnungsnummer\": \"Eindeutige Nummer der Rechnung, z.B. ''RE-2023-0471''. Wichtig f\u00fcr die Buchhaltung und steuerliche Nachweispflicht gem\u00e4\u00df \u00a714 UStG.\", \"gegenstandswert\": \"Wert des Streitgegenstands in Euro, z.B. ''5000.00''. Grundlage f\u00fcr die Berechnung der RVG-Geb\u00fchren. Bei steuerrelevanten F\u00e4llen wichtig f\u00fcr die H\u00f6he der absetzbaren Kosten.\"}"',
    'Anwaltsrechnung, Rechtsanwalt, Kanzlei, Mandant, Aktenzeichen, RVG, Gegenstandswert, Gebühren nach RVG, Auslagen, Mehrwertsteuer, Rechnungsnummer, Rechnungsdatum, Zahlungsbedingungen, Bankverbindung, Honorar, Rechtsberatung, Gerichtsverfahren, außergerichtliche Vertretung, attorney fees, legal fees, law firm invoice',
    'Anwälte',
    '{"paragraphen": "§4 Abs. 4 EStG (Betriebsausgaben), §9 EStG (Werbungskosten), §35a EStG (haushaltsnahe Dienstleistungen, falls zutreffend)", "anlage": "N (bei selbstständiger Tätigkeit), S (bei Werbungskosten), Vorsorgeaufwand (falls Teil eines Versicherungsfalls)", "absetzbar": "Gebühren und Auslagen können als Betriebsausgaben oder Werbungskosten abgesetzt werden, sofern sie beruflich veranlasst sind. Bei privaten Rechtsstreitigkeiten (z.B. Scheidung) sind die Kosten in der Regel nicht absetzbar, es sei denn, es handelt sich um außergewöhnliche Belastungen (§33 EStG). Prozesskostenhilfe oder Erstattungen durch die Gegenseite müssen berücksichtigt werden.", "hinweise": "Die Rechnung muss den formalen Anforderungen des §14 UStG entsprechen, um steuerlich geltend gemacht werden zu können. Bei gemischter Nutzung (beruflich/privat) ist eine Aufteilung erforderlich."}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
ON CONFLICT (id) DO UPDATE SET category=EXCLUDED.category, display_name=EXCLUDED.display_name, description=EXCLUDED.description, schema=EXCLUDED.schema, field_descriptions=EXCLUDED.field_descriptions, classify_keywords=EXCLUDED.classify_keywords, typical_senders=EXCLUDED.typical_senders, steuer_relevanz=EXCLUDED.steuer_relevanz, priority=EXCLUDED.priority, enabled=EXCLUDED.enabled, version=EXCLUDED.version, source=EXCLUDED.source, notes=EXCLUDED.notes;

INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'legal_brief',
    'D. Steuern & Behörden',
    'Schriftsatz',
    'Ein Schriftsatz ist ein formelles juristisches Dokument, das von Anwälten im Rahmen eines Gerichtsverfahrens oder einer rechtlichen Auseinandersetzung verfasst wird. Es enthält Anträge, Forderungen oder Stellungnahmen und wird an Gerichte, gegnerische Parteien oder Mandanten gesendet. Im Gegensatz zu behördlichen Bescheiden oder Steuerdokumenten ist es rein prozessualer Natur und dient der rechtlichen Kommunikation zwischen Parteien oder mit dem Gericht.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "legal_brief", "description": "Schriftsatz", "type": "object", "properties": {"anwalt": {"type": "object", "properties": {"name": {"type": "string"}, "titel": {"type": "string", "nullable": true}, "telefon": {"type": "string", "pattern": "^\\+[0-9]{8,15}$", "nullable": true}, "email": {"type": "string", "format": "email", "nullable": true}}, "required": ["name"]}, "kanzlei": {"type": "object", "properties": {"name": {"type": "string"}, "strasse": {"type": "string"}, "plz": {"type": "string", "pattern": "^[0-9]{5}$"}, "ort": {"type": "string"}, "land": {"type": "string", "pattern": "^[A-Z]{2}$"}}, "required": ["name", "strasse", "plz", "ort", "land"]}, "mandant": {"type": "object", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string", "pattern": "^[0-9]{5}$"}, "ort": {"type": "string"}, "land": {"type": "string", "pattern": "^[A-Z]{2}$"}}, "required": ["strasse", "plz", "ort", "land"]}, "telefon": {"type": "string", "pattern": "^\\+[0-9]{8,15}$", "nullable": true}, "email": {"type": "string", "format": "email", "nullable": true}}, "required": ["name", "adresse"]}, "gegner": {"type": "object", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string", "pattern": "^[0-9]{5}$"}, "ort": {"type": "string"}, "land": {"type": "string", "pattern": "^[A-Z]{2}$"}}, "required": ["strasse", "plz", "ort", "land"]}, "telefon": {"type": "string", "pattern": "^\\+[0-9]{8,15}$", "nullable": true}, "email": {"type": "string", "format": "email", "nullable": true}}, "required": ["name", "adresse"]}, "gericht": {"type": "object", "properties": {"name": {"type": "string"}, "abteilung": {"type": "string", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string", "pattern": "^[0-9]{5}$"}, "ort": {"type": "string"}, "land": {"type": "string", "pattern": "^[A-Z]{2}$"}}, "required": ["strasse", "plz", "ort", "land"]}}, "required": ["name", "adresse"]}, "aktenzeichen": {"type": "string"}, "datum": {"type": "string", "format": "date"}, "betreff": {"type": "string"}, "forderung_antrag": {"type": "object", "properties": {"beschreibung": {"type": "string"}, "betrag": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$", "nullable": true}, "waehrung": {"type": "string", "pattern": "^[A-Z]{3}$", "nullable": true}, "frist": {"type": "string", "format": "date", "nullable": true}}, "required": ["beschreibung"]}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^[0-9]{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$", "nullable": true}, "mwst_satz": {"type": "string", "pattern": "^[0-9]+(\\.[0-9]{1,2})?$", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}}, "required": ["anwalt", "kanzlei", "mandant", "aktenzeichen", "datum", "betreff", "_meta"]}',
    '"{\"anwalt\": \"Name des unterzeichnenden Rechtsanwalts oder der Rechtsanw\u00e4ltin. Wichtig f\u00fcr die Identifikation des Absenders, z. B. ''Rechtsanwalt Dr. Max Mustermann''.\", \"kanzlei\": \"Name und Adresse der Anwaltskanzlei, die den Schriftsatz verfasst hat. Format: ''Mustermann & Partner Rechtsanw\u00e4lte, Musterstra\u00dfe 1, 12345 Berlin''.\", \"mandant\": \"Name und ggf. Adresse des Mandanten, in dessen Namen der Schriftsatz eingereicht wird. Beispiel: ''Max Mustermann, Musterweg 2, 12345 Berlin''.\", \"gegner\": \"Name und ggf. Adresse der gegnerischen Partei oder deren Rechtsvertreter. Beispiel: ''Erika Musterfrau, vertreten durch Rechtsanwalt Schmidt''.\", \"gericht\": \"Name und Sitz des Gerichts, an das der Schriftsatz gerichtet ist. Beispiel: ''Amtsgericht Berlin-Mitte, Littenstra\u00dfe 12-17, 10179 Berlin''.\", \"aktenzeichen\": \"Gerichtliches Aktenzeichen zur eindeutigen Identifikation des Verfahrens. Format variiert je nach Gericht, z. B. ''123 C 456/23'' oder ''52 Js 7890/22''. Wichtig f\u00fcr die Zuordnung zu einem konkreten Verfahren.\", \"datum\": \"Datum der Erstellung oder Einreichung des Schriftsatzes. Format: TT.MM.JJJJ, z. B. ''15.10.2023''.\", \"betreff\": \"Kurze Beschreibung des Inhalts oder Zwecks des Schriftsatzes. Beispiel: ''Klageerwiderung im Verfahren 123 C 456/23'' oder ''Antrag auf einstweilige Verf\u00fcgung''.\", \"forderung_antrag\": \"Der konkrete Antrag oder die Forderung, die im Schriftsatz gestellt wird. Beispiel: ''Die Klage wird abgewiesen.'' oder ''Der Beklagte wird verurteilt, an den Kl\u00e4ger 5.000 \u20ac nebst Zinsen in H\u00f6he von 5 Prozentpunkten \u00fcber dem Basiszinssatz seit dem 01.01.2023 zu zahlen.''\"}"',
    'Schriftsatz, Klageschrift, Antrag, Anwalt, Kanzlei, Mandant, Gegner, Gericht, Aktenzeichen, Rechtsanwalt, Prozess, Forderung, Stellungnahme, Klageerwiderung, Berufung, Revision, §, BGB, ZPO, StPO, GVG, Ladung, Termin, mündliche Verhandlung, Beweisantrag, Vergleichsvorschlag, legal brief, court filing, plaintiff, defendant, case number',
    'Anwälte',
    NULL,
    0,
    1,
    1,
    'mistral_batch',
    'Häufige Verwechslungen: Schriftsätze können mit behördlichen Bescheiden (z. B. vom Finanzamt) oder privaten Rechtsdokumenten (z. B. Mahnungen) verwechselt werden. Typische Erkennungsmerkmale sind die Nennung eines Gerichts, eines Aktenzeichens und die formelle Sprache mit juristischen Fachbegriffen. Sonderfälle: Schriftsätze können auch in außergerichtlichen Verfahren (z. B. Mahnverfahren) oder in Verwaltungsverfahren (z. B. Widerspruch gegen einen Bescheid) vorkommen. Achte auf die Absenderangabe (meist eine Anwaltskanzlei) und die typische Struktur mit Rubrum (Parteien, Gericht, Aktenzeichen).'
)
ON CONFLICT (id) DO UPDATE SET category=EXCLUDED.category, display_name=EXCLUDED.display_name, description=EXCLUDED.description, schema=EXCLUDED.schema, field_descriptions=EXCLUDED.field_descriptions, classify_keywords=EXCLUDED.classify_keywords, typical_senders=EXCLUDED.typical_senders, steuer_relevanz=EXCLUDED.steuer_relevanz, priority=EXCLUDED.priority, enabled=EXCLUDED.enabled, version=EXCLUDED.version, source=EXCLUDED.source, notes=EXCLUDED.notes;

INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'objection',
    'D. Steuern & Behörden',
    'Widerspruch/Einspruch',
    'Ein Widerspruch oder Einspruch ist ein formelles Rechtsmittel, mit dem ein Bürger gegen einen behördlichen oder gerichtlichen Bescheid vorgeht. Es kommt typischerweise nach Erhalt eines Steuerbescheids, Verwaltungsakts oder Gerichtsurteils vor und dient der Anfechtung der Entscheidung. Im Gegensatz zu einer einfachen Beschwerde ist der Widerspruch/Einspruch fristgebunden und muss begründet werden, um eine Überprüfung durch die Behörde oder das Gericht zu erwirken.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "Widerspruch/Einspruch", "type": "object", "properties": {"einleger": {"type": "object", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort"]}, "telefon": {"type": "string"}, "email": {"type": "string", "format": "email"}}, "required": ["name", "adresse"]}, "gegner": {"type": "object", "properties": {"name": {"type": "string"}, "behoerde": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort"]}}, "required": ["name", "adresse"]}, "aktenzeichen": {"type": "string"}, "gegen_bescheid_vom": {"type": "string", "format": "date"}, "begruendung_zusammenfassung": {"type": "string"}, "frist": {"type": "string", "format": "date"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^\\d{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$", "nullable": true}, "mwst_satz": {"type": "string", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}}, "required": ["einleger", "gegner", "aktenzeichen", "gegen_bescheid_vom", "begruendung_zusammenfassung"]}',
    '"{\"einleger\": \"Name und Adresse der Person oder Institution, die den Widerspruch/Einspruch einlegt. Wichtig f\u00fcr die Identifikation des Einspruchsf\u00fchrers und die Zustellung von Bescheiden. Beispiel: ''Max Mustermann, Musterstra\u00dfe 1, 12345 Musterstadt''.\", \"gegner\": \"Name und Adresse der Beh\u00f6rde oder des Gerichts, gegen dessen Bescheid der Widerspruch/Einspruch gerichtet ist. Beispiel: ''Finanzamt Musterstadt, Steuer-Nr. 123/456/7890''. Wichtig f\u00fcr die korrekte Zuordnung des Verfahrens.\", \"aktenzeichen\": \"Offizielle Kennung des Bescheids oder Verfahrens, gegen das sich der Widerspruch/Einspruch richtet. Beispiel: ''St.-Nr. 123/456/7890, Bescheid vom 01.01.2023''. Entscheidend f\u00fcr die eindeutige Identifikation des Verfahrens.\", \"gegen_bescheid_vom\": \"Datum des Bescheids, gegen den der Widerspruch/Einspruch eingelegt wird. Format: TT.MM.JJJJ. Beispiel: ''01.01.2023''. Wichtig f\u00fcr die Fristberechnung (Einspruchsfrist betr\u00e4gt meist 1 Monat ab Bekanntgabe des Bescheids).\", \"begruendung_zusammenfassung\": \"Kurze Zusammenfassung der Gr\u00fcnde f\u00fcr den Widerspruch/Einspruch. Beispiel: ''Der Steuerbescheid enth\u00e4lt fehlerhafte Werbungskosten in H\u00f6he von 500 \u20ac, die nicht anerkannt wurden. Belege liegen bei.''. Wichtig f\u00fcr die inhaltliche Pr\u00fcfung durch die Beh\u00f6rde oder das Gericht.\"}"',
    'Widerspruch, Einspruch, Rechtsbehelf, Anfechtung, Bescheid, Frist, Begründung, Akte, Aktenzeichen, Behörde, Gericht, Steuerbescheid, Verwaltungsakt, §347 AO, §68 VwGO, §355 AO, Widerspruchsverfahren, Einspruchsverfahren, appeal, objection, deadline, reasoning, file number, tax assessment, administrative act',
    'Bürger → Behörde/Gericht',
    '{"relevanz": "Hoch", "paragraphen": "§347 AO (Einspruch gegen Steuerbescheide), §355 AO (Einspruchsfrist), §367 AO (Ablauf des Einspruchsverfahrens)", "anlage": "Keine direkte Anlage, aber relevant für die Korrektur von Steuerbescheiden (z. B. Anlage N, V, KAP). Einspruch kann zu Änderungen in bereits eingereichten Anlagen führen.", "absetzbare_betraege": "Keine direkten Beträge, aber Einspruch kann zu Erstattungen oder Nachzahlungen führen, die in der Steuererklärung zu berücksichtigen sind. Kosten des Einspruchsverfahrens (z. B. Anwaltskosten) können unter bestimmten Voraussetzungen als außergewöhnliche Belastungen (§33 EStG) geltend gemacht werden."}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
ON CONFLICT (id) DO UPDATE SET category=EXCLUDED.category, display_name=EXCLUDED.display_name, description=EXCLUDED.description, schema=EXCLUDED.schema, field_descriptions=EXCLUDED.field_descriptions, classify_keywords=EXCLUDED.classify_keywords, typical_senders=EXCLUDED.typical_senders, steuer_relevanz=EXCLUDED.steuer_relevanz, priority=EXCLUDED.priority, enabled=EXCLUDED.enabled, version=EXCLUDED.version, source=EXCLUDED.source, notes=EXCLUDED.notes;

INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'official_notice',
    'D. Steuern & Behörden',
    'Bescheid',
    'Ein Bescheid ist ein amtliches Dokument, das von einer Behörde erstellt wird und eine verbindliche Entscheidung oder Regelung enthält. Es kommt typischerweise im Rahmen von Verwaltungsverfahren vor, z. B. Steuerbescheide, Wohngeldbescheide oder Baugenehmigungen. Im Gegensatz zu einfachen Informationsschreiben oder Aufforderungen enthält ein Bescheid eine konkrete Entscheidung (Tenor) und eine Rechtsmittelbelehrung, die auf mögliche Einspruchsfristen hinweist.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "official_notice", "description": "Schema f\u00fcr einen beh\u00f6rdlichen Bescheid", "type": "object", "properties": {"behoerde": {"type": "object", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort"]}, "telefon": {"type": "string"}, "email": {"type": "string", "format": "email"}}, "required": ["name"]}, "aktenzeichen": {"type": "string"}, "datum": {"type": "string", "format": "date"}, "gegenstand": {"type": "string"}, "tenor": {"type": "string"}, "rechtsmittelbelehrung": {"type": "string"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^\\d{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$", "nullable": true}, "mwst_satz": {"type": "string", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}, "anordnungen": {"type": "array", "description": "Einzelne Anordnungen/Verf\u00fcgungspunkte des Bescheids", "items": {"type": "object", "properties": {"punkt_nr": {"type": "string"}, "inhalt": {"type": "string"}, "frist": {"type": "string"}}}}}, "required": ["behoerde", "datum", "gegenstand", "tenor"]}',
    '"{\"behoerde\": \"Name und Anschrift der ausstellenden Beh\u00f6rde, z. B. ''Finanzamt M\u00fcnchen'', ''Stadt K\u00f6ln \u2013 Amt f\u00fcr Wohnen''. Wichtig f\u00fcr die Zuordnung des Bescheids und ggf. f\u00fcr die Kommunikation bei Einspr\u00fcchen.\", \"aktenzeichen\": \"Eindeutige Referenznummer des Bescheids, z. B. ''12345/2023''. Wird f\u00fcr R\u00fcckfragen oder Einspr\u00fcche ben\u00f6tigt. Format variiert je nach Beh\u00f6rde (z. B. mit Schr\u00e4gstrich, Bindestrich oder Leerzeichen).\", \"datum\": \"Ausstellungsdatum des Bescheids im Format TT.MM.JJJJ. Relevant f\u00fcr die Berechnung von Einspruchsfristen (meist 1 Monat ab Zustellung, \u00a7 355 AO).\", \"gegenstand\": \"Kurze Beschreibung des Sachverhalts, z. B. ''Einkommensteuerbescheid 2022'', ''Wohngeldbewilligung''. Wichtig f\u00fcr die steuerliche Einordnung und Archivierung.\", \"tenor\": \"Kernentscheidung des Bescheids, z. B. ''Die Einkommensteuer f\u00fcr 2022 wird auf 5.000 \u20ac festgesetzt.'' oder ''Der Antrag auf Wohngeld wird abgelehnt.''. Bei Steuerbescheiden: Betrag und Veranlagungszeitraum sind zentral f\u00fcr die Steuererkl\u00e4rung.\"}"',
    'Bescheid, Entscheidung, Tenor, Rechtsmittelbelehrung, Einspruch, Frist, Behörde, Aktenzeichen, Steuerbescheid, Widerspruch, Verwaltungsakt, official notice, decision, appeal, deadline, authority, file reference, tax assessment, objection',
    'Behörden',
    '{"relevanz": "Je nach Art des Bescheids (z. B. Steuerbescheid, Kindergeldbescheid, Grundsteuerbescheid) unterschiedlich. Steuerbescheide sind direkt für die Steuererklärung relevant (§ 155 AO).", "anlagen": {"Steuerbescheid": "Anlage N (Einkünfte), Anlage V (Mieteinnahmen), Hauptvordruck (ESt 1A) – je nach Gegenstand des Bescheids. Einspruchsfrist beachten (§ 355 AO).", "Kindergeldbescheid": "Anlage Kind (§ 32 EStG), ggf. Anlage Vorsorgeaufwand (§ 10 EStG).", "Grundsteuerbescheid": "Nicht direkt absetzbar, aber relevant für Nebenkostenabrechnung (§ 35a EStG bei haushaltsnahen Dienstleistungen)."}, "absetzbare_betraege": null}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
ON CONFLICT (id) DO UPDATE SET category=EXCLUDED.category, display_name=EXCLUDED.display_name, description=EXCLUDED.description, schema=EXCLUDED.schema, field_descriptions=EXCLUDED.field_descriptions, classify_keywords=EXCLUDED.classify_keywords, typical_senders=EXCLUDED.typical_senders, steuer_relevanz=EXCLUDED.steuer_relevanz, priority=EXCLUDED.priority, enabled=EXCLUDED.enabled, version=EXCLUDED.version, source=EXCLUDED.source, notes=EXCLUDED.notes;

INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'settlement',
    'D. Steuern & Behörden',
    'Vergleich',
    'Ein Vergleich (auch gerichtlicher Vergleich oder außergerichtliche Einigung) ist eine Vereinbarung zwischen Konfliktparteien zur Beilegung eines Rechtsstreits, oft mit Hilfe eines Gerichts oder Anwalts. Er kommt nach Verhandlungen oder während eines Gerichtsverfahrens vor und unterscheidet sich von Urteilen oder Beschlüssen durch seine konsensuale Natur. Typisch sind Formulierungen wie ''die Parteien vereinbaren'' oder ''im Wege des Vergleichs''.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "settlement", "description": "Vergleichsdokument mit Parteien, Gericht, Aktenzeichen und Vereinbarungen", "type": "object", "properties": {"parteien": {"type": "array", "items": {"type": "object", "properties": {"name": {"type": "string", "description": "Name der Partei"}, "rolle": {"type": "string", "description": "Rolle der Partei (z.B. Kl\u00e4ger, Beklagter)", "enum": ["klaeger", "beklagter", "nebenintervenient", "streithelfer"]}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "pattern": "^[A-Z]{2}$"}}, "required": ["strasse", "plz", "ort", "land"]}, "vertreter": {"type": "object", "properties": {"name": {"type": "string"}, "kanzlei": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "pattern": "^[A-Z]{2}$"}}, "required": ["strasse", "plz", "ort", "land"]}}}}, "required": ["name", "rolle"]}}, "gericht": {"type": "object", "properties": {"name": {"type": "string"}, "instanz": {"type": "string", "enum": ["erstinstanz", "berufung", "revision", "beschwerde"]}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "pattern": "^[A-Z]{2}$"}}, "required": ["strasse", "plz", "ort", "land"]}}, "required": ["name"]}, "aktenzeichen": {"type": "string"}, "gegenstand": {"type": "string", "description": "Kurze Beschreibung des Streitgegenstands"}, "vereinbarung_zusammenfassung": {"type": "string", "description": "Zusammenfassung der getroffenen Vereinbarungen"}, "kosten_regelung": {"type": "object", "properties": {"kosten_tragung": {"type": "string", "enum": ["kl\u00e4ger", "beklagter", "quotale_teilung", "gerichtskosten_getrennt", "sonstiges"]}, "kosten_betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}, "kosten_w\u00e4hrung": {"type": "string", "pattern": "^[A-Z]{3}$"}, "anwaltskosten_kl\u00e4ger": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}, "anwaltskosten_beklagter": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}, "sonstige_kosten": {"type": "array", "items": {"type": "object", "properties": {"beschreibung": {"type": "string"}, "betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}, "w\u00e4hrung": {"type": "string", "pattern": "^[A-Z]{3}$"}}, "required": ["beschreibung", "betrag", "w\u00e4hrung"]}}}}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^\\d{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$", "nullable": true}, "mwst_satz": {"type": "string", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}, "vereinbarungen": {"type": "array", "description": "Einzelne Vereinbarungspunkte des Vergleichs", "items": {"type": "object", "properties": {"punkt_nr": {"type": "string"}, "inhalt": {"type": "string"}, "betrag": {"type": "string"}}}}}, "required": ["parteien", "gericht", "aktenzeichen", "gegenstand", "vereinbarung_zusammenfassung"]}',
    '"parteien[], gericht, aktenzeichen, gegenstand, vereinbarung_zusammenfassung, kosten_regelung"',
    'Vergleich, gerichtlicher Vergleich, außergerichtliche Einigung, Vergleichsvereinbarung, Parteien vereinbaren, Streitbeilegung, Akte, Aktenzeichen, Gericht, Kostenregelung, Rechtsstreit, Klageverzicht, Zahlungsverpflichtung, settlement agreement, court settlement, mutual agreement, legal dispute, case number, jurisdiction, cost allocation',
    'Parteien, Anwälte, Gericht',
    '{"allgemein": "Abhängig vom Gegenstand des Vergleichs (z.B. Schadensersatz, Unterhalt, Arbeitsrecht).", "mögliche_paragraphen": {"§22 Nr. 3 EStG": "Sonstige Einkünfte (z.B. bei privaten Vergleichen über Schadensersatz ohne Schmerzensgeld).", "§33 EStG": "Außergewöhnliche Belastungen (z.B. Prozesskosten bei existenziellen Rechtsstreiten).", "§10 Abs. 1 Nr. 1a EStG": "Unterhaltsleistungen (wenn Vergleich Unterhaltszahlungen regelt).", "§4 Abs. 4 EStG": "Betriebsausgaben (bei geschäftlichen Vergleichen, z.B. Vertragsstrafen)."}, "anlage": "Je nach Kontext: Anlage N (Werbungskosten), Anlage V (Mieteinnahmen), Anlage SO (sonstige Einkünfte), oder direkt in der Haupterklärung (z.B. §33 EStG)."}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
