INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'tax_assessment',
    'D. Steuern & Behörden',
    'Steuerbescheid',
    'Der Steuerbescheid ist das offizielle Dokument des Finanzamts, das die festgesetzte Steuerlast oder -erstattung für ein bestimmtes Veranlagungsjahr bestätigt. Er wird nach Einreichung der Steuererklärung versandt und enthält die endgültige Berechnung der Steuer (z. B. Einkommensteuer, Gewerbesteuer). Im Gegensatz zur Steuererklärung (die vom Steuerpflichtigen eingereicht wird) oder zur Steueranmeldung (z. B. Umsatzsteuer-Voranmeldung) ist der Steuerbescheid das verbindliche Ergebnis der Prüfung durch das Finanzamt.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "tax_assessment", "description": "Steuerbescheid Dokumenten-Extraktions-Template", "type": "object", "properties": {"aktenzeichen": {"type": "string", "description": "Aktenzeichen des Steuerbescheids"}, "steuernummer": {"type": "string", "description": "Steuernummer des Steuerpflichtigen"}, "steuer_id": {"type": "string", "description": "Steueridentifikationsnummer des Steuerpflichtigen"}, "veranlagungsjahr": {"type": "string", "description": "Jahr der Veranlagung (YYYY)"}, "steuerart": {"type": "string", "description": "Art der Steuer (z.B. Einkommensteuer, K\u00f6rperschaftsteuer)"}, "festgesetzt": {"type": "string", "description": "Festgesetzter Steuerbetrag (Format: ''49.99'')"}, "nachzahlung": {"type": "string", "description": "Nachzahlungsbetrag (Format: ''49.99'')"}, "erstattung": {"type": "string", "description": "Erstattungsbetrag (Format: ''49.99'')"}, "einspruchsfrist": {"type": "string", "description": "Frist f\u00fcr Einspruch (YYYY-MM-DD)"}, "rechtsmittelbelehrung": {"type": "string", "description": "Text der Rechtsmittelbelehrung"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean", "enum": [true]}, "steuerrelevanz_hinweis": {"type": "string", "enum": ["Steuerbescheid ist grundlegend f\u00fcr die Steuererkl\u00e4rung und m\u00f6gliche Einspr\u00fcche."]}, "steuer_kategorie": {"type": "string", "enum": [null]}, "steuerjahr": {"type": "string", "description": "Veranlagungsjahr (YYYY)", "pattern": "^\\d{4}$"}, "mwst_ausgewiesen": {"type": "boolean", "enum": [false]}, "mwst_betrag": {"type": "string", "enum": [null]}, "mwst_satz": {"type": "string", "enum": [null]}, "aktenzeichen": {"type": "string", "description": "Aktenzeichen des Steuerbescheids"}, "dokumenten_id": {"type": "string", "description": "Interne Dokumenten-ID"}}, "required": ["steuerrelevant", "steuerrelevanz_hinweis", "mwst_ausgewiesen"]}, "positionen": {"type": "array", "description": "Einzelpositionen des Steuerbescheids (Steuerarten, Bemessungsgrundlagen, Betr\u00e4ge)", "items": {"type": "object", "properties": {"steuerart": {"type": "string"}, "bemessungsgrundlage": {"type": "string"}, "steuerbetrag": {"type": "string"}}}}}, "required": ["aktenzeichen", "steuernummer", "veranlagungsjahr", "steuerart", "festgesetzt", "_meta"]}',
    '"aktenzeichen, steuernummer, steuer_id, veranlagungsjahr, steuerart, festgesetzt, nachzahlung, erstattung, einspruchsfrist, rechtsmittelbelehrung"',
    'Steuerbescheid, Einkommensteuerbescheid, Festsetzung, Veranlagungsjahr, Finanzamt, Steuererstattung, Nachzahlung, Einspruchsfrist, Rechtsbehelfsbelehrung, Aktenzeichen, Steuernummer, Steuer-ID, Bescheid, festgesetzte Steuer, §155 AO, Steuerart, Bescheiddatum, Fälligkeit, Zahlungsaufforderung, Erstattungsbetrag, tax assessment, final tax notice, tax refund, tax payment, appeal deadline',
    'Finanzamt',
    '{"relevanz": "Hoch – Grundlage für Steuererklärung und Zahlungspflichten", "paragraphen": "§155 AO (Steuerfestsetzung), §36 EStG (Steuererhebung), §37 EStG (Steuerabzug und -erstattung)", "anlage": "Keine direkte Anlage, aber Referenz für Anlage N (Einkünfte), Anlage Vorsorgeaufwand (z. B. bei Erstattungen), oder Anlage KAP (Kapitalerträge). Wichtig für Nachweise bei Einsprüchen oder späteren Korrekturen (§173 AO)."}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
ON CONFLICT (id) DO UPDATE SET category=EXCLUDED.category, display_name=EXCLUDED.display_name, description=EXCLUDED.description, schema=EXCLUDED.schema, field_descriptions=EXCLUDED.field_descriptions, classify_keywords=EXCLUDED.classify_keywords, typical_senders=EXCLUDED.typical_senders, steuer_relevanz=EXCLUDED.steuer_relevanz, priority=EXCLUDED.priority, enabled=EXCLUDED.enabled, version=EXCLUDED.version, source=EXCLUDED.source, notes=EXCLUDED.notes;

INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'witness_summons',
    'D. Steuern & Behörden',
    'Zeugenladung',
    'Eine Zeugenladung ist eine offizielle Aufforderung eines Gerichts, als Zeuge in einem Gerichtsverfahren auszusagen. Sie wird typischerweise in Straf-, Zivil- oder Verwaltungsverfahren verschickt und enthält konkrete Angaben zum Termin, Ort und dem betreffenden Verfahren. Im Gegensatz zu einer Vorladung als Beschuldigter oder einer einfachen Terminmitteilung ist die Zeugenladung spezifisch an Zeugen gerichtet und verpflichtet zur Anwesenheit.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "Witness Summons", "description": "Extracted data from a witness summons document", "type": "object", "properties": {"gericht": {"type": "string", "description": "Name of the court issuing the summons"}, "aktenzeichen": {"type": "string", "description": "Case number or file reference"}, "zeuge": {"type": "object", "description": "Information about the witness", "properties": {"name": {"type": "string", "description": "Full name of the witness"}, "adresse": {"type": "object", "description": "Address of the witness", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "default": "DE"}}, "required": ["strasse", "plz", "ort"]}, "telefon": {"type": "string", "description": "Phone number in E.164 format"}}, "required": ["name"]}, "termin_datum": {"type": "string", "format": "date", "description": "Date of the hearing in YYYY-MM-DD format"}, "termin_uhrzeit": {"type": "string", "description": "Time of the hearing in HH:MM format"}, "saal": {"type": "string", "description": "Courtroom or hearing room number"}, "verfahren": {"type": "string", "description": "Description of the legal proceedings"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean", "default": false}, "steuerrelevanz_hinweis": {"type": "string", "default": null}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "default": null}, "steuerjahr": {"type": "string", "pattern": "^[0-9]{4}$", "default": null}, "mwst_ausgewiesen": {"type": "boolean", "default": false}, "mwst_betrag": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$", "default": null}, "mwst_satz": {"type": "string", "default": null}, "aktenzeichen": {"type": "string", "default": null}, "dokumenten_id": {"type": "string", "default": null}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}}, "required": ["gericht", "aktenzeichen", "zeuge", "termin_datum"]}',
    '"{\"gericht\": \"Name und ggf. Sitz des Gerichts, das die Ladung ausstellt, z. B. ''Amtsgericht M\u00fcnchen''. Wichtig f\u00fcr die Dokumentation, falls Reisekosten oder Verdienstausfall geltend gemacht werden.\", \"aktenzeichen\": \"Eindeutige Kennung des Verfahrens, z. B. ''42 Cs 123/24''. Wird ben\u00f6tigt, um das Dokument dem richtigen Verfahren zuzuordnen und bei R\u00fcckfragen zu referenzieren.\", \"zeuge\": \"Name der als Zeuge geladenen Person, z. B. ''Max Mustermann''. Wichtig f\u00fcr die Identifikation und ggf. f\u00fcr die Geltendmachung von Anspr\u00fcchen (z. B. Reisekosten).\", \"termin_datum\": \"Datum des Gerichtstermins im Format TT.MM.JJJJ, z. B. ''15.10.2024''. Relevant f\u00fcr die Planung und ggf. f\u00fcr die Erstattung von Verdienstausfall.\", \"termin_uhrzeit\": \"Uhrzeit des Termins im Format HH:MM, z. B. ''10:00''. Wichtig f\u00fcr die zeitliche Einordnung und ggf. f\u00fcr die Berechnung von Reisezeiten oder Verdienstausfall.\", \"saal\": \"Bezeichnung des Sitzungssaals, z. B. ''Saal 301''. Hilft bei der Orientierung im Gerichtsgeb\u00e4ude.\", \"verfahren\": \"Kurze Beschreibung des Verfahrensgegenstands, z. B. ''Strafverfahren wegen Diebstahls''. Wichtig f\u00fcr die Vorbereitung auf die Aussage und die Einordnung des Kontexts.\"}"',
    'Zeugenladung, Zeuge, Gericht, Termin, Saal, Aktenzeichen, Verfahren, Ladung, Aussagepflicht, §48 StPO, witness summons, court, hearing, case number, legal proceeding, appearance, obligation to testify, judicial summons, Vernehmung',
    'Gericht',
    NULL,
    0,
    1,
    1,
    'mistral_batch',
    'Häufige Verwechslungen: Zeugenladungen werden oft mit Vorladungen als Beschuldigter (z. B. im Strafverfahren) oder mit einfachen Terminmitteilungen (z. B. für Parteien in Zivilverfahren) verwechselt. Eine Zeugenladung enthält stets den Hinweis auf die Zeugenrolle und die Aussagepflicht. Sonderfall: Bei Nichterscheinen kann ein Ordnungsgeld oder zwangsweise Vorführung drohen (§51 StPO). Reisekosten oder Verdienstausfall können unter Umständen erstattet werden – hierfür sollte die Ladung aufbewahrt werden. Tipp: Prüfen, ob eine Aussageverweigerung (z. B. bei nahen Angehörigen) möglich ist.'
)
ON CONFLICT (id) DO UPDATE SET category=EXCLUDED.category, display_name=EXCLUDED.display_name, description=EXCLUDED.description, schema=EXCLUDED.schema, field_descriptions=EXCLUDED.field_descriptions, classify_keywords=EXCLUDED.classify_keywords, typical_senders=EXCLUDED.typical_senders, steuer_relevanz=EXCLUDED.steuer_relevanz, priority=EXCLUDED.priority, enabled=EXCLUDED.enabled, version=EXCLUDED.version, source=EXCLUDED.source, notes=EXCLUDED.notes;

INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'freelance_invoice',
    'E. Arbeit & Einkommen',
    'Freiberufler-Rechnung',
    'Eine Rechnung von einem Freiberufler oder Selbstständigen an einen Auftraggeber für erbrachte Dienstleistungen oder Projekte. Typisch für freiberufliche Tätigkeiten wie Beratung, Design, Programmierung oder Coaching. Unterscheidet sich von Gewerberechnungen durch spezifische Angaben wie Leistungszeitraum und detaillierte Positionsaufschlüsselung, oft ohne Warenlieferungen.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "Freelance Invoice", "description": "Schema für die Extraktion von Freiberufler-Rechnungen", "type": "object", "properties": {"rechnungsnummer": {"type": "string", "description": "Eindeutige Rechnungsnummer"}, "datum": {"type": "string", "format": "date", "description": "Rechnungsdatum im Format YYYY-MM-DD"}, "auftragnehmer": {"type": "object", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort", "land"]}, "steuernummer": {"type": "string"}, "ust_id": {"type": "string"}, "telefon": {"type": "string"}, "email": {"type": "string", "format": "email"}}, "required": ["name", "adresse"]}, "auftraggeber": {"type": "object", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort", "land"]}, "ust_id": {"type": "string"}}, "required": ["name", "adresse"]}, "steuernummer": {"type": "string", "description": "Steuernummer des Auftragnehmers"}, "ust_id": {"type": "string", "description": "Umsatzsteuer-Identifikationsnummer des Auftragnehmers"}, "leistungszeitraum": {"type": "object", "properties": {"von": {"type": "string", "format": "date"}, "bis": {"type": "string", "format": "date"}}, "required": ["von", "bis"]}, "projektnummer": {"type": "string"}, "positionen": {"type": "array", "items": {"type": "object", "properties": {"beschreibung": {"type": "string"}, "stunden": {"type": "number"}, "stundensatz": {"type": "string", "description": "Stundensatz in Währungseinheiten mit 2 Dezimalstellen"}, "betrag": {"type": "string", "description": "Gesamtbetrag der Position in Währungseinheiten mit 2 Dezimalstellen"}}, "required": ["beschreibung", "betrag"]}}, "netto": {"type": "string", "description": "Nettobetrag in Währungseinheiten mit 2 Dezimalstellen"}, "mwst": {"type": "string", "description": "Mehrwertsteuerbetrag in Währungseinheiten mit 2 Dezimalstellen"}, "brutto": {"type": "string", "description": "Bruttobetrag in Währungseinheiten mit 2 Dezimalstellen"}, "zahlungsfrist": {"type": "string", "description": "Zahlungsfrist in Tagen oder Datum im Format YYYY-MM-DD"}, "iban": {"type": "string", "description": "IBAN für die Zahlung ohne Leerzeichen"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^[0-9]{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "nullable": true}, "mwst_satz": {"type": "string", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}, "waehrung": {"type": "string", "default": "EUR", "description": "Waehrung ISO 4217 (EUR, USD, etc.)"}}, "required": ["rechnungsnummer", "datum", "auftragnehmer", "auftraggeber", "netto", "brutto", "_meta"]}',
    '"rechnungsnummer, datum, auftragnehmer, auftraggeber, steuernummer, ust_id, leistungszeitraum, projektnummer, positionen[] (beschreibung, stunden, stundensatz, betrag), netto, mwst, brutto, zahlungsfrist, iban"',
    'Rechnung, Freiberufler, Honorar, Dienstleistung, Leistungszeitraum, Stundensatz, Stundenaufstellung, Nettobetrag, Umsatzsteuer, Bruttobetrag, Zahlungsfrist, IBAN, USt-ID, Steuer-Nr., Projektnummer, Auftragnehmer, Auftraggeber, invoice, freelance, consultant, services rendered, VAT, tax number',
    'Freelancer',
    '{"einkommensteuer": {"paragraphen": "§18 EStG (Einkünfte aus selbstständiger Arbeit), §4 Abs. 3 EStG (Einnahmen-Überschuss-Rechnung)", "anlage": "S (Selbstständige Arbeit), ggf. Anlage EÜR", "hinweise": "Nettobetrag als Betriebseinnahme, Vorsteuerabzug bei Umsatzsteuer möglich. MwSt muss separat ausgewiesen sein (§14 UStG)."}, "umsatzsteuer": {"paragraphen": "§14 UStG (Rechnung), §19 UStG (Kleinunternehmerregelung), §15 UStG (Vorsteuerabzug)", "anlage": "USt-Voranmeldung, Anlage UR (Umsatzsteuererklärung)"}}',
    0,
