INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'insurance_deduction_cert',
    'E. Arbeit & Einkommen',
    'Bescheinigung Vorsorgeaufwendungen',
    'Diese Bescheinigung wird von Versicherungen jährlich ausgestellt und dokumentiert die im Beitragsjahr geleisteten Vorsorgeaufwendungen des Versicherungsnehmers. Sie dient als Nachweis für die steuerliche Geltendmachung von Versicherungsbeiträgen in der Einkommensteuererklärung und unterscheidet sich von anderen Bescheinigungen durch die detaillierte Aufschlüsselung verschiedener Versicherungsarten (z.B. Kranken-, Pflege-, Rentenversicherung). Im Gegensatz zu einfachen Beitragsrechnungen enthält sie spezifische Angaben für die Steuererklärung.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "insurance_deduction_cert", "description": "Bescheinigung Vorsorgeaufwendungen", "type": "object", "properties": {"versicherungsnehmer": {"type": "object", "properties": {"name": {"type": "string"}, "vorname": {"type": "string"}, "geburtsdatum": {"type": "string", "format": "date"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort", "land"]}, "steuer_id": {"type": "string"}}, "required": ["name", "vorname", "adresse", "steuer_id"]}, "steuer_id": {"type": "string"}, "beitragsjahr": {"type": "string"}, "beitraege_kranken_basis": {"type": "string"}, "beitraege_kranken_wahltarif": {"type": "string"}, "beitraege_pflege": {"type": "string"}, "beitraege_rente": {"type": "string"}, "beitraege_arbeitslosen": {"type": "string"}, "beitraege_haftpflicht": {"type": "string"}, "beitraege_berufsunfaehigkeit": {"type": "string"}, "beitraege_unfall": {"type": "string"}, "beitraege_riester": {"type": "string"}, "beitraege_ruerup": {"type": "string"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["vorsorgeaufwendungen"], "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^\\d{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "nullable": true}, "mwst_satz": {"type": "string", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"], "additionalProperties": false}, "positionen": {"type": "array", "description": "Einzelpositionen der Versicherungsbescheinigung (Beitr\u00e4ge, Zusch\u00fcsse, etc.)", "items": {"type": "object", "properties": {"bezeichnung": {"type": "string"}, "betrag": {"type": "string"}, "zeile_vorsorgeaufwand": {"type": "string"}}}}}, "required": ["versicherungsnehmer", "steuer_id", "beitragsjahr", "_meta"], "additionalProperties": false}',
    '"versicherungsnehmer, steuer_id, beitragsjahr, beitraege_kranken_basis, beitraege_kranken_wahltarif, beitraege_pflege, beitraege_rente, beitraege_arbeitslosen, beitraege_haftpflicht, beitraege_berufsunfaehigkeit, beitraege_unfall, beitraege_riester, beitraege_ruerup"',
    'Vorsorgeaufwendungen, Bescheinigung, Beitragsbescheinigung, steuerliche Geltendmachung, Krankenversicherung, Pflegeversicherung, Rentenversicherung, Riester-Rente, Rürup-Rente, Basisabsicherung, Wahltarif, Haftpflicht, Berufsunfähigkeit, Arbeitslosenversicherung, Beitragsjahr, Steuer-ID, Versicherungsnehmer, Altersvorsorgebeiträge, Sonderausgaben, insurance contributions, deduction certificate, tax deductible, social security contributions',
    'Versicherungen',
    '{"paragraphen": "§10 Abs. 1 Nr. 3, §10 Abs. 1 Nr. 3a, §10a EStG (Riester-Rente), §10 Abs. 1 Nr. 2b EStG (Rürup-Rente)", "anlage": "Vorsorgeaufwand (Anlage Vorsorgeaufwand), ggf. Anlage AV (Altersvorsorgebeiträge für Riester/Rürup)", "absetzbare_betraege": {"kranken_pflege_basis": "Bis zu 100% der Beiträge zur Basis-Kranken- und Pflegeversicherung (max. 2.800 €/Jahr für Angestellte, 2.400 € für Beamte, §10 Abs. 4 EStG)", "sonstige_vorsorge": "Max. 1.900 €/Jahr (Angestellte) bzw. 2.800 € (Selbstständige) für sonstige Vorsorgeaufwendungen (z.B. Haftpflicht, Arbeitslosenversicherung, §10 Abs. 4 EStG)", "riester": "Bis zu 2.100 €/Jahr (Grundzulage + Sonderausgabenabzug, §10a EStG)"}}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
