INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'payslip',
    'E. Arbeit & Einkommen',
    'Lohn-/Gehaltsabrechnung',
    'Die Lohn-/Gehaltsabrechnung ist ein monatliches Dokument des Arbeitgebers, das die Zusammensetzung des Arbeitsentgelts detailliert auflistet. Es zeigt Brutto- und Nettolohn, Abzüge wie Steuern und Sozialversicherungsbeiträge sowie weitere Leistungen oder Abzüge. Im Gegensatz zu einer einfachen Gehaltsmitteilung oder einem Arbeitsvertrag enthält es spezifische Berechnungen für den jeweiligen Abrechnungsmonat und ist essenziell für die Steuererklärung und Nachweise gegenüber Behörden.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "Payslip", "description": "Schema für Lohn-/Gehaltsabrechnungen", "type": "object", "properties": {"arbeitnehmer": {"type": "object", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "pattern": "^[A-Z]{2}$"}}, "required": ["strasse", "plz", "ort", "land"]}, "steuer_id": {"type": "string"}}, "required": ["name", "adresse", "steuer_id"]}, "arbeitgeber": {"type": "object", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "pattern": "^[A-Z]{2}$"}}, "required": ["strasse", "plz", "ort", "land"]}, "steuernummer": {"type": "string"}}, "required": ["name", "adresse"]}, "personalnummer": {"type": "string"}, "monat": {"type": "string", "pattern": "^\\d{4}-(0[1-9]|1[0-2])$"}, "bruttolohn": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}, "nettolohn": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}, "steuerklasse": {"type": "integer", "minimum": 1, "maximum": 6}, "steuer_id": {"type": "string"}, "lohnsteuer": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}, "soli": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}, "kirchensteuer": {"type": "string", "pattern": "^\\d+\\.\\d{2}$", "nullable": true}, "sozialabgaben_an": {"type": "object", "properties": {"kv": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}, "pv": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}, "rv": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}, "av": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}}, "required": ["kv", "pv", "rv", "av"]}, "sozialabgaben_ag": {"type": "object", "properties": {"kv": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}, "pv": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}, "rv": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}, "av": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}}, "required": ["kv", "pv", "rv", "av"]}, "geldwerte_vorteile": {"type": "string", "pattern": "^\\d+\\.\\d{2}$", "nullable": true}, "vermoegenswirksame_leistungen": {"type": "string", "pattern": "^\\d+\\.\\d{2}$", "nullable": true}, "abzuege": {"type": "array", "items": {"type": "object", "properties": {"grund": {"type": "string"}, "betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}}, "required": ["grund", "betrag"]}}, "auszahlungsbetrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}, "arbeitsstunden_soll": {"type": "number", "minimum": 0}, "arbeitsstunden_ist": {"type": "number", "minimum": 0}, "ueberstunden": {"type": "number", "minimum": 0, "nullable": true}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["vorsorgeaufwendungen", null]}, "steuerjahr": {"type": "string", "pattern": "^\\d{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$", "nullable": true}, "mwst_satz": {"type": "string", "pattern": "^\\d+\\.\\d{2}$", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}, "zulagen": {"type": "array", "description": "Zulagen und Zuschläge (Überstunden, VWL, Schichtzulage, etc.)", "items": {"type": "object", "properties": {"bezeichnung": {"type": "string"}, "betrag": {"type": "string"}}}}, "arbeitsstunden_einheit": {"type": "string", "description": "Einheit der Arbeitsstunden (z.B. h, Std)"}}, "required": ["arbeitnehmer", "arbeitgeber", "personalnummer", "monat", "bruttolohn", "nettolohn", "steuerklasse", "lohnsteuer", "soli", "sozialabgaben_an", "sozialabgaben_ag", "auszahlungsbetrag", "arbeitsstunden_soll", "arbeitsstunden_ist", "_meta"]}',
    '"arbeitnehmer, arbeitgeber, personalnummer, monat, bruttolohn, nettolohn, steuerklasse, steuer_id, lohnsteuer, soli, kirchensteuer, sozialabgaben_an (KV, PV, RV, AV), sozialabgaben_ag, geldwerte_vorteile, vermoegenswirksame_leistungen, abzuege[], auszahlungsbetrag, arbeitsstunden_soll, arbeitsstunden_ist, ueberstunden"',
    'Lohnabrechnung, Gehaltsabrechnung, Bruttolohn, Nettolohn, Lohnsteuer, Solidaritätszuschlag, Kirchensteuer, Sozialversicherung, KV, PV, RV, AV, Steuerklasse, geldwerte Vorteile, vermögenswirksame Leistungen, Auszahlungsbetrag, Arbeitsstunden, Überstunden, pay slip, gross salary, net salary, tax class, social security contributions, employer, employee, payroll, Steuer-ID, Personalnummer',
    'Arbeitgeber',
    '{"paragraphen": "§38a EStG (Lohnsteuerabzug), §39b EStG (Lohnsteuerberechnung), §10 EStG (Vorsorgeaufwendungen), §35a EStG (haushaltsnahe Dienstleistungen, falls zutreffend)", "anlage": "N (Einkünfte aus nichtselbstständiger Arbeit), Vorsorgeaufwand in Anlage Vorsorgeaufwand, ggf. Anlage Kind (für Kinderfreibeträge)", "absetzbare_betraege": {"sozialabgaben_an": "Teilweise als Vorsorgeaufwendungen absetzbar (KV, PV, RV, AV) – Grenzen gemäß §10 EStG (z. B. 2023: max. 2.100 € für KV/PV, 25.639 € für RV/AV bei Arbeitnehmern)", "werbungskosten": "Pauschbetrag von 1.230 € (2023) wird automatisch berücksichtigt; höhere Kosten müssen in Anlage N geltend gemacht werden"}}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
