INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'pension_notice',
    'E. Arbeit & Einkommen',
    'Rentenbescheid',
    'Der Rentenbescheid ist ein offizielles Dokument der Deutschen Rentenversicherung (DRV), das den Anspruch auf gesetzliche Rente bestätigt. Es wird jährlich oder bei Rentenantragstellung versendet und enthält detaillierte Informationen über die Höhe der monatlichen Rente (brutto/netto), den Rentenbeginn, die Rentenart sowie Beitragszeiten. Im Gegensatz zu Renteninformationen (vorläufige Berechnungen) oder Rentenanpassungsmitteilungen ist der Rentenbescheid ein rechtsverbindliches Dokument mit finalen Werten.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "Pension Notice", "description": "Schema for extracting data from a pension notice document", "type": "object", "properties": {"aktenzeichen": {"type": "string", "description": "Official file reference of the pension notice"}, "versicherungsnummer": {"type": "string", "description": "Insurance number of the pension recipient"}, "rentenbeginn": {"type": "string", "format": "date", "description": "Start date of the pension in YYYY-MM-DD format"}, "monatsrente_brutto": {"type": "string", "pattern": "^\\d+\\.\\d{2}$", "description": "Gross monthly pension amount with 2 decimal places"}, "monatsrente_netto": {"type": "string", "pattern": "^\\d+\\.\\d{2}$", "description": "Net monthly pension amount with 2 decimal places"}, "rentenart": {"type": "string", "description": "Type of pension (e.g., Altersrente, Erwerbsminderungsrente)"}, "beitragszeiten": {"type": "array", "description": "Array of contribution periods", "items": {"type": "object", "properties": {"von": {"type": "string", "format": "date", "description": "Start date of the contribution period in YYYY-MM-DD format"}, "bis": {"type": "string", "format": "date", "description": "End date of the contribution period in YYYY-MM-DD format"}, "art": {"type": "string", "description": "Type of contribution period"}}, "required": ["von", "bis", "art"]}}, "kv_beitrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$", "description": "Monthly health insurance contribution with 2 decimal places"}, "pv_beitrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$", "description": "Monthly long-term care insurance contribution with 2 decimal places"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean", "description": "Indicates if the document is relevant for tax purposes"}, "steuerrelevanz_hinweis": {"type": "string", "description": "Additional information regarding tax relevance", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "description": "Tax category of the document", "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^\\d{4}$", "description": "Tax year in YYYY format", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean", "description": "Indicates if VAT is shown on the document"}, "mwst_betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$", "description": "VAT amount with 2 decimal places", "nullable": true}, "mwst_satz": {"type": "string", "description": "VAT rate (e.g., ''19'')", "nullable": true}, "aktenzeichen": {"type": "string", "description": "Official file reference of the document", "nullable": true}, "dokumenten_id": {"type": "string", "description": "Unique identifier for the document", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}, "rentenberechnung": {"type": "array", "description": "Einzelne Berechnungspositionen der Rente (Entgeltpunkte, Zugangsfaktor, etc.)", "items": {"type": "object", "properties": {"bezeichnung": {"type": "string"}, "wert": {"type": "string"}}}}}, "required": ["_meta"]}',
    '"aktenzeichen, versicherungsnummer, rentenbeginn, monatsrente_brutto, monatsrente_netto, rentenart, beitragszeiten, kv_beitrag, pv_beitrag"',
    'Rentenbescheid, Deutsche Rentenversicherung, DRV, Rentenbeginn, Monatsrente brutto, Monatsrente netto, Rentenart, Altersrente, Erwerbsminderungsrente, Witwenrente, Beitragszeiten, Versicherungsnummer, Aktenzeichen, Krankenversicherung, Pflegeversicherung, Rentenanpassung, Rentenhöhe, Rentenanspruch, finaler Bescheid, rentenrechtliche Zeiten, KV-Beitrag, PV-Beitrag, gesetzliche Rente, Rentenversicherungsträger',
    'DRV',
    '{"paragraphen": "§22 Nr. 1 Satz 3 Buchstabe a EStG (sonstige Einkünfte), §10 Abs. 1 Nr. 3 EStG (Kranken- und Pflegeversicherungsbeiträge), §3 Nr. 62 EStG (steuerfreie Arbeitgeberanteile zur KV/PV)", "anlage": "Anlage R (Einkünfte aus gesetzlicher Rente), Anlage Vorsorgeaufwand (KV/PV-Beiträge)", "absetzbare_betrage": {"kv_beitrag": "voll als Sonderausgabe absetzbar (Anlage Vorsorgeaufwand)", "pv_beitrag": "voll als Sonderausgabe absetzbar (Anlage Vorsorgeaufwand)"}}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
