INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'salary_statement',
    'E. Arbeit & Einkommen',
    'Bezügemitteilung',
    'Die Bezügemitteilung ist ein monatliches oder jährliches Dokument für Beamte und Angestellte des öffentlichen Dienstes, das die Zusammensetzung des Gehalts detailliert auflistet. Es unterscheidet sich von einer herkömmlichen Gehaltsabrechnung durch die spezifischen Besoldungsgruppen, Stufen und Zulagen des öffentlichen Dienstes sowie die typischen Abzüge wie Lohnsteuer, Solidaritätszuschlag und Kirchensteuer.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "Salary Statement", "description": "Schema for salary statement document extraction", "type": "object", "properties": {"beamter": {"type": "boolean"}, "dienststelle": {"type": "string"}, "personalnummer": {"type": "string"}, "besoldungsgruppe": {"type": "string"}, "stufe": {"type": "string"}, "grundgehalt": {"type": "string", "pattern": "^\\d{1,10}\\.\\d{2}$"}, "familienzuschlag": {"type": "string", "pattern": "^\\d{1,10}\\.\\d{2}$", "nullable": true}, "zulagen": {"type": "array", "items": {"type": "object", "properties": {"bezeichnung": {"type": "string"}, "betrag": {"type": "string", "pattern": "^\\d{1,10}\\.\\d{2}$"}}, "required": ["bezeichnung", "betrag"]}}, "abzuege": {"type": "array", "items": {"type": "object", "properties": {"bezeichnung": {"type": "string"}, "betrag": {"type": "string", "pattern": "^\\d{1,10}\\.\\d{2}$"}}, "required": ["bezeichnung", "betrag"]}}, "lohnsteuer": {"type": "string", "pattern": "^\\d{1,10}\\.\\d{2}$"}, "soli": {"type": "string", "pattern": "^\\d{1,10}\\.\\d{2}$"}, "kirchensteuer": {"type": "string", "pattern": "^\\d{1,10}\\.\\d{2}$", "nullable": true}, "nettobezuege": {"type": "string", "pattern": "^\\d{1,10}\\.\\d{2}$"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean", "const": true}, "steuerrelevanz_hinweis": {"type": "string", "const": "Lohnsteuerbescheinigung f\u00fcr Einkommensteuererkl\u00e4rung"}, "steuer_kategorie": {"type": "string", "const": "vorsorgeaufwendungen"}, "steuerjahr": {"type": "string", "pattern": "^\\d{4}$"}, "mwst_ausgewiesen": {"type": "boolean", "const": false}, "mwst_betrag": {"type": "null"}, "mwst_satz": {"type": "null"}, "aktenzeichen": {"type": "null"}, "dokumenten_id": {"type": "string"}}, "required": ["steuerrelevant", "steuerrelevanz_hinweis", "steuer_kategorie", "steuerjahr", "mwst_ausgewiesen", "dokumenten_id"]}}, "required": ["beamter", "dienststelle", "personalnummer", "besoldungsgruppe", "stufe", "grundgehalt", "zulagen", "abzuege", "lohnsteuer", "soli", "nettobezuege", "_meta"]}',
    '"beamter, dienststelle, personalnummer, besoldungsgruppe, stufe, grundgehalt, familienzuschlag, zulagen[], abzuege[], lohnsteuer, soli, kirchensteuer, nettobezuege"',
    'Bezügemitteilung, Besoldung, Besoldungsgruppe, Stufe, Grundgehalt, Familienzuschlag, Zulagen, Abzüge, Lohnsteuer, Soli, Solidaritätszuschlag, Kirchensteuer, Nettobezüge, Beamter, öffentlicher Dienst, Dienststelle, Personalnummer, Gehaltsabrechnung, salary statement, public service, pay scale, allowances, deductions',
    'Öffentlicher Dienst',
    '{"paragraphen": "§19 EStG (Einkünfte aus nichtselbstständiger Arbeit), §38a EStG (Lohnsteuerabzug), §41a EStG (Anmeldung und Abführung der Lohnsteuer)", "anlage": "Anlage N (Einkünfte aus nichtselbstständiger Arbeit)", "absetzbare_betraege": {"werbungskosten": "Pauschbetrag von 1.230 € (2024) oder höhere tatsächliche Kosten (z. B. Fahrtkosten, Arbeitsmittel)", "sonderausgaben": "Kirchensteuer (§10 Abs. 1 Nr. 4 EStG) in voller Höhe absetzbar"}}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
