INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'severance_agreement',
    'E. Arbeit & Einkommen',
    'Aufhebungsvertrag',
    'Ein Aufhebungsvertrag ist eine Vereinbarung zwischen Arbeitgeber und Arbeitnehmer zur einvernehmlichen Beendigung des Arbeitsverhältnisses. Er regelt Details wie Abfindung, Freistellung, Resturlaub und Wettbewerbsverbote. Im Gegensatz zu einer Kündigung wird der Vertrag hier im gegenseitigen Einvernehmen geschlossen, oft mit finanziellen oder anderen Zugeständnissen für den Arbeitnehmer.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "severance_agreement", "description": "Aufhebungsvertrag", "type": "object", "properties": {"arbeitgeber": {"type": "object", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort", "land"]}, "vertreter": {"type": "string"}, "firmenbuchnummer": {"type": "string"}}, "required": ["name", "adresse"]}, "arbeitnehmer": {"type": "object", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort", "land"]}, "geburtsdatum": {"type": "string", "format": "date"}, "personalnummer": {"type": "string"}}, "required": ["name", "adresse"]}, "beendigungsdatum": {"type": "string", "format": "date"}, "abfindung": {"type": "object", "properties": {"betrag": {"type": "string"}, "waehrung": {"type": "string"}, "faelligkeit": {"type": "string", "format": "date"}, "zahlungsmodalitaeten": {"type": "string"}}, "required": ["betrag", "waehrung"]}, "freistellung": {"type": "object", "properties": {"von": {"type": "string", "format": "date"}, "bis": {"type": "string", "format": "date"}, "verguetung": {"type": "boolean"}, "hinweise": {"type": "string"}}, "required": ["von", "bis"]}, "resturlaub": {"type": "object", "properties": {"tage": {"type": "number"}, "abgeltung": {"type": "boolean"}, "abgeltungsbetrag": {"type": "string"}, "abgeltungswaehrung": {"type": "string"}}, "required": ["tage"]}, "zeugnis_vereinbarung": {"type": "object", "properties": {"art": {"type": "string"}, "formulierung": {"type": "string"}, "ausstellungsdatum": {"type": "string", "format": "date"}}, "required": ["art"]}, "wettbewerbsverbot": {"type": "object", "properties": {"aktiv": {"type": "boolean"}, "dauer": {"type": "string"}, "entgelt": {"type": "string"}, "entgelt_waehrung": {"type": "string"}, "branchen": {"type": "array", "items": {"type": "string"}}}, "required": ["aktiv"]}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^\\d{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "nullable": true}, "mwst_satz": {"type": "string", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}, "vereinbarungen": {"type": "array", "description": "Einzelne Vereinbarungspunkte der Aufhebungsvereinbarung", "items": {"type": "object", "properties": {"punkt_nr": {"type": "string"}, "titel": {"type": "string"}, "inhalt": {"type": "string"}}}}}, "required": ["arbeitgeber", "arbeitnehmer", "beendigungsdatum", "_meta"]}',
    '"{\"arbeitgeber\": \"Name und Anschrift des Arbeitgebers, der den Aufhebungsvertrag ausstellt. Wichtig f\u00fcr steuerliche Zuordnung und Nachweispflichten.\", \"arbeitnehmer\": \"Name, Anschrift und ggf. Personalnummer des Arbeitnehmers. Wichtig f\u00fcr Identifikation und steuerliche Zuordnung der Abfindung.\", \"beendigungsdatum\": \"Datum, an dem das Arbeitsverh\u00e4ltnis endet (Format: YYYY-MM-DD). Relevant f\u00fcr Fristenberechnung (z. B. K\u00fcndigungsschutz, Sozialversicherung) und steuerliche Zuordnung des Veranlagungszeitraums.\", \"abfindung\": \"H\u00f6he der vereinbarten Abfindung in Euro (Bruttobetrag). Wichtig f\u00fcr Steuererkl\u00e4rung (F\u00fcnftelregelung, \u00a7 34 EStG) und ggf. Sozialversicherungsbeitr\u00e4ge. Beispiel: 15000.00\", \"freistellung\": \"Angabe, ob und f\u00fcr welchen Zeitraum der Arbeitnehmer von der Arbeitspflicht freigestellt wird (z. B. ''bis zum Beendigungsdatum'' oder ''6 Monate''). Relevant f\u00fcr Sozialversicherungspflicht und ggf. steuerliche Behandlung von Lohnersatzleistungen.\", \"resturlaub\": \"Anzahl der verbleibenden Urlaubstage oder deren Abgeltung in Euro. Abgeltung ist steuerpflichtig und muss in der Anlage N angegeben werden. Beispiel: ''10 Tage'' oder ''2500.00 Euro''.\", \"zeugnis_vereinbarung\": \"Vereinbarung \u00fcber die Ausstellung eines Arbeitszeugnisses (z. B. ''qualifiziert'', ''einfach'', ''Formulierungswunsch''). Nicht steuerrelevant, aber wichtig f\u00fcr berufliche Zukunft des Arbeitnehmers.\"}"',
    'Aufhebungsvertrag, Auflösungsvertrag, Beendigung Arbeitsverhältnis, Abfindung, Freistellung, Resturlaub, Wettbewerbsverbot, Zeugnisvereinbarung, einvernehmliche Beendigung, severance agreement, termination agreement, mutual separation, compensation payment, garden leave, non-compete clause, reference agreement',
    'Arbeitgeber',
    '{"paragraphen": "§ 3 Nr. 9 EStG (bis 2017), § 24 Nr. 1a EStG, § 34 EStG (Fünftelregelung)", "anlage": "N (Einkünfte aus nichtselbstständiger Arbeit), ggf. Anlage Vorsorgeaufwand (bei Abfindungsversteuerung)", "hinweise": "Abfindungen sind steuerpflichtig, können aber unter bestimmten Bedingungen ermäßigt besteuert werden (Fünftelregelung). Resturlaubsabgeltung ist voll steuerpflichtig. Freistellungszeiten sind sozialversicherungsrechtlich relevant (ggf. Meldepflicht)."}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
