INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'tax_certificate',
    'E. Arbeit & Einkommen',
    'Lohnsteuerbescheinigung',
    'Die Lohnsteuerbescheinigung ist ein offizielles Dokument des Arbeitgebers, das die steuerrelevanten Daten eines Arbeitnehmers für ein Kalenderjahr zusammenfasst. Sie wird jährlich nach Ablauf des Steuerjahres ausgestellt und ist essenziell für die Erstellung der Einkommensteuererklärung. Im Gegensatz zu Gehaltsabrechnungen, die monatlich ausgestellt werden, enthält die Lohnsteuerbescheinigung kumulierte Jahreswerte und spezifische Steuerdaten wie Lohnsteuer, Solidaritätszuschlag und Kirchensteuer.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "tax_certificate", "description": "Lohnsteuerbescheinigung", "type": "object", "properties": {"arbeitnehmer": {"type": "object", "properties": {"name": {"type": "string"}, "vorname": {"type": "string"}, "geburtsdatum": {"type": "string", "format": "date"}, "anschrift": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "default": "DE"}}, "required": ["strasse", "plz", "ort"]}, "steuer_id": {"type": "string"}}, "required": ["name", "vorname", "steuer_id"]}, "arbeitgeber": {"type": "object", "properties": {"name": {"type": "string"}, "anschrift": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "default": "DE"}}, "required": ["strasse", "plz", "ort"]}, "steuernummer": {"type": "string"}, "arbeitgeber_id": {"type": "string"}}, "required": ["name", "steuernummer"]}, "steuerjahr": {"type": "string"}, "steuer_id": {"type": "string"}, "steuerklasse": {"type": "integer", "minimum": 1, "maximum": 6}, "jahresbrutto": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}, "lohnsteuer_gesamt": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}, "soli_gesamt": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}, "kirchensteuer_gesamt": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}, "kv_beitraege_an": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}, "pv_beitraege_an": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}, "rv_beitraege_an": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}, "av_beitraege_an": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}, "kv_beitraege_ag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}, "pv_beitraege_ag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean", "default": true}, "steuerrelevanz_hinweis": {"type": "string", "default": "Lohnsteuerbescheinigung f\u00fcr die Einkommensteuererkl\u00e4rung"}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "default": null}, "steuerjahr": {"type": "string"}, "mwst_ausgewiesen": {"type": "boolean", "default": false}, "mwst_betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$", "default": null}, "mwst_satz": {"type": "string", "default": null}, "aktenzeichen": {"type": "string", "default": null}, "dokumenten_id": {"type": "string", "default": null}}, "required": ["steuerrelevant", "steuerrelevanz_hinweis", "steuerjahr", "mwst_ausgewiesen"]}}, "required": ["arbeitnehmer", "arbeitgeber", "steuerjahr", "steuer_id", "steuerklasse", "jahresbrutto", "lohnsteuer_gesamt", "_meta"]}',
    '"arbeitnehmer, arbeitgeber, steuerjahr, steuer_id, steuerklasse, jahresbrutto, lohnsteuer_gesamt, soli_gesamt, kirchensteuer_gesamt, kv_beitraege_an, pv_beitraege_an, rv_beitraege_an, av_beitraege_an, kv_beitraege_ag, pv_beitraege_ag"',
    'Lohnsteuerbescheinigung, Jahresbrutto, Lohnsteuer, Solidaritätszuschlag, Soli, Kirchensteuer, Sozialversicherungsbeiträge, Arbeitnehmer, Arbeitgeber, Steuer-ID, Steuerklasse, Krankenversicherung, Pflegeversicherung, Rentenversicherung, Arbeitslosenversicherung, elektronische Lohnsteuerbescheinigung, ELStAM, Steuerjahr, lohnsteuerliche Daten, payroll tax certificate, annual salary, income tax, social security contributions',
    'Arbeitgeber',
    '{"paragraphen": "§38b EStG (Lohnsteuerabzug), §41b EStG (elektronische Lohnsteuerbescheinigung), §10 EStG (Vorsorgeaufwendungen)", "anlage": "Anlage N (Einkünfte aus nichtselbstständiger Arbeit), Vorsorgeaufwand in Hauptvordruck", "absetzbare_betraege": {"kv_beitraege_an": "Beiträge zur Krankenversicherung (Basisabsicherung) als Sonderausgaben absetzbar (§10 Abs. 1 Nr. 3 EStG), maximal 2.800 € (Selbstständige: 3.068 €)", "pv_beitraege_an": "Beiträge zur Pflegeversicherung als Sonderausgaben absetzbar (§10 Abs. 1 Nr. 3 EStG), zusammen mit KV-Beiträgen", "rv_beitraege_an": "Beiträge zur Rentenversicherung als Vorsorgeaufwendungen absetzbar (§10 Abs. 1 Nr. 2 EStG), maximal 25.639 € (2023)"}}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
