INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'tax_table',
    'E. Arbeit & Einkommen',
    'Lohnsteuertabelle',
    'Die Lohnsteuertabelle ist eine offizielle Übersicht des Finanzamts, die die Höhe der Lohnsteuer, des Solidaritätszuschlags und der Kirchensteuer in Abhängigkeit vom zu versteuernden Einkommen und der Steuerklasse für ein bestimmtes Steuerjahr darstellt. Sie dient Arbeitgebern und Arbeitnehmern zur Orientierung über die voraussichtliche Steuerlast und unterscheidet sich von individuellen Steuerbescheiden oder Lohnabrechnungen durch ihre allgemeingültige, tabellarische Form ohne persönliche Daten.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "tax_table", "description": "Lohnsteuertabelle", "type": "object", "properties": {"steuerjahr": {"type": "string", "pattern": "^[0-9]{4}$"}, "steuerklasse": {"type": "integer", "minimum": 1, "maximum": 6}, "einkommensbereich": {"type": "object", "properties": {"von": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$"}, "bis": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$"}}, "required": ["von", "bis"]}, "lohnsteuer": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$"}, "soli": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$"}, "kirchensteuer": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^[0-9]{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$", "nullable": true}, "mwst_satz": {"type": "string", "pattern": "^[0-9]+(\\.[0-9]{1,2})?$", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}}, "required": ["steuerjahr", "steuerklasse", "einkommensbereich", "lohnsteuer", "_meta"]}',
    '"{\"steuerjahr\": \"Das Jahr, f\u00fcr das die Lohnsteuertabelle gilt. Format: JJJJ (z. B. 2023). Wichtig f\u00fcr die Zuordnung der Steuerdaten zum richtigen Veranlagungszeitraum in der Steuererkl\u00e4rung.\", \"steuerklasse\": \"Die Steuerklasse (I-VI), f\u00fcr die die Tabelle gilt. Format: R\u00f6mische Ziffer (z. B. III). Relevant f\u00fcr die korrekte Einordnung der Lohnsteuer in Anlage N der Steuererkl\u00e4rung.\", \"einkommensbereich\": \"Der Bruttoeinkommensbereich in Euro, f\u00fcr den die Steuerwerte gelten. Format: ''von-bis'' (z. B. ''30.000-30.500''). Wichtig zur \u00dcberpr\u00fcfung, ob die eigene Lohnsteuer korrekt berechnet wurde.\", \"lohnsteuer\": \"Die H\u00f6he der Lohnsteuer in Euro f\u00fcr den angegebenen Einkommensbereich und die Steuerklasse. Format: Dezimalzahl (z. B. 4500.00). Wird in Anlage N der Steuererkl\u00e4rung zur Gegen\u00fcberstellung mit den tats\u00e4chlich abgef\u00fchrten Betr\u00e4gen genutzt.\", \"soli\": \"Die H\u00f6he des Solidarit\u00e4tszuschlags in Euro f\u00fcr den angegebenen Einkommensbereich und die Steuerklasse. Format: Dezimalzahl (z. B. 247.50). Relevant f\u00fcr die Steuererkl\u00e4rung, da der Soli in der Anlage N (Zeile 26) anzugeben ist.\"}"',
    'Lohnsteuertabelle, Steuerklasse, Einkommensbereich, Lohnsteuer, Solidaritätszuschlag, Soli, Kirchensteuer, Jahreslohnsteuer, Steuerjahr, Bruttoeinkommen, Nettoeinkommen, Steuerberechnung, Finanzamt, Lohnsteuerabzug, tax table, income tax table, wage tax, church tax, solidarity surcharge, tax class, taxable income',
    'Finanzamt',
    '{"paragraphen": "§38a EStG (Lohnsteuerabzug), §3 Abs. 4 SolZG (Solidaritätszuschlag), §51a EStG (Kirchensteuer)", "anlage": null, "hinweise": "Die Lohnsteuertabelle selbst ist nicht direkt in der Steuererklärung anzugeben, dient aber als Grundlage für die Berechnung der bereits abgeführten Lohnsteuer (Anlage N, Zeilen 21-24). Die Werte können zur Plausibilitätsprüfung der eigenen Lohnabrechnung oder zur Schätzung der Steuerlast genutzt werden."}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
