INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'timesheet',
    'E. Arbeit & Einkommen',
    'Arbeitszeitnachweis/Stundenzettel',
    'Ein Arbeitszeitnachweis oder Stundenzettel dokumentiert die geleisteten Arbeitsstunden eines Arbeitnehmers innerhalb eines bestimmten Zeitraums. Er wird typischerweise monatlich oder wöchentlich erstellt und dient der Abrechnung von Arbeitszeiten, Überstunden, Urlaubs- und Krankheitstagen. Im Gegensatz zu Gehaltsabrechnungen oder Arbeitsverträgen enthält er detaillierte tägliche Einträge zu Arbeitsbeginn, -ende, Pausen und Tätigkeiten.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "Timesheet", "description": "Arbeitszeitnachweis/Stundenzettel", "type": "object", "properties": {"arbeitnehmer": {"type": "object", "properties": {"name": {"type": "string"}, "personalnummer": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort", "land"]}, "steuernummer": {"type": "string"}}, "required": ["name"]}, "arbeitgeber": {"type": "object", "properties": {"name": {"type": "string"}, "firmennummer": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort", "land"]}, "steuernummer": {"type": "string"}}, "required": ["name"]}, "zeitraum": {"type": "object", "properties": {"von": {"type": "string", "format": "date"}, "bis": {"type": "string", "format": "date"}}, "required": ["von", "bis"]}, "eintraege": {"type": "array", "items": {"type": "object", "properties": {"datum": {"type": "string", "format": "date"}, "beginn": {"type": "string", "pattern": "^([01]?[0-9]|2[0-3]):[0-5][0-9]$"}, "ende": {"type": "string", "pattern": "^([01]?[0-9]|2[0-3]):[0-5][0-9]$"}, "pause_minuten": {"type": "integer", "minimum": 0}, "ist_stunden": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}, "projekt": {"type": "string"}, "taetigkeit": {"type": "string"}}, "required": ["datum", "beginn", "ende", "ist_stunden"]}}, "soll_stunden_gesamt": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}, "ist_stunden_gesamt": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}, "ueberstunden": {"type": "string", "pattern": "^(-?\\d+\\.\\d{2})$"}, "urlaubstage_genommen": {"type": "number", "minimum": 0}, "krankheitstage": {"type": "number", "minimum": 0}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^\\d{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$", "nullable": true}, "mwst_satz": {"type": "string", "pattern": "^\\d+(\\.\\d{1,2})?$", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant"]}}, "required": ["arbeitnehmer", "arbeitgeber", "zeitraum", "eintraege", "_meta"]}',
    '"arbeitnehmer, arbeitgeber, zeitraum, eintraege[] (datum, beginn, ende, pause_minuten, ist_stunden, projekt, taetigkeit), soll_stunden_gesamt, ist_stunden_gesamt, ueberstunden, urlaubstage_genommen, krankheitstage"',
    'Arbeitszeitnachweis, Stundenzettel, timesheet, Arbeitszeiten, geleistete Stunden, Überstunden, Urlaubstage, Krankheitstage, Projekt, Tätigkeit, Beginn, Ende, Pause, Soll-Stunden, Ist-Stunden, Arbeitnehmer, Arbeitgeber, Zeitraum, Monatsübersicht, Wochenübersicht, Arbeitszeiterfassung, Zeiterfassung, Arbeitsnachweis',
    'Arbeitnehmer, Arbeitgeber',
    '{"relevanz": "indirekt"}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
