INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'travel_expense',
    'E. Arbeit & Einkommen',
    'Reisekostenabrechnung',
    'Eine Reisekostenabrechnung dokumentiert berufsbedingte Ausgaben eines Arbeitnehmers für Dienstreisen, die vom Arbeitgeber erstattet werden. Sie umfasst typischerweise Fahrtkosten, Übernachtungskosten, Verpflegungsmehraufwand und Nebenkosten. Im Gegensatz zu privaten Reiseunterlagen oder Spesenabrechnungen für Kunden enthält sie spezifische Angaben zur dienstlichen Veranlassung und wird vom Arbeitnehmer an den Arbeitgeber übermittelt.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "travel_expense", "description": "Reisekostenabrechnung", "type": "object", "properties": {"reisender": {"type": "object", "properties": {"name": {"type": "string"}, "mitarbeiter_nummer": {"type": "string"}, "abteilung": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort", "land"]}}, "required": ["name"]}, "dienstreise_von": {"type": "string", "format": "date"}, "dienstreise_bis": {"type": "string", "format": "date"}, "reiseziel": {"type": "object", "properties": {"ort": {"type": "string"}, "land": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": []}}, "required": ["ort", "land"]}, "reiseanlass": {"type": "string"}, "fahrtkosten": {"type": "object", "properties": {"betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}, "w\u00e4hrung": {"type": "string", "pattern": "^[A-Z]{3}$"}, "belegnummer": {"type": "string"}, "fahrzeug": {"type": "object", "properties": {"kennzeichen": {"type": "string"}, "typ": {"type": "string"}, "eigenes_fahrzeug": {"type": "boolean"}}, "required": []}, "strecke_km": {"type": "number", "minimum": 0}, "hin_und_rueck": {"type": "boolean"}}, "required": ["betrag", "w\u00e4hrung"]}, "uebernachtungskosten": {"type": "object", "properties": {"betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}, "w\u00e4hrung": {"type": "string", "pattern": "^[A-Z]{3}$"}, "belegnummer": {"type": "string"}, "hotel_name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": []}, "uebernachtungen": {"type": "integer", "minimum": 1}}, "required": ["betrag", "w\u00e4hrung"]}, "verpflegungsmehraufwand": {"type": "object", "properties": {"betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}, "w\u00e4hrung": {"type": "string", "pattern": "^[A-Z]{3}$"}, "tage_24h": {"type": "integer", "minimum": 0}, "tage_14h": {"type": "integer", "minimum": 0}, "tage_8h": {"type": "integer", "minimum": 0}}, "required": ["betrag", "w\u00e4hrung"]}, "nebenkosten": {"type": "array", "items": {"type": "object", "properties": {"betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}, "w\u00e4hrung": {"type": "string", "pattern": "^[A-Z]{3}$"}, "belegnummer": {"type": "string"}, "beschreibung": {"type": "string"}, "datum": {"type": "string", "format": "date"}, "kategorie": {"type": "string"}}, "required": ["betrag", "w\u00e4hrung", "beschreibung"]}}, "gesamtbetrag": {"type": "object", "properties": {"betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}, "w\u00e4hrung": {"type": "string", "pattern": "^[A-Z]{3}$"}}, "required": ["betrag", "w\u00e4hrung"]}, "km_pauschale": {"type": "object", "properties": {"betrag_pro_km": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}, "w\u00e4hrung": {"type": "string", "pattern": "^[A-Z]{3}$"}, "gesamt_km": {"type": "number", "minimum": 0}, "gesamtbetrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}}, "required": ["betrag_pro_km", "w\u00e4hrung", "gesamt_km", "gesamtbetrag"]}, "abwesenheitsstunden": {"type": "integer", "minimum": 0}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null]}, "steuerjahr": {"type": "string", "pattern": "^\\d{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$", "nullable": true}, "mwst_satz": {"type": "string", "pattern": "^\\d+(\\.\\d{1,2})?$", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}, "positionen": {"type": "array", "description": "Einzelpositionen der Reisekostenabrechnung (Fahrt, \u00dcbernachtung, Verpflegung, etc.)", "items": {"type": "object", "properties": {"beschreibung": {"type": "string"}, "datum": {"type": "string"}, "betrag": {"type": "string"}}}}}, "required": ["reisender", "dienstreise_von", "dienstreise_bis", "reiseziel", "reiseanlass", "gesamtbetrag", "_meta"]}',
    '"reisender, dienstreise_von, dienstreise_bis, reiseziel, reiseanlass, fahrtkosten, uebernachtungskosten, verpflegungsmehraufwand, nebenkosten[], gesamtbetrag, km_pauschale, abwesenheitsstunden"',
    'Reisekostenabrechnung, Dienstreise, Fahrtkosten, Übernachtungskosten, Verpflegungsmehraufwand, Verpflegungspauschale, Nebenkosten, Reiseziel, Reiseanlass, Abwesenheitsdauer, km-Pauschale, Spesenabrechnung, travel expense report, business trip, per diem, accommodation costs, travel costs, absence hours',
    'Arbeitnehmer → Arbeitgeber',
    '{"paragraphen": "§4 Abs. 4, §9 EStG (Werbungskosten), §3 Nr. 16 EStG (steuerfreie Erstattungen), §9 Abs. 4a EStG (Verpflegungspauschalen)", "anlage": "Anlage N (Werbungskosten), ggf. Anlage Vorsorgeaufwand (bei nicht erstatteten Kosten)", "absetzbare_betraege": {"verpflegungsmehraufwand": "28€ (24h Abwesenheit), 14€ (8-24h), 14€ (An-/Abreisetag mit Übernachtung)", "fahrtkosten": "0,30€ pro km (Dienstwagen: 0,03% des Listenpreises pro km), öffentliche Verkehrsmittel: tatsächliche Kosten", "uebernachtungskosten": "Tatsächliche Kosten (ohne Frühstück, sofern separat ausgewiesen)"}}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
