INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'warning_letter',
    'E. Arbeit & Einkommen',
    'Abmahnung',
    'Eine Abmahnung ist ein formelles Schreiben des Arbeitgebers an den Arbeitnehmer, das ein Fehlverhalten dokumentiert und Konsequenzen bei Wiederholung androht. Sie dient als Vorstufe zu einer möglichen Kündigung und kommt typischerweise bei Verstößen gegen arbeitsvertragliche Pflichten vor. Im Gegensatz zu einer einfachen Rüge oder einem Feedbackgespräch ist die Abmahnung rechtlich bindend und muss schriftlich erfolgen.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "warning_letter", "description": "Abmahnung", "type": "object", "properties": {"arbeitgeber": {"type": "object", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort", "land"]}, "kontakt": {"type": "object", "properties": {"telefon": {"type": "string"}, "email": {"type": "string", "format": "email"}}}}, "required": ["name", "adresse"]}, "arbeitnehmer": {"type": "object", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort", "land"]}, "personalnummer": {"type": "string"}}, "required": ["name", "adresse"]}, "datum": {"type": "string", "format": "date"}, "vorfall_datum": {"type": "string", "format": "date"}, "vorfall_beschreibung": {"type": "string"}, "konsequenz_androhung": {"type": "string"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^[0-9]{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$", "nullable": true}, "mwst_satz": {"type": "string", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"], "additionalProperties": false}}, "required": ["arbeitgeber", "arbeitnehmer", "datum", "vorfall_datum", "vorfall_beschreibung", "konsequenz_androhung", "_meta"], "additionalProperties": false}',
    '"{\"arbeitgeber\": \"Name und Anschrift des Arbeitgebers, der die Abmahnung ausstellt. Wichtig f\u00fcr die Zuordnung des Dokuments zum richtigen Arbeitsverh\u00e4ltnis. Beispiel: ''Muster GmbH, Musterstra\u00dfe 1, 12345 Berlin''.\", \"arbeitnehmer\": \"Name und Anschrift des Arbeitnehmers, an den die Abmahnung gerichtet ist. Beispiel: ''Max Mustermann, Musterweg 2, 12345 Berlin''.\", \"datum\": \"Ausstellungsdatum der Abmahnung im Format TT.MM.JJJJ. Wichtig f\u00fcr die Dokumentation des Zeitpunkts der Abmahnung. Beispiel: ''15.10.2023''.\", \"vorfall_datum\": \"Datum des Vorfalls, der zur Abmahnung gef\u00fchrt hat, im Format TT.MM.JJJJ. Beispiel: ''10.10.2023''. Wichtig f\u00fcr die zeitliche Einordnung des Fehlverhaltens.\", \"vorfall_beschreibung\": \"Detaillierte Beschreibung des Fehlverhaltens oder der Pflichtverletzung. Beispiel: ''Unentschuldigtes Fehlen am 10.10.2023 ohne vorherige Information''.\", \"konsequenz_androhung\": \"Angedrohte Konsequenzen bei Wiederholung des Fehlverhaltens, z. B. K\u00fcndigung. Beispiel: ''Im Wiederholungsfall behalten wir uns die K\u00fcndigung des Arbeitsverh\u00e4ltnisses vor''.\"}"',
    'Abmahnung, Mahnung, Fehlverhalten, Pflichtverletzung, arbeitsrechtlich, Kündigungsandrohung, Wiederholungsfall, Verstoß, Arbeitgeber, Arbeitnehmer, schriftliche Rüge, Vorfall, Konsequenzen, arbeitsvertraglich, Ermahnung, warning letter, misconduct, breach of duty, termination threat',
    'Arbeitgeber',
    NULL,
    0,
    1,
    1,
    'mistral_batch',
    'Häufige Verwechslungen mit einfachen Rügen oder Feedbackgesprächsprotokollen. Eine Abmahnung muss immer schriftlich erfolgen und eine klare Konsequenzandrohung enthalten. Sonderfälle: Abmahnungen können auch bei leichteren Verstößen ausgesprochen werden, wenn diese wiederholt auftreten. Tipp: Achten Sie auf Formulierungen wie ''Abmahnung'' oder ''Kündigungsandrohung'' im Dokument.'
)
