INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'work_hours_overview',
    'E. Arbeit & Einkommen',
    'Arbeitszeitübersicht',
    'Eine Arbeitszeitübersicht ist ein Dokument, das vom Arbeitgeber ausgestellt wird und die geleisteten Arbeitsstunden, Überstunden, Urlaubstage sowie Krankheitstage eines Arbeitnehmers innerhalb eines bestimmten Zeitraums auflistet. Es dient der Transparenz und Nachweisführung für Arbeitnehmer und kann für Lohnabrechnungen oder steuerliche Zwecke relevant sein. Im Gegensatz zu einer reinen Lohnabrechnung liegt der Fokus hier auf der detaillierten Aufschlüsselung der Arbeitszeiten und Abwesenheiten.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "work_hours_overview", "description": "Arbeitszeit\u00fcbersicht f\u00fcr einen Arbeitnehmer", "type": "object", "properties": {"arbeitnehmer": {"type": "object", "properties": {"name": {"type": "string"}, "personalnummer": {"type": "string"}, "abteilung": {"type": "string"}}, "required": ["name"]}, "zeitraum": {"type": "object", "properties": {"von": {"type": "string", "format": "date"}, "bis": {"type": "string", "format": "date"}}, "required": ["von", "bis"]}, "soll_stunden": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}, "ist_stunden": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}, "ueberstunden_konto": {"type": "string", "pattern": "^(-?\\d+\\.\\d{2})$"}, "urlaub_genommen": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}, "urlaub_rest": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}, "krankheitstage": {"type": "integer", "minimum": 0}, "feiertage": {"type": "integer", "minimum": 0}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^\\d{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$", "nullable": true}, "mwst_satz": {"type": "string", "pattern": "^\\d+(\\.\\d{1,2})?$", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}, "eintraege": {"type": "array", "description": "Einzelne Arbeitszeiteintr\u00e4ge (Tage, Stunden, \u00dcberstunden, etc.)", "items": {"type": "object", "properties": {"datum": {"type": "string"}, "beginn": {"type": "string"}, "ende": {"type": "string"}, "stunden": {"type": "string"}, "ueberstunden": {"type": "string"}}}}}, "required": ["arbeitnehmer", "zeitraum", "soll_stunden", "ist_stunden", "_meta"]}',
    '"{\"arbeitnehmer\": \"Name des Arbeitnehmers, f\u00fcr den die Arbeitszeit\u00fcbersicht erstellt wurde. Format: Vorname Nachname. Beispiel: ''Max Mustermann''. Wichtig f\u00fcr die Zuordnung des Dokuments zum richtigen Arbeitnehmer.\", \"zeitraum\": \"Der Zeitraum, f\u00fcr den die Arbeitszeiten und Abwesenheiten aufgelistet werden. Format: ''MM.JJJJ - MM.JJJJ'' oder ''TT.MM.JJJJ - TT.MM.JJJJ''. Beispiel: ''01.2023 - 12.2023'' oder ''01.01.2023 - 31.12.2023''. Wichtig f\u00fcr die zeitliche Einordnung der Daten.\", \"soll_stunden\": \"Die vertraglich vereinbarten Arbeitsstunden, die im angegebenen Zeitraum geleistet werden sollen. Format: Dezimalzahl (z. B. 160,0 f\u00fcr 160 Stunden). Beispiel: ''160,0''. Dient als Referenzwert f\u00fcr die Ist-Stunden.\", \"ist_stunden\": \"Die tats\u00e4chlich geleisteten Arbeitsstunden im angegebenen Zeitraum. Format: Dezimalzahl (z. B. 158,5 f\u00fcr 158,5 Stunden). Beispiel: ''158,5''. Wichtig f\u00fcr den Abgleich mit den Soll-Stunden und die Berechnung von \u00dcberstunden.\", \"ueberstunden_konto\": \"Der Stand des \u00dcberstundenkontos am Ende des angegebenen Zeitraums. Format: Dezimalzahl (positiv oder negativ, z. B. +5,5 oder -2,0). Beispiel: ''+5,5''. Relevant f\u00fcr die Dokumentation von Mehrarbeit oder Minderarbeit.\", \"urlaub_genommen\": \"Die Anzahl der im Zeitraum genommenen Urlaubstage. Format: Ganzzahl. Beispiel: ''20''. Wichtig f\u00fcr die Nachverfolgung des Urlaubsanspruchs.\", \"urlaub_rest\": \"Der verbleibende Urlaubsanspruch am Ende des Zeitraums. Format: Ganzzahl. Beispiel: ''10''. Relevant f\u00fcr die Planung zuk\u00fcnftiger Urlaubstage.\", \"krankheitstage\": \"Die Anzahl der Krankheitstage im angegebenen Zeitraum. Format: Ganzzahl. Beispiel: ''5''. Kann f\u00fcr steuerliche oder sozialversicherungsrechtliche Zwecke relevant sein (z. B. Nachweis f\u00fcr Krankengeld).\", \"feiertage\": \"Die Anzahl der Feiertage, die in den Zeitraum fallen und an denen nicht gearbeitet wurde. Format: Ganzzahl. Beispiel: ''8''. Wichtig f\u00fcr die korrekte Berechnung der Soll-Stunden.\"}"',
    'Arbeitszeitübersicht, Arbeitszeitnachweis, Stundenübersicht, Soll-Stunden, Ist-Stunden, Überstundenkonto, Überstunden, Urlaubstage, Resturlaub, Krankheitstage, Feiertage, Arbeitnehmer, Zeitraum, Arbeitszeit, time tracking, work hours, overtime, leave days, sick days, public holidays, employee, period',
    'Arbeitgeber',
    NULL,
    0,
    1,
    1,
    'mistral_batch',
    'Häufig wird die Arbeitszeitübersicht mit der Lohnabrechnung verwechselt, da beide Dokumente vom Arbeitgeber stammen und ähnliche Informationen enthalten können. Die Arbeitszeitübersicht fokussiert sich jedoch auf die detaillierte Aufschlüsselung der Arbeitszeiten und Abwesenheiten, während die Lohnabrechnung die finanziellen Aspekte (Gehalt, Abzüge etc.) behandelt. Achte auf Begriffe wie ''Soll-Stunden'', ''Ist-Stunden'' oder ''Überstundenkonto'', die typisch für dieses Template sind. Bei Teilzeitkräften oder flexiblen Arbeitszeitmodellen können die Felder ''soll_stunden'' und ''ist_stunden'' stark variieren.'
)
