    'CO2-Kostenaufteilung zwischen Vermieter und Mieter nach CO2KostAufG',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "co2_statement", "description": "Schema fuer CO2-Kostenaufteilung", "type": "object", "properties": {"abrechnungszeitraum": {"type": "object", "properties": {"von": {"type": "string", "format": "date"}, "bis": {"type": "string", "format": "date"}}}, "co2_emissionen_gesamt_kg": {"type": "string"}, "co2_kosten_gesamt": {"type": "string"}, "anteil_vermieter_prozent": {"type": "string"}, "anteil_mieter_prozent": {"type": "string"}, "anteil_vermieter_betrag": {"type": "string"}, "anteil_mieter_betrag": {"type": "string"}, "energietraeger": {"type": "string"}, "verbrauch_kwh": {"type": "string"}, "co2_preis_pro_tonne": {"type": "string"}, "objekt_adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "pattern": "^[A-Z]{2}$"}}}, "einstufung": {"type": "string", "description": "Gebaeude-Einstufung nach CO2KostAufG"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "default": null}, "steuer_kategorie": {"type": "string", "default": null}, "steuerjahr": {"type": "string", "pattern": "^[0-9]{4}$", "default": null}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "default": null}, "mwst_satz": {"type": "string", "default": null}, "aktenzeichen": {"type": "string", "default": null}, "dokumenten_id": {"type": "string", "default": null}, "absender": {"type": "string"}, "empfaenger": {"type": "string"}, "datum": {"type": "string", "format": "date"}, "betreff": {"type": "string"}}}}}',
    NULL,
    NULL,
    NULL,
    NULL,
    0,
