INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'condo_protocol',
    'F. Wohnen & Immobilien',
    'WEG-Eigentümerversammlungs-Protokoll',
    'Das WEG-Eigentümerversammlungs-Protokoll dokumentiert die Beschlüsse und Diskussionen einer Versammlung von Wohnungseigentümern (WEG). Es wird nach jeder Eigentümerversammlung von der Hausverwaltung erstellt und enthält wichtige Entscheidungen zu Wirtschaftsplan, Instandhaltung oder baulichen Maßnahmen. Im Gegensatz zu Mietverträgen oder Hausgeldabrechnungen liegt der Fokus auf kollektiven Beschlüssen und Abstimmungsergebnissen der Eigentümergemeinschaft.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "condo_protocol", "description": "WEG-Eigentümerversammlungs-Protokoll", "type": "object", "properties": {"verwaltung": {"type": "object", "properties": {"name": {"type": "string"}, "ansprechpartner": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort", "land"]}, "telefon": {"type": "string"}, "email": {"type": "string", "format": "email"}}, "required": ["name"]}, "weg_name": {"type": "string"}, "objekt": {"type": "object", "properties": {"bezeichnung": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort", "land"]}}, "required": ["bezeichnung", "adresse"]}, "datum": {"type": "string", "format": "date"}, "teilnehmer_anwesend": {"type": "array", "items": {"type": "object", "properties": {"name": {"type": "string"}, "einheit": {"type": "string"}, "vertreten_durch": {"type": "string"}}, "required": ["name"]}}, "teilnehmer_vertreten": {"type": "array", "items": {"type": "object", "properties": {"name": {"type": "string"}, "einheit": {"type": "string"}, "vertreter": {"type": "string"}}, "required": ["name", "vertreter"]}}, "beschluesse": {"type": "array", "items": {"type": "object", "properties": {"top": {"type": "string"}, "beschluss": {"type": "string"}, "abstimmung_ja_nein_enthaltung": {"type": "object", "properties": {"ja": {"type": "integer"}, "nein": {"type": "integer"}, "enthaltung": {"type": "integer"}}, "required": ["ja", "nein", "enthaltung"]}}, "required": ["top", "beschluss", "abstimmung_ja_nein_enthaltung"]}}, "wirtschaftsplan": {"type": "object", "properties": {"gesamtvolumen": {"type": "string"}, "währung": {"type": "string"}, "aufschluesselung": {"type": "array", "items": {"type": "object", "properties": {"position": {"type": "string"}, "betrag": {"type": "string"}}, "required": ["position", "betrag"]}}}, "required": ["gesamtvolumen", "währung"]}, "instandhaltungsruecklage": {"type": "object", "properties": {"aktueller_stand": {"type": "string"}, "währung": {"type": "string"}, "geplante_entnahmen": {"type": "array", "items": {"type": "object", "properties": {"zweck": {"type": "string"}, "betrag": {"type": "string"}, "datum": {"type": "string", "format": "date"}}, "required": ["zweck", "betrag"]}}}, "required": ["aktueller_stand", "währung"]}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^[0-9]{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "nullable": true}, "mwst_satz": {"type": "string", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}, "objekt_adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "default": "DE"}}, "description": "WEG-Objekt/Liegenschaft"}}, "required": ["weg_name", "objekt", "datum", "beschluesse", "_meta"]}',
    '"verwaltung, weg_name, objekt, datum, teilnehmer_anwesend, teilnehmer_vertreten, beschluesse[] (top, beschluss, abstimmung_ja_nein_enthaltung), wirtschaftsplan, instandhaltungsruecklage"',
    'WEG, Wohnungseigentümergemeinschaft, Eigentümerversammlung, Protokoll, Beschlüsse, Abstimmung, Hausverwaltung, Wirtschaftsplan, Instandhaltungsrücklage, TOP, Tagesordnung, Ja-Stimmen, Nein-Stimmen, Enthaltungen, Eigentümerliste, Vertretung, Unterschrift, Protokollführer, Beschlussfassung, Sonderumlage, Hausgeld, Gemeinschaftseigentum, condominium, owner''s meeting, minutes, resolution',
    'Hausverwaltung',
    '{"paragraphen": "§35a EStG (haushaltsnahe Dienstleistungen), §10f EStG (Sanierungsmaßnahmen)", "anlage": "V (bei vermieteten Einheiten), N (bei selbstgenutztem Wohneigentum)"}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
