INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'declaration_of_division',
    'F. Wohnen & Immobilien',
    'Teilungserklärung',
    'Die Teilungserklärung ist ein notarielles Dokument, das die Aufteilung einer Immobilie in einzelne Wohneinheiten (z. B. Eigentumswohnungen) rechtlich regelt. Sie wird bei der Begründung von Wohnungseigentum nach dem Wohnungseigentumsgesetz (WEG) erstellt und definiert die Eigentumsverhältnisse, Miteigentumsanteile sowie Sonder- und Gemeinschaftseigentum. Im Gegensatz zum Kaufvertrag oder Grundbuchauszug liegt der Fokus hier auf der strukturellen und rechtlichen Aufteilung der Immobilie, nicht auf dem Eigentumsübergang oder Grundstücksdetails.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "declaration_of_division", "description": "Teilungserklärung", "type": "object", "properties": {"notar": {"type": "object", "properties": {"name": {"type": "string"}, "anschrift": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "pattern": "^[A-Z]{2}$"}}, "required": ["strasse", "plz", "ort", "land"]}, "telefon": {"type": "string", "pattern": "^\\+[0-9]{8,15}$"}, "email": {"type": "string", "format": "email"}}, "required": ["name"]}, "urkundennummer": {"type": "string"}, "objekt": {"type": "object", "properties": {"bezeichnung": {"type": "string"}, "anschrift": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "pattern": "^[A-Z]{2}$"}}, "required": ["strasse", "plz", "ort", "land"]}, "grundbuch": {"type": "object", "properties": {"blatt": {"type": "string"}, "amt": {"type": "string"}, "bezirk": {"type": "string"}}, "required": ["blatt", "amt"]}}, "required": ["bezeichnung", "anschrift"]}, "einheiten": {"type": "array", "items": {"type": "object", "properties": {"einheit_nr": {"type": "string"}, "lage": {"type": "string"}, "nutzflaeche_qm": {"type": "number", "minimum": 0}, "raeume": {"type": "array", "items": {"type": "object", "properties": {"raumtyp": {"type": "string"}, "flaeche_qm": {"type": "number", "minimum": 0}}, "required": ["raumtyp", "flaeche_qm"]}}, "sondernutzungsrechte": {"type": "array", "items": {"type": "string"}}}, "required": ["einheit_nr", "lage", "nutzflaeche_qm"]}}, "miteigentumsanteile": {"type": "array", "items": {"type": "object", "properties": {"einheit_nr": {"type": "string"}, "anteil_zaehler": {"type": "integer", "minimum": 1}, "anteil_nenner": {"type": "integer", "minimum": 1}, "anteil_prozent": {"type": "number", "minimum": 0, "maximum": 100}}, "required": ["einheit_nr", "anteil_zaehler", "anteil_nenner"]}}, "sondernutzungsrechte": {"type": "array", "items": {"type": "object", "properties": {"bezeichnung": {"type": "string"}, "beschreibung": {"type": "string"}, "zugeordnete_einheiten": {"type": "array", "items": {"type": "string"}}}, "required": ["bezeichnung", "zugeordnete_einheiten"]}}, "gemeinschaftsordnung_zusammenfassung": {"type": "string"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^[0-9]{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$", "nullable": true}, "mwst_satz": {"type": "string", "pattern": "^[0-9]+(\\.[0-9]{1,2})?$", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}, "objekt_adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "default": "DE"}}, "description": "Objekt/Liegenschaft"}}, "required": ["urkundennummer", "objekt", "einheiten", "miteigentumsanteile", "_meta"]}',
    '"{\"notar\": \"Name und Anschrift des Notars oder der Notarkanzlei, der/die die Teilungserkl\u00e4rung beurkundet hat. Format: ''Notar Dr. Max Mustermann, Musterstra\u00dfe 1, 12345 Berlin''. Wichtig f\u00fcr die Identifikation des Dokuments und ggf. f\u00fcr Nachfragen beim Grundbuchamt.\", \"urkundennummer\": \"Eindeutige Nummer der notariellen Urkunde, z. B. ''UR-Nr. 123/2023''. Format: alphanumerisch, oft mit Pr\u00e4fix wie ''UR-Nr.'' oder ''Not.-Urk.-RNr.''. Wichtig f\u00fcr die Zuordnung im Grundbuch und bei sp\u00e4teren \u00c4nderungen der Teilungserkl\u00e4rung.\", \"objekt\": \"Beschreibung der Gesamtimmobilie, z. B. ''Mehrfamilienhaus mit 6 Wohneinheiten und 2 Gewerbeeinheiten, Musterstra\u00dfe 10, 12345 Berlin''. Enth\u00e4lt oft Grundbuchblatt-Nummer und Flurst\u00fcck. Wichtig f\u00fcr die Identifikation der Immobilie im Grundbuch und f\u00fcr steuerliche Zwecke (z. B. AfA-Bemessung).\"}"',
    'Teilungserklärung, WEG, Wohnungseigentumsgesetz, Miteigentumsanteil, Sondereigentum, Gemeinschaftseigentum, Sondernutzungsrecht, Aufteilungsplan, Urkundennummer, Notar, Eigentumswohnung, Teilungsvermerk, Gemeinschaftsordnung, Sondereigentumseinheit, Miteigentumsbruchteil, Grundbuchblatt, declaration of division, condominium declaration, co-ownership share, special ownership, common property',
    'Notar, WEG',
    '{"einkommensteuer": {"paragraphen": "§3 EStG (Einkünfte aus Vermietung und Verpachtung), §7 EStG (Absetzung für Abnutzung - AfA), §9 EStG (Werbungskosten)", "anlage": "Anlage V (Einkünfte aus Vermietung und Verpachtung)", "hinweise": "Die Teilungserklärung selbst ist nicht direkt steuerrelevant, aber die darin definierten Miteigentumsanteile und Sondereigentumseinheiten sind Grundlage für die Aufteilung von Einnahmen (Miete) und Ausgaben (AfA, Instandhaltung) bei vermieteten Eigentumswohnungen. Die Miteigentumsanteile bestimmen den prozentualen Anteil an Gemeinschaftseigentum (z. B. Dach, Fassade), der bei der AfA-Berechnung berücksichtigt wird. Sondernutzungsrechte können den Wert des Sondereigentums erhöhen und damit die AfA-Bemessungsgrundlage beeinflussen."}, "grunderwerbsteuer": {"paragraphen": "§1 GrEStG", "hinweise": "Die Teilungserklärung kann bei der Begründung von Wohnungseigentum grunderwerbsteuerpflichtig sein, wenn die Aufteilung mit einer Übertragung von Miteigentumsanteilen verbunden ist (z. B. bei Umwandlung eines Mehrfamilienhauses in Eigentumswohnungen). Die Steuer bemisst sich nach dem Wert der Gegenleistung oder dem Grundbesitzwert."}}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
