INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'deposit_settlement',
    'F. Wohnen & Immobilien',
    'Kautionsabrechnung',
    'Die Kautionsabrechnung ist ein Dokument, das vom Vermieter nach Beendigung des Mietverhältnisses erstellt wird, um die Rückzahlung der hinterlegten Mietkaution inklusive Zinsen zu regeln. Es listet die einbehaltenen Beträge für Schäden oder Nachzahlungen (z. B. Nebenkosten) auf und zeigt den finalen Auszahlungsbetrag. Im Gegensatz zur Nebenkostenabrechnung bezieht sich die Kautionsabrechnung ausschließlich auf die Kaution und deren Abzüge, nicht auf laufende Betriebskosten.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "Deposit Settlement", "description": "Schema für Kautionsabrechnungen", "type": "object", "properties": {"vermieter": {"type": "object", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort", "land"]}, "telefon": {"type": "string"}, "email": {"type": "string", "format": "email"}, "iban": {"type": "string"}}, "required": ["name", "adresse"]}, "mieter": {"type": "object", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort", "land"]}, "telefon": {"type": "string"}, "email": {"type": "string", "format": "email"}}, "required": ["name", "adresse"]}, "objekt": {"type": "object", "properties": {"adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort", "land"]}, "wohnungsnummer": {"type": "string"}, "mietvertragsnummer": {"type": "string"}, "mietbeginn": {"type": "string", "format": "date"}, "mietende": {"type": "string", "format": "date"}}, "required": ["adresse"]}, "kaution_betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}, "zinsen": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}, "abzuege": {"type": "array", "items": {"type": "object", "properties": {"schaeden": {"type": "object", "properties": {"beschreibung": {"type": "string"}, "betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}}, "required": ["beschreibung", "betrag"]}, "nachzahlung_nebenkosten": {"type": "object", "properties": {"betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}, "begruendung": {"type": "string"}}, "required": ["betrag"]}}, "anyOf": [{"required": ["schaeden"]}, {"required": ["nachzahlung_nebenkosten"]}]}}, "auszahlungsbetrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^\\d{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$", "nullable": true}, "mwst_satz": {"type": "string", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}, "positionen": {"type": "array", "description": "Einzelpositionen der Kautionsabrechnung (Reparaturen, Reinigung, ausstehende Nebenkosten, etc.)", "items": {"type": "object", "properties": {"beschreibung": {"type": "string"}, "betrag": {"type": "string"}, "beleg": {"type": "string"}}}}, "objekt_adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "default": "DE"}}, "description": "Mietobjekt-Adresse"}}, "required": ["vermieter", "mieter", "objekt", "kaution_betrag", "auszahlungsbetrag", "_meta"]}',
    '"vermieter, mieter, objekt, kaution_betrag, zinsen, abzuege[] (schaeden, nachzahlung_nebenkosten), auszahlungsbetrag"',
    'Kautionsabrechnung, Mietkaution, Kaution, Rückzahlung, Zinsen, Schäden, Abzüge, Auszahlungsbetrag, Mietsicherheit, deposit settlement, damage deduction, Nebenkostennachzahlung, Vermieter, Mieter, Mietobjekt, Kautionskonto, Endabrechnung, Mietende, Kautionsrückzahlung, security deposit, final settlement',
    'Vermieter',
    '{"einkommensteuer": {"paragraph": "§20 EStG (Einkünfte aus Kapitalvermögen)", "anlage": "KAP", "hinweis": "Zinsen auf die Mietkaution sind als Kapitalerträge steuerpflichtig, sofern sie den Sparer-Pauschbetrag (1.000 €/Jahr) überschreiten. Der Vermieter muss die Zinsen in der Regel automatisch versteuern, der Mieter muss sie ggf. in der Anlage KAP angeben, falls sie ihm direkt gutgeschrieben werden."}, "werbungskosten": {"paragraph": "§9 EStG (Werbungskosten bei Vermietung und Verpachtung)", "anlage": "V"}}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
