INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'energy_bill',
    'F. Wohnen & Immobilien',
    'Energierechnung',
    'Eine Energierechnung ist die regelmäßige Abrechnung eines Energieversorgers (Strom, Gas) für den tatsächlichen Verbrauch eines Haushalts innerhalb eines bestimmten Zeitraums. Sie enthält detaillierte Angaben zu Verbrauch, Preisen, Abschlägen und einer eventuellen Nachzahlung oder Gutschrift. Im Gegensatz zu Abschlagsrechnungen oder Vorauszahlungsaufforderungen basiert sie auf dem tatsächlichen Zählerstand und ist die Grundlage für die Endabrechnung.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "energy_bill", "description": "Schema für Energierechnungen", "type": "object", "properties": {"zaehlernummer": {"description": "Eindeutige Nummer des Strom- oder Gaszählers", "type": "string"}, "verbrauch_kwh": {"description": "Verbrauch im Abrechnungszeitraum in Kilowattstunden", "type": "string"}, "zeitraum": {"description": "Abrechnungszeitraum", "type": "object", "properties": {"von": {"description": "Startdatum des Abrechnungszeitraums", "type": "string", "format": "date"}, "bis": {"description": "Enddatum des Abrechnungszeitraums", "type": "string", "format": "date"}}, "required": ["von", "bis"]}, "arbeitspreis": {"description": "Preis pro kWh in Währungseinheiten", "type": "object", "properties": {"betrag": {"type": "string"}, "waehrung": {"type": "string", "pattern": "^[A-Z]{3}$"}}, "required": ["betrag", "waehrung"]}, "grundpreis": {"description": "Grundpreis pro Abrechnungszeitraum", "type": "object", "properties": {"betrag": {"type": "string"}, "waehrung": {"type": "string", "pattern": "^[A-Z]{3}$"}}, "required": ["betrag", "waehrung"]}, "abschlag": {"description": "Monatlicher Abschlagsbetrag", "type": "object", "properties": {"betrag": {"type": "string"}, "waehrung": {"type": "string", "pattern": "^[A-Z]{3}$"}}, "required": ["betrag", "waehrung"]}, "nachzahlung_guthaben": {"description": "Nachzahlungs- oder Guthabenbetrag am Ende des Abrechnungszeitraums", "type": "object", "properties": {"betrag": {"type": "string"}, "waehrung": {"type": "string", "pattern": "^[A-Z]{3}$"}, "typ": {"description": "Art des Betrags (nachzahlung oder guthaben)", "type": "string", "enum": ["nachzahlung", "guthaben"]}}, "required": ["betrag", "waehrung", "typ"]}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^[0-9]{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "nullable": true}, "mwst_satz": {"type": "string", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}, "positionen": {"type": "array", "description": "Einzelpositionen der Energierechnung (Verbrauch, Grundpreis, Netzentgelte, Abgaben, etc.)", "items": {"type": "object", "properties": {"beschreibung": {"type": "string"}, "menge": {"type": "string"}, "einzelpreis": {"type": "string"}, "betrag": {"type": "string"}, "einheit": {"type": "string", "description": "Einheit (z.B. kWh, m3, Monat)"}}}}, "objekt_adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "default": "DE"}}, "description": "Verbrauchsstelle/Liegenschaft"}, "waehrung": {"type": "string", "default": "EUR", "description": "Waehrung ISO 4217 (EUR, USD, etc.)"}, "verbrauch_einheit": {"type": "string", "description": "Einheit des Verbrauchs (z.B. kWh, m3)"}}, "required": ["zaehlernummer", "verbrauch_kwh", "zeitraum", "arbeitspreis", "grundpreis", "abschlag", "_meta"]}',
    '"{\"zaehlernummer\": \"Eindeutige Identifikationsnummer des Strom- oder Gasz\u00e4hlers, meist 10-15-stellig. Wichtig f\u00fcr die Zuordnung der Rechnung zum richtigen Z\u00e4hler und zur \u00dcberpr\u00fcfung der Abrechnung. Beispiel: ''DE123456789012''.\", \"verbrauch_kwh\": \"Tats\u00e4chlicher Energieverbrauch im Abrechnungszeitraum in Kilowattstunden (kWh). Wichtig f\u00fcr die Berechnung der Kosten und zur \u00dcberpr\u00fcfung der Plausibilit\u00e4t. Beispiel: ''2500 kWh''.\", \"zeitraum\": \"Abrechnungszeitraum, meist ein Kalenderjahr oder 12 Monate. Format: ''TT.MM.JJJJ - TT.MM.JJJJ'' oder ''01.01.2023 - 31.12.2023''. Wichtig f\u00fcr die steuerliche Zuordnung (z. B. Homeoffice-Anteil).\", \"arbeitspreis\": \"Preis pro verbrauchter Kilowattstunde (kWh) in Cent oder Euro. Beispiel: ''30,5 ct/kWh'' oder ''0,305 \u20ac/kWh''. Wichtig f\u00fcr die Berechnung der Energiekosten und zur \u00dcberpr\u00fcfung der Preisgestaltung.\", \"grundpreis\": \"Fester monatlicher oder j\u00e4hrlicher Grundpreis f\u00fcr die Bereitstellung der Energie, unabh\u00e4ngig vom Verbrauch. Beispiel: ''120,00 \u20ac/Jahr'' oder ''10,00 \u20ac/Monat''. Wichtig f\u00fcr die Gesamtkostenberechnung.\", \"abschlag\": \"Regelm\u00e4\u00dfige Vorauszahlung (meist monatlich), die im Voraus geleistet wurde. Beispiel: ''12 x 80,00 \u20ac = 960,00 \u20ac''. Wichtig f\u00fcr die Berechnung der Nachzahlung oder Gutschrift.\"}"',
    'Stromrechnung, Gasrechnung, Energierechnung, Verbrauch, kWh, Zählernummer, Arbeitspreis, Grundpreis, Abschlag, Nachzahlung, Gutschrift, Rechnungsnummer, Zählerstand, Versorger, Netzbetreiber, EEG-Umlage, Stromsteuer, Zeitraum, Jahresverbrauch, energy bill, consumption, meter number, base price, energy price, advance payment, final settlement',
    'Versorger',
    '{"haushaltsnahe Dienstleistungen": {"paragraph": "§35a Abs. 3 EStG", "anlage": "Haushaltsnahe Aufwendungen (Anlage N)", "betrag": "20% der Arbeitskosten (z. B. Messdienstleistung), maximal 1.200 € pro Jahr", "hinweis": "Nur die Kosten für den Messdienst (z. B. Ablesung) sind absetzbar, nicht die Energiekosten selbst."}, "beruflich genutzter Anteil": {"paragraph": "§4 Abs. 4 EStG, §9 EStG", "anlage": "Anlage N (bei Selbstständigen) oder Werbungskosten", "betrag": "Anteilige Kosten bei Homeoffice oder beruflicher Nutzung (z. B. 20% des Verbrauchs)", "hinweis": "Nachweis durch Arbeitszimmer oder berufliche Nutzung erforderlich."}}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
