    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "energy_certificate", "description": "Schema fuer Energieausweise", "type": "object", "properties": {"gebaeude_adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "pattern": "^[A-Z]{2}$"}}}, "ausweistyp": {"type": "string", "description": "Bedarfsausweis oder Verbrauchsausweis"}, "endenergiebedarf": {"type": "string", "description": "kWh/m2a"}, "primaerenergiebedarf": {"type": "string", "description": "kWh/m2a"}, "energieeffizienzklasse": {"type": "string", "description": "A+ bis H"}, "baujahr": {"type": "string"}, "heizungsart": {"type": "string"}, "energietraeger": {"type": "string", "description": "Gas, Oel, Strom, Pellets, Fernwaerme, Waermepumpe"}, "co2_emissionen": {"type": "string", "description": "kg CO2/m2a"}, "gueltig_bis": {"type": "string", "format": "date"}, "aussteller": {"type": "string"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "default": null}, "steuer_kategorie": {"type": "string", "default": null}, "steuerjahr": {"type": "string", "pattern": "^[0-9]{4}$", "default": null}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "default": null}, "mwst_satz": {"type": "string", "default": null}, "aktenzeichen": {"type": "string", "default": null}, "dokumenten_id": {"type": "string", "default": null}, "absender": {"type": "string"}, "empfaenger": {"type": "string"}, "datum": {"type": "string", "format": "date"}, "betreff": {"type": "string"}}}}}',
