INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'land_register',
    'F. Wohnen & Immobilien',
    'Grundbuchauszug',
    'Ein Grundbuchauszug ist ein amtliches Dokument, das vom Grundbuchamt ausgestellt wird und alle rechtlichen Verhältnisse eines Grundstücks dokumentiert. Es kommt bei Immobilienkäufen, -verkäufen, Erbschaften oder Finanzierungen vor und enthält Eigentumsverhältnisse, Belastungen und Rechte Dritter. Im Gegensatz zu einem Katasterauszug (rein technische Daten) oder einem Flurstücksnachweis (nur Lage und Größe) ist der Grundbuchauszug das zentrale rechtliche Dokument für Eigentums- und Belastungsnachweise.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "Land Register Extraction Template", "description": "Schema for extracting data from a land register excerpt (Grundbuchauszug)", "type": "object", "properties": {"grundbuchamt": {"type": "string", "description": "Name of the land registry office"}, "grundbuchbezirk": {"type": "string", "description": "District of the land register"}, "blatt": {"type": "string", "description": "Land register volume/page number"}, "flurstueck": {"type": "string", "description": "Cadastral parcel number"}, "eigentuemer": {"type": "array", "items": {"type": "object", "properties": {"name": {"type": "string", "description": "Name of the owner"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort", "land"]}, "anteil": {"type": "string", "description": "Ownership share (e.g., ''1/2'')"}}, "required": ["name"]}}, "lasten_beschraenkungen": {"type": "array", "items": {"type": "object", "properties": {"typ": {"type": "string", "enum": ["hypothek", "grundschuld", "wegerecht", "wohnrecht"], "description": "Type of encumbrance or restriction"}, "betrag": {"type": "string", "description": "Amount for mortgages/land charges (e.g., ''50000.00'')"}, "waehrung": {"type": "string", "description": "Currency (ISO 4217)"}, "beguenstigter": {"type": "string", "description": "Beneficiary of the encumbrance"}, "eintragungsdatum": {"type": "string", "format": "date", "description": "Date of registration (YYYY-MM-DD)"}, "rang": {"type": "string", "description": "Ranking of the encumbrance"}, "beschreibung": {"type": "string", "description": "Additional description of the encumbrance"}}, "required": ["typ"]}}, "abteilung_I_II_III": {"type": "object", "properties": {"abteilung_I": {"type": "array", "items": {"type": "object", "properties": {"eintrag": {"type": "string", "description": "Entry in department I (ownership)"}, "datum": {"type": "string", "format": "date", "description": "Date of entry (YYYY-MM-DD)"}}, "required": ["eintrag"]}}, "abteilung_II": {"type": "array", "items": {"type": "object", "properties": {"eintrag": {"type": "string", "description": "Entry in department II (encumbrances)"}, "datum": {"type": "string", "format": "date", "description": "Date of entry (YYYY-MM-DD)"}}, "required": ["eintrag"]}}, "abteilung_III": {"type": "array", "items": {"type": "object", "properties": {"eintrag": {"type": "string", "description": "Entry in department III (mortgages/land charges)"}, "datum": {"type": "string", "format": "date", "description": "Date of entry (YYYY-MM-DD)"}, "betrag": {"type": "string", "description": "Amount for mortgages/land charges (e.g., ''50000.00'')"}, "waehrung": {"type": "string", "description": "Currency (ISO 4217)"}}, "required": ["eintrag"]}}}}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^[0-9]{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "nullable": true}, "mwst_satz": {"type": "string", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}, "objekt_adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "default": "DE"}}, "description": "Grundstueck/Liegenschaft"}}, "required": ["grundbuchamt", "grundbuchbezirk", "blatt", "flurstueck"]}',
    '"grundbuchamt, grundbuchbezirk, blatt, flurstueck, eigentuemer[], lasten_beschraenkungen[] (hypotheken, grundschulden, wegerechte, wohnrechte), abteilung_I_II_III"',
    'Grundbuchauszug, Grundbuchamt, Grundbuchbezirk, Blattnummer, Flurstück, Eigentümer, Abteilung I, Abteilung II, Abteilung III, Belastungen, Hypotheken, Grundschulden, Wegerecht, Wohnrecht, Grunddienstbarkeit, Auflassungsvormerkung, Erbbaurecht, Grundbuchauszug bestellen, Eigentumsnachweis, lastenfreier Erwerb, Grundstücksrecht, land register, encumbrances, easements, mortgage, property ownership',
    'Grundbuchamt',
    '{"einkommensteuer": {"paragraphen": "§ 23 EStG (private Veräußerungsgeschäfte), § 10e EStG (Altfälle: Eigenheimzulage), § 33 EStG (außergewöhnliche Belastungen bei Erbschaft/Schenkung)", "anlage": "Anlage V (Einkünfte aus Vermietung und Verpachtung), Anlage SO (Sonstige Einkünfte bei Veräußerungsgewinnen)", "hinweise": "Grundbuchauszüge sind für die steuerliche Bewertung von Immobilien relevant, z.B. bei Verkauf (Spekulationsfrist 10 Jahre), Vermietung (Abschreibung § 7 EStG) oder Erbschaft (Bewertung nach § 12 ErbStG). Belastungen wie Grundschulden können bei Schuldzinsenabzug (§ 9 EStG) eine Rolle spielen."}, "erbschaftsteuer": {"paragraphen": "§ 12 ErbStG (Bewertung von Grundbesitz), § 13d ErbStG (Familienheim)", "hinweise": "Der Grundbuchauszug dient als Nachweis für die Bewertung des vererbten Grundstücks. Lasten und Beschränkungen können den steuerlichen Wert mindern."}, "grunderwerbsteuer": {"paragraphen": "§ 1 GrEStG (Steuerbarkeit), § 8 GrEStG (Bemessungsgrundlage)"}}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
