INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'municipal_bill',
    'F. Wohnen & Immobilien',
    'Kommunale Rechnung',
    'Eine kommunale Rechnung ist eine Abrechnung von Stadtwerken oder der Kommune für Leistungen wie Wasser, Abwasser, Müllentsorgung oder Straßenreinigung. Sie unterscheidet sich von privaten Versorgerrechnungen (z. B. Strom/Gas) durch spezifische Gebühren wie Niederschlagswassergebühr und wird direkt von öffentlichen Einrichtungen ausgestellt. Typisch sind Zählernummern für Wasserverbrauch und detaillierte Aufschlüsselungen der Gebührenarten.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "municipal_bill", "description": "Schema für kommunale Rechnungen (z.B. Wasser, Abwasser, Müll)", "type": "object", "properties": {"zaehlernummer": {"description": "Eindeutige Nummer des Zählers", "type": "string"}, "verbrauch": {"description": "Verbrauch im Abrechnungszeitraum (Einheit je nach Medium)", "type": "number"}, "zeitraum": {"description": "Abrechnungszeitraum", "type": "object", "properties": {"von": {"description": "Startdatum des Abrechnungszeitraums", "type": "string", "format": "date"}, "bis": {"description": "Enddatum des Abrechnungszeitraums", "type": "string", "format": "date"}}, "required": ["von", "bis"]}, "grundgebuehr": {"description": "Feste Grundgebühr", "type": "string", "pattern": "^\\d+\\.\\d{2}$"}, "verbrauchsgebuehr": {"description": "Gebühr basierend auf dem Verbrauch", "type": "string", "pattern": "^\\d+\\.\\d{2}$"}, "niederschlagsgebuehr": {"description": "Gebühr für Niederschlagswasser (falls zutreffend)", "type": "string", "pattern": "^\\d+\\.\\d{2}$"}, "gesamtbetrag": {"description": "Gesamtbetrag der Rechnung", "type": "string", "pattern": "^\\d+\\.\\d{2}$"}, "waehrung": {"description": "Währung des Rechnungsbetrags (ISO 4217)", "type": "string", "pattern": "^[A-Z]{3}$", "default": "EUR"}, "rechnungsnummer": {"description": "Eindeutige Rechnungsnummer", "type": "string"}, "rechnungsdatum": {"description": "Datum der Rechnungserstellung", "type": "string", "format": "date"}, "zahlungsfrist": {"description": "Frist für die Zahlung", "type": "string", "format": "date"}, "empfaenger": {"description": "Empfänger der Rechnung (Adresse)", "type": "object", "properties": {"name": {"type": "string"}, "strasse": {"type": "string"}, "plz": {"type": "string", "pattern": "^\\d{5}$"}, "ort": {"type": "string"}, "land": {"type": "string", "pattern": "^[A-Z]{2}$", "default": "DE"}}, "required": ["name", "strasse", "plz", "ort"]}, "versorger": {"description": "Kommunaler Versorger (Adresse)", "type": "object", "properties": {"name": {"type": "string"}, "strasse": {"type": "string"}, "plz": {"type": "string", "pattern": "^\\d{5}$"}, "ort": {"type": "string"}, "land": {"type": "string", "pattern": "^[A-Z]{2}$", "default": "DE"}, "steuernummer": {"type": "string"}, "kundennummer": {"type": "string"}}, "required": ["name", "strasse", "plz", "ort"]}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean", "default": false}, "steuerrelevanz_hinweis": {"type": "string", "default": null}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "default": null}, "steuerjahr": {"type": "string", "pattern": "^\\d{4}$", "default": null}, "mwst_ausgewiesen": {"type": "boolean", "default": false}, "mwst_betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$", "default": null}, "mwst_satz": {"type": "string", "pattern": "^\\d+(\\.\\d{1,2})?$", "default": null}, "aktenzeichen": {"type": "string", "default": null}, "dokumenten_id": {"type": "string", "default": null}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}, "positionen": {"type": "array", "description": "Einzelpositionen der kommunalen Rechnung (Grundsteuer, Abwasser, Straßenreinigung, etc.)", "items": {"type": "object", "properties": {"beschreibung": {"type": "string"}, "betrag": {"type": "string"}, "zeitraum": {"type": "string"}, "einheit": {"type": "string", "description": "Einheit (z.B. m3, kWh, Monat)"}}}}, "objekt_adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "default": "DE"}}, "description": "Grundstueck/Liegenschaft der kommunalen Rechnung"}, "verbrauch_einheit": {"type": "string", "description": "Einheit des Verbrauchs (z.B. m3, kWh)"}}, "required": ["zaehlernummer", "zeitraum", "gesamtbetrag", "_meta"]}',
    '"zaehlernummer, verbrauch, zeitraum, grundgebuehr, verbrauchsgebuehr, niederschlagsgebuehr, gesamtbetrag"',
    'Wasser, Abwasser, Niederschlagswassergebühr, Niederschlagswasser, Müllgebühren, Straßenreinigung, Grundgebühr, Verbrauchsgebühr, Zählernummer, Stadtwerke, Kommune, Entwässerungsgebühren, Frischwasser, Abrechnungszeitraum, Rechnungsnummer, Zahlungsfrist, municipal bill, water supply, wastewater, rainwater fee, waste disposal',
    'Stadtwerke, Kommune',
    '{"paragraphen": "§35a EStG (haushaltsnahe Dienstleistungen), §9 EStG (Werbungskosten bei Vermietung)", "anlage": "V (bei Vermietung), N (bei Eigennutzung als haushaltsnahe Dienstleistung)", "absetzbare_betraege": {"haushaltsnahe_dienstleistungen": "20% der Arbeitskosten (max. 4.000 €/Jahr), z. B. Müllabfuhr, Straßenreinigung", "handwerkerleistungen": "20% der Arbeitskosten (max. 1.200 €/Jahr), z. B. Reparaturen an Wasserzählern"}}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
