INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'notary_contract',
    'F. Wohnen & Immobilien',
    'Notarvertrag',
    'Ein Notarvertrag ist ein notariell beurkundetes Dokument, das den Kauf oder Verkauf einer Immobilie oder eines Grundstücks rechtlich festhält. Es wird vom Notar erstellt und enthält alle wesentlichen Vertragsdetails wie Kaufpreis, Vertragsparteien und Grundstücksdaten. Im Gegensatz zu einfachen Kaufverträgen ist der Notarvertrag zwingend für die Eigentumsübertragung im Grundbuch erforderlich und unterliegt strengen Formvorschriften.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "Notarvertrag", "description": "Schema f\u00fcr die Extraktion von Daten aus einem Notarvertrag", "type": "object", "properties": {"notar": {"type": "object", "properties": {"name": {"type": "string"}, "anschrift": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "default": "DE"}}, "required": ["strasse", "plz", "ort"]}, "telefon": {"type": "string", "pattern": "^\\+[0-9]{11,15}$"}, "amtsgericht": {"type": "string"}}, "required": ["name", "anschrift"]}, "urkundennummer": {"type": "string"}, "datum": {"type": "string", "format": "date"}, "verkaeufer": {"type": "array", "items": {"type": "object", "properties": {"name": {"type": "string"}, "anschrift": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "default": "DE"}}, "required": ["strasse", "plz", "ort"]}, "geburtsdatum": {"type": "string", "format": "date"}, "geburtsort": {"type": "string"}, "steuernummer": {"type": "string"}, "identifikationsnummer": {"type": "string"}}, "required": ["name", "anschrift"]}}, "kaeufer": {"type": "array", "items": {"type": "object", "properties": {"name": {"type": "string"}, "anschrift": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "default": "DE"}}, "required": ["strasse", "plz", "ort"]}, "geburtsdatum": {"type": "string", "format": "date"}, "geburtsort": {"type": "string"}, "steuernummer": {"type": "string"}, "identifikationsnummer": {"type": "string"}}, "required": ["name", "anschrift"]}}, "objekt_adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "hausnummer": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "default": "DE"}}, "required": ["strasse", "plz", "ort"]}, "flurstueck": {"type": "object", "properties": {"flurnummer": {"type": "string"}, "flurstuecksnummer": {"type": "string"}, "gemarkung": {"type": "string"}, "groesse": {"type": "string"}}, "required": ["flurnummer", "flurstuecksnummer"]}, "kaufpreis": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$"}, "grunderwerbsteuer": {"type": "object", "properties": {"betrag": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$"}, "satz": {"type": "string"}}, "required": ["betrag", "satz"]}, "uebergabedatum": {"type": "string", "format": "date"}, "auflassung": {"type": "object", "properties": {"datum": {"type": "string", "format": "date"}, "ort": {"type": "string"}}, "required": ["datum"]}, "grundschuld": {"type": "object", "properties": {"betrag": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$"}, "glaeubiger": {"type": "object", "properties": {"name": {"type": "string"}, "anschrift": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "default": "DE"}}, "required": ["strasse", "plz", "ort"]}}, "required": ["name", "anschrift"]}, "zins": {"type": "string"}}, "required": ["betrag", "glaeubiger"]}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean", "default": true}, "steuerrelevanz_hinweis": {"type": "string", "default": "Grunderwerbsteuer und Kaufpreis sind steuerrelevant."}, "steuer_kategorie": {"type": "string", "enum": ["vermietung", null], "default": null}, "steuerjahr": {"type": "string", "pattern": "^[0-9]{4}$", "default": null}, "mwst_ausgewiesen": {"type": "boolean", "default": false}, "mwst_betrag": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$", "default": null}, "mwst_satz": {"type": "string", "default": null}, "aktenzeichen": {"type": "string", "default": null}, "dokumenten_id": {"type": "string", "default": null}}, "required": ["steuerrelevant"]}}, "required": ["notar", "urkundennummer", "datum", "verkaeufer", "kaeufer", "objekt_adresse", "kaufpreis"]}',
    '"notar, urkundennummer, datum, verkaeufer, kaeufer, objekt_adresse, flurstueck, kaufpreis, grunderwerbsteuer, uebergabedatum, auflassung, grundschuld"',
    'Notarvertrag, Kaufvertrag, Grundstückskaufvertrag, Immobilienkaufvertrag, notarielle Urkunde, Urkundennummer, Auflassung, Grundschuld, Flurstück, Grunderwerbsteuer, Eigentumsübertragung, Kaufpreis, Übergabedatum, Verkäufer, Käufer, Beurkundung, Grundbuchamt, Grundbuch, Eigentumsübergang, notary deed, land register',
    'Notar',
    '{"paragraphen": "§3 Nr. 2 GrEStG (Grunderwerbsteuer), §10e EStG (Eigenheimzulage, historisch), §9 EStG (Werbungskosten bei Vermietung), §23 EStG (private Veräußerungsgeschäfte)", "anlagen": "Anlage V (Einkünfte aus Vermietung und Verpachtung), Anlage SO (Sonstige Einkünfte bei privater Veräußerung innerhalb von 10 Jahren)", "absetzbar": {"grunderwerbsteuer": "Nicht direkt absetzbar, aber Teil der Anschaffungskosten (AfA-Bemessungsgrundlage bei Vermietung)", "notarkosten": "Teil der Anschaffungsnebenkosten (absetzbar über AfA bei Vermietung, §9 EStG)"}}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
