INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'property_tax',
    'F. Wohnen & Immobilien',
    'Grundsteuerbescheid',
    'Der Grundsteuerbescheid ist ein amtliches Dokument, das von der Kommune oder dem Finanzamt an Eigentümer von Grundstücken oder Immobilien versendet wird. Es legt die jährlich zu entrichtende Grundsteuer fest, basierend auf Einheitswert, Steuermesszahl und Hebesatz. Im Gegensatz zur Grunderwerbsteuer (einmalige Zahlung beim Kauf) oder Mietnebenkostenabrechnung (für Mieter) handelt es sich um eine wiederkehrende Steuerlast für Eigentümer.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "property_tax", "description": "Grundsteuerbescheid", "type": "object", "properties": {"aktenzeichen": {"type": "string", "description": "Aktenzeichen des Grundsteuerbescheids"}, "einheitswert": {"type": "string", "description": "Einheitswert des Grundstücks", "pattern": "^[0-9]+(?:\\.[0-9]{2})?$"}, "steuermesszahl": {"type": "string", "description": "Steuermesszahl in Prozent", "pattern": "^[0-9]+(?:\\.[0-9]{2})?$"}, "hebesatz": {"type": "string", "description": "Hebesatz der Gemeinde in Prozent", "pattern": "^[0-9]+(?:\\.[0-9]{2})?$"}, "grundsteuer_betrag": {"type": "string", "description": "Jährlicher Grundsteuerbetrag", "pattern": "^[0-9]+(?:\\.[0-9]{2})$"}, "grundstueck": {"type": "object", "description": "Informationen zum Grundstück", "properties": {"flurstueck": {"type": "string", "description": "Flurstücksnummer"}, "flurnummer": {"type": "string", "description": "Flurnummer"}, "gemarkung": {"type": "string", "description": "Gemarkung"}, "groesse": {"type": "string", "description": "Grundstücksgröße in m²", "pattern": "^[0-9]+(?:\\.[0-9]{2})?$"}, "adresse": {"type": "object", "description": "Adresse des Grundstücks", "properties": {"strasse": {"type": "string", "description": "Straße und Hausnummer"}, "plz": {"type": "string", "description": "Postleitzahl", "pattern": "^[0-9]{5}$"}, "ort": {"type": "string", "description": "Ort"}, "land": {"type": "string", "description": "Ländercode (ISO 3166-1 alpha-2)", "pattern": "^[A-Z]{2}$"}}, "required": ["strasse", "plz", "ort", "land"]}}, "required": ["flurstueck", "flurnummer", "gemarkung", "adresse"]}, "rechtsmittelbelehrung": {"type": "boolean", "description": "Gibt an, ob eine Rechtsmittelbelehrung enthalten ist"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean", "enum": [true]}, "steuerrelevanz_hinweis": {"type": "string", "enum": ["Grundsteuer ist als Kostenposition bei Vermietung oder als sonstige Ausgabe abziehbar"]}, "steuer_kategorie": {"type": "string", "enum": ["vermietung", "sonderausgaben"]}, "steuerjahr": {"type": "string", "description": "Steuerjahr des Bescheids", "pattern": "^[0-9]{4}$"}, "mwst_ausgewiesen": {"type": "boolean", "enum": [false]}, "mwst_betrag": {"type": "null"}, "mwst_satz": {"type": "null"}, "aktenzeichen": {"type": "string", "description": "Aktenzeichen des Dokuments"}, "dokumenten_id": {"type": "string", "description": "Interne Dokumenten-ID"}}, "required": ["steuerrelevant", "steuerrelevanz_hinweis", "steuer_kategorie", "mwst_ausgewiesen"]}, "positionen": {"type": "array", "description": "Einzelpositionen des Grundsteuerbescheids (Grundsteuer A/B, Messbetrag, Hebesatz, etc.)", "items": {"type": "object", "properties": {"beschreibung": {"type": "string"}, "messbetrag": {"type": "string"}, "hebesatz": {"type": "string"}, "betrag": {"type": "string"}}}}, "objekt_adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "default": "DE"}}, "description": "Grundstueck/Liegenschaft"}}, "required": ["aktenzeichen", "einheitswert", "steuermesszahl", "hebesatz", "grundsteuer_betrag", "grundstueck", "_meta"]}',
    '"{\"aktenzeichen\": \"Amtliches Aktenzeichen des Bescheids, oft mit Jahr und laufender Nummer (z. B. ''2023/4711/00123''). Wichtig f\u00fcr Nachfragen oder Rechtsmittel, da es den Bescheid eindeutig identifiziert.\", \"einheitswert\": \"Der vom Finanzamt festgestellte Wert des Grundst\u00fccks (in Euro), z. B. ''50.000 \u20ac''. Basis f\u00fcr die Berechnung der Grundsteuer; kann f\u00fcr Erbschaftssteuer oder bei Verkauf relevant sein.\", \"steuermesszahl\": \"Prozentualer Faktor (z. B. ''0,35 %''), der sich nach Grundst\u00fccksart (Ackerland, Einfamilienhaus etc.) richtet. Multipliziert mit dem Einheitswert ergibt den Steuermessbetrag.\", \"hebesatz\": \"Kommunaler Prozentsatz (z. B. ''500 %''), der auf den Steuermessbetrag angewendet wird. Entscheidend f\u00fcr die H\u00f6he der Grundsteuer; variiert je nach Gemeinde.\", \"grundsteuer_betrag\": \"J\u00e4hrlich zu zahlender Betrag (in Euro, z. B. ''250,00 \u20ac''), oft quartalsweise f\u00e4llig. Bei vermieteten Immobilien als Betriebskosten umlagef\u00e4hig oder als Werbungskosten absetzbar.\", \"grundstueck\": \"Beschreibung des Grundst\u00fccks (Adresse, Flurst\u00fccknummer, Nutzungsart wie ''Einfamilienhaus'' oder ''Bauerwartungsland''). Wichtig f\u00fcr die korrekte Zuordnung des Bescheids und ggf. Widerspruch bei Fehlklassifizierung.\"}"',
    'Grundsteuerbescheid, Grundsteuer, Einheitswert, Steuermessbetrag, Hebesatz, Grundstücksart, Aktenzeichen, Finanzamt, Kommune, jährliche Steuer, Grundsteuerbetrag, Rechtsbehelfsbelehrung, Grundbesitzabgaben, property tax assessment, assessed value, tax rate, municipal tax, real estate tax, Grundsteuermessbetrag, Grundsteuer A/B',
    'Finanzamt/Kommune',
    '{"relevanz": "teilweise", "paragraphen": "§ 35a EStG (haushaltsnahe Dienstleistungen), § 9 UStG (bei gewerblicher Vermietung)", "anlage": null, "hinweis": "Die Grundsteuer selbst ist nicht direkt absetzbar, aber bei vermieteten Immobilien als Werbungskosten (Anlage V) oder bei selbstgenutztem Wohneigentum anteilig über § 35a EStG (Handwerkerleistungen für Instandhaltung, max. 1.200 €/Jahr). Der Einheitswert kann für Erbschafts-/Schenkungssteuer relevant sein."}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
ON CONFLICT (id) DO UPDATE SET category=EXCLUDED.category, display_name=EXCLUDED.display_name, description=EXCLUDED.description, schema=EXCLUDED.schema, field_descriptions=EXCLUDED.field_descriptions, classify_keywords=EXCLUDED.classify_keywords, typical_senders=EXCLUDED.typical_senders, steuer_relevanz=EXCLUDED.steuer_relevanz, priority=EXCLUDED.priority, enabled=EXCLUDED.enabled, version=EXCLUDED.version, source=EXCLUDED.source, notes=EXCLUDED.notes;

INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'rent_increase',
    'F. Wohnen & Immobilien',
    'Mieterhöhung',
    'Eine Mieterhöhung ist eine formelle Mitteilung des Vermieters an den Mieter über die Anpassung der Miete gemäß den gesetzlichen Bestimmungen (z. B. § 558 BGB). Sie kommt vor, wenn der Vermieter die Miete aufgrund von Mietspiegel, Modernisierungen oder Indexanpassungen erhöhen möchte. Im Gegensatz zu einer Nebenkostenabrechnung oder Kündigung betrifft sie ausschließlich die Grundmiete und muss bestimmte formale und inhaltliche Anforderungen erfüllen, wie z. B. eine Begründung und Fristsetzung für die Zustimmung.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "rent_increase", "description": "Mieterhöhung", "type": "object", "properties": {"vermieter": {"type": "object", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort", "land"]}, "telefon": {"type": "string"}, "email": {"type": "string", "format": "email"}}, "required": ["name", "adresse"]}, "mieter": {"type": "object", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort", "land"]}}, "required": ["name", "adresse"]}, "objekt": {"type": "object", "properties": {"adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort", "land"]}, "wohnungsnummer": {"type": "string"}, "groesse_qm": {"type": "number"}}, "required": ["adresse"]}, "bisherige_miete": {"type": "string", "pattern": "^\\d{1,6}(\\.\\d{2})?$"}, "neue_miete": {"type": "string", "pattern": "^\\d{1,6}(\\.\\d{2})?$"}, "erhoehung_betrag": {"type": "string", "pattern": "^\\d{1,6}(\\.\\d{2})?$"}, "erhoehung_prozent": {"type": "string", "pattern": "^\\d{1,3}(\\.\\d{1,2})?$"}, "wirksam_ab": {"type": "string", "format": "date"}, "begruendung": {"type": "string", "enum": ["mietspiegel", "modernisierung", "index"]}, "zustimmungsfrist": {"type": "string", "format": "date"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^\\d{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "pattern": "^\\d{1,6}(\\.\\d{2})?$", "nullable": true}, "mwst_satz": {"type": "string", "pattern": "^\\d{1,2}(\\.\\d{1,2})?$", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}, "positionen": {"type": "array", "description": "Begründungspositionen der Mieterhöhung (Modernisierung, Vergleichsmiete, etc.)", "items": {"type": "object", "properties": {"beschreibung": {"type": "string"}, "betrag_alt": {"type": "string"}, "betrag_neu": {"type": "string"}}}}, "objekt_adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "default": "DE"}}, "description": "Mietobjekt-Adresse"}}, "required": ["vermieter", "mieter", "objekt", "bisherige_miete", "neue_miete", "erhoehung_betrag", "erhoehung_prozent", "wirksam_ab", "begruendung", "_meta"]}',
    '"vermieter, mieter, objekt, bisherige_miete, neue_miete, erhoehung_betrag, erhoehung_prozent, wirksam_ab, begruendung (mietspiegel/modernisierung/index), zustimmungsfrist"',
    'Mieterhöhung, Mietanpassung, Mietsteigerung, § 558 BGB, Mietspiegel, Modernisierung, Indexmiete, Zustimmung, Frist, neue Miete, bisherige Miete, Erhöhungsbetrag, wirksam ab, Vermieter, Mieter, Wohnraum, ortsübliche Vergleichsmiete, Kappungsgrenze, Mieterhöhungsverlangen, rent increase, modernization, index adjustment, notice period',
    'Vermieter',
    '{"einkommensteuer": {"paragraph": "§ 9 Abs. 1 EStG (Werbungskosten bei vermieteten Immobilien), § 21 EStG (Einkünfte aus Vermietung und Verpachtung)", "anlage": "Anlage V (Einkünfte aus Vermietung und Verpachtung)"}}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
ON CONFLICT (id) DO UPDATE SET category=EXCLUDED.category, display_name=EXCLUDED.display_name, description=EXCLUDED.description, schema=EXCLUDED.schema, field_descriptions=EXCLUDED.field_descriptions, classify_keywords=EXCLUDED.classify_keywords, typical_senders=EXCLUDED.typical_senders, steuer_relevanz=EXCLUDED.steuer_relevanz, priority=EXCLUDED.priority, enabled=EXCLUDED.enabled, version=EXCLUDED.version, source=EXCLUDED.source, notes=EXCLUDED.notes;

INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'utility_bill',
    'F. Wohnen & Immobilien',
    'Nebenkostenabrechnung',
    'Die Nebenkostenabrechnung ist ein jährliches Dokument, das Vermieter an Mieter senden, um die tatsächlich angefallenen Betriebskosten für eine Mietwohnung abzurechnen. Sie unterscheidet sich von der monatlichen Nebenkostenvorauszahlung oder der Heizkostenabrechnung durch die detaillierte Aufschlüsselung aller umlagefähigen Kostenpositionen (z. B. Müllabfuhr, Hausmeister, Versicherungen) und den Abgleich mit den geleisteten Vorauszahlungen, was in einer Nachzahlung oder einem Guthaben resultiert.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "Utility Bill - Nebenkostenabrechnung", "type": "object", "properties": {"abrechnungszeitraum": {"type": "object", "properties": {"von": {"type": "string", "format": "date", "description": "Startdatum des Abrechnungszeitraums (YYYY-MM-DD)"}, "bis": {"type": "string", "format": "date", "description": "Enddatum des Abrechnungszeitraums (YYYY-MM-DD)"}}, "required": ["von", "bis"]}, "gesamtkosten": {"type": "string", "pattern": "^\\d+\\.\\d{2}$", "description": "Gesamtkosten in Euro (z.B. 49.99)"}, "vorauszahlungen": {"type": "string", "pattern": "^\\d+\\.\\d{2}$", "description": "Summe der Vorauszahlungen in Euro (z.B. 49.99)"}, "nachzahlung_guthaben": {"type": "string", "pattern": "^\\d+\\.\\d{2}$", "description": "Nachzahlungs- oder Guthabenbetrag in Euro (z.B. 49.99, negativ bei Guthaben)"}, "positionen": {"type": "array", "items": {"type": "object", "properties": {"bezeichnung": {"type": "string", "description": "Bezeichnung der Position (z.B. Heizkosten, Wasser, Müllgebühren)"}, "betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$", "description": "Betrag der Position in Euro (z.B. 49.99)"}, "einzelheiten": {"type": "string", "description": "Zusätzliche Details zur Position (optional)"}, "mwst_betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$", "description": "Mehrwertsteuerbetrag für diese Position (optional)"}, "mwst_satz": {"type": "string", "description": "Mehrwertsteuersatz für diese Position (z.B. 19, 7, 0)"}, "einheit": {"type": "string", "description": "Einheit (z.B. m2, Personen, kWh)"}}, "required": ["bezeichnung", "betrag"]}}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean", "description": "Gibt an, ob das Dokument steuerrelevant ist"}, "steuerrelevanz_hinweis": {"type": "string", "description": "Hinweis zur Steuerrelevanz (optional)", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "description": "Kategorie der Steuerrelevanz (optional)", "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^\\d{4}$", "description": "Steuerjahr (YYYY) (optional)", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean", "description": "Gibt an, ob Mehrwertsteuer ausgewiesen ist"}, "mwst_betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$", "description": "Gesamtbetrag der Mehrwertsteuer (optional)", "nullable": true}, "mwst_satz": {"type": "string", "description": "Mehrwertsteuersatz (z.B. 19, 7, 0) (optional)", "nullable": true}, "aktenzeichen": {"type": "string", "description": "Aktenzeichen (optional)", "nullable": true}, "dokumenten_id": {"type": "string", "description": "Interne Dokumenten-ID (optional)", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}, "objekt_adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "default": "DE"}}, "description": "Mietobjekt/Liegenschaft der Nebenkostenabrechnung"}, "waehrung": {"type": "string", "default": "EUR", "description": "Waehrung ISO 4217 (EUR, USD, etc.)"}}, "required": ["abrechnungszeitraum", "gesamtkosten", "vorauszahlungen", "nachzahlung_guthaben", "_meta"]}',
    '"abrechnungszeitraum, gesamtkosten, vorauszahlungen, nachzahlung_guthaben, positionen[]"',
    'Nebenkostenabrechnung, Betriebskostenabrechnung, Abrechnungszeitraum, Vorauszahlungen, Nachzahlung, Guthaben, umlagefähige Kosten, Heizkosten, Warmwasserkosten, Kaltwasserkosten, Müllabfuhr, Hausmeisterdienst, Gebäudeversicherung, Grundsteuer, Schornsteinfeger, Betriebskosten, Gesamtkosten, Umlageschlüssel, Mieter, Vermieter, annual settlement, service charges, utility bill, advance payments',
    'Vermieter',
    '{"paragraphen": "§ 35a EStG (haushaltsnahe Dienstleistungen), § 9 EStG (Werbungskosten bei doppelter Haushaltsführung)", "anlage": null, "details": {"haushaltsnahe_dienstleistungen": {"positionen": ["Hausmeisterdienst", "Gartenpflege", "Reinigungskosten"], "betrag": "20% der Kosten, max. 4.000 € pro Jahr (§ 35a Abs. 2 EStG)", "hinweis": "Nur der auf den Mieter entfallende Anteil ist absetzbar. Rechnungen und Zahlungsnachweise erforderlich."}, "handwerkerleistungen": {"positionen": ["Schornsteinfeger", "Wartungsarbeiten"], "betrag": "20% der Arbeitskosten (ohne Material), max. 1.200 € pro Jahr (§ 35a Abs. 3 EStG)"}}}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
ON CONFLICT (id) DO UPDATE SET category=EXCLUDED.category, display_name=EXCLUDED.display_name, description=EXCLUDED.description, schema=EXCLUDED.schema, field_descriptions=EXCLUDED.field_descriptions, classify_keywords=EXCLUDED.classify_keywords, typical_senders=EXCLUDED.typical_senders, steuer_relevanz=EXCLUDED.steuer_relevanz, priority=EXCLUDED.priority, enabled=EXCLUDED.enabled, version=EXCLUDED.version, source=EXCLUDED.source, notes=EXCLUDED.notes;

INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'utility_statement',
    'F. Wohnen & Immobilien',
    'Nebenkostenaufstellung',
    'Die Nebenkostenaufstellung ist eine jährliche Abrechnung des Vermieters oder der Hausverwaltung über die angefallenen Betriebskosten einer Mietwohnung. Sie listet detailliert die Kostenpositionen wie Heizung, Wasser, Müllentsorgung oder Hausmeisterdienste auf und zeigt die Umlage auf den Mieter sowie dessen Eigenanteil. Im Gegensatz zur einfachen Mietnebenkostenabrechnung (Vorauszahlungen) enthält sie eine vollständige Kostenaufschlüsselung und ist Grundlage für Nachzahlungen oder Guthaben.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "utility_statement", "description": "Nebenkostenaufstellung für ein Mietobjekt", "type": "object", "properties": {"objekt": {"type": "object", "properties": {"adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "default": "DE"}}, "required": ["strasse", "plz", "ort"]}, "objekt_id": {"type": "string"}, "wohnungsnummer": {"type": "string"}}, "required": ["adresse"]}, "zeitraum": {"type": "object", "properties": {"von": {"type": "string", "format": "date"}, "bis": {"type": "string", "format": "date"}}, "required": ["von", "bis"]}, "positionen": {"type": "array", "items": {"type": "object", "properties": {"kategorie": {"type": "string", "enum": ["heizung", "wasser", "muell", "hausmeister", "versicherung", "strom", "reinigung", "gartenpflege", "allgemeinstrom", "sonstiges"]}, "betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}, "währung": {"type": "string", "default": "EUR"}, "beschreibung": {"type": "string"}, "einzelbetrag_anteile": {"type": "array", "items": {"type": "object", "properties": {"mieter": {"type": "string"}, "betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}}, "required": ["mieter", "betrag"]}}, "einheit": {"type": "string", "description": "Einheit (z.B. m2, Personen, kWh, Monate)"}}, "required": ["kategorie", "betrag"]}}, "umlageschluessel": {"type": "object", "properties": {"typ": {"type": "string", "enum": ["flaeche", "personen", "verbrauch", "festanteil", "sonstiges"]}, "beschreibung": {"type": "string"}, "wert": {"type": "number"}}, "required": ["typ"]}, "eigenanteil": {"type": "object", "properties": {"betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}, "währung": {"type": "string", "default": "EUR"}, "beglichen_am": {"type": "string", "format": "date", "nullable": true}, "zahlungsreferenz": {"type": "string", "nullable": true}}, "required": ["betrag"]}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean", "default": false}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": [null, "haushaltsnahe_dienstleistungen", "werbungskosten"], "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^\\d{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean", "default": false}, "mwst_betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$", "nullable": true}, "mwst_satz": {"type": "string", "pattern": "^\\d+(\\.\\d{1,2})?$", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}, "objekt_adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "default": "DE"}}, "description": "Mietobjekt/Liegenschaft der Nebenkostenaufstellung"}}, "required": ["objekt", "zeitraum", "positionen", "eigenanteil"]}',
    '"{\"objekt\": \"Adresse oder Bezeichnung der Mietwohnung/des Mietobjekts, z.B. ''Musterstra\u00dfe 12, 10115 Berlin''. Wichtig f\u00fcr die Zuordnung zur richtigen Immobilie in der Steuererkl\u00e4rung (Anlage V).\", \"zeitraum\": \"Abrechnungszeitraum im Format ''TT.MM.JJJJ - TT.MM.JJJJ'', z.B. ''01.01.2023 - 31.12.2023''. Relevant f\u00fcr die zeitliche Zuordnung der Kosten in der Steuererkl\u00e4rung.\", \"positionen\": {\"heizung\": \"Kosten f\u00fcr Heizung und Warmwasser, oft in kWh oder Euro angegeben, z.B. ''Heizung: 1.200 \u20ac (Verbrauch: 12.000 kWh)''. Wichtig f\u00fcr \u00a735a EStG, falls haushaltsnahe Dienstleistungen enthalten sind.\", \"wasser\": \"Kosten f\u00fcr Kalt- und Warmwasser, z.B. ''Wasser: 300 \u20ac (Verbrauch: 150 m\u00b3)''. Relevant f\u00fcr die Aufteilung bei doppelter Haushaltsf\u00fchrung.\", \"muell\": \"Kosten f\u00fcr M\u00fcllentsorgung, z.B. ''M\u00fcllgeb\u00fchren: 150 \u20ac''. Kann bei \u00a735a EStG relevant sein, wenn Entsorgungsdienstleistungen enthalten sind.\", \"hausmeister\": \"Kosten f\u00fcr Hausmeisterdienste, z.B. ''Hausmeister: 400 \u20ac''. Arbeitskosten sind zu 20% absetzbar (\u00a735a EStG).\", \"versicherung\": \"Kosten f\u00fcr Geb\u00e4udeversicherungen, z.B. ''Geb\u00e4udeversicherung: 250 \u20ac''. Nur relevant, wenn der Mieter diese direkt tr\u00e4gt (selten).\"}}"',
    'Nebenkostenabrechnung, Betriebskostenabrechnung, Heizkostenabrechnung, Umlage, Vorauszahlungen, Nachzahlung, Guthaben, Warmwasser, Kaltwasser, Müllgebühren, Hausmeisterdienst, Gebäudeversicherung, Grundsteuer, Betriebskosten, Abrechnungszeitraum, Umlageschlüssel, Verbrauch, Gesamtkosten, Mieteranteil, Vermieter, Hausverwaltung, Nebenkostenspiegel, Nebenkostenposition, energy costs, utility bill, service charges',
    'Vermieter, Hausverwaltung',
    '{"paragraphen": "§ 35a EStG (haushaltsnahe Dienstleistungen), § 9 EStG (Werbungskosten bei doppelter Haushaltsführung)", "anlage": "Anlage V (bei Vermietung), Anlage N (bei Werbungskosten)", "details": "Absetzbar sind 20% der Arbeitskosten für haushaltsnahe Dienstleistungen (z.B. Hausmeister, Reinigung) bis max. 4.000 € pro Jahr (§35a EStG). Bei doppelter Haushaltsführung können tatsächliche Nebenkosten als Werbungskosten geltend gemacht werden. Heizkosten sind nur relevant, wenn sie nicht bereits über die Warmmiete abgerechnet werden."}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
ON CONFLICT (id) DO UPDATE SET category=EXCLUDED.category, display_name=EXCLUDED.display_name, description=EXCLUDED.description, schema=EXCLUDED.schema, field_descriptions=EXCLUDED.field_descriptions, classify_keywords=EXCLUDED.classify_keywords, typical_senders=EXCLUDED.typical_senders, steuer_relevanz=EXCLUDED.steuer_relevanz, priority=EXCLUDED.priority, enabled=EXCLUDED.enabled, version=EXCLUDED.version, source=EXCLUDED.source, notes=EXCLUDED.notes;

INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'care_assessment',
    'G. Gesundheit & Pflege',
    'Pflegegutachten',
    'Das Pflegegutachten ist ein offizielles Dokument des Medizinischen Dienstes der Krankenversicherung (MDK), das im Rahmen eines Antrags auf Pflegeleistungen erstellt wird. Es bewertet die Pflegebedürftigkeit einer Person anhand definierter Kriterien und empfiehlt einen Pflegegrad. Im Gegensatz zu ärztlichen Attesten oder Reha-Berichten liegt der Fokus hier ausschließlich auf der Feststellung der Pflegebedürftigkeit und der Zuordnung zu einem Pflegegrad (1-5).',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "care_assessment", "description": "Pflegegutachten zur Feststellung des Pflegegrades", "type": "object", "properties": {"patient": {"type": "object", "properties": {"name": {"type": "string"}, "vorname": {"type": "string"}, "geburtsdatum": {"type": "string", "format": "date"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "pattern": "^[A-Z]{2}$"}}, "required": ["strasse", "plz", "ort", "land"]}, "versichertennummer": {"type": "string"}}, "required": ["name", "vorname", "geburtsdatum"]}, "gutachter": {"type": "object", "properties": {"name": {"type": "string"}, "vorname": {"type": "string"}, "organisation": {"type": "string"}, "datum": {"type": "string", "format": "date"}}, "required": ["name", "vorname", "datum"]}, "pflegegrad_empfehlung": {"type": "integer", "minimum": 1, "maximum": 5}, "einschraenkungen": {"type": "array", "items": {"type": "object", "properties": {"bereich": {"type": "string", "enum": ["mobilitaet", "kognitive_und_kommunikative_faehigkeiten", "verhaltensweisen_und_psychische_problemlagen", "selbstversorgung", "bewaeltigung_von_und_selbststaendiger_umgang_mit_krankheits_oder_therapiebedingten_anforderungen_und_belastungen", "gestaltung_des_alltagslebens_und_sozialer_kontakte"]}, "beschreibung": {"type": "string"}, "schweregrad": {"type": "integer", "minimum": 0, "maximum": 3}}, "required": ["bereich", "beschreibung"]}}, "punkte": {"type": "object", "properties": {"gesamt": {"type": "integer", "minimum": 0}, "einzelbewertungen": {"type": "array", "items": {"type": "object", "properties": {"bereich": {"type": "string", "enum": ["mobilitaet", "kognitive_und_kommunikative_faehigkeiten", "verhaltensweisen_und_psychische_problemlagen", "selbstversorgung", "bewaeltigung_von_und_selbststaendiger_umgang_mit_krankheits_oder_therapiebedingten_anforderungen_und_belastungen", "gestaltung_des_alltagslebens_und_sozialer_kontakte"]}, "punkte": {"type": "integer", "minimum": 0}}, "required": ["bereich", "punkte"]}}}, "required": ["gesamt"]}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^[0-9]{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$", "nullable": true}, "mwst_satz": {"type": "string", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"], "additionalProperties": false}, "module": {"type": "array", "description": "Einzelne Begutachtungsmodule mit Punktzahlen", "items": {"type": "object", "properties": {"modul_nr": {"type": "string"}, "bezeichnung": {"type": "string"}, "punkte": {"type": "string"}, "gewichtete_punkte": {"type": "string"}}}}}, "required": ["patient", "gutachter", "pflegegrad_empfehlung", "_meta"]}',
    '"{\"patient\": \"Name, Geburtsdatum und Versicherungsnummer der begutachteten Person. Wichtig f\u00fcr die Zuordnung des Gutachtens zur steuerpflichtigen Person oder zum Pflegefall. Beispiel: {''name'': ''Max Mustermann'', ''geburtsdatum'': ''12.03.1945'', ''versicherungsnummer'': ''A123456789''}.\", \"gutachter\": \"Name und Kontaktdaten des MDK-Gutachters, der die Begutachtung durchgef\u00fchrt hat. Beispiel: {''name'': ''Dr. Anna Schmidt'', ''mdk_region'': ''MDK Bayern'', ''datum'': ''15.10.2023''}. Relevant f\u00fcr R\u00fcckfragen oder Widerspr\u00fcche.\", \"pflegegrad_empfehlung\": \"Empfohlener Pflegegrad (1-5) basierend auf der Begutachtung. Format: Integer (1, 2, 3, 4 oder 5). Beispiel: 3. Entscheidend f\u00fcr die H\u00f6he der Pflegeleistungen und steuerliche Absetzbarkeit von Pflegekosten.\", \"einschraenkungen\": \"Liste der festgestellten Einschr\u00e4nkungen in verschiedenen Modulen (z. B. Mobilit\u00e4t, kognitive F\u00e4higkeiten). Jeder Eintrag enth\u00e4lt das Modul, die Beschreibung der Einschr\u00e4nkung und ggf. Punkte. Beispiel: [{''modul'': ''Mobilit\u00e4t'', ''beschreibung'': ''Ben\u00f6tigt Hilfe beim Aufstehen'', ''punkte'': 3}, {''modul'': ''Kognitive F\u00e4higkeiten'', ''beschreibung'': ''Desorientierung zu Zeit und Ort'', ''punkte'': 5}]. Wichtig f\u00fcr den Nachweis der Pflegebed\u00fcrftigkeit im Steuerrecht.\"}"',
    'Pflegegutachten, MDK, Medizinischer Dienst, Pflegegrad, Pflegebedürftigkeit, Begutachtung, Einschränkungen, Punkte, Modul 1, Modul 2, Modul 3, Modul 4, Modul 5, Modul 6, Selbstständigkeit, Gutachter, Pflegeversicherung, SGB XI, §18 SGB XI, Empfehlung, Bewertung, Alltagskompetenz, Mobilität, kognitive Fähigkeiten, Verhaltensweisen, Pflegeaufwand, care assessment, nursing care degree, limitations',
    'MDK',
    '{"paragraphen": "§33 EStG (außergewöhnliche Belastungen), §35a EStG (haushaltsnahe Dienstleistungen/Pflege)", "anlage": "Anlage Vorsorgeaufwand (für Pflegeversicherungsbeiträge), ggf. Anlage Kind (bei Pflege von Angehörigen)", "hinweise": "Pflegekosten können als außergewöhnliche Belastungen abgesetzt werden, sofern sie nicht von der Pflegeversicherung erstattet werden. Die Höhe der absetzbaren Beträge hängt vom Pflegegrad und den tatsächlichen Aufwendungen ab. Bei §35a EStG können bis zu 20% der Pflegekosten (max. 4.000 € pro Jahr) direkt von der Steuer abgezogen werden. Das Gutachten dient als Nachweis für den Pflegegrad und die Notwendigkeit von Pflegeleistungen."}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
ON CONFLICT (id) DO UPDATE SET category=EXCLUDED.category, display_name=EXCLUDED.display_name, description=EXCLUDED.description, schema=EXCLUDED.schema, field_descriptions=EXCLUDED.field_descriptions, classify_keywords=EXCLUDED.classify_keywords, typical_senders=EXCLUDED.typical_senders, steuer_relevanz=EXCLUDED.steuer_relevanz, priority=EXCLUDED.priority, enabled=EXCLUDED.enabled, version=EXCLUDED.version, source=EXCLUDED.source, notes=EXCLUDED.notes;

INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'care_notice',
    'G. Gesundheit & Pflege',
    'Pflegebescheid',
    'Ein Pflegebescheid ist ein offizielles Dokument der Pflegekasse oder des Medizinischen Dienstes der Krankenversicherung (MDK), das den anerkannten Pflegegrad sowie die bewilligten Leistungen und deren Gültigkeitszeitraum festlegt. Er wird nach einer Begutachtung der Pflegebedürftigkeit ausgestellt und ist die Grundlage für die Inanspruchnahme von Pflegeleistungen. Im Gegensatz zu reinen Gutachten oder Informationsschreiben enthält der Pflegebescheid verbindliche Entscheidungen und Fristen für Widersprüche.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "care_notice", "description": "Pflegebescheid Dokumenten-Extraktions-Template", "type": "object", "properties": {"aktenzeichen": {"type": "string", "description": "Aktenzeichen des Pflegebescheids"}, "pflegegrad": {"type": "integer", "minimum": 1, "maximum": 5, "description": "Bewilligter Pflegegrad (1-5)"}, "begutachtungsdatum": {"type": "string", "format": "date", "description": "Datum der Begutachtung (YYYY-MM-DD)"}, "leistungen": {"type": "array", "items": {"type": "object", "properties": {"leistungsart": {"type": "string", "description": "Art der Leistung (z.B. Pflegegeld, Pflegesachleistung)"}, "betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$", "description": "Betrag der Leistung (z.B. 49.99)"}, "w\u00e4hrung": {"type": "string", "pattern": "^[A-Z]{3}$", "description": "W\u00e4hrung der Leistung (ISO 4217)"}, "beginn": {"type": "string", "format": "date", "description": "Beginn der Leistung (YYYY-MM-DD)"}, "ende": {"type": "string", "format": "date", "description": "Ende der Leistung (YYYY-MM-DD)"}}, "required": ["leistungsart", "betrag", "w\u00e4hrung"]}}, "bewilligungszeitraum": {"type": "object", "properties": {"beginn": {"type": "string", "format": "date", "description": "Beginn des Bewilligungszeitraums (YYYY-MM-DD)"}, "ende": {"type": "string", "format": "date", "description": "Ende des Bewilligungszeitraums (YYYY-MM-DD)"}}, "required": ["beginn", "ende"]}, "rechtsmittelbelehrung": {"type": "boolean", "description": "Gibt an, ob eine Rechtsmittelbelehrung enthalten ist"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean", "description": "Gibt an, ob das Dokument steuerrelevant ist"}, "steuerrelevanz_hinweis": {"type": "string", "description": "Hinweis zur Steuerrelevanz", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^\\d{4}$", "description": "Steuerjahr (YYYY)", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean", "description": "Gibt an, ob Mehrwertsteuer ausgewiesen ist"}, "mwst_betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$", "description": "Mehrwertsteuerbetrag (z.B. 19.00)", "nullable": true}, "mwst_satz": {"type": "string", "description": "Mehrwertsteuersatz (z.B. 19%)", "nullable": true}, "aktenzeichen": {"type": "string", "description": "Aktenzeichen des Dokuments", "nullable": true}, "dokumenten_id": {"type": "string", "description": "Eindeutige ID des Dokuments", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}}, "required": ["aktenzeichen", "pflegegrad", "_meta"]}',
    '"{\"aktenzeichen\": \"Offizielle Referenznummer des Bescheids, z. B. ''PG-2023-123456''. Wichtig f\u00fcr R\u00fcckfragen oder Widerspr\u00fcche bei der Pflegekasse. Format: alphanumerisch, oft mit Pr\u00e4fix f\u00fcr Pflegegrad-Verfahren.\", \"pflegegrad\": \"Anerkannter Pflegegrad (1 bis 5), z. B. ''Pflegegrad 3''. Entscheidend f\u00fcr die H\u00f6he der Leistungen und steuerliche Ber\u00fccksichtigung von Pflegekosten. Wird als Zahl oder ausgeschrieben angegeben.\", \"begutachtungsdatum\": \"Datum der Begutachtung durch den MDK, z. B. ''15.05.2023''. Wichtig f\u00fcr die zeitliche Einordnung des Verfahrens und ggf. f\u00fcr die Berechnung von Fristen. Format: TT.MM.JJJJ oder JJJJ-MM-TT.\", \"leistungen\": \"Bewilligte Leistungen, z. B. ''Pflegegeld in H\u00f6he von 545 \u20ac monatlich'' oder ''Pflegesachleistungen bis zu 1.298 \u20ac monatlich''. Kann auch Kombinationsleistungen oder zus\u00e4tzliche Betreuungsleistungen umfassen. Wichtig f\u00fcr die Steuererkl\u00e4rung, da nicht erstattete Kosten als au\u00dfergew\u00f6hnliche Belastungen absetzbar sein k\u00f6nnen.\", \"bewilligungszeitraum\": \"Zeitraum, f\u00fcr den die Leistungen bewilligt sind, z. B. ''01.06.2023 bis 31.05.2024''. Wichtig f\u00fcr die Planung und ggf. f\u00fcr die steuerliche Zuordnung von Pflegekosten. Format: TT.MM.JJJJ bis TT.MM.JJJJ.\"}"',
    'Pflegebescheid, Pflegegrad, Pflegekasse, MDK, Medizinischer Dienst, Begutachtung, Leistungen, Bewilligungszeitraum, Rechtsmittelbelehrung, Widerspruchsfrist, Pflegebedürftigkeit, §18 SGB XI, Gutachten, Pflegegeld, Pflegesachleistungen, Kombinationsleistung, aktenzeichen, Bescheid, Entscheidung, Pflegeversicherung, care notice, care assessment',
    'Pflegekasse, MDK',
    '{"paragraphen": "§33 EStG (außergewöhnliche Belastungen), §35a EStG (haushaltsnahe Dienstleistungen und Handwerkerleistungen)", "anlage": "Anlage Vorsorgeaufwand (für Pflegeversicherungsbeiträge), ggf. Anlage Kind (bei Pflege von Angehörigen)", "hinweise": "Pflegekosten können als außergewöhnliche Belastungen geltend gemacht werden, sofern sie nicht von der Pflegeversicherung erstattet werden. Bei Inanspruchnahme von Pflegeleistungen im Haushalt (z. B. ambulante Pflege) können 20% der Aufwendungen (max. 4.000 €) nach §35a EStG abgesetzt werden. Der Pflegebescheid dient als Nachweis für den anerkannten Pflegegrad und die bewilligten Leistungen."}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
ON CONFLICT (id) DO UPDATE SET category=EXCLUDED.category, display_name=EXCLUDED.display_name, description=EXCLUDED.description, schema=EXCLUDED.schema, field_descriptions=EXCLUDED.field_descriptions, classify_keywords=EXCLUDED.classify_keywords, typical_senders=EXCLUDED.typical_senders, steuer_relevanz=EXCLUDED.steuer_relevanz, priority=EXCLUDED.priority, enabled=EXCLUDED.enabled, version=EXCLUDED.version, source=EXCLUDED.source, notes=EXCLUDED.notes;

INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'lab_report',
    'G. Gesundheit & Pflege',
    'Laborbericht',
    'Ein Laborbericht dokumentiert die Ergebnisse medizinischer Laboruntersuchungen, die im Rahmen von Diagnostik, Vorsorge oder Therapiekontrolle durchgeführt werden. Er wird typischerweise von einem Labor oder Arzt an den Patienten oder behandelnden Arzt übermittelt und enthält detaillierte Messwerte, Referenzbereiche und eine ärztliche Bewertung. Im Gegensatz zu reinen Arztbriefen oder Rezepten liegt der Fokus auf quantitativen oder qualitativen Analyseergebnissen (z. B. Blutwerte, Urinanalysen).',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "Lab Report", "description": "Schema f\u00fcr Laborberichte", "type": "object", "properties": {"patient": {"type": "object", "properties": {"name": {"type": "string"}, "vorname": {"type": "string"}, "geburtsdatum": {"type": "string", "format": "date"}, "patientennummer": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort"]}}, "required": ["name", "geburtsdatum"]}, "labor": {"type": "object", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort"]}, "labor_id": {"type": "string"}, "arzt": {"type": "object", "properties": {"name": {"type": "string"}, "vorname": {"type": "string"}, "berufsbezeichnung": {"type": "string"}, "lanr": {"type": "string"}}, "required": ["name", "lanr"]}}, "required": ["name"]}, "datum": {"type": "string", "format": "date"}, "untersuchung": {"type": "object", "properties": {"bezeichnung": {"type": "string"}, "auftragsnummer": {"type": "string"}, "auftragsdatum": {"type": "string", "format": "date"}, "abnahmezeitpunkt": {"type": "string", "format": "date-time"}, "einsender": {"type": "object", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort"]}}, "required": ["name"]}}, "required": ["bezeichnung"]}, "parameter": {"type": "array", "items": {"type": "object", "properties": {"name": {"type": "string"}, "wert": {"type": "string"}, "einheit": {"type": "string"}, "methode": {"type": "string"}}, "required": ["name", "wert"]}}, "referenzwerte": {"type": "array", "items": {"type": "object", "properties": {"parameter": {"type": "string"}, "untergrenze": {"type": "string"}, "obergrenze": {"type": "string"}, "einheit": {"type": "string"}, "geschlecht": {"type": "string", "enum": ["m\u00e4nnlich", "weiblich", null]}, "alter_min": {"type": "integer"}, "alter_max": {"type": "integer"}}, "required": ["parameter"]}}, "befund": {"type": "object", "properties": {"text": {"type": "string"}, "pathologisch": {"type": "boolean"}, "hinweise": {"type": "string"}, "arzt": {"type": "object", "properties": {"name": {"type": "string"}, "vorname": {"type": "string"}, "berufsbezeichnung": {"type": "string"}, "unterschrift": {"type": "string"}}, "required": ["name"]}}}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^[0-9]{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$", "nullable": true}, "mwst_satz": {"type": "string", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}}, "required": ["patient", "labor", "datum", "untersuchung", "_meta"]}',
    '"{\"patient\": \"Name und ggf. Geburtsdatum des Patienten, f\u00fcr den die Untersuchung durchgef\u00fchrt wurde. Format: Freitext (z. B. ''Max Mustermann, geb. 12.03.1980''). Wichtig f\u00fcr die Zuordnung zu steuerrelevanten Krankheitskosten (Nachweis der pers\u00f6nlichen Betroffenheit).\", \"labor\": \"Name und Adresse des durchf\u00fchrenden Labors. Format: Freitext (z. B. ''Labor Dr. Meyer, Musterstra\u00dfe 1, 10115 Berlin''). Relevant f\u00fcr die Plausibilit\u00e4t des Dokuments und ggf. f\u00fcr die Erstattung durch die Krankenkasse.\", \"datum\": \"Datum der Probenentnahme oder des Befundberichts. Format: ISO-8601 (YYYY-MM-DD) oder deutsches Format (DD.MM.YYYY). Wichtig f\u00fcr die zeitliche Einordnung in Krankheitsverl\u00e4ufe und steuerliche Geltendmachung (z. B. bei chronischen Erkrankungen).\", \"untersuchung\": \"Art der durchgef\u00fchrten Untersuchung (z. B. ''Gro\u00dfes Blutbild'', ''Schilddr\u00fcsenwerte'', ''Urinstatus''). Format: Freitext. Dient der Einordnung der Parameter und ist relevant f\u00fcr die steuerliche Absetzbarkeit (z. B. nur bestimmte Untersuchungen sind anerkannt).\", \"parameter[]\": \"Liste der gemessenen Laborparameter (z. B. ''H\u00e4moglobin'', ''Leukozyten'', ''Glukose''). Format: Array von Freitexten. Wichtig f\u00fcr die medizinische Bewertung und ggf. f\u00fcr die steuerliche Anerkennung (z. B. bei Nachweis von Krankheitskosten).\", \"referenzwerte[]\": \"Referenzbereiche f\u00fcr die jeweiligen Parameter (z. B. ''12,0\u201316,0 g/dl'' f\u00fcr H\u00e4moglobin). Format: Array von Freitexten oder strukturierten Werten (z. B. Min/Max). Wichtig f\u00fcr die Interpretation der Befunde, aber nicht direkt steuerrelevant.\"}"',
    'Laborbericht, Laborbefund, Laborergebnis, Blutbild, Blutwerte, Urinanalyse, Serum, Plasma, Referenzbereich, Normwert, pathologisch, Befund, Untersuchung, Parameter, Hämoglobin, Leukozyten, Cholesterin, Glukose, CRP, TSH, lab report, reference range, test results, medical analysis, diagnostic findings',
    'Labore, Ärzte',
    '{"einordnung": "§33 EStG (außergewöhnliche Belastungen)", "anlage": "Keine direkte Anlage, aber Nachweis für Steuererklärung (z. B. bei Krankheitskosten)", "hinweise": "Kosten für Laboruntersuchungen können als außergewöhnliche Belastungen geltend gemacht werden, sofern sie nicht von der Krankenkasse erstattet wurden. Relevant sind vor allem privat finanzierte Untersuchungen (z. B. IGeL-Leistungen) oder Zuzahlungen. Belege müssen als Nachweis aufbewahrt werden (Aufbewahrungsfrist: 6 Jahre)."}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
ON CONFLICT (id) DO UPDATE SET category=EXCLUDED.category, display_name=EXCLUDED.display_name, description=EXCLUDED.description, schema=EXCLUDED.schema, field_descriptions=EXCLUDED.field_descriptions, classify_keywords=EXCLUDED.classify_keywords, typical_senders=EXCLUDED.typical_senders, steuer_relevanz=EXCLUDED.steuer_relevanz, priority=EXCLUDED.priority, enabled=EXCLUDED.enabled, version=EXCLUDED.version, source=EXCLUDED.source, notes=EXCLUDED.notes;

INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'medical_certificate',
    'G. Gesundheit & Pflege',
    'Attest/ärztliche Bescheinigung',
    'Ein ärztliches Attest oder eine Arbeitsunfähigkeitsbescheinigung (AU) bestätigt die medizinische Notwendigkeit einer Krankschreibung. Es wird von Ärzten ausgestellt, um die Arbeitsunfähigkeit eines Patienten für einen bestimmten Zeitraum zu dokumentieren. Im Gegensatz zu reinen Rezepten oder Überweisungen enthält es konkrete Angaben zur Diagnose und Dauer der Arbeitsunfähigkeit, was für Arbeitgeber und Krankenkassen relevant ist.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "medical_certificate", "description": "Attest/\u00e4rztliche Bescheinigung", "type": "object", "properties": {"patient": {"type": "object", "properties": {"name": {"type": "string"}, "vorname": {"type": "string"}, "geburtsdatum": {"type": "string", "format": "date"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "pattern": "^[A-Z]{2}$"}}, "required": ["strasse", "plz", "ort"]}, "versichertennummer": {"type": "string"}}, "required": ["name", "vorname", "geburtsdatum"]}, "arzt": {"type": "object", "properties": {"name": {"type": "string"}, "vorname": {"type": "string"}, "fachrichtung": {"type": "string"}, "praxisname": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "pattern": "^[A-Z]{2}$"}}, "required": ["strasse", "plz", "ort"]}, "telefon": {"type": "string", "pattern": "^\\+[0-9]{11,15}$"}, "lanr": {"type": "string"}}, "required": ["name", "praxisname", "adresse"]}, "datum": {"type": "string", "format": "date"}, "diagnose": {"type": "string"}, "arbeitsunfaehig_von": {"type": "string", "format": "date"}, "arbeitsunfaehig_bis": {"type": "string", "format": "date"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^[0-9]{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$", "nullable": true}, "mwst_satz": {"type": "string", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}, "diagnosen": {"type": "array", "description": "Diagnosen und Befunde des \u00e4rztlichen Attests", "items": {"type": "object", "properties": {"diagnose": {"type": "string"}, "icd_code": {"type": "string"}}}}}, "required": ["patient", "arzt", "datum", "diagnose"]}',
    '"{\"patient\": \"Name und ggf. Geburtsdatum des Patienten. Wichtig f\u00fcr die Zuordnung des Attests zur Person. Beispiel: ''Max Mustermann, geb. 01.01.1980''.\", \"arzt\": \"Name, Praxis und Kontaktdaten des ausstellenden Arztes. Wichtig f\u00fcr die Authentizit\u00e4t des Attests. Beispiel: ''Dr. med. Anna Schmidt, Musterpraxis, Musterstra\u00dfe 1, 12345 Musterstadt''.\", \"datum\": \"Ausstellungsdatum des Attests. Format: TT.MM.JJJJ. Wichtig f\u00fcr die zeitliche Einordnung der Arbeitsunf\u00e4higkeit. Beispiel: ''15.10.2023''.\", \"diagnose\": \"Medizinische Diagnose, oft mit ICD-10-Code. Wichtig f\u00fcr den Nachweis der Arbeitsunf\u00e4higkeit und ggf. f\u00fcr steuerliche Zwecke (z. B. bei chronischen Erkrankungen). Beispiel: ''J06.9 \u2013 Akute Infektion der oberen Atemwege''.\", \"arbeitsunfaehig_von\": \"Beginn der Arbeitsunf\u00e4higkeit. Format: TT.MM.JJJJ. Wichtig f\u00fcr die Dauer der Krankschreibung und ggf. f\u00fcr Lohnfortzahlungsanspr\u00fcche. Beispiel: ''10.10.2023''.\", \"arbeitsunfaehig_bis\": \"Ende der Arbeitsunf\u00e4higkeit. Format: TT.MM.JJJJ. Wichtig f\u00fcr die Dauer der Krankschreibung und ggf. f\u00fcr Lohnfortzahlungsanspr\u00fcche. Beispiel: ''20.10.2023''.\"}"',
    'Arbeitsunfähigkeitsbescheinigung, Attest, AU-Bescheinigung, Krankschreibung, ärztliche Bescheinigung, Arbeitsunfähigkeit, Diagnose, ICD-10, patient, arzt, arbeitsunfähig, von, bis, Gesundheitsamt, Krankenkasse, Arbeitgeber, medical certificate, sick note, incapacity for work, diagnosis, doctor''s note',
    'Ärzte',
    '{"paragraphen": "§33 EStG (außergewöhnliche Belastungen), §9 EStG (Werbungskosten bei chronischen Erkrankungen)", "anlage": null, "hinweise": "Kosten für Atteste sind nur in Ausnahmefällen (z. B. bei chronischen Erkrankungen oder als Nachweis für außergewöhnliche Belastungen) steuerlich absetzbar. Die Arbeitsunfähigkeitsdauer selbst ist nicht direkt steuerrelevant, kann aber für den Nachweis von Krankheitskosten oder Fahrtkosten (§9 EStG) relevant sein."}',
    0,
    1,
    1,
    'mistral_batch',
    'Häufige Verwechslungen: Atteste werden oft mit Rezepten oder Überweisungen verwechselt, enthalten aber im Gegensatz zu diesen konkrete Angaben zur Arbeitsunfähigkeit. Sonderfälle: Atteste für Kinder (z. B. für Schulbefreiung) oder für spezielle Zwecke (z. B. Sportbefreiung) können abweichen. Bei digitalen AU-Bescheinigungen (eAU) können Felder wie ''Krankenkasse'' oder ''Arbeitgeber'' zusätzlich vorkommen.'
)
ON CONFLICT (id) DO UPDATE SET category=EXCLUDED.category, display_name=EXCLUDED.display_name, description=EXCLUDED.description, schema=EXCLUDED.schema, field_descriptions=EXCLUDED.field_descriptions, classify_keywords=EXCLUDED.classify_keywords, typical_senders=EXCLUDED.typical_senders, steuer_relevanz=EXCLUDED.steuer_relevanz, priority=EXCLUDED.priority, enabled=EXCLUDED.enabled, version=EXCLUDED.version, source=EXCLUDED.source, notes=EXCLUDED.notes;

INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'prescription',
    'G. Gesundheit & Pflege',
    'Rezept',
    'Ein Rezept ist eine ärztliche Verordnung von Medikamenten oder Heilmitteln für Patienten. Es wird typischerweise nach einem Arztbesuch ausgestellt und dient zur Einlösung in Apotheken. Im Gegensatz zu einem Privatrezept (Selbstzahler) oder einem grünen Rezept (Empfehlung) handelt es sich hier meist um ein Kassenrezept (rosa) oder ein Betäubungsmittelrezept (gelb), das von der Krankenkasse erstattet wird.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "prescription", "description": "Schema f\u00fcr ein Rezept-Dokument", "type": "object", "properties": {"patient": {"type": "object", "properties": {"name": {"type": "string"}, "geburtsdatum": {"type": "string", "format": "date"}, "versichertennummer": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "default": "DE"}}, "required": ["strasse", "plz", "ort"]}}, "required": ["name"]}, "arzt": {"type": "object", "properties": {"name": {"type": "string"}, "fachrichtung": {"type": "string"}, "lanr": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "default": "DE"}}, "required": ["strasse", "plz", "ort"]}, "telefon": {"type": "string"}}, "required": ["name"]}, "medikament": {"type": "array", "items": {"type": "object", "properties": {"name": {"type": "string"}, "pzn": {"type": "string"}, "darreichungsform": {"type": "string"}, "wirkstoff": {"type": "string"}, "dosierung": {"type": "string"}, "packungsgroesse": {"type": "string"}, "aut_idem": {"type": "boolean"}}, "required": ["name", "dosierung", "packungsgroesse"]}}, "datum": {"type": "string", "format": "date"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean", "default": false}, "steuerrelevanz_hinweis": {"type": "string", "default": null}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "default": null}, "steuerjahr": {"type": "string", "pattern": "^[0-9]{4}$", "default": null}, "mwst_ausgewiesen": {"type": "boolean", "default": false}, "mwst_betrag": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$", "default": null}, "mwst_satz": {"type": "string", "default": null}, "aktenzeichen": {"type": "string", "default": null}, "dokumenten_id": {"type": "string", "default": null}}, "required": ["steuerrelevant"]}}, "required": ["patient", "arzt", "medikament", "datum"]}',
    '"{\"patient\": \"Name und ggf. Adresse des Patienten, f\u00fcr den das Rezept ausgestellt wurde. Format: ''Max Mustermann'' oder ''Max Mustermann, Musterstra\u00dfe 1, 12345 Musterstadt''. Wichtig f\u00fcr die Zuordnung der Kosten im Rahmen der Steuererkl\u00e4rung (\u00a733 EStG).\", \"arzt\": \"Name, Fachrichtung und Praxisadresse des ausstellenden Arztes. Format: ''Dr. med. Anna Beispiel, Fach\u00e4rztin f\u00fcr Allgemeinmedizin, Beispielstra\u00dfe 2, 12345 Musterstadt''. Wichtig zur Dokumentation der medizinischen Notwendigkeit.\", \"medikament\": \"Name des verordneten Medikaments, ggf. mit Wirkstoff und Pharmazentralnummer (PZN). Format: ''Ibuprofen 400mg (PZN: 1234567)''. Relevant f\u00fcr die steuerliche Anerkennung als Krankheitskosten.\", \"dosierung\": \"Verordnete Dosierung und Einnahmehinweise. Format: ''1 Tablette t\u00e4glich morgens''. Wichtig f\u00fcr die Plausibilit\u00e4t der Verordnung, aber nicht direkt steuerrelevant.\", \"packungsgroesse\": \"Anzahl der verordneten Einheiten (z. B. ''20 St\u00fcck'', ''100 ml''). Format: numerisch oder als Text. Relevant f\u00fcr die Berechnung der Gesamtkosten bei der Steuererkl\u00e4rung.\"}"',
    'Rezept, Kassenrezept, Privatrezept, Arzt, Medikament, Dosierung, Packungsgröße, Verordnung, Apotheke, Krankenkasse, Arzneimittel, Verschreibung, Rosa Rezept, Gelbes Rezept, Arztstempel, Unterschrift, PZN, Pharmazentralnummer, Aut-idem, Gebührenpflichtig, Gültigkeit, patient, arzt, datum',
    'Ärzte',
    '{"paragraphen": ["§33 EStG (außergewöhnliche Belastungen)"], "anlage": null, "hinweise": "Rezeptkosten können als außergewöhnliche Belastungen geltend gemacht werden, sofern sie nicht von der Krankenkasse erstattet wurden. Die Kosten müssen zusammen mit anderen Krankheitskosten die zumutbare Belastungsgrenze überschreiten. Quittungen der Apotheke sind zusätzlich erforderlich."}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
ON CONFLICT (id) DO UPDATE SET category=EXCLUDED.category, display_name=EXCLUDED.display_name, description=EXCLUDED.description, schema=EXCLUDED.schema, field_descriptions=EXCLUDED.field_descriptions, classify_keywords=EXCLUDED.classify_keywords, typical_senders=EXCLUDED.typical_senders, steuer_relevanz=EXCLUDED.steuer_relevanz, priority=EXCLUDED.priority, enabled=EXCLUDED.enabled, version=EXCLUDED.version, source=EXCLUDED.source, notes=EXCLUDED.notes;

INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'care_directive',
    'H. Recht & Vollmachten',
    'Betreuungsverfügung',
    'Eine Betreuungsverfügung ist ein rechtliches Dokument, in dem eine Person (der Verfügende) für den Fall einer zukünftigen Betreuungsbedürftigkeit festlegt, wer als Betreuer bestellt werden soll und welche Aufgabenbereiche dieser übernehmen soll. Im Gegensatz zur Vorsorgevollmacht tritt die Betreuungsverfügung erst in Kraft, wenn eine gerichtliche Betreuerbestellung notwendig wird, und dient als Empfehlung für das Betreuungsgericht. Sie unterscheidet sich von einer Patientenverfügung, die medizinische Maßnahmen regelt, und ist nicht mit einer Vollmacht gleichzusetzen, die sofortige Handlungsbefugnis erteilt.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "care_directive", "description": "Betreuungsverf\u00fcgung zur Regelung der Betreuung im Pflegefall", "type": "object", "properties": {"verfuegender": {"type": "object", "properties": {"name": {"type": "string"}, "vorname": {"type": "string"}, "geburtsdatum": {"type": "string", "format": "date"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "pattern": "^[A-Z]{2}$"}}, "required": ["strasse", "plz", "ort", "land"]}, "telefon": {"type": "string", "pattern": "^\\+[0-9]{8,15}$"}, "email": {"type": "string", "format": "email"}}, "required": ["name", "vorname", "geburtsdatum", "adresse"]}, "gewuenschter_betreuer": {"type": "object", "properties": {"name": {"type": "string"}, "vorname": {"type": "string"}, "geburtsdatum": {"type": "string", "format": "date"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "pattern": "^[A-Z]{2}$"}}, "required": ["strasse", "plz", "ort", "land"]}, "telefon": {"type": "string", "pattern": "^\\+[0-9]{8,15}$"}, "email": {"type": "string", "format": "email"}, "verwandtschaftsgrad": {"type": "string"}}, "required": ["name", "vorname", "adresse"]}, "aufgabenkreise": {"type": "array", "items": {"type": "object", "properties": {"aufgabenkreis": {"type": "string", "enum": ["gesundheitssorge", "vermoegenssorge", "aufenthaltsbestimmung", "post- und fernmeldeverkehr", "vertetung_gegenueber_behoerden", "wohnungsangelegenheiten", "sonstiges"]}, "details": {"type": "string"}}, "required": ["aufgabenkreis"]}}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^[0-9]{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$", "nullable": true}, "mwst_satz": {"type": "string", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}}, "required": ["verfuegender", "_meta"]}',
    '"{\"verfuegender\": \"Name, Geburtsdatum und Adresse der Person, die die Betreuungsverf\u00fcgung erstellt. Wichtig f\u00fcr die Identifikation des Verf\u00fcgenden und die rechtliche Wirksamkeit des Dokuments. Beispiel: ''Max Mustermann, geboren am 15.03.1950, Musterstra\u00dfe 1, 12345 Berlin''.\", \"gewuenschter_betreuer\": \"Name, Geburtsdatum und Adresse der Person, die im Betreuungsfall als Betreuer eingesetzt werden soll. Kann auch eine Ersatzperson benennen. Beispiel: ''Anna Mustermann, geboren am 20.07.1980, Musterweg 2, 12345 Berlin''. Wichtig f\u00fcr das Betreuungsgericht, um den Wunsch des Verf\u00fcgenden zu ber\u00fccksichtigen.\", \"aufgabenkreise\": \"Konkrete Bereiche, f\u00fcr die der Betreuer zust\u00e4ndig sein soll, z.B. Gesundheitsf\u00fcrsorge, Verm\u00f6genssorge, Wohnungsangelegenheiten, Vertretung gegen\u00fcber Beh\u00f6rden. Beispiel: [''Gesundheitsf\u00fcrsorge'', ''Verm\u00f6genssorge'', ''Wohnungsangelegenheiten'']. Diese Felder sind entscheidend, um den Umfang der Betreuung festzulegen und Missverst\u00e4ndnisse zu vermeiden.\"}"',
    'Betreuungsverfügung, Betreuer, Betreuungsgericht, Aufgabenkreise, Betreuung, Vorsorge, §1896 BGB, gerichtliche Betreuung, Betreuungswunsch, Vollmacht, Verfügung, Betreuungsfall, rechtliche Betreuung, bevollmächtigte Person, Gesundheitsfürsorge, Vermögenssorge, Wohnungsangelegenheiten, care directive, legal guardianship, court-appointed guardian, areas of responsibility',
    'Privatpersonen',
    NULL,
    0,
    1,
    1,
    'mistral_batch',
    'Häufig wird die Betreuungsverfügung mit einer Vorsorgevollmacht verwechselt. Während die Vorsorgevollmacht sofortige Handlungsbefugnis erteilt, ist die Betreuungsverfügung nur eine Empfehlung für das Betreuungsgericht und tritt erst bei gerichtlicher Betreuerbestellung in Kraft. Das Dokument sollte handschriftlich unterschrieben und datiert sein, um rechtlich wirksam zu sein. Es empfiehlt sich, die Betreuungsverfügung regelmäßig zu aktualisieren, insbesondere bei Änderungen der persönlichen Verhältnisse oder des Betreuerwunsches.'
)
ON CONFLICT (id) DO UPDATE SET category=EXCLUDED.category, display_name=EXCLUDED.display_name, description=EXCLUDED.description, schema=EXCLUDED.schema, field_descriptions=EXCLUDED.field_descriptions, classify_keywords=EXCLUDED.classify_keywords, typical_senders=EXCLUDED.typical_senders, steuer_relevanz=EXCLUDED.steuer_relevanz, priority=EXCLUDED.priority, enabled=EXCLUDED.enabled, version=EXCLUDED.version, source=EXCLUDED.source, notes=EXCLUDED.notes;

INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'inheritance_cert',
    'H. Recht & Vollmachten',
    'Erbschein',
    'Ein Erbschein ist ein amtliches Dokument, das vom Nachlassgericht ausgestellt wird und die Erben sowie ihre Erbquoten nach einem Verstorbenen offiziell bestätigt. Er dient als Nachweis der Erbberechtigung, z. B. für Banken, Grundbuchämter oder Versicherungen, und ist besonders relevant bei gesetzlicher Erbfolge oder wenn kein Testament vorliegt. Im Gegensatz zu einem Testament oder Erbvertrag wird der Erbschein erst nach dem Tod des Erblassers ausgestellt und ist ein hoheitlicher Akt des Gerichts.',
    '{"type": "object", "properties": {"erblasser": {"type": "object", "properties": {"name": {"type": "string"}, "vorname": {"type": "string"}, "geburtsname": {"type": "string", "nullable": true}, "geburtsdatum": {"type": "string", "format": "date"}, "sterbedatum": {"type": "string", "format": "date"}, "letzte_anschrift": {"type": "object", "properties": {"strasse": {"type": "string"}, "hausnummer": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort", "land"]}}, "required": ["name", "vorname", "geburtsdatum", "sterbedatum", "letzte_anschrift"]}, "erben": {"type": "array", "items": {"type": "object", "properties": {"name": {"type": "string"}, "vorname": {"type": "string"}, "geburtsname": {"type": "string", "nullable": true}, "geburtsdatum": {"type": "string", "format": "date"}, "anschrift": {"type": "object", "properties": {"strasse": {"type": "string"}, "hausnummer": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort", "land"]}, "beziehung_zum_erblasser": {"type": "string"}, "ausschlagung": {"type": "boolean"}}, "required": ["name", "vorname", "geburtsdatum", "anschrift", "beziehung_zum_erblasser"]}}, "erbquoten": {"type": "array", "items": {"type": "object", "properties": {"erben_index": {"type": "integer"}, "quote": {"type": "string"}, "quote_prozent": {"type": "string", "nullable": true}}, "required": ["erben_index", "quote"]}}, "nachlassgericht": {"type": "object", "properties": {"name": {"type": "string"}, "anschrift": {"type": "object", "properties": {"strasse": {"type": "string"}, "hausnummer": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort", "land"]}, "telefon": {"type": "string", "nullable": true}, "email": {"type": "string", "format": "email", "nullable": true}}, "required": ["name", "anschrift"]}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^[0-9]{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$", "nullable": true}, "mwst_satz": {"type": "string", "nullable": true}, "aktenzeichen": {"type": "string"}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen", "aktenzeichen"]}}, "required": ["erblasser", "erben", "erbquoten", "nachlassgericht", "_meta"]}',
    '"{\"erblasser\": \"Name, Geburtsname, Geburtsdatum und Sterbedatum der verstorbenen Person. Wichtig f\u00fcr die Identifikation des Nachlasses und die steuerliche Zuordnung (z. B. Sterbedatum f\u00fcr Fristen nach \u00a730 ErbStG). Beispiel: ''Max Mustermann, geb. M\u00fcller, *01.01.1940, \u202015.03.2023''.\", \"erben\": \"Liste der Erben mit vollst\u00e4ndigen Namen, Geburtsdaten und Adressen. Relevant f\u00fcr die Erbschaftsteuererkl\u00e4rung (Anlage Erb) und die Zuordnung der Freibetr\u00e4ge. Beispiel: [{''name'': ''Anna Mustermann'', ''geburtsdatum'': ''01.01.1970'', ''adresse'': ''Musterstra\u00dfe 1, 12345 Berlin''}]\", \"erbquoten\": \"Anteil am Nachlass in Prozent oder Bruchteilen (z. B. 1/2, 25%). Bestimmt die Aufteilung des steuerpflichtigen Erwerbs und ist Grundlage f\u00fcr die Berechnung der Erbschaftsteuer. Beispiel: [''1/2'', ''1/4'', ''1/4''] oder [50, 25, 25].\", \"nachlassgericht\": \"Name und Anschrift des ausstellenden Gerichts. Wichtig f\u00fcr R\u00fcckfragen oder bei Verlust des Dokuments. Beispiel: ''Amtsgericht Musterstadt, Nachlassgericht, Postfach 1234, 12345 Musterstadt''.\"}"',
    'Erbschein, Erbnachweis, Nachlassgericht, Erblasser, Erbe, Erbquote, gesetzliche Erbfolge, testamentarische Erbfolge, Erbschaft, Erbenstellung, aktenzeichen, Nachlassverfahren, Erbscheinsantrag, Erbenlegitimation, certificate of inheritance, heir, inheritance share, probate court, estate proceedings',
    'Nachlassgericht',
    '{"paragraphen": "§3 ErbStG (Erbschaftsteuer), §30 ErbStG (Anzeigepflicht), §15 ErbStG (Steuerklassen), §16 ErbStG (Freibeträge)", "anlage": "Anlage Erb (Erbschaftsteuererklärung)", "hinweise": "Der Erbschein ist Grundlage für die Erbschaftsteuererklärung. Die Erbquoten bestimmen die Aufteilung des Nachlasses und damit die Höhe der individuellen Steuerlast. Freibeträge (§16 ErbStG) hängen vom Verwandtschaftsgrad ab (z. B. 500.000 € für Ehepartner, 400.000 € für Kinder). Die Anzeigepflicht gegenüber dem Finanzamt besteht innerhalb von 3 Monaten nach Kenntnis des Erbfalls (§30 ErbStG)."}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
ON CONFLICT (id) DO UPDATE SET category=EXCLUDED.category, display_name=EXCLUDED.display_name, description=EXCLUDED.description, schema=EXCLUDED.schema, field_descriptions=EXCLUDED.field_descriptions, classify_keywords=EXCLUDED.classify_keywords, typical_senders=EXCLUDED.typical_senders, steuer_relevanz=EXCLUDED.steuer_relevanz, priority=EXCLUDED.priority, enabled=EXCLUDED.enabled, version=EXCLUDED.version, source=EXCLUDED.source, notes=EXCLUDED.notes;

INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'living_will',
    'H. Recht & Vollmachten',
    'Patientenverfügung',
    'Eine Patientenverfügung ist eine schriftliche Vorausverfügung einer Person für den Fall, dass sie ihren Willen nicht mehr (wirksam) erklären kann. Sie regelt medizinische Maßnahmen wie lebenserhaltende Behandlungen oder Schmerztherapien und ist rechtlich bindend (§1901a BGB). Im Gegensatz zu einer Vorsorgevollmacht, die eine Vertrauensperson bevollmächtigt, legt die Patientenverfügung konkrete Behandlungswünsche fest und ist unabhängig von einer Vollmacht gültig.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "Living Will", "description": "Schema f\u00fcr eine Patientenverf\u00fcgung (Living Will)", "type": "object", "properties": {"verfuegender": {"type": "object", "properties": {"name": {"type": "string"}, "vorname": {"type": "string"}, "geburtsdatum": {"type": "string", "format": "date"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort"]}, "telefon": {"type": "string"}, "email": {"type": "string", "format": "email"}}, "required": ["name", "vorname", "geburtsdatum"]}, "vertrauensperson": {"type": "object", "properties": {"name": {"type": "string"}, "vorname": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort"]}, "telefon": {"type": "string"}, "email": {"type": "string", "format": "email"}, "beziehung": {"type": "string"}}, "required": ["name", "vorname"]}, "behandlungswuensche": {"type": "array", "items": {"type": "object", "properties": {"beschreibung": {"type": "string"}, "situation": {"type": "string"}, "wunsch": {"type": "string"}}, "required": ["beschreibung"]}}, "datum": {"type": "string", "format": "date"}, "unterschrift": {"type": "boolean"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "enum": [null], "default": null}, "steuer_kategorie": {"type": "string", "enum": [null], "default": null}, "steuerjahr": {"type": "string", "enum": [null], "default": null}, "mwst_ausgewiesen": {"type": "boolean", "default": false}, "mwst_betrag": {"type": "string", "enum": [null], "default": null}, "mwst_satz": {"type": "string", "enum": [null], "default": null}, "aktenzeichen": {"type": "string", "enum": [null], "default": null}, "dokumenten_id": {"type": "string"}}, "required": ["steuerrelevant", "dokumenten_id"]}}, "required": ["verfuegender", "_meta"]}',
    '"{\"verfuegender\": \"Name, Geburtsdatum und Adresse der Person, die die Patientenverf\u00fcgung erstellt. Wichtig f\u00fcr die eindeutige Identifikation und rechtliche Zuordnung. Beispiel: ''Max Mustermann, geboren am 15.03.1950, Musterstra\u00dfe 1, 12345 Berlin''.\", \"vertrauensperson\": \"Name und Kontaktdaten einer oder mehrerer Personen, die im Falle der Entscheidungsunf\u00e4higkeit des Verf\u00fcgenden als Ansprechpartner f\u00fcr \u00c4rzte dienen. Beispiel: ''Anna Mustermann, Musterstra\u00dfe 1, 12345 Berlin, Telefon: 030 123456''. Nicht zu verwechseln mit einem Bevollm\u00e4chtigten in einer Vorsorgevollmacht \u2013 hier hat die Vertrauensperson keine Entscheidungsbefugnis, sondern dient nur der Information.\", \"behandlungswuensche\": \"Konkrete Angaben zu gew\u00fcnschten oder abgelehnten medizinischen Ma\u00dfnahmen, z. B. ''keine k\u00fcnstliche Beatmung'', ''Schmerztherapie auch bei Bewusstseinsverlust''. Oft in Flie\u00dftext oder als Checkliste formuliert. Wichtig f\u00fcr die Umsetzung des Willens durch \u00c4rzte und Pflegekr\u00e4fte. Beispiel: ''Ich w\u00fcnsche keine Reanimation, wenn mein Herzstillstand l\u00e4nger als 10 Minuten andauert.''\", \"datum\": \"Datum der Unterzeichnung der Patientenverf\u00fcgung. Wichtig f\u00fcr die G\u00fcltigkeit, da \u00e4ltere Verf\u00fcgungen ggf. auf Aktualit\u00e4t gepr\u00fcft werden m\u00fcssen. Format: TT.MM.JJJJ, z. B. ''10.05.2023''.\", \"unterschrift\": \"Handschriftliche Unterschrift des Verf\u00fcgenden. Ohne Unterschrift ist die Patientenverf\u00fcgung nicht rechtswirksam. Beispiel: ''Max Mustermann'' (als Faksimile oder Original).\"}"',
    'Patientenverfügung, Behandlungswünsche, lebenserhaltende Maßnahmen, medizinische Behandlung, Sterbehilfe, palliative Versorgung, Vorsorge, §1901a BGB, Willenserklärung, Gesundheitsfürsorge, mutmaßlicher Wille, Reanimation, künstliche Ernährung, Beatmung, Schmerztherapie, Notfallplan, advance directive, living will, healthcare proxy, end-of-life care',
    'Privatpersonen',
    NULL,
    0,
    1,
    1,
    'mistral_batch',
    'Häufige Verwechslungen: Patientenverfügung vs. Vorsorgevollmacht (letztere bevollmächtigt eine Person, erstere regelt konkrete Maßnahmen). Eine Patientenverfügung sollte regelmäßig (z. B. alle 2 Jahre) aktualisiert und neu unterschrieben werden, um Zweifel an der Aktualität des Willens zu vermeiden. Tipp: Kombiniert mit einer Vorsorgevollmacht und Betreuungsverfügung hinterlegen, um alle Vorsorgeaspekte abzudecken. Ärzte sind verpflichtet, die Patientenverfügung zu beachten, sofern sie auf die aktuelle Situation zutrifft.'
)
