INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'power_of_attorney',
    'H. Recht & Vollmachten',
    'Vollmacht',
    'Eine Vollmacht ist ein rechtliches Dokument, mit dem eine Person (Vollmachtgeber) einer anderen Person (Bevollmächtigter) die Befugnis erteilt, in ihrem Namen zu handeln. Sie kommt in verschiedenen Lebenslagen vor, z.B. für Bankgeschäfte, Gesundheitsangelegenheiten oder Vertretung vor Behörden. Im Gegensatz zu einer Generalvollmacht ist der Umfang oft spezifisch begrenzt und kann notariell beglaubigt sein, was sie von einfachen mündlichen Absprachen unterscheidet.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "Power of Attorney", "description": "Schema for extracting information from a power of attorney document", "type": "object", "properties": {"vollmachtgeber": {"type": "object", "properties": {"name": {"type": "string"}, "geburtsdatum": {"type": "string", "format": "date"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort", "land"]}, "ausweisnummer": {"type": "string"}}, "required": ["name", "adresse"]}, "bevollmaechtigter": {"type": "object", "properties": {"name": {"type": "string"}, "geburtsdatum": {"type": "string", "format": "date"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort", "land"]}, "ausweisnummer": {"type": "string"}}, "required": ["name", "adresse"]}, "umfang": {"type": "array", "items": {"type": "object", "properties": {"bereich": {"type": "string"}, "beschreibung": {"type": "string"}}, "required": ["bereich"]}}, "art": {"type": "string"}, "notar": {"type": "object", "properties": {"name": {"type": "string"}, "notarkammer": {"type": "string"}, "datum": {"type": "string", "format": "date"}, "siegelnummer": {"type": "string"}}, "required": ["name"]}, "gueltig_ab": {"type": "string", "format": "date"}, "gueltig_bis": {"type": "string", "format": "date"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^[0-9]{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$", "nullable": true}, "mwst_satz": {"type": "string", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}}, "required": ["vollmachtgeber", "bevollmaechtigter", "art", "_meta"]}',
    '"{\"vollmachtgeber\": \"Name und Adresse der Person, die die Vollmacht erteilt. Wichtig f\u00fcr die Identifikation der vertretenden Partei. Format: Vorname Nachname, Stra\u00dfe Hausnummer, PLZ Ort. Beispiel: Max Mustermann, Musterstra\u00dfe 1, 12345 Musterstadt.\", \"bevollmaechtigter\": \"Name und Adresse der Person, die bevollm\u00e4chtigt wird. Wichtig f\u00fcr die Identifikation der vertretenden Partei. Format: Vorname Nachname, Stra\u00dfe Hausnummer, PLZ Ort. Beispiel: Anna Beispiel, Beispielweg 2, 54321 Beispielstadt.\", \"umfang\": \"Beschreibung der Handlungen oder Bereiche, f\u00fcr die die Vollmacht gilt. Beispiel: ''Vertretung in allen Bankangelegenheiten bei der Musterbank'' oder ''Entscheidungen \u00fcber medizinische Behandlungen''. Wichtig f\u00fcr die Abgrenzung der Befugnisse.\", \"art\": \"Typ der Vollmacht, z.B. Generalvollmacht, Vorsorgevollmacht, Bankvollmacht, Handlungsvollmacht. Beispiel: ''Vorsorgevollmacht''.\", \"notar\": \"Angabe, ob die Vollmacht notariell beglaubigt oder beurkundet wurde. Format: Boolean (true/false). Beispiel: true. Wichtig f\u00fcr die rechtliche Wirksamkeit in bestimmten F\u00e4llen (z.B. Grundst\u00fccksgesch\u00e4fte).\", \"gueltig_ab\": \"Datum, ab dem die Vollmacht g\u00fcltig ist. Format: ISO 8601 (YYYY-MM-DD). Beispiel: 2023-10-01. Wichtig f\u00fcr die zeitliche Einordnung der Befugnisse.\", \"gueltig_bis\": \"Datum, bis zu dem die Vollmacht g\u00fcltig ist. Kann auch ''unbefristet'' sein. Format: ISO 8601 (YYYY-MM-DD) oder String. Beispiel: 2025-12-31 oder ''unbefristet''. Wichtig f\u00fcr die zeitliche Einordnung der Befugnisse.\"}"',
    'Vollmacht, Bevollmächtigter, Vollmachtgeber, Vertretungsbefugnis, Unterschrift, notariell beglaubigt, Generalvollmacht, Vorsorgevollmacht, Bankvollmacht, Handlungsvollmacht, power of attorney, authorization, legal representation, scope of authority, gültig ab, gültig bis, hiermit ermächtige ich, hiermit bevollmächtige ich',
    'Privatpersonen, Notare',
    NULL,
    0,
    1,
    1,
    'mistral_batch',
    'Häufige Verwechslungen: Vorsorgevollmachten werden oft mit Patientenverfügungen verwechselt, obwohl sie unterschiedliche Zwecke haben (Vertretungsbefugnis vs. medizinische Wünsche). Notariell beglaubigte Vollmachten sind besonders wichtig für Rechtsgeschäfte wie Grundstückskäufe oder bestimmte Banktransaktionen. Bei Vollmachten ohne Notar sollte geprüft werden, ob sie für den vorgesehenen Zweck ausreichen. Tipp: Achten Sie auf Formulierungen wie ''hiermit bevollmächtige ich'' oder ''Vertretungsbefugnis'' zur Erkennung.'
)
ON CONFLICT (id) DO UPDATE SET category=EXCLUDED.category, display_name=EXCLUDED.display_name, description=EXCLUDED.description, schema=EXCLUDED.schema, field_descriptions=EXCLUDED.field_descriptions, classify_keywords=EXCLUDED.classify_keywords, typical_senders=EXCLUDED.typical_senders, steuer_relevanz=EXCLUDED.steuer_relevanz, priority=EXCLUDED.priority, enabled=EXCLUDED.enabled, version=EXCLUDED.version, source=EXCLUDED.source, notes=EXCLUDED.notes;

INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'will',
    'H. Recht & Vollmachten',
    'Testament',
    'Ein Testament ist eine letztwillige Verfügung, in der eine Person (Erblasser) regelt, wie ihr Vermögen nach dem Tod verteilt werden soll. Es kommt im Erbfall zum Einsatz und unterscheidet sich von anderen Dokumenten wie Erbverträgen oder Vorsorgevollmachten durch seine einseitige, widerrufliche Natur. Notariell beglaubigte Testamente sind besonders formell und rechtssicher.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "Testament", "description": "Extraktionsschema f\u00fcr ein Testament", "type": "object", "properties": {"erblasser": {"type": "object", "properties": {"name": {"type": "string"}, "geburtsdatum": {"type": "string", "format": "date"}, "geburtsort": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort"]}, "steuer_id": {"type": "string"}}, "required": ["name", "adresse"]}, "erben": {"type": "array", "items": {"type": "object", "properties": {"name": {"type": "string"}, "geburtsdatum": {"type": "string", "format": "date"}, "verwandtschaftsgrad": {"type": "string"}, "anteil": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort"]}}, "required": ["name", "anteil"]}}, "vermaechtnisnehmer": {"type": "array", "items": {"type": "object", "properties": {"name": {"type": "string"}, "vermaechtnis": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort"]}}, "required": ["name", "vermaechtnis"]}}, "datum": {"type": "string", "format": "date"}, "notar": {"type": "object", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort"]}, "aktenzeichen": {"type": "string"}}, "required": ["name", "adresse"]}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^\\d{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$", "nullable": true}, "mwst_satz": {"type": "string", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}}, "required": ["erblasser", "datum", "_meta"]}',
    '"{\"erblasser\": \"Name, Geburtsdatum und Adresse der Person, die das Testament verfasst hat. Wichtig f\u00fcr die Identifikation des Testaments und die Zuordnung des Nachlasses. Beispiel: ''Max Mustermann, geboren am 15.03.1950, Musterstra\u00dfe 1, 12345 Berlin''.\", \"erben\": \"Liste der Personen oder Institutionen, die als Erben eingesetzt werden (z.B. Familienmitglieder, Freunde, Stiftungen). Enth\u00e4lt Namen, Verwandtschaftsgrad und ggf. Erbquoten (z.B. ''50% an meine Ehefrau Anna Mustermann''). Relevant f\u00fcr die Erbschaftsteuererkl\u00e4rung der Erben.\", \"vermaechtnisnehmer\": \"Personen oder Institutionen, die ein Verm\u00e4chtnis (z.B. Geldbetrag, Immobilie, Gegenstand) erhalten, ohne Erben zu sein. Beispiel: ''Mein Neffe Paul erh\u00e4lt mein Klavier''. Wichtig f\u00fcr die Erbschaftsteuer, da Verm\u00e4chtnisse separat besteuert werden.\", \"datum\": \"Datum der Testamentserstellung oder -unterzeichnung. Format: ISO 8601 (YYYY-MM-DD). Beispiel: ''2023-10-15''. Relevant f\u00fcr die G\u00fcltigkeit (z.B. bei mehreren Testamenten gilt das j\u00fcngste) und f\u00fcr die Erbschaftsteuererkl\u00e4rung.\"}"',
    'Testament, letztwillige Verfügung, Erblasser, Erbe, Vermächtnis, Nachlass, Erbschaft, Notar, Unterschrift, Zeugen, §1937 BGB, §2231 BGB, §2247 BGB, handschriftlich, eigenhändig, Testamentseröffnung, Erbvertrag, legacy, will, testator, heir, bequest, notarized',
    'Privatpersonen, Notare',
    '{"paragraphen": "§3 ErbStG (Erbschaftsteuer), §13 ErbStG (Steuerbefreiungen), §15 ErbStG (Steuerklassen), §16 ErbStG (Freibeträge)", "anlage": null, "hinweise": "Das Testament selbst ist nicht direkt steuerrelevant, aber die darin festgelegten Erb- und Vermächtnisanteile bestimmen die Erbschaftsteuerpflicht der Begünstigten. Freibeträge hängen vom Verwandtschaftsgrad ab (z.B. Ehepartner: 500.000 €, Kinder: 400.000 €)."}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
ON CONFLICT (id) DO UPDATE SET category=EXCLUDED.category, display_name=EXCLUDED.display_name, description=EXCLUDED.description, schema=EXCLUDED.schema, field_descriptions=EXCLUDED.field_descriptions, classify_keywords=EXCLUDED.classify_keywords, typical_senders=EXCLUDED.typical_senders, steuer_relevanz=EXCLUDED.steuer_relevanz, priority=EXCLUDED.priority, enabled=EXCLUDED.enabled, version=EXCLUDED.version, source=EXCLUDED.source, notes=EXCLUDED.notes;

INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'birth_certificate',
    'I. Urkunden & Bescheinigungen',
    'Geburtsurkunde',
    'Die Geburtsurkunde ist eine amtliche Bescheinigung über die Geburt einer Person, ausgestellt vom Standesamt. Sie enthält grundlegende persönliche Daten wie Name, Geburtsdatum, Geburtsort sowie Informationen zu den Eltern. Im Gegensatz zur Geburtsbescheinigung (für religiöse Zwecke) oder dem internationalen Geburtsregisterauszug ist die Geburtsurkunde das offizielle Dokument für behördliche und rechtliche Angelegenheiten in Deutschland.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "Geburtsurkunde", "description": "Extraktionsschema f\u00fcr Geburtsurkunden", "type": "object", "properties": {"name": {"type": "object", "properties": {"vorname": {"type": "string"}, "nachname": {"type": "string"}, "geburtsname": {"type": "string"}}, "required": ["vorname", "nachname"]}, "geburtsdatum": {"type": "string", "format": "date"}, "geburtsort": {"type": "object", "properties": {"ort": {"type": "string"}, "krankenhaus": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "default": "DE"}}}}, "required": ["ort"]}, "eltern": {"type": "array", "items": {"type": "object", "properties": {"vorname": {"type": "string"}, "nachname": {"type": "string"}, "geburtsname": {"type": "string"}, "geburtsdatum": {"type": "string", "format": "date"}, "geburtsort": {"type": "string"}, "staatsangehoerigkeit": {"type": "string"}, "wohnort": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}}}, "required": ["vorname", "nachname"]}}, "standesamt": {"type": "object", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "default": "DE"}}}}, "required": ["name"]}, "registernummer": {"type": "string"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean", "default": false}, "steuerrelevanz_hinweis": {"type": "string", "default": null}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "default": null}, "steuerjahr": {"type": "string", "pattern": "^[0-9]{4}$", "default": null}, "mwst_ausgewiesen": {"type": "boolean", "default": false}, "mwst_betrag": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$", "default": null}, "mwst_satz": {"type": "string", "default": null}, "aktenzeichen": {"type": "string", "default": null}, "dokumenten_id": {"type": "string", "default": null}}, "required": ["steuerrelevant", "steuerrelevanz_hinweis", "steuer_kategorie", "mwst_ausgewiesen"]}}, "required": ["name", "geburtsdatum", "geburtsort", "standesamt", "registernummer", "_meta"]}',
    '"{\"name\": \"Vollst\u00e4ndiger Name des Kindes (Vor- und Nachname) wie in der Urkunde eingetragen. Format: String, z. B. ''Max Mustermann''. Wichtig f\u00fcr die Zuordnung zu steuerlichen Anspr\u00fcchen (Kindergeld, Freibetr\u00e4ge).\", \"geburtsdatum\": \"Datum der Geburt im Format YYYY-MM-DD (ISO 8601), z. B. ''2023-05-15''. Entscheidend f\u00fcr die Altersberechnung bei steuerlichen Freibetr\u00e4gen (z. B. bis zum 18. oder 25. Lebensjahr).\", \"geburtsort\": \"Ort der Geburt (Stadt, ggf. Krankenhaus), z. B. ''Berlin''. Format: String. Wird f\u00fcr beh\u00f6rdliche Antr\u00e4ge oder Nachweise ben\u00f6tigt, ist aber nicht steuerrelevant.\", \"eltern\": \"Namen der Eltern (Mutter und/oder Vater) im Format Array von Objekten, z. B. [{''name'': ''Anna Mustermann'', ''rolle'': ''Mutter''}, {''name'': ''Paul Mustermann'', ''rolle'': ''Vater''}]. Wichtig f\u00fcr die Zuordnung von Sorgerecht oder steuerlichen Anspr\u00fcchen (z. B. bei Alleinerziehenden).\", \"standesamt\": \"Name und Ort des ausstellenden Standesamts, z. B. ''Standesamt Berlin-Mitte''. Format: String. Dient der Authentifizierung der Urkunde, nicht steuerrelevant.\"}"',
    'Geburtsurkunde, Geburtsregister, Standesamt, Name des Kindes, Geburtsdatum, Geburtsort, Eltern, Mutter, Vater, Registernummer, Geburtsbescheinigung, birth certificate, register number, place of birth, date of birth, parents, registrar''s office, amtliche Urkunde',
    'Standesamt',
    '{"relevanz": "indirekt", "hinweise": "Die Geburtsurkunde selbst ist nicht direkt steuerrelevant, aber die darin enthaltenen Daten (z. B. Name, Geburtsdatum des Kindes) sind Grundlage für steuerliche Ansprüche wie Kindergeld (§31 EStG), Kinderfreibetrag (§32 EStG) oder Entlastungsbetrag für Alleinerziehende (§24b EStG). Die Registernummer kann zur Identifikation in behördlichen Anträgen (z. B. Anlage Kind) benötigt werden."}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
