INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'certificate',
    'I. Urkunden & Bescheinigungen',
    'Bescheinigung',
    'Eine Bescheinigung ist ein offizielles Dokument, das von einer Behörde, einem Arbeitgeber oder einem Verein ausgestellt wird, um bestimmte Tatsachen oder Qualifikationen zu bestätigen. Sie kommt in verschiedenen Kontexten vor, z. B. als Arbeitsbescheinigung, Immatrikulationsbescheinigung oder Mitgliedschaftsbestätigung. Im Gegensatz zu Verträgen oder Rechnungen dient sie primär der Bestätigung von Zuständen oder Berechtigungen und enthält keine vertraglichen Verpflichtungen oder finanziellen Transaktionen.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "certificate", "description": "Schema f\u00fcr Bescheinigungen", "type": "object", "properties": {"aussteller": {"type": "object", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort", "land"]}, "kontakt": {"type": "object", "properties": {"telefon": {"type": "string"}, "email": {"type": "string", "format": "email"}}}}, "required": ["name"]}, "empfaenger": {"type": "object", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort", "land"]}}, "required": ["name"]}, "gegenstand": {"type": "string"}, "datum": {"type": "string", "format": "date"}, "gueltig_bis": {"type": "string", "format": "date"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^[0-9]{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$", "nullable": true}, "mwst_satz": {"type": "string", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}}, "required": ["aussteller", "empfaenger", "gegenstand", "datum", "_meta"]}',
    '"{\"aussteller\": \"Der Name der ausstellenden Institution, Beh\u00f6rde, des Arbeitgebers oder Vereins. Beispiel: ''Stadt M\u00fcnchen'', ''Universit\u00e4t Heidelberg'', ''Deutsche Rentenversicherung''. Wichtig f\u00fcr die Identifikation der Quelle und ggf. sp\u00e4tere Nachweise.\", \"empfaenger\": \"Der Name der Person, f\u00fcr die die Bescheinigung ausgestellt wurde. Beispiel: ''Max Mustermann''. Wichtig f\u00fcr die Zuordnung des Dokuments zum Empf\u00e4nger.\", \"gegenstand\": \"Der konkrete Inhalt oder Zweck der Bescheinigung. Beispiel: ''Immatrikulationsbescheinigung f\u00fcr das Wintersemester 2023/24'', ''Mitgliedschaft im Sportverein XY e.V.'', ''Arbeitsbescheinigung f\u00fcr das Jahr 2023''. Dieser Feldinhalt ist entscheidend, um den Typ der Bescheinigung zu klassifizieren.\", \"datum\": \"Das Ausstellungsdatum der Bescheinigung im Format TT.MM.JJJJ. Beispiel: ''15.10.2023''. Wichtig f\u00fcr die zeitliche Einordnung und ggf. Fristen (z. B. bei Arbeitsbescheinigungen f\u00fcr die Agentur f\u00fcr Arbeit).\", \"gueltig_bis\": \"Das Datum, bis zu dem die Bescheinigung g\u00fcltig ist (falls zutreffend), im Format TT.MM.JJJJ. Beispiel: ''31.12.2024''. Nicht alle Bescheinigungen haben ein Ablaufdatum, z. B. Arbeitsbescheinigungen sind oft zeitlich unbegrenzt g\u00fcltig. Wichtig f\u00fcr die Pr\u00fcfung der Aktualit\u00e4t des Dokuments.\"}"',
    'Bescheinigung, Zertifikat, Certificate, Bestätigung, Nachweis, Attest, Ausweis, Urkunde, Confirmation, Membership, Immatrikulation, Arbeitsbescheinigung, behördlich, ausgestellt, gültig bis, Aussteller, Empfänger, Gegenstand, datum',
    'Behörden, Arbeitgeber, Vereine',
    NULL,
    0,
    1,
    1,
    'mistral_batch',
    'Häufige Verwechslungen: Bescheinigungen können mit ähnlichen Dokumenten wie Urkunden (z. B. Geburtsurkunde) oder Zeugnissen (z. B. Schulzeugnis) verwechselt werden. Urkunden sind jedoch oft einmalige Dokumente mit hoheitlichem Charakter (z. B. Geburts-, Heiratsurkunde), während Bescheinigungen häufiger wiederkehrend oder temporär sind. Zeugnisse enthalten in der Regel Bewertungen oder Leistungsnachweise, während Bescheinigungen reine Tatsachenbestätigungen sind. Tipp: Achte auf Formulierungen wie ''bescheinigt hiermit'' oder ''bestätigt'', die typisch für Bescheinigungen sind.'
)
ON CONFLICT (id) DO UPDATE SET category=EXCLUDED.category, display_name=EXCLUDED.display_name, description=EXCLUDED.description, schema=EXCLUDED.schema, field_descriptions=EXCLUDED.field_descriptions, classify_keywords=EXCLUDED.classify_keywords, typical_senders=EXCLUDED.typical_senders, steuer_relevanz=EXCLUDED.steuer_relevanz, priority=EXCLUDED.priority, enabled=EXCLUDED.enabled, version=EXCLUDED.version, source=EXCLUDED.source, notes=EXCLUDED.notes;

INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'death_certificate',
    'I. Urkunden & Bescheinigungen',
    'Sterbeurkunde',
    'Die Sterbeurkunde ist eine amtliche Bescheinigung über den Tod einer Person, ausgestellt vom Standesamt. Sie wird benötigt für die Abwicklung des Nachlasses, Versicherungsansprüche, Rentenangelegenheiten und andere behördliche oder rechtliche Vorgänge. Im Gegensatz zur Todesbescheinigung (ärztliches Dokument) ist die Sterbeurkunde das offizielle Registerdokument mit öffentlichem Glauben.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "death_certificate", "description": "Schema f\u00fcr die Extraktion von Sterbeurkunden", "type": "object", "properties": {"name": {"description": "Vollst\u00e4ndiger Name des Verstorbenen", "type": "string"}, "sterbedatum": {"description": "Datum des Todes im Format YYYY-MM-DD", "type": "string", "format": "date"}, "sterbeort": {"description": "Ort des Todes (Adresse)", "type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "default": "DE"}}, "required": ["strasse", "plz", "ort"]}, "standesamt": {"description": "Name des ausstellenden Standesamts", "type": "string"}, "registernummer": {"description": "Registernummer der Sterbeurkunde", "type": "string"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean", "default": false}, "steuerrelevanz_hinweis": {"type": "string", "default": null}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "default": null}, "steuerjahr": {"type": "string", "pattern": "^[0-9]{4}$", "default": null}, "mwst_ausgewiesen": {"type": "boolean", "default": false}, "mwst_betrag": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$", "default": null}, "mwst_satz": {"type": "string", "default": null}, "aktenzeichen": {"type": "string", "default": null}, "dokumenten_id": {"type": "string", "default": null}}, "required": ["steuerrelevant"]}}, "required": ["name", "sterbedatum", "sterbeort", "standesamt", "registernummer"]}',
    '"{\"name\": \"Vollst\u00e4ndiger Name der verstorbenen Person (Vor- und Nachname, ggf. Geburtsname). Wichtig f\u00fcr die eindeutige Identifizierung im Nachlassverfahren und f\u00fcr steuerliche Zwecke (z. B. Erbschaftssteuererkl\u00e4rung). Format: String, Beispiel: ''Max Mustermann'' oder ''Erika Musterfrau geb. Schmidt''.\", \"sterbedatum\": \"Datum des Todes im Format TT.MM.JJJJ. Entscheidend f\u00fcr Fristenberechnungen (z. B. Erbausschlagung \u00a71944 BGB, Steuererkl\u00e4rung \u00a731 ErbStG) und Bewertungsstichtag (\u00a711 ErbStG). Beispiel: ''15.08.2023''.\", \"sterbeort\": \"Ort des Todes (Stadt, Gemeinde, ggf. Krankenhaus oder Adresse). Wichtig f\u00fcr die Zust\u00e4ndigkeit des Standesamts und ggf. f\u00fcr regionale steuerliche Besonderheiten. Format: String, Beispiel: ''Berlin'' oder ''M\u00fcnchen, Klinikum Rechts der Isar''.\", \"standesamt\": \"Name und Ort des ausstellenden Standesamts. Relevant f\u00fcr die Authentizit\u00e4t der Urkunde und ggf. f\u00fcr Nachfragen. Format: String, Beispiel: ''Standesamt M\u00fcnchen'' oder ''Standesamt Berlin-Charlottenburg''.\"}"',
    'Sterbeurkunde, Sterbefall, Standesamt, Registereintrag, Registernummer, Todesdatum, Todesort, verstorben, amtliche Bescheinigung, death certificate, register number, civil registry, official death record, Sterbefallanzeige, Beurkundung, Sterberegister',
    'Standesamt',
    '{"relevanz": "indirekt", "hinweise": "Die Sterbeurkunde selbst ist nicht direkt steuerrelevant, aber Voraussetzung für steuerliche Vorgänge wie Erbschaftssteuererklärung (§30 ErbStG), Nachlassabwicklung oder die Meldung an das Finanzamt (§33 ErbStG). Dient als Nachweis für den Todeszeitpunkt, der für Fristen (z. B. §195 BGB) und steuerliche Bewertungen (z. B. §11 ErbStG) entscheidend ist. Anlage: Bei Erbschaftssteuererklärung (Anlage Erb) oder ggf. als Beleg für außergewöhnliche Belastungen (§33 EStG) bei Beerdigungskosten."}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
ON CONFLICT (id) DO UPDATE SET category=EXCLUDED.category, display_name=EXCLUDED.display_name, description=EXCLUDED.description, schema=EXCLUDED.schema, field_descriptions=EXCLUDED.field_descriptions, classify_keywords=EXCLUDED.classify_keywords, typical_senders=EXCLUDED.typical_senders, steuer_relevanz=EXCLUDED.steuer_relevanz, priority=EXCLUDED.priority, enabled=EXCLUDED.enabled, version=EXCLUDED.version, source=EXCLUDED.source, notes=EXCLUDED.notes;

INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'diploma',
    'I. Urkunden & Bescheinigungen',
    'Zeugnis/Diplom/Urkunde',
    'Ein Zeugnis, Diplom oder eine Urkunde bestätigt den erfolgreichen Abschluss einer schulischen, beruflichen oder akademischen Ausbildung. Es wird von Bildungseinrichtungen wie Schulen, Universitäten oder Berufsakademien ausgestellt und enthält Angaben zum Absolventen, der Institution, dem Abschlussgrad, dem Datum der Verleihung und oft einer Abschlussnote. Im Gegensatz zu einfachen Teilnahmebescheinigungen oder Zertifikaten für einzelne Kurse handelt es sich hier um offizielle Dokumente, die einen formalen Bildungsabschluss belegen.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "Diploma", "description": "Schema for extracting information from diplomas, certificates, and academic documents", "type": "object", "properties": {"name": {"description": "Full name of the person who received the diploma", "type": "string"}, "institution": {"description": "Name of the educational institution issuing the diploma", "type": "string"}, "abschluss": {"description": "Type of degree or qualification awarded", "type": "string"}, "datum": {"description": "Date when the diploma was issued (YYYY-MM-DD)", "type": "string", "format": "date"}, "note": {"description": "Final grade or score achieved (e.g., ''1.5'', ''A'', ''sehr gut'')", "type": "string"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean", "default": false}, "steuerrelevanz_hinweis": {"type": "string", "default": null}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "default": null}, "steuerjahr": {"type": "string", "pattern": "^[0-9]{4}$", "default": null}, "mwst_ausgewiesen": {"type": "boolean", "default": false}, "mwst_betrag": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$", "default": null}, "mwst_satz": {"type": "string", "default": null}, "aktenzeichen": {"type": "string", "default": null}, "dokumenten_id": {"type": "string", "default": null}}, "additionalProperties": false}}, "required": ["name", "institution", "abschluss", "datum"], "additionalProperties": false}',
    '"{\"name\": \"Der vollst\u00e4ndige Name der Person, die den Abschluss erhalten hat. Format: Vorname Nachname, z.B. ''Max Mustermann''. Wichtig f\u00fcr die Identifikation des Dokumenteninhabers, aber nicht direkt steuerrelevant.\", \"institution\": \"Name der ausstellenden Bildungseinrichtung, z.B. ''Technische Universit\u00e4t M\u00fcnchen'' oder ''Goethe-Gymnasium Berlin''. Format: Vollst\u00e4ndiger offizieller Name der Institution.\", \"abschluss\": \"Der erworbene akademische oder schulische Grad bzw. Abschluss, z.B. ''Abitur'', ''Bachelor of Science in Informatik'', ''Staatlich gepr\u00fcfter Techniker'' oder ''Promotion zum Dr. rer. nat.''. Wichtig f\u00fcr die Dokumentation der Qualifikation, aber nicht direkt steuerrelevant.\", \"datum\": \"Das Ausstellungsdatum des Zeugnisses/Diploms im Format TT.MM.JJJJ, z.B. ''15.07.2023''. Relevant f\u00fcr die zeitliche Einordnung des Abschlusses, aber nicht steuerrelevant.\", \"note\": \"Die Abschlussnote oder Durchschnittsnote, sofern im Dokument angegeben. Format variiert je nach Institution (z.B. ''1,3'', ''sehr gut'', ''mit Auszeichnung''). Wichtig f\u00fcr die Bewertung der Leistung, aber nicht direkt steuerrelevant.\"}"',
    'Zeugnis, Diplom, Urkunde, Abschlusszeugnis, Hochschulzeugnis, Schulabschluss, Bachelor, Master, Staatsexamen, Promotion, Abschlussurkunde, Prüfungsamt, Rektor, Dekan, Note, Durchschnittsnote, Leistungsnachweis, Bildungseinrichtung, Universität, Hochschule, Schule, Berufsakademie, diploma, certificate, graduation, degree, final grade, academic transcript',
    'Schulen, Hochschulen',
    NULL,
    0,
    1,
    1,
    'mistral_batch',
    'Häufige Verwechslungen können mit einfachen Teilnahmebescheinigungen, Zertifikaten für Fortbildungen oder Sprachkursen auftreten, die keinen formalen Abschluss darstellen. Diplome/Zeugnisse sind oft auf hochwertigem Papier gedruckt, enthalten offizielle Siegel oder Stempel der Institution und sind unterzeichnet von Rektoren, Dekanen oder Schulleitern. Bei ausländischen Abschlüssen können zusätzliche Felder wie ''Anerkennungsvermerk'' oder ''Umrechnung der Note'' relevant sein, die jedoch nicht im Standard-Schema enthalten sind.'
)
ON CONFLICT (id) DO UPDATE SET category=EXCLUDED.category, display_name=EXCLUDED.display_name, description=EXCLUDED.description, schema=EXCLUDED.schema, field_descriptions=EXCLUDED.field_descriptions, classify_keywords=EXCLUDED.classify_keywords, typical_senders=EXCLUDED.typical_senders, steuer_relevanz=EXCLUDED.steuer_relevanz, priority=EXCLUDED.priority, enabled=EXCLUDED.enabled, version=EXCLUDED.version, source=EXCLUDED.source, notes=EXCLUDED.notes;

INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'divorce_certificate',
    'I. Urkunden & Bescheinigungen',
    'Scheidungsurkunde',
    'Die Scheidungsurkunde ist ein amtliches Dokument, das die rechtskräftige Scheidung einer Ehe durch ein Familiengericht bescheinigt. Sie wird nach Abschluss des Scheidungsverfahrens ausgestellt und enthält wesentliche Daten wie die Namen der Ehepartner, das Scheidungsdatum und das zuständige Gericht. Im Gegensatz zu einer Trennungsvereinbarung oder einem Scheidungsbeschluss ist die Scheidungsurkunde das finale, rechtsverbindliche Dokument, das die Ehe offiziell auflöst.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "Scheidungsurkunde", "description": "Extraktionsschema f\u00fcr eine Scheidungsurkunde", "type": "object", "properties": {"ehepartner1": {"type": "object", "properties": {"vorname": {"type": "string"}, "nachname": {"type": "string"}, "geburtsname": {"type": "string", "description": "Geburtsname falls abweichend vom Nachnamen"}, "geburtsdatum": {"type": "string", "format": "date", "description": "YYYY-MM-DD"}, "geburtsort": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "description": "ISO 3166-1 alpha-2 L\u00e4ndercode"}}, "required": ["strasse", "plz", "ort", "land"]}}, "required": ["vorname", "nachname", "geburtsdatum"]}, "ehepartner2": {"type": "object", "properties": {"vorname": {"type": "string"}, "nachname": {"type": "string"}, "geburtsname": {"type": "string", "description": "Geburtsname falls abweichend vom Nachnamen"}, "geburtsdatum": {"type": "string", "format": "date", "description": "YYYY-MM-DD"}, "geburtsort": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "description": "ISO 3166-1 alpha-2 L\u00e4ndercode"}}, "required": ["strasse", "plz", "ort", "land"]}}, "required": ["vorname", "nachname", "geburtsdatum"]}, "scheidungsdatum": {"type": "string", "format": "date", "description": "YYYY-MM-DD"}, "gericht": {"type": "object", "properties": {"name": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "description": "ISO 3166-1 alpha-2 L\u00e4ndercode"}}, "required": ["name", "ort"]}, "aktenzeichen": {"type": "string"}, "rechtskraeftig_seit": {"type": "string", "format": "date", "description": "YYYY-MM-DD"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^[0-9]{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$", "nullable": true}, "mwst_satz": {"type": "string", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"], "additionalProperties": false}}, "required": ["ehepartner1", "ehepartner2", "scheidungsdatum", "gericht", "_meta"], "additionalProperties": false}',
    '"{\"ehepartner1\": \"Name (Vor- und Nachname) des ersten Ehepartners, wie im Dokument angegeben. Wichtig f\u00fcr die Identifikation der beteiligten Personen, z. B. f\u00fcr Unterhaltszahlungen oder Steuerklassenwechsel. Beispiel: ''Max Mustermann''.\", \"ehepartner2\": \"Name (Vor- und Nachname) des zweiten Ehepartners, wie im Dokument angegeben. Wichtig f\u00fcr die Identifikation der beteiligten Personen, z. B. f\u00fcr Unterhaltszahlungen oder Steuerklassenwechsel. Beispiel: ''Erika Mustermann''.\", \"scheidungsdatum\": \"Datum, an dem die Scheidung ausgesprochen wurde (Format: YYYY-MM-DD). Relevant f\u00fcr den Zeitpunkt der steuerlichen Auswirkungen (z. B. Wechsel der Steuerklasse). Beispiel: ''2023-10-15''.\", \"gericht\": \"Name des Familiengerichts, das die Scheidung ausgesprochen hat. Wichtig f\u00fcr die Zuordnung des Dokuments und ggf. f\u00fcr Nachfragen. Beispiel: ''Amtsgericht M\u00fcnchen, Familiengericht''.\", \"aktenzeichen\": \"Aktenzeichen des Scheidungsverfahrens, wie im Dokument angegeben. Dient als eindeutiger Identifikator f\u00fcr das Verfahren und kann f\u00fcr Nachweise ben\u00f6tigt werden. Beispiel: ''34 F 12345/22''.\"}"',
    'Scheidungsurkunde, Eheurkunde, rechtskräftige Scheidung, Familiengericht, Scheidungsbeschluss, Scheidungsdatum, Aktenzeichen, Ehepartner, Auflösung der Ehe, Gericht, Urteilsdatum, Rechtskraft, divorce decree, divorce certificate, family court, dissolution of marriage, final judgment, case number, spouse',
    'Familiengericht',
    '{"relevanz": "Eingeschränkt steuerrelevant", "hinweise": "Die Scheidungsurkunde selbst ist nicht direkt steuerrelevant, kann aber für die Steuererklärung in folgenden Kontexten wichtig sein: 1) Unterhaltszahlungen (§10 Abs. 1a EStG, Anlage U) – Nachweis der rechtskräftigen Scheidung ist Voraussetzung für die steuerliche Berücksichtigung von Unterhalt. 2) Änderung des Familienstands für die Steuerklasse (ab dem Folgemonat der Rechtskraft). 3) Bei Versorgungsausgleich (§10a EStG, Anlage Vorsorgeaufwand) – kann Auswirkungen auf die Altersvorsorge haben. 4) Nachweis für den Wechsel von gemeinsamer zu getrennter Veranlagung (§26 EStG)."}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
