INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'family_register',
    'I. Urkunden & Bescheinigungen',
    'Stammbuch/Familienbuch',
    'Das Stammbuch oder Familienbuch ist ein amtliches Dokument, das vom Standesamt ausgestellt wird und die wichtigsten familienrechtlichen Ereignisse wie Geburten, Heiraten und Todesfälle einer Familie dokumentiert. Es dient als Nachweis für den Familienstand und wird häufig für behördliche Angelegenheiten, wie z.B. die Beantragung von Ausweisdokumenten oder Erbscheinen, benötigt. Im Gegensatz zu einzelnen Geburts-, Heirats- oder Sterbeurkunden fasst das Stammbuch diese Ereignisse zentral zusammen und ist oft mit einer fortlaufenden Registernummer versehen.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "family_register", "description": "Schema f\u00fcr die Extraktion von Daten aus einem Familienbuch/Stammbuch", "type": "object", "properties": {"familienname": {"description": "Nachname der Familie", "type": "string"}, "eintraege": {"description": "Liste der Eintr\u00e4ge im Familienbuch", "type": "array", "items": {"type": "object", "properties": {"typ": {"description": "Typ des Eintrags (geburt, heirat, tod)", "type": "string", "enum": ["geburt", "heirat", "tod"]}, "datum": {"description": "Datum des Ereignisses (YYYY-MM-DD)", "type": "string", "format": "date"}, "person": {"description": "Betroffene Person", "type": "object", "properties": {"vorname": {"description": "Vorname der Person", "type": "string"}, "nachname": {"description": "Nachname der Person", "type": "string"}, "geburtsname": {"description": "Geburtsname der Person", "type": "string"}, "geburtsdatum": {"description": "Geburtsdatum der Person (YYYY-MM-DD)", "type": "string", "format": "date"}, "geburtsort": {"description": "Geburtsort der Person", "type": "string"}, "adresse": {"description": "Adresse der Person", "type": "object", "properties": {"strasse": {"description": "Stra\u00dfe und Hausnummer", "type": "string"}, "plz": {"description": "Postleitzahl", "type": "string"}, "ort": {"description": "Ort", "type": "string"}, "land": {"description": "Land (ISO 3166-1 alpha-2)", "type": "string"}}, "required": ["strasse", "plz", "ort"]}}, "required": ["vorname", "nachname"]}, "partner": {"description": "Partner bei Heiratseintrag", "type": "object", "properties": {"vorname": {"description": "Vorname des Partners", "type": "string"}, "nachname": {"description": "Nachname des Partners", "type": "string"}, "geburtsname": {"description": "Geburtsname des Partners", "type": "string"}, "geburtsdatum": {"description": "Geburtsdatum des Partners (YYYY-MM-DD)", "type": "string", "format": "date"}, "geburtsort": {"description": "Geburtsort des Partners", "type": "string"}}, "required": ["vorname", "nachname"]}, "eltern": {"description": "Eltern bei Geburtseintrag", "type": "array", "items": {"type": "object", "properties": {"vorname": {"description": "Vorname des Elternteils", "type": "string"}, "nachname": {"description": "Nachname des Elternteils", "type": "string"}, "geburtsname": {"description": "Geburtsname des Elternteils", "type": "string"}, "geburtsdatum": {"description": "Geburtsdatum des Elternteils (YYYY-MM-DD)", "type": "string", "format": "date"}}, "required": ["vorname", "nachname"]}}, "standesamt": {"description": "Standesamt, das den Eintrag vorgenommen hat", "type": "string"}, "registernummer": {"description": "Registernummer des Eintrags", "type": "string"}, "bemerkungen": {"description": "Weitere Bemerkungen zum Eintrag", "type": "string"}}, "required": ["typ", "datum"]}}, "standesamt": {"description": "Standesamt, das das Familienbuch f\u00fchrt", "type": "string"}, "registernummern": {"description": "Registernummern des Familienbuchs", "type": "object", "properties": {"hauptnummer": {"description": "Hauptregisternummer", "type": "string"}, "band": {"description": "Bandnummer", "type": "string"}, "seite": {"description": "Seitennummer", "type": "string"}}}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean", "enum": [false]}, "steuerrelevanz_hinweis": {"type": "string", "enum": [null]}, "steuer_kategorie": {"type": "string", "enum": [null]}, "steuerjahr": {"type": "string", "enum": [null]}, "mwst_ausgewiesen": {"type": "boolean", "enum": [false]}, "mwst_betrag": {"type": "string", "enum": [null]}, "mwst_satz": {"type": "string", "enum": [null]}, "aktenzeichen": {"type": "string", "enum": [null]}, "dokumenten_id": {"description": "Eindeutige ID des Dokuments", "type": "string"}}, "required": ["steuerrelevant", "steuerrelevanz_hinweis", "steuer_kategorie", "steuerjahr", "mwst_ausgewiesen", "mwst_betrag", "mwst_satz", "aktenzeichen"]}}, "required": ["_meta"]}',
    '"{\"familienname\": \"Der gemeinsame Familienname der Familie, unter dem die Eintr\u00e4ge im Stammbuch gef\u00fchrt werden. Beispiel: ''M\u00fcller''. Wichtig f\u00fcr die Identifikation der Familie, aber nicht direkt steuerrelevant.\", \"eintraege\": \"Eine Liste von Eintr\u00e4gen zu familienrechtlichen Ereignissen. Jeder Eintrag enth\u00e4lt Typ (Geburt, Heirat, Tod), Datum, Ort, Namen der beteiligten Personen und ggf. weitere Details wie Geburtsnamen oder Standesamt. Beispiel: {''typ'': ''Heirat'', ''datum'': ''15.05.2000'', ''ort'': ''Berlin'', ''personen'': [''Max Mustermann'', ''Erika Mustermann''], ''standesamt'': ''Standesamt Berlin-Mitte''}. Relevant f\u00fcr Nachweise im Erbfall oder bei Namens\u00e4nderungen, aber nicht direkt f\u00fcr die Steuererkl\u00e4rung.\", \"standesamt\": \"Das Standesamt, das das Stammbuch ausgestellt hat und die Eintr\u00e4ge verwaltet. Beispiel: ''Standesamt M\u00fcnchen''. Wichtig f\u00fcr die Authentifizierung des Dokuments, aber nicht steuerrelevant.\", \"registernummern\": \"Die vom Standesamt vergebenen Registernummern f\u00fcr die einzelnen Eintr\u00e4ge (z.B. Geburtsregister, Heiratsregister). Beispiel: {''geburt'': ''123/2000'', ''heirat'': ''456/2000''}. Dient der eindeutigen Identifikation der Eintr\u00e4ge, aber nicht steuerrelevant.\"}"',
    'Stammbuch, Familienbuch, Standesamt, Registernummer, Geburtsurkunde, Heiratsurkunde, Sterbeurkunde, Eintrag, Familienname, Eheschließung, Geburt, Tod, Familienstand, Urkundenregister, standesamtliche Eintragung, family register, civil registry, marriage certificate, birth certificate, death certificate',
    'Standesamt',
    NULL,
    0,
    1,
    1,
    'mistral_batch',
    'Häufig wird das Stammbuch mit einzelnen Urkunden wie Geburts- oder Heiratsurkunden verwechselt. Ein Stammbuch erkennt man daran, dass es mehrere familienrechtliche Ereignisse in einem Dokument zusammenfasst und oft eine fortlaufende Registernummer oder ein Siegel des Standesamts trägt. Sonderfälle: Bei Adoptionen oder Scheidungen können zusätzliche Einträge oder Vermerke im Stammbuch vorgenommen werden. Das Stammbuch ist kein Ersatz für beglaubigte Abschriften einzelner Urkunden, die für bestimmte behördliche Vorgänge benötigt werden.'
)
