INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'marriage_certificate',
    'I. Urkunden & Bescheinigungen',
    'Heiratsurkunde',
    'Die Heiratsurkunde ist eine amtliche Urkunde, die die Eheschließung zweier Personen dokumentiert. Sie wird vom Standesamt ausgestellt und ist für rechtliche Angelegenheiten wie Namensänderungen, Steuerklassenwechsel oder Erbschaftsfälle relevant. Im Gegensatz zur beglaubigten Abschrift aus dem Eheregister enthält die Heiratsurkunde nur die grundlegenden Daten der Eheschließung ohne zusätzliche Eintragungen wie Geburtsdaten der Eltern oder frühere Ehen.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "Marriage Certificate", "description": "Schema for extracting data from a marriage certificate", "type": "object", "properties": {"ehepartner1": {"type": "object", "properties": {"vorname": {"type": "string"}, "nachname": {"type": "string"}, "geburtsname": {"type": "string", "description": "Maiden name if applicable"}, "geburtsdatum": {"type": "string", "format": "date"}, "geburtsort": {"type": "string"}, "staatsangehoerigkeit": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort", "land"]}}, "required": ["vorname", "nachname", "geburtsdatum", "geburtsort", "staatsangehoerigkeit"]}, "ehepartner2": {"type": "object", "properties": {"vorname": {"type": "string"}, "nachname": {"type": "string"}, "geburtsname": {"type": "string", "description": "Maiden name if applicable"}, "geburtsdatum": {"type": "string", "format": "date"}, "geburtsort": {"type": "string"}, "staatsangehoerigkeit": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort", "land"]}}, "required": ["vorname", "nachname", "geburtsdatum", "geburtsort", "staatsangehoerigkeit"]}, "datum": {"type": "string", "format": "date", "description": "Date of marriage"}, "standesamt": {"type": "object", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort", "land"]}}, "required": ["name"]}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^[0-9]{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$", "nullable": true}, "mwst_satz": {"type": "string", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"], "additionalProperties": false}}, "required": ["ehepartner1", "ehepartner2", "datum", "standesamt", "_meta"], "additionalProperties": false}',
    '"{\"ehepartner1\": \"Name (Vor- und Nachname) des ersten Ehepartners, wie in der Urkunde angegeben. Wichtig f\u00fcr die Identifikation der steuerpflichtigen Personen und ggf. Namens\u00e4nderungen nach der Eheschlie\u00dfung. Beispiel: ''Max Mustermann''.\", \"ehepartner2\": \"Name (Vor- und Nachname) des zweiten Ehepartners, wie in der Urkunde angegeben. Relevant f\u00fcr die gemeinsame Veranlagung und steuerliche Ber\u00fccksichtigung des Partners. Beispiel: ''Maria Mustermann''.\", \"datum\": \"Datum der Eheschlie\u00dfung im Format TT.MM.JJJJ. Entscheidend f\u00fcr die steuerliche Ber\u00fccksichtigung im Jahr der Eheschlie\u00dfung (z. B. f\u00fcr den Splittingtarif oder Steuerklassenwechsel). Beispiel: ''15.08.2023''.\", \"standesamt\": \"Name und Ort des Standesamts, das die Eheschlie\u00dfung beurkundet hat. Wichtig f\u00fcr Nachweise bei Beh\u00f6rden oder im Ausland. Beispiel: ''Standesamt Berlin-Mitte''.\"}"',
    'Heiratsurkunde, Eheurkunde, Eheschließung, Trauung, Standesamt, verheiratet, Ehepartner, Ehepartnerin, Datum der Eheschließung, marriage certificate, civil marriage, registry office, spouse, wedding date, Familienstand, Namensänderung',
    'Standesamt',
    '{"paragraphen": "§ 26 EStG (Zusammenveranlagung), § 32a EStG (Splittingtarif), § 10 Abs. 1a EStG (Versorgungsausgleich)", "anlage": "Grundlage für Anlage N (gemeinsame Veranlagung), ggf. Anlage Vorsorgeaufwand (Krankenversicherung des Partners)", "hinweise": "Die Heiratsurkunde ist Voraussetzung für die Wahl der Steuerklassenkombination III/V oder IV/IV mit Faktor. Bei Zusammenveranlagung (§ 26 EStG) können Ehepartner vom Splittingtarif profitieren. Das Datum der Eheschließung ist entscheidend für die steuerliche Berücksichtigung im betreffenden Jahr."}',
    0,
    1,
    1,
    'mistral_batch',
    'Häufige Verwechslung mit der ''beglaubigten Abschrift aus dem Eheregister'', die zusätzliche Informationen wie Geburtsdaten der Eltern oder frühere Ehen enthält. Die Heiratsurkunde ist oft kürzer und enthält nur die wesentlichen Daten der Eheschließung. Bei internationalen Ehen kann die Urkunde mehrsprachig ausgestellt sein. Für steuerliche Zwecke ist das Datum der Eheschließung besonders relevant, da es den Zeitpunkt für die Anwendung des Splittingtarifs oder Steuerklassenwechsels bestimmt.'
)
ON CONFLICT (id) DO UPDATE SET category=EXCLUDED.category, display_name=EXCLUDED.display_name, description=EXCLUDED.description, schema=EXCLUDED.schema, field_descriptions=EXCLUDED.field_descriptions, classify_keywords=EXCLUDED.classify_keywords, typical_senders=EXCLUDED.typical_senders, steuer_relevanz=EXCLUDED.steuer_relevanz, priority=EXCLUDED.priority, enabled=EXCLUDED.enabled, version=EXCLUDED.version, source=EXCLUDED.source, notes=EXCLUDED.notes;

INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'vehicle_reg_part1',
    'I. Urkunden & Bescheinigungen',
    'KFZ-Schein',
    'Der KFZ-Schein (offiziell: Zulassungsbescheinigung Teil I) ist das Dokument, das die Zulassung eines Fahrzeugs in Deutschland nachweist. Er wird bei der Erstzulassung oder Ummeldung eines Fahrzeugs von der Zulassungsstelle ausgestellt und muss im Fahrzeug mitgeführt werden. Im Gegensatz zum KFZ-Brief (Zulassungsbescheinigung Teil II) enthält der Schein aktuelle Halterdaten und technische Details, aber keine Eigentumsnachweise.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "vehicle_reg_part1", "description": "KFZ-Schein (Fahrzeugschein Teil 1)", "type": "object", "properties": {"halter": {"type": "object", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "pattern": "^[A-Z]{2}$"}}, "required": ["strasse", "plz", "ort", "land"]}, "geburtsdatum": {"type": "string", "format": "date"}}, "required": ["name", "adresse"]}, "kennzeichen": {"type": "string"}, "fahrzeug": {"type": "object", "properties": {"hersteller": {"type": "string"}, "modell": {"type": "string"}, "fin": {"type": "string"}, "fahrzeugklasse": {"type": "string"}}, "required": ["hersteller", "modell", "fin"]}, "hsn_tsn": {"type": "object", "properties": {"hsn": {"type": "string"}, "tsn": {"type": "string"}}, "required": ["hsn", "tsn"]}, "erstzulassung": {"type": "string", "format": "date"}, "hu_faellig": {"type": "string", "format": "date"}, "hubraum": {"type": "integer"}, "leistung_kw": {"type": "number"}, "kraftstoff": {"type": "string"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^[0-9]{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$", "nullable": true}, "mwst_satz": {"type": "string", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}, "hubraum_einheit": {"type": "string", "description": "Einheit des Hubraums (z.B. ccm, cm3)"}}, "required": ["halter", "kennzeichen", "fahrzeug", "hsn_tsn", "erstzulassung", "hu_faellig", "hubraum", "leistung_kw", "kraftstoff", "_meta"]}',
    '"halter, kennzeichen, fahrzeug, hsn_tsn, erstzulassung, hu_faellig, hubraum, leistung_kw, kraftstoff"',
    'Zulassungsbescheinigung Teil I, KFZ-Schein, Fahrzeugschein, Halter, Kennzeichen, HSN, TSN, Erstzulassung, Hauptuntersuchung, HU, AU, Hubraum, Leistung kW, Kraftstoff, Zulassungsstelle, Fahrzeugdaten, Fahrzeugidentifikationsnummer, FIN, eVB-Nummer, Fahrzeugklasse, CO2-Emission, Fahrzeuggewicht, StVZO, §18 FZV',
    'Zulassungsstelle',
    '{"paragraphen": "§3 KraftStG (Kraftfahrzeugsteuer), §9 Abs. 1 Nr. 2 EStG (Dienstwagen), §4 Abs. 5 EStG (Betriebsausgaben)", "anlage": "Keine direkte Anlage, aber Daten relevant für: Anlage N (Werbungskosten bei Dienstwagen), Anlage EÜR (Betriebsausgaben), Kraftfahrzeugsteuererklärung"}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
