INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'vehicle_reg_part2',
    'I. Urkunden & Bescheinigungen',
    'KFZ-Brief',
    'Zulassungsbescheinigung Teil II (KFZ-Brief) — Eigentumsdokument eines Fahrzeugs mit FIN. Bleibt beim Eigentümer (oft bei finanzierender Bank). Nicht verwechseln mit Teil I (KFZ-Schein/vehicle_reg_part1).',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "vehicle_reg_part2", "description": "KFZ-Brief (Fahrzeugschein Teil II)", "type": "object", "properties": {"halter": {"type": "object", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort", "land"]}, "geburtsdatum": {"type": "string", "format": "date"}, "ausweisnummer": {"type": "string"}}, "required": ["name", "adresse"]}, "eigentuemer": {"type": "object", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort", "land"]}, "geburtsdatum": {"type": "string", "format": "date"}, "ausweisnummer": {"type": "string"}}, "required": ["name", "adresse"]}, "kennzeichen": {"type": "string"}, "fahrzeug": {"type": "object", "properties": {"hersteller": {"type": "string"}, "modell": {"type": "string"}, "fahrzeugtyp": {"type": "string"}, "farbe": {"type": "string"}}, "required": ["hersteller", "modell"]}, "fin": {"type": "string"}, "hsn_tsn": {"type": "object", "properties": {"hsn": {"type": "string"}, "tsn": {"type": "string"}}, "required": ["hsn", "tsn"]}, "erstzulassung": {"type": "string", "format": "date"}, "voreigentuemer": {"type": "array", "items": {"type": "object", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort", "land"]}, "besitzzeitraum": {"type": "object", "properties": {"von": {"type": "string", "format": "date"}, "bis": {"type": "string", "format": "date"}}, "required": ["von", "bis"]}}, "required": ["name", "adresse", "besitzzeitraum"]}}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^[0-9]{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$", "nullable": true}, "mwst_satz": {"type": "string", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}}, "required": ["halter", "eigentuemer", "kennzeichen", "fahrzeug", "fin", "hsn_tsn", "erstzulassung", "_meta"]}',
    '"{\"halter\": \"Aktueller Halter\", \"eigentuemer\": \"Eigent\u00fcmer\", \"kennzeichen\": \"Amtliches Kennzeichen\", \"fahrzeug\": \"Marke, Modell, Typ\", \"fin\": \"17-stellige FIN\", \"hsn_tsn\": \"Herstellerschl\u00fcssel + Typschl\u00fcssel\", \"erstzulassung\": \"YYYY-MM-DD\", \"voreigentuemer\": \"Array bisheriger Eigent\u00fcmer\"}"',
    'Zulassungsbescheinigung Teil II,Fahrzeugbrief,KFZ-Brief,Eigentümer,FIN,Fahrzeugidentifikationsnummer,HSN,TSN,Erstzulassung,Voreigentümer',
    'Zulassungsstelle',
    NULL,
    0,
    1,
    1,
    'mistral_batch',
    'Wertdokument — bei Verlust Aufgebotsverfahren nötig. Bei Finanzierung liegt Brief bei der Bank. Teil I = KFZ-Schein (mitführungspflichtig), Teil II = Brief (Eigentum).'
)
