INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'work_reference',
    'I. Urkunden & Bescheinigungen',
    'Arbeitszeugnis',
    'Ein Arbeitszeugnis ist eine vom Arbeitgeber ausgestellte Bescheinigung über die Dauer und Art der Beschäftigung eines Arbeitnehmers sowie eine Bewertung seiner Leistungen und seines Verhaltens. Es wird typischerweise bei Beendigung des Arbeitsverhältnisses oder auf Anfrage ausgestellt und dient als Referenz für zukünftige Arbeitgeber. Im Gegensatz zu einer einfachen Arbeitsbescheinigung (z. B. für das Arbeitsamt) enthält es eine qualitative Bewertung und ist oft ausführlicher formuliert.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "work_reference", "description": "Arbeitszeugnis", "type": "object", "properties": {"arbeitnehmer": {"type": "object", "properties": {"name": {"type": "string"}, "vorname": {"type": "string"}, "geburtsdatum": {"type": "string", "format": "date"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort"]}}, "required": ["name", "vorname"]}, "arbeitgeber": {"type": "object", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort"]}, "kontakt": {"type": "object", "properties": {"telefon": {"type": "string"}, "email": {"type": "string", "format": "email"}}}}, "required": ["name"]}, "position": {"type": "string"}, "zeitraum": {"type": "object", "properties": {"von": {"type": "string", "format": "date"}, "bis": {"type": "string", "format": "date"}}, "required": ["von", "bis"]}, "bewertung": {"type": "object", "properties": {"gesamtbewertung": {"type": "string"}, "leistungsbewertung": {"type": "string"}, "verhaltensbewertung": {"type": "string"}, "schlussformel": {"type": "string"}, "unterschrift": {"type": "object", "properties": {"name": {"type": "string"}, "position": {"type": "string"}, "datum": {"type": "string", "format": "date"}}}}}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean", "default": false}, "steuerrelevanz_hinweis": {"type": "string", "default": null}, "steuer_kategorie": {"type": "string", "enum": [null, "werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden"], "default": null}, "steuerjahr": {"type": "string", "pattern": "^[0-9]{4}$", "default": null}, "mwst_ausgewiesen": {"type": "boolean", "default": false}, "mwst_betrag": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$", "default": null}, "mwst_satz": {"type": "string", "default": null}, "aktenzeichen": {"type": "string", "default": null}, "dokumenten_id": {"type": "string", "default": null}}, "required": ["steuerrelevant"]}}, "required": ["arbeitnehmer", "arbeitgeber", "position", "zeitraum"]}',
    '"{\"arbeitnehmer\": \"Name und ggf. Adresse des Arbeitnehmers, f\u00fcr den das Zeugnis ausgestellt wird. Beispiel: ''Max Mustermann, Musterstra\u00dfe 1, 12345 Musterstadt''. Wichtig f\u00fcr die Zuordnung des Dokuments zum Arbeitnehmer, aber nicht direkt steuerrelevant.\", \"arbeitgeber\": \"Name und Anschrift des ausstellenden Arbeitgebers. Beispiel: ''Muster GmbH, Gesch\u00e4ftsf\u00fchrung, Musterweg 2, 12345 Musterstadt''. Dient der Identifikation des Ausstellers und der Authentizit\u00e4t des Dokuments.\", \"position\": \"Die genaue Berufsbezeichnung oder Position des Arbeitnehmers w\u00e4hrend des Besch\u00e4ftigungsverh\u00e4ltnisses. Beispiel: ''Softwareentwickler'', ''Vertriebsmitarbeiter''. Wichtig f\u00fcr die Einordnung der T\u00e4tigkeit, aber nicht steuerrelevant.\", \"zeitraum\": \"Der Beginn und das Ende des Besch\u00e4ftigungsverh\u00e4ltnisses im Format ''TT.MM.JJJJ \u2013 TT.MM.JJJJ'' oder ''von TT.MM.JJJJ bis TT.MM.JJJJ''. Beispiel: ''01.01.2020 \u2013 31.12.2022''. Relevant f\u00fcr die Dokumentation der Besch\u00e4ftigungsdauer, aber nicht f\u00fcr die Steuererkl\u00e4rung.\", \"bewertung\": \"Die qualitative Bewertung der Leistungen und des Verhaltens des Arbeitnehmers, oft in standardisierten Formulierungen. Beispiel: ''Herr Mustermann hat die ihm \u00fcbertragenen Aufgaben stets zu unserer vollsten Zufriedenheit erledigt.'' Wichtig f\u00fcr zuk\u00fcnftige Bewerbungen, aber nicht steuerrelevant.\"}"',
    'Arbeitszeugnis, Zeugnis, Referenz, Arbeitsverhältnis, Beschäftigungsdauer, Leistung, Verhalten, Arbeitgeber, Arbeitnehmer, Position, Bewertung, Schlussformel, wohlwollend, qualifiziertes Zeugnis, einfaches Zeugnis, employment reference, job reference, performance evaluation, employer, employee, period of employment',
    'Arbeitgeber',
    NULL,
    0,
    1,
    1,
    'mistral_batch',
    'Häufige Verwechslungen: Arbeitszeugnisse werden oft mit Arbeitsbescheinigungen (z. B. für das Arbeitsamt) oder Zwischenzeugnissen verwechselt. Ein Arbeitszeugnis enthält immer eine Bewertung, während eine Arbeitsbescheinigung nur Fakten wie Beschäftigungsdauer und Position auflistet. Achte auf typische Formulierungen wie ''stets zu unserer vollsten Zufriedenheit'' oder ''hat sich bemüht'', die auf die Bewertung hinweisen. Sonderfall: Ein ''einfaches Zeugnis'' enthält keine Bewertung, sondern nur Fakten – dies ist jedoch selten und sollte nicht mit einer Arbeitsbescheinigung verwechselt werden.'
)
ON CONFLICT (id) DO UPDATE SET category=EXCLUDED.category, display_name=EXCLUDED.display_name, description=EXCLUDED.description, schema=EXCLUDED.schema, field_descriptions=EXCLUDED.field_descriptions, classify_keywords=EXCLUDED.classify_keywords, typical_senders=EXCLUDED.typical_senders, steuer_relevanz=EXCLUDED.steuer_relevanz, priority=EXCLUDED.priority, enabled=EXCLUDED.enabled, version=EXCLUDED.version, source=EXCLUDED.source, notes=EXCLUDED.notes;

INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'accident_report',
    'J. Protokolle & Berichte',
    'Unfallbericht',
    'Ein Unfallbericht dokumentiert die Umstände eines Verkehrsunfalls, inklusive beteiligter Personen, Fahrzeuge, Schadensdetails und Zeugenaussagen. Er wird typischerweise von der Polizei, Versicherungen oder Unfallbeteiligten erstellt und dient als Grundlage für Schadensregulierung und rechtliche Klärung. Im Gegensatz zu reinen Schadensmeldungen enthält ein Unfallbericht detaillierte Angaben zum Hergang und oft polizeiliche Feststellungen.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "accident_report", "description": "Unfallbericht", "type": "object", "properties": {"unfalldatum": {"description": "Datum des Unfalls im Format YYYY-MM-DD", "type": "string", "format": "date"}, "unfallort": {"description": "Adresse des Unfallorts", "type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort"]}, "beteiligte": {"description": "Liste der Unfallbeteiligten", "type": "array", "items": {"type": "object", "properties": {"name": {"type": "string"}, "kennzeichen": {"type": "string"}, "versicherung": {"type": "string"}, "schadennummer": {"type": "string"}}, "required": ["name"]}}, "unfallhergang": {"description": "Beschreibung des Unfallhergangs", "type": "string"}, "zeugen": {"description": "Liste der Zeugen", "type": "array", "items": {"type": "object", "properties": {"name": {"type": "string"}, "kontakt": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}}}, "required": ["name"]}}, "polizei_aktenzeichen": {"description": "Aktenzeichen der Polizei", "type": "string"}, "skizze_vorhanden": {"description": "Gibt an, ob eine Unfallskizze vorhanden ist", "type": "boolean"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^[0-9]{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$", "nullable": true}, "mwst_satz": {"type": "string", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}}, "required": ["unfalldatum", "_meta"]}',
    '"{\"unfalldatum\": \"Datum und ggf. Uhrzeit des Unfalls im Format TT.MM.JJJJ oder TT.MM.JJJJ HH:MM. Wichtig f\u00fcr zeitliche Einordnung und Fristen bei Schadensmeldungen.\", \"unfallort\": \"Genauer Ort des Unfalls, inklusive Stra\u00dfe, Hausnummer, Kreuzung oder Kilometerangabe bei Autobahnen. Beispiel: ''Bundesstra\u00dfe 12, km 45,8 bei M\u00fcnchen''. Wichtig f\u00fcr \u00f6rtliche Zuordnung und ggf. polizeiliche Ermittlungen.\", \"beteiligte\": \"Liste der Unfallbeteiligten mit folgenden Unterfeldern: name (vollst\u00e4ndiger Name der Person), kennzeichen (Fahrzeugkennzeichen, z.B. ''M-AB 123''), versicherung (Name der Haftpflichtversicherung, z.B. ''Allianz''), schadennummer (von der Versicherung vergebene Nummer, z.B. ''S-2023-45678''). Wichtig f\u00fcr Schadensregulierung und Zuordnung der Haftung.\", \"unfallhergang\": \"Detaillierte Beschreibung des Unfallhergangs in Flie\u00dftext, oft mit Angaben zu Wetter, Stra\u00dfenverh\u00e4ltnissen, Geschwindigkeit und Schuldfrage. Beispiel: ''Fahrzeug A bog von der Hauptstra\u00dfe ab, ohne Vorfahrt von Fahrzeug B zu gew\u00e4hren. Kollision erfolgte an der Fahrerseite von Fahrzeug B.''. Wichtig f\u00fcr rechtliche Bewertung und Versicherungsanspr\u00fcche.\", \"zeugen\": \"Liste der Zeugen mit Namen und Kontaktdaten (Adresse, Telefonnummer). Beispiel: [{''name'': ''Max Mustermann'', ''adresse'': ''Musterstra\u00dfe 1, 12345 Berlin'', ''telefon'': ''0123/456789''}]. Wichtig f\u00fcr Beweissicherung und sp\u00e4tere Kl\u00e4rung des Unfallhergangs.\", \"polizei_aktenzeichen\": \"Von der Polizei vergebenes Aktenzeichen, falls diese am Unfallort war. Format variiert je nach Bundesland, z.B. ''1234/2023'' oder ''PP M\u00fcnchen 2023/45678''. Wichtig f\u00fcr Anfragen bei der Polizei und rechtliche Verfahren.\", \"skizze_vorhanden\": \"Boolescher Wert (true/false), ob dem Bericht eine Unfallskizze beigef\u00fcgt ist. Wichtig f\u00fcr visuelle Dokumentation des Unfallhergangs und Beweissicherung.\"}"',
    'Unfallbericht, Unfallprotokoll, Verkehrsunfall, Unfallhergang, Beteiligte, Zeugen, Kennzeichen, Versicherung, Schadennummer, Polizei, Aktenzeichen, Unfallskizze, damage report, accident report, police report, witness statement, license plate, insurance number, claim number',
    'Polizei, Versicherung, Beteiligte',
    NULL,
    0,
    1,
    1,
    'mistral_batch',
    'Häufige Verwechslungen: Unfallberichte werden oft mit reinen Schadensmeldungen (z.B. an die Versicherung) verwechselt, die weniger detailliert sind. Ein Unfallbericht enthält typischerweise polizeiliche Feststellungen oder detaillierte Angaben zum Hergang. Sonderfälle: Bei Unfällen mit Personenschaden oder hohem Sachschaden ist fast immer ein polizeilicher Unfallbericht vorhanden. Tipp: Achten Sie auf das Vorhandensein eines Polizei-Aktenzeichens oder einer detaillierten Beschreibung des Unfallhergangs, um den Bericht von einer einfachen Schadensmeldung zu unterscheiden.'
)
ON CONFLICT (id) DO UPDATE SET category=EXCLUDED.category, display_name=EXCLUDED.display_name, description=EXCLUDED.description, schema=EXCLUDED.schema, field_descriptions=EXCLUDED.field_descriptions, classify_keywords=EXCLUDED.classify_keywords, typical_senders=EXCLUDED.typical_senders, steuer_relevanz=EXCLUDED.steuer_relevanz, priority=EXCLUDED.priority, enabled=EXCLUDED.enabled, version=EXCLUDED.version, source=EXCLUDED.source, notes=EXCLUDED.notes;

INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'expert_opinion',
    'J. Protokolle & Berichte',
    'Gutachten',
    'Ein Gutachten ist eine fachliche Stellungnahme oder Bewertung durch einen Sachverständigen oder Gutachter, die im Auftrag einer Privatperson oder Institution erstellt wird. Es kommt typischerweise bei Schadensfällen, Wertbestimmungen (z.B. Immobilien, Kunst), medizinischen oder technischen Fragestellungen vor. Im Gegensatz zu einfachen Berichten oder Protokollen enthält ein Gutachten eine fundierte Analyse, Schlussfolgerungen und oft eine rechtliche oder finanzielle Bewertung.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "expert_opinion", "description": "Schema für Gutachten-Dokumente", "type": "object", "properties": {"auftraggeber": {"type": "object", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort"]}, "telefon": {"type": "string"}, "email": {"type": "string", "format": "email"}}, "required": ["name"]}, "gutachter": {"type": "object", "properties": {"name": {"type": "string"}, "titel": {"type": "string"}, "organisation": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort"]}, "telefon": {"type": "string"}, "email": {"type": "string", "format": "email"}}, "required": ["name"]}, "gegenstand": {"type": "string"}, "ergebnis": {"type": "string"}, "datum": {"type": "string", "format": "date"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^[0-9]{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$", "nullable": true}, "mwst_satz": {"type": "string", "pattern": "^[0-9]+(\\.[0-9]{1,2})?$", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}, "feststellungen": {"type": "array", "description": "Wesentliche Feststellungen und Bewertungen des Gutachtens", "items": {"type": "object", "properties": {"thema": {"type": "string"}, "feststellung": {"type": "string"}, "bewertung": {"type": "string"}}}}, "objekt_adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "default": "DE"}}, "description": "Begutachtetes Objekt/Liegenschaft"}}, "required": ["gegenstand", "datum"]}',
    '"{\"auftraggeber\": \"Name und Adresse der Person oder Institution, die das Gutachten in Auftrag gegeben hat. Wichtig f\u00fcr die steuerliche Zuordnung (z.B. ob das Gutachten beruflich oder privat veranlasst ist). Format: String, Beispiel: ''Max Mustermann, Musterstra\u00dfe 1, 12345 Berlin''.\", \"gutachter\": \"Name, Berufsbezeichnung und Kontaktdaten des Sachverst\u00e4ndigen oder Gutachters. Relevant f\u00fcr die Glaubw\u00fcrdigkeit des Gutachtens und ggf. f\u00fcr die steuerliche Anerkennung (z.B. bei medizinischen Gutachten). Format: String, Beispiel: ''Dr. Anna Schmidt, \u00f6ffentlich bestellte und vereidigte Sachverst\u00e4ndige f\u00fcr Bausch\u00e4den''.\", \"gegenstand\": \"Kurze Beschreibung des Objekts, der Situation oder der Fragestellung, die begutachtet wurde. Wichtig f\u00fcr die steuerliche Einordnung (z.B. ob es sich um ein berufliches, privates oder medizinisches Gutachten handelt). Format: String, Beispiel: ''Bausch\u00e4den am Einfamilienhaus Musterstra\u00dfe 1, 12345 Berlin''.\", \"ergebnis\": \"Zusammenfassung der wichtigsten Erkenntnisse, Schlussfolgerungen und Empfehlungen des Gutachters. Kann f\u00fcr die steuerliche Bewertung relevant sein (z.B. H\u00f6he eines Schadens oder Wertminderung). Format: String, Beispiel: ''Es liegt ein erheblicher Schimmelbefall vor, der auf undichte Fenster zur\u00fcckzuf\u00fchren ist. Die Sanierungskosten werden auf 15.000 \u20ac gesch\u00e4tzt.''.\"}"',
    'Gutachten, Sachverständiger, Expertise, Bewertung, Schadensgutachten, Wertgutachten, medizinisches Gutachten, technisches Gutachten, Auftraggeber, Gutachter, Gegenstand, Ergebnis, Schlussfolgerung, Analyse, Beurteilung, assessment, expert opinion, valuation, damage report, appraisal',
    'Gutachter, Sachverständige',
    '{"relevanz": "§9 EStG (Werbungskosten), §33 EStG (außergewöhnliche Belastungen), §35a EStG (haushaltsnahe Dienstleistungen), §10 EStG (Vorsorgeaufwendungen - z.B. medizinische Gutachten)", "anlage": "Je nach Kontext: Anlage N (Werbungskosten), Anlage Vorsorgeaufwand (medizinische Gutachten), oder direkte Berücksichtigung in der Haupterklärung (z.B. bei außergewöhnlichen Belastungen).", "absetzbar": {"allgemein": "Kosten für Gutachten können als Werbungskosten (z.B. bei beruflicher Nutzung) oder außergewöhnliche Belastungen (z.B. medizinische Gutachten) abgesetzt werden, sofern sie nicht von Dritten (z.B. Versicherung) erstattet werden.", "grenzen": {"§33 EStG": "Nur der Teil, der die zumutbare Belastung übersteigt.", "§35a EStG": "Bis zu 20% der Kosten (max. 4.000 € pro Jahr) für haushaltsnahe Dienstleistungen, wenn das Gutachten im Zusammenhang mit der Haushaltsführung steht (z.B. Schimmelgutachten)."}}}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
