INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'inspection_protocol',
    'J. Protokolle & Berichte',
    'Prüfprotokoll',
    'Ein Prüfprotokoll dokumentiert die Ergebnisse einer technischen oder sicherheitstechnischen Überprüfung von Geräten, Anlagen oder Immobilien. Es wird typischerweise von Gutachtern, Handwerkern oder Prüfern nach einer Inspektion erstellt und enthält detaillierte Prüfpunkte, festgestellte Mängel sowie das Gesamtergebnis. Im Gegensatz zu einem Gutachten oder Bericht liegt der Fokus auf standardisierten Prüfkriterien und einer klaren Bewertung (z. B. ''bestanden''/''nicht bestanden'').',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "Inspection Protocol", "description": "Schema for inspection protocol documents", "type": "object", "properties": {"gegenstand": {"type": "string", "description": "Object or area that was inspected"}, "pruefer": {"type": "string", "description": "Name of the inspector"}, "datum": {"type": "string", "format": "date", "description": "Date of inspection in YYYY-MM-DD format"}, "pruefpunkte": {"type": "array", "items": {"type": "object", "properties": {"punkt": {"type": "string", "description": "Specific inspection point"}, "beschreibung": {"type": "string", "description": "Description of the inspection point"}, "status": {"type": "string", "description": "Status of the inspection point (e.g., ''ok'', ''defekt'')"}}, "required": ["punkt"]}, "description": "List of inspection points"}, "ergebnis": {"type": "string", "description": "Overall result of the inspection"}, "maengel": {"type": "array", "items": {"type": "object", "properties": {"mangel": {"type": "string", "description": "Description of the defect"}, "schweregrad": {"type": "string", "description": "Severity of the defect (e.g., ''leicht'', ''mittel'', ''schwer'')"}, "massnahme": {"type": "string", "description": "Recommended action to resolve the defect"}}, "required": ["mangel"]}, "description": "List of defects found during inspection"}, "naechste_pruefung": {"type": "string", "format": "date", "description": "Date of next inspection in YYYY-MM-DD format"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^[0-9]{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$", "nullable": true}, "mwst_satz": {"type": "string", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}, "objekt_adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "default": "DE"}}, "description": "Pruefobjekt/Liegenschaft"}}, "required": ["gegenstand", "pruefer", "datum", "ergebnis"]}',
    '"gegenstand, pruefer, datum, pruefpunkte[], ergebnis, maengel[], naechste_pruefung"',
    'Prüfprotokoll, Inspektionsbericht, Prüfbericht, Gutachten, Prüfpunkte, Mängel, Ergebnis, nächste Prüfung, Prüfdatum, Prüfer, Gegenstand, Abnahmeprotokoll, Sicherheitsprüfung, TÜV, DEKRA, Elektroprüfung, Brandschutzprüfung, inspection report, defects, test points, compliance check, maintenance log',
    'Prüfer, Gutachter, Handwerker',
    '{"relevanz": "teilweise", "details": {"§35a EStG": {"voraussetzung": "Handwerkerleistungen für Renovierungs-, Erhaltungs- oder Modernisierungsmaßnahmen im Haushalt (z. B. Prüfung von Heizungsanlagen, Elektroinstallationen).", "anlage": "Anlage Haushaltsnahe Dienstleistungen (N)", "betrag": "20% der Arbeitskosten (max. 1.200 € pro Jahr), sofern Rechnung und Zahlung per Überweisung vorliegen."}, "§9 EStG (Werbungskosten)": {"voraussetzung": "Prüfprotokolle für beruflich genutzte Gegenstände (z. B. Homeoffice-Equipment, Firmenwagen).", "anlage": "Anlage N (Zeile 44 ff.)", "hinweis": "Nur absetzbar, wenn berufliche Nutzung nachgewiesen wird (z. B. durch Arbeitsvertrag oder Nutzungsnachweis)."}, "§10f EStG (Denkmalschutz)": {"voraussetzung": "Prüfprotokolle im Rahmen von Sanierungsmaßnahmen an denkmalgeschützten Gebäuden."}}}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
ON CONFLICT (id) DO UPDATE SET category=EXCLUDED.category, display_name=EXCLUDED.display_name, description=EXCLUDED.description, schema=EXCLUDED.schema, field_descriptions=EXCLUDED.field_descriptions, classify_keywords=EXCLUDED.classify_keywords, typical_senders=EXCLUDED.typical_senders, steuer_relevanz=EXCLUDED.steuer_relevanz, priority=EXCLUDED.priority, enabled=EXCLUDED.enabled, version=EXCLUDED.version, source=EXCLUDED.source, notes=EXCLUDED.notes;

INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'protocol',
    'J. Protokolle & Berichte',
    'Protokoll',
    'Ein Protokoll dokumentiert den Ablauf und die Ergebnisse von Sitzungen, Versammlungen oder Besprechungen, typischerweise in Vereinen, Eigentümerversammlungen oder behördlichen Gremien. Es unterscheidet sich von anderen Dokumenten wie Berichten oder Beschlussvorlagen durch seine strukturierte Wiedergabe von Teilnehmern, Tagesordnungspunkten (TOPs) und gefassten Beschlüssen, oft mit formalem Charakter und rechtlicher Relevanz (z. B. für Nachweispflichten).',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "protocol", "description": "Protokoll-Dokument", "type": "object", "properties": {"datum": {"description": "Datum des Protokolls im Format YYYY-MM-DD", "type": "string", "format": "date"}, "ort": {"description": "Ort der Veranstaltung", "type": "string"}, "teilnehmer": {"description": "Liste der Teilnehmer", "type": "array", "items": {"type": "object", "properties": {"name": {"description": "Name des Teilnehmers", "type": "string"}, "rolle": {"description": "Rolle des Teilnehmers", "type": "string"}, "anwesend": {"description": "Anwesenheit des Teilnehmers", "type": "boolean"}}, "required": ["name"]}}, "tagesordnung": {"description": "Liste der Tagesordnungspunkte", "type": "array", "items": {"type": "object", "properties": {"punkt": {"description": "Tagesordnungspunkt", "type": "string"}, "beschreibung": {"description": "Beschreibung des Tagesordnungspunkts", "type": "string"}}, "required": ["punkt"]}}, "beschluesse": {"description": "Liste der Beschl\u00fcsse", "type": "array", "items": {"type": "object", "properties": {"beschluss": {"description": "Beschlusstext", "type": "string"}, "abstimmungsergebnis": {"description": "Ergebnis der Abstimmung", "type": "string"}, "verantwortlicher": {"description": "Verantwortlicher f\u00fcr die Umsetzung", "type": "string"}}, "required": ["beschluss"]}}, "protokollant": {"description": "Name des Protokollanten", "type": "string"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^[0-9]{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$", "nullable": true}, "mwst_satz": {"type": "string", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}}, "required": ["datum", "_meta"]}',
    '"{\"datum\": \"Datum der Sitzung oder Versammlung im Format TT.MM.JJJJ oder JJJJ-MM-TT. Wichtig f\u00fcr die chronologische Einordnung und ggf. Nachweispflichten (z. B. bei Vereinen oder Eigent\u00fcmergemeinschaften). Beispiel: ''15.05.2024''.\", \"ort\": \"Ort der Veranstaltung, oft mit Adresse oder Raumangabe. Beispiel: ''B\u00fcrgerzentrum, Raum 3, Musterstra\u00dfe 1, 12345 Berlin''. Relevant f\u00fcr die Nachvollziehbarkeit des Sitzungsortes.\", \"teilnehmer[]\": \"Liste der anwesenden Personen, oft mit Namen, ggf. Funktion (z. B. ''Vorsitzender'', ''Schriftf\u00fchrer'') oder Vertretungsverh\u00e4ltnissen. Beispiel: [''Max Mustermann (Vorsitzender)'', ''Anna Schmidt (Protokollantin)'']. Wichtig f\u00fcr die Legitimation von Beschl\u00fcssen.\", \"tagesordnung[]\": \"Strukturierte Auflistung der Tagesordnungspunkte (TOPs) mit Titel und ggf. Referenten oder Zeitangaben. Beispiel: [{''titel'': ''Genehmigung des letzten Protokolls'', ''referent'': ''Vorsitzender''}, {''titel'': ''Neuwahlen des Vorstands''}]. Dient der Nachvollziehbarkeit des Sitzungsablaufs.\", \"beschluesse[]\": \"Dokumentation der gefassten Beschl\u00fcsse mit Inhalt, Abstimmungsergebnis (z. B. ''einstimmig'', ''Mehrheit: 12/2'') und ggf. Verantwortlichen f\u00fcr die Umsetzung. Beispiel: [{''inhalt'': ''Der Mitgliedsbeitrag wird auf 60\u20ac j\u00e4hrlich erh\u00f6ht.'', ''ergebnis'': ''Mehrheit: 15/2'', ''verantwortlich'': ''Kassenwart''}]. Rechtlich relevant f\u00fcr die Umsetzung und Nachweispflichten.\", \"protokollant\": \"Name der Person, die das Protokoll erstellt hat. Beispiel: ''Anna Schmidt''. Wichtig f\u00fcr die Zuordnung der Verantwortlichkeit f\u00fcr die Richtigkeit des Protokolls.\"}"',
    'Protokoll, Niederschrift, Versammlungsprotokoll, Sitzungsprotokoll, Teilnehmerliste, Tagesordnung, TOP, Beschluss, Beschlussfassung, Abstimmung, Protokollant, Ort, Datum, minutes, meeting minutes, resolution, agenda, attendance, chairman, secretary, Eigentümerversammlung, Mitgliederversammlung, Vereinssitzung, behördliche Sitzung',
    'Vereine, Eigentümerversammlungen, Behörden',
    NULL,
    0,
    1,
    1,
    'mistral_batch',
    'Häufige Verwechslungen: Protokolle werden oft mit *Berichten* (z. B. Tätigkeitsberichten) oder *Einladungen* verwechselt, die jedoch keine Beschlüsse oder Teilnehmerlisten enthalten. Sonderfälle: Bei Eigentümerversammlungen können Protokolle rechtliche Bindungswirkung entfalten (z. B. für Beschlüsse zur Hausgeldabrechnung). Bei Vereinen sind Protokolle oft satzungsrelevant (z. B. für Vorstandswahlen). Tipp: Achte auf formale Merkmale wie ''TOP'', ''Beschluss'', ''Abstimmung'' oder ''Protokollant'' zur Erkennung.'
)
ON CONFLICT (id) DO UPDATE SET category=EXCLUDED.category, display_name=EXCLUDED.display_name, description=EXCLUDED.description, schema=EXCLUDED.schema, field_descriptions=EXCLUDED.field_descriptions, classify_keywords=EXCLUDED.classify_keywords, typical_senders=EXCLUDED.typical_senders, steuer_relevanz=EXCLUDED.steuer_relevanz, priority=EXCLUDED.priority, enabled=EXCLUDED.enabled, version=EXCLUDED.version, source=EXCLUDED.source, notes=EXCLUDED.notes;

INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'tuev_report',
    'J. Protokolle & Berichte',
    'TÜV-Bescheid/HU-Bericht',
    'Der TÜV-Bescheid oder HU-Bericht (Hauptuntersuchung) dokumentiert das Ergebnis der gesetzlich vorgeschriebenen Fahrzeugprüfung in Deutschland. Er wird nach jeder Hauptuntersuchung (alle 2 Jahre) oder nach einer Nachprüfung ausgestellt und enthält das Prüfdatum, das nächste Fälligkeitsdatum sowie eventuelle Mängel. Im Gegensatz zu Werkstattrechnungen oder Gutachten bezieht sich dieses Dokument ausschließlich auf die Verkehrssicherheit und Umweltverträglichkeit des Fahrzeugs gemäß §29 StVZO.',
    '{"type": "object", "properties": {"fahrzeug": {"type": "object", "properties": {"hersteller": {"type": "string"}, "modell": {"type": "string"}, "erstzulassung": {"type": "string", "format": "date"}, "fahrzeugtyp": {"type": "string"}, "kraftstoffart": {"type": "string"}}, "required": ["hersteller", "modell"]}, "kennzeichen": {"type": "string"}, "fin": {"type": "string"}, "pruefer": {"type": "object", "properties": {"name": {"type": "string"}, "pruefstelle": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort"]}}, "required": ["name", "pruefstelle"]}, "datum": {"type": "string", "format": "date"}, "naechste_hu": {"type": "string", "format": "date"}, "ergebnis": {"type": "string", "enum": ["bestanden", "nicht_bestanden"]}, "maengel": {"type": "array", "items": {"type": "object", "properties": {"beschreibung": {"type": "string"}, "schweregrad": {"type": "string", "enum": ["gering", "erheblich", "gefährlich"]}, "massnahme": {"type": "string"}}, "required": ["beschreibung", "schweregrad"]}}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean", "const": false}, "steuerrelevanz_hinweis": {"type": "string", "const": null}, "steuer_kategorie": {"type": "string", "const": null}, "steuerjahr": {"type": "string", "const": null}, "mwst_ausgewiesen": {"type": "boolean", "const": false}, "mwst_betrag": {"type": "string", "const": null}, "mwst_satz": {"type": "string", "const": null}, "aktenzeichen": {"type": "string", "const": null}, "dokumenten_id": {"type": "string"}}, "required": ["steuerrelevant", "steuerrelevanz_hinweis", "steuer_kategorie", "steuerjahr", "mwst_ausgewiesen", "mwst_betrag", "mwst_satz", "aktenzeichen"]}, "objekt_adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "default": "DE"}}, "description": "Prueffort/Werkstatt"}}, "required": ["fahrzeug", "kennzeichen", "datum", "naechste_hu", "ergebnis", "_meta"]}',
    '"{\"fahrzeug\": \"Modellbezeichnung des Fahrzeugs, z.B. ''VW Golf 1.6 TDI''. Wird zur eindeutigen Zuordnung des Berichts zum Fahrzeug ben\u00f6tigt.\", \"kennzeichen\": \"Aktuelles amtliches Kennzeichen des Fahrzeugs, z.B. ''M-AB 123''. Wichtig f\u00fcr die Identifikation des Fahrzeugs im Dokumentenmanagement.\", \"fin\": \"Fahrzeug-Identifizierungsnummer (17-stellig), z.B. ''WVWZZZ1JZ3W123456''. Eindeutige Identifikation des Fahrzeugs, relevant f\u00fcr Historie und Zuordnung.\", \"pruefer\": \"Name oder Kennnummer des Pr\u00fcfers/der Pr\u00fcfstelle, z.B. ''T\u00dcV S\u00fcd, Pr\u00fcfstelle M\u00fcnchen''. Dient der Nachverfolgbarkeit der Pr\u00fcfung.\", \"datum\": \"Datum der Hauptuntersuchung im Format TT.MM.JJJJ, z.B. ''15.05.2023''. Wichtig f\u00fcr die Fristen\u00fcberwachung der n\u00e4chsten HU.\", \"naechste_hu\": \"Datum der n\u00e4chsten f\u00e4lligen Hauptuntersuchung im Format TT.MM.JJJJ, z.B. ''15.05.2025''. Entscheidend f\u00fcr die Einhaltung gesetzlicher Fristen (\u00a729 StVZO).\", \"ergebnis\": \"Pr\u00fcfergebnis, entweder ''bestanden'' oder ''nicht_bestanden''. Bestimmt, ob das Fahrzeug weiter zugelassen bleibt oder Nachpr\u00fcfungen erforderlich sind.\", \"maengel\": \"Liste der festgestellten M\u00e4ngel mit Beschreibung und Klassifizierung (z.B. ''gering'', ''erheblich'', ''verkehrsunsicher''). Wichtig f\u00fcr Reparaturma\u00dfnahmen und Nachpr\u00fcfungen. Beispiel: [{''beschreibung'': ''Bremsbel\u00e4ge abgenutzt'', ''schweregrad'': ''erheblich''}]\"}"',
    'Hauptuntersuchung, HU, TÜV, DEKRA, GTÜ, Plakette, Prüfbericht, Fahrzeugprüfung, Mängel, Verkehrssicherheit, Abgasuntersuchung, AU, §29 StVZO, next inspection, defects, vehicle inspection, emission test, Prüfplakette, Nachprüfung, bestanden, nicht bestanden',
    'TÜV, DEKRA, GTÜ',
    NULL,
    0,
    1,
    1,
    'mistral_batch',
    'Häufige Verwechslung mit der Abgasuntersuchung (AU), die oft zeitgleich durchgeführt wird, aber ein separates Dokument darstellt. Der HU-Bericht enthält keine Kostenangaben – diese finden sich auf der separaten Rechnung. Bei ''nicht_bestanden'' ist eine Nachprüfung innerhalb einer Frist (meist 1 Monat) erforderlich. Tipp: Das Dokument ist oft mit einer Prüfplakette (Farbe kodiert das Jahr der nächsten HU) verbunden, die auf dem Kennzeichen angebracht wird.'
)
ON CONFLICT (id) DO UPDATE SET category=EXCLUDED.category, display_name=EXCLUDED.display_name, description=EXCLUDED.description, schema=EXCLUDED.schema, field_descriptions=EXCLUDED.field_descriptions, classify_keywords=EXCLUDED.classify_keywords, typical_senders=EXCLUDED.typical_senders, steuer_relevanz=EXCLUDED.steuer_relevanz, priority=EXCLUDED.priority, enabled=EXCLUDED.enabled, version=EXCLUDED.version, source=EXCLUDED.source, notes=EXCLUDED.notes;

INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'vehicle_deregistration',
    'J. Protokolle & Berichte',
    'KFZ-Abmeldung',
    'Die KFZ-Abmeldung ist ein amtliches Dokument, das die Stilllegung eines Fahrzeugs bei der Zulassungsstelle bestätigt. Sie wird benötigt, wenn ein Fahrzeug verkauft, verschrottet oder außer Betrieb genommen wird. Im Gegensatz zur Ummeldung oder Neuzulassung dokumentiert die Abmeldung das Ende der Zulassung und ist Voraussetzung für die Beendigung von Versicherungs- und Steuerpflichten.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "vehicle_deregistration", "description": "KFZ-Abmeldung Dokumenten-Extraktions-Template", "type": "object", "properties": {"halter": {"type": "object", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort", "land"]}, "geburtsdatum": {"type": "string", "format": "date"}}, "required": ["name", "adresse"]}, "kennzeichen": {"type": "string"}, "fahrzeug": {"type": "object", "properties": {"hersteller": {"type": "string"}, "modell": {"type": "string"}, "erstzulassung": {"type": "string", "format": "date"}, "fahrzeugtyp": {"type": "string"}, "kraftstoffart": {"type": "string"}}, "required": ["hersteller", "modell"]}, "fin": {"type": "string"}, "abmeldedatum": {"type": "string", "format": "date"}, "verwertungsnachweis": {"type": "boolean"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^[0-9]{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$", "nullable": true}, "mwst_satz": {"type": "string", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}}, "required": ["halter", "kennzeichen", "abmeldedatum"]}',
    '"{\"halter\": \"Name und Adresse des Fahrzeughalters zum Zeitpunkt der Abmeldung. Wichtig f\u00fcr die Zuordnung der Steuerpflicht bis zum Abmeldedatum. Beispiel: ''Max Mustermann, Musterstra\u00dfe 1, 12345 Musterstadt''.\", \"kennzeichen\": \"Amtliches Kennzeichen des Fahrzeugs, das abgemeldet wird. Format: Kombination aus Buchstaben und Ziffern, z. B. ''B-AB 123''. Relevant f\u00fcr die Identifikation des Fahrzeugs im Steuerkontext.\", \"fahrzeug\": \"Beschreibung des Fahrzeugs, meist Marke, Modell und Typ. Beispiel: ''Volkswagen Golf 1.6 TDI''. Dient der eindeutigen Zuordnung des abgemeldeten Fahrzeugs.\", \"fin\": \"Fahrzeug-Identifizierungsnummer (FIN), auch Fahrzeugnummer oder VIN (Vehicle Identification Number). 17-stellige alphanumerische Zeichenfolge, z. B. ''WVWZZZ1JZ3W123456''. Wichtig f\u00fcr die eindeutige Identifikation des Fahrzeugs im Steuer- und Zulassungskontext.\", \"abmeldedatum\": \"Datum, an dem die Abmeldung wirksam wird. Format: TT.MM.JJJJ oder JJJJ-MM-TT. Entscheidend f\u00fcr die Berechnung der Steuerpflicht (Kraftfahrzeugsteuer endet mit diesem Datum). Beispiel: ''15.05.2023''.\"}"',
    'KFZ-Abmeldung, Fahrzeugabmeldung, Stilllegung, Zulassungsstelle, Abmeldebestätigung, Außerbetriebsetzung, Deregistration, Vehicle deregistration, Kennzeichen, FIN, Fahrzeug-Identifizierungsnummer, Halter, Abmeldedatum, Verwertungsnachweis, Entsorgungsnachweis, §14 FZV, Fahrzeugzulassungsverordnung',
    'Zulassungsstelle',
    '{"paragraphen": "§3 KraftStG (Kraftfahrzeugsteuergesetz), §14 FZV (Fahrzeug-Zulassungsverordnung)", "anlage": null, "hinweise": "Die Abmeldung beendet die Steuerpflicht für das Fahrzeug ab dem Abmeldedatum. Relevant für die Steuererklärung, wenn das Fahrzeug im laufenden Jahr abgemeldet wurde (z. B. bei Verkauf oder Verschrottung). Die Kraftfahrzeugsteuer wird nur bis zum Abmeldedatum fällig. Bei vorzeitiger Abmeldung kann eine Erstattung beantragt werden. Keine direkte Eintragung in die Steuererklärung, aber Nachweis für das Finanzamt bei Rückfragen."}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
ON CONFLICT (id) DO UPDATE SET category=EXCLUDED.category, display_name=EXCLUDED.display_name, description=EXCLUDED.description, schema=EXCLUDED.schema, field_descriptions=EXCLUDED.field_descriptions, classify_keywords=EXCLUDED.classify_keywords, typical_senders=EXCLUDED.typical_senders, steuer_relevanz=EXCLUDED.steuer_relevanz, priority=EXCLUDED.priority, enabled=EXCLUDED.enabled, version=EXCLUDED.version, source=EXCLUDED.source, notes=EXCLUDED.notes;

INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'delivery_note',
    'K. Handel & Versand',
    'Lieferschein',
    'Ein Lieferschein ist ein Dokument, das bei der Lieferung von Waren vom Verkäufer an den Käufer ausgestellt wird. Es dient als Nachweis über den Versand und die empfangenen Artikel, enthält jedoch keine Preisinformationen (im Gegensatz zur Rechnung). Typischerweise wird es bei Warensendungen, Online-Bestellungen oder Lieferungen im B2B- und B2C-Bereich verwendet.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "Lieferschein", "description": "Schema f\u00fcr die Extraktion von Lieferscheindaten", "type": "object", "properties": {"lieferscheinnummer": {"type": "string", "description": "Eindeutige Nummer des Lieferscheins"}, "sendungsnummer": {"type": "string", "description": "Nummer der Sendung (z.B. Tracking-Nummer)"}, "datum": {"type": "string", "format": "date", "description": "Datum des Lieferscheins im Format YYYY-MM-DD"}, "lieferant": {"type": "object", "description": "Informationen zum Lieferanten", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort", "land"]}, "telefon": {"type": "string", "pattern": "^\\+[0-9]{11,15}$"}, "email": {"type": "string", "format": "email"}}, "required": ["name"]}, "empfaenger": {"type": "object", "description": "Informationen zum Empf\u00e4nger", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort", "land"]}, "telefon": {"type": "string", "pattern": "^\\+[0-9]{11,15}$"}, "email": {"type": "string", "format": "email"}}, "required": ["name"]}, "bestellnummer": {"type": "string", "description": "Nummer der zugeh\u00f6rigen Bestellung"}, "po_nummer": {"type": "string", "description": "Purchase Order Nummer (alternativ zur Bestellnummer)"}, "kundenauftrag": {"type": "string", "description": "Nummer des Kundenauftrags"}, "projektnummer": {"type": "string", "description": "Nummer des zugeh\u00f6rigen Projekts"}, "stichwort": {"type": "string", "description": "Kurze Beschreibung oder Stichwort zum Lieferschein"}, "positionen": {"type": "array", "description": "Liste der gelieferten Positionen", "items": {"type": "object", "properties": {"artikelnr": {"type": "string", "description": "Artikelnummer der Position"}, "beschreibung": {"type": "string", "description": "Beschreibung der Position"}, "menge": {"type": "number", "description": "Menge der gelieferten Artikel"}, "einheit": {"type": "string", "description": "Ma\u00dfeinheit der Menge (z.B. St\u00fcck, kg, m)"}}, "required": ["artikelnr", "menge"]}}, "versandart": {"type": "string", "description": "Art des Versands (z.B. DHL, Spedition)"}, "gewicht": {"type": "string", "description": "Gesamtgewicht der Lieferung (z.B. ''12.50'' kg)"}, "pakete_anzahl": {"type": "integer", "description": "Anzahl der Pakete in der Lieferung"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^[0-9]{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$", "nullable": true}, "mwst_satz": {"type": "string", "pattern": "^[0-9]+(\\.[0-9]{1,2})?$", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}}, "required": ["lieferscheinnummer", "datum", "lieferant", "empfaenger", "positionen"]}',
    '"{\"lieferscheinnummer\": \"Eindeutige Identifikationsnummer des Lieferscheins, oft alphanumerisch. Beispiel: ''LS-2023-4711''. Wichtig f\u00fcr die Zuordnung zu Bestellungen und zur Dokumentation des Wareneingangs.\", \"sendungsnummer\": \"Tracking-Nummer der Sendung, oft vom Logistikdienstleister (z. B. DHL, Hermes) vergeben. Beispiel: ''123456789012345678''. Wichtig f\u00fcr die Sendungsverfolgung und bei Reklamationen.\", \"datum\": \"Datum der Lieferung oder Ausstellung des Lieferscheins. Format: ISO-8601 (YYYY-MM-DD). Beispiel: ''2023-10-15''. Relevant f\u00fcr die zeitliche Zuordnung des Wareneingangs.\", \"lieferant\": \"Name und Adresse des Lieferanten (Absender der Ware). Beispiel: ''Muster GmbH, Musterstra\u00dfe 1, 12345 Musterstadt''. Wichtig f\u00fcr die Zuordnung zu Gesch\u00e4ftspartnern.\", \"empfaenger\": \"Name und Adresse des Empf\u00e4ngers (Kunde oder Besteller). Beispiel: ''Max Mustermann, Beispielweg 2, 54321 Beispielstadt''. Wichtig f\u00fcr die korrekte Zustellung und Dokumentation.\", \"bestellnummer\": \"Referenznummer der Bestellung, auf die sich der Lieferschein bezieht. Beispiel: ''B-2023-1234''. Wichtig f\u00fcr die Zuordnung zur urspr\u00fcnglichen Bestellung.\", \"po_nummer\": \"Purchase Order Number (Bestellnummer des K\u00e4ufers), oft im B2B-Bereich verwendet. Beispiel: ''PO-2023-5678''. Wichtig f\u00fcr die Abstimmung mit dem Bestellprozess des K\u00e4ufers.\", \"kundenauftrag\": \"Interne Auftragsnummer des Kunden, falls abweichend von der Bestellnummer. Beispiel: ''KA-2023-9876''. Wichtig f\u00fcr die interne Zuordnung beim Kunden.\", \"projektnummer\": \"Projektnummer, falls die Lieferung einem bestimmten Projekt zugeordnet ist. Beispiel: ''P-2023-001''. Wichtig f\u00fcr die projektbezogene Abrechnung oder Dokumentation.\", \"stichwort\": \"Kurze Beschreibung oder Stichwort zur Lieferung. Beispiel: ''B\u00fcromaterial Oktober''. Wichtig f\u00fcr die schnelle Identifikation des Lieferinhalts.\"}"',
    'Lieferschein, Lieferavis, Delivery Note, Versandbestätigung, Warensendung, Paketinhalt, Artikelnummer, Menge, Einheit, Lieferdatum, Sendungsnummer, Bestellnummer, Auftragsnummer, Projektnummer, Versandart, Gewicht, Packstücke, Empfangsbestätigung, Logistik, Lieferant, Empfänger, delivery confirmation, shipment details',
    'Händler, Logistik, Lieferanten',
    NULL,
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
ON CONFLICT (id) DO UPDATE SET category=EXCLUDED.category, display_name=EXCLUDED.display_name, description=EXCLUDED.description, schema=EXCLUDED.schema, field_descriptions=EXCLUDED.field_descriptions, classify_keywords=EXCLUDED.classify_keywords, typical_senders=EXCLUDED.typical_senders, steuer_relevanz=EXCLUDED.steuer_relevanz, priority=EXCLUDED.priority, enabled=EXCLUDED.enabled, version=EXCLUDED.version, source=EXCLUDED.source, notes=EXCLUDED.notes;

INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'product_instruction',
    'K. Handel & Versand',
    'Produktbeschreibung/Anleitung',
    'Dieses Dokument enthält Produktbeschreibungen oder Bedienungsanleitungen, die von Herstellern zu gekauften Waren mitgeliefert werden. Es dient der Information über Nutzung, Materialzusammensetzung und Sicherheitshinweise des Produkts. Im Gegensatz zu Garantieunterlagen oder Rechnungen liegt der Fokus hier auf der Funktionsweise und Handhabung, nicht auf Kauf- oder Gewährleistungsdetails.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "Product Instruction", "description": "Schema f\u00fcr Produktbeschreibungen und Anleitungen", "type": "object", "properties": {"produktname": {"type": "string", "description": "Name des Produkts"}, "artikelnummer": {"type": "string", "description": "Eindeutige Artikelnummer des Produkts"}, "material": {"type": "string", "description": "Materialzusammensetzung des Produkts"}, "sicherheitshinweise": {"type": "array", "description": "Liste von Sicherheitshinweisen", "items": {"type": "string"}}, "anwendung": {"type": "string", "description": "Anleitung zur Anwendung des Produkts"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean", "default": false}, "steuerrelevanz_hinweis": {"type": "string", "default": null}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "default": null}, "steuerjahr": {"type": "string", "pattern": "^[0-9]{4}$", "default": null}, "mwst_ausgewiesen": {"type": "boolean", "default": false}, "mwst_betrag": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$", "default": null}, "mwst_satz": {"type": "string", "default": null}, "aktenzeichen": {"type": "string", "default": null}, "dokumenten_id": {"type": "string", "default": null}}, "additionalProperties": false}}, "required": ["produktname", "artikelnummer"], "additionalProperties": false}',
    '"{\"produktname\": \"Der offizielle Name des Produkts, wie er vom Hersteller vergeben wurde. Beispiel: ''Staubsauger XYZ Pro 2000''. Wichtig f\u00fcr die Identifikation des Produkts, z. B. bei Garantieanspr\u00fcchen oder R\u00fcckfragen.\", \"artikelnummer\": \"Eindeutige Identifikationsnummer des Produkts, oft als EAN, Modellnummer oder interne Hersteller-Nummer. Beispiel: ''ART-123456'' oder ''4012345678901''. Wichtig f\u00fcr Nachbestellungen oder Serviceanfragen.\", \"material\": \"Beschreibung der Materialien, aus denen das Produkt besteht. Beispiel: ''Kunststoff (Polypropylen), Metall (Edelstahl), Textil (Polyester)''. Kann f\u00fcr Entsorgungshinweise oder Allergiker relevant sein.\", \"sicherheitshinweise\": \"Liste von Warnungen, Sicherheitshinweisen oder Warnhinweisen zur sicheren Nutzung des Produkts. Beispiel: [''Nicht f\u00fcr Kinder unter 3 Jahren geeignet'', ''Nur in gut bel\u00fcfteten R\u00e4umen verwenden'']. Wichtig f\u00fcr die Haftungsfreistellung des Herstellers und zur Vermeidung von Unf\u00e4llen.\", \"anwendung\": \"Anleitung zur Nutzung, Montage oder Pflege des Produkts. Beispiel: ''1. Stecker in die Steckdose stecken. 2. Ein-/Ausschalter bet\u00e4tigen.''. Dient der korrekten Handhabung und Verl\u00e4ngerung der Produktlebensdauer.\"}"',
    'Bedienungsanleitung, Gebrauchsanweisung, Produktbeschreibung, user manual, instructions, safety instructions, Sicherheitshinweise, Anwendung, Handhabung, Materialzusammensetzung, Artikelnummer, EAN, Produktname, Herstellerhinweise, CE-Kennzeichnung, Warnsymbole, Pflegehinweise, Entsorgungshinweise, Montageanleitung, assembly instructions',
    'Hersteller',
    NULL,
    0,
    1,
    1,
    'mistral_batch',
    'Häufige Verwechslungen: Dieses Template wird oft mit Garantieunterlagen oder Rechnungen verwechselt, da diese Dokumente oft zusammen mit der Produktbeschreibung geliefert werden. Produktanleitungen enthalten jedoch keine Kauf- oder Garantieinformationen, sondern ausschließlich Hinweise zur Nutzung. Tipp: Achte auf Schlüsselwörter wie ''Bedienungsanleitung'', ''Gebrauchsanweisung'' oder ''Sicherheitshinweise'', um das Dokument korrekt zuzuordnen. Bei elektronischen Geräten sind oft auch CE-Kennzeichnungen oder Warnsymbole enthalten.'
)
ON CONFLICT (id) DO UPDATE SET category=EXCLUDED.category, display_name=EXCLUDED.display_name, description=EXCLUDED.description, schema=EXCLUDED.schema, field_descriptions=EXCLUDED.field_descriptions, classify_keywords=EXCLUDED.classify_keywords, typical_senders=EXCLUDED.typical_senders, steuer_relevanz=EXCLUDED.steuer_relevanz, priority=EXCLUDED.priority, enabled=EXCLUDED.enabled, version=EXCLUDED.version, source=EXCLUDED.source, notes=EXCLUDED.notes;

INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'return_label',
    'K. Handel & Versand',
    'Retourenlabel',
    'Ein Retourenlabel ist ein vorfrankiertes Versandetikett, das von Händlern zur Rücksendung von Waren durch den Kunden bereitgestellt wird. Es kommt typischerweise bei Online-Käufen vor, wenn der Kunde die Ware zurücksenden möchte, und enthält alle notwendigen Versandinformationen. Im Gegensatz zu regulären Versandlabels wird es vom Händler generiert und ist oft mit einer vordefinierten Gültigkeitsdauer versehen.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "Return Label", "description": "Schema f\u00fcr Retourenlabel-Dokumente", "type": "object", "properties": {"sendungsnummer": {"description": "Eindeutige Sendungsnummer der Retoure", "type": "string"}, "ruecksendeadresse": {"description": "Adresse, an die die Retoure zur\u00fcckgesendet wird", "type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort", "land"]}, "gueltig_bis": {"description": "G\u00fcltigkeitsdatum des Retourenlabels im Format YYYY-MM-DD", "type": "string", "format": "date"}, "barcode": {"description": "Barcode-Daten der Retoure (z.B. als Base64 oder Bild-Referenz)", "type": "string"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean", "default": false}, "steuerrelevanz_hinweis": {"type": "string", "default": null}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "default": null}, "steuerjahr": {"type": "string", "pattern": "^[0-9]{4}$", "default": null}, "mwst_ausgewiesen": {"type": "boolean", "default": false}, "mwst_betrag": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$", "default": null}, "mwst_satz": {"type": "string", "default": null}, "aktenzeichen": {"type": "string", "default": null}, "dokumenten_id": {"type": "string", "default": null}}, "required": ["steuerrelevant"]}}, "required": ["sendungsnummer", "_meta"]}',
    '"{\"sendungsnummer\": \"Eindeutige Nummer zur Identifikation der R\u00fccksendung, oft alphanumerisch. Wird f\u00fcr die Sendungsverfolgung verwendet. Beispiel: ''123456789012''. Nicht steuerrelevant, aber wichtig f\u00fcr die Zuordnung der R\u00fccksendung.\", \"ruecksendeadresse\": \"Adresse des H\u00e4ndlers oder Logistikdienstleisters, an die die Ware zur\u00fcckgesendet werden soll. Enth\u00e4lt typischerweise Name, Stra\u00dfe, Hausnummer, Postleitzahl und Ort. Beispiel: ''Musterh\u00e4ndler GmbH, Retourenabteilung, Musterstra\u00dfe 1, 12345 Musterstadt''.\", \"gueltig_bis\": \"Datum, bis zu dem das Retourenlabel verwendet werden kann. Format: ISO 8601 (YYYY-MM-DD) oder deutsches Format (TT.MM.JJJJ). Beispiel: ''31.12.2023''. Wichtig f\u00fcr die Einhaltung der R\u00fcckgabefrist.\", \"barcode\": \"Maschinenlesbarer Code (z. B. Code 128 oder QR-Code), der die Sendungsnummer oder andere R\u00fccksendedaten enth\u00e4lt. Wird vom Logistikdienstleister gescannt. Beispiel: ''||123456789012||''.\"}"',
    'Retourenlabel, Rücksendeetikett, Rücksendeschein, Retourenschein, Rücksendeadresse, Sendungsnummer, Barcode, gültig bis, Retouren, Rücksendung, return label, return shipping label, return address, tracking number, valid until, prepaid, Rückgaberecht, Widerrufsrecht',
    'Händler',
    NULL,
    0,
    1,
    1,
    'mistral_batch',
    'Häufige Verwechslung mit regulären Versandlabels oder Paketaufklebern, die nicht für Retouren bestimmt sind. Retourenlabels sind oft mit dem Hinweis ''Retoure'' oder ''Rücksendung'' gekennzeichnet und enthalten eine explizite Gültigkeitsdauer. Bei manchen Händlern ist das Retourenlabel direkt in die Rechnung oder den Lieferschein integriert. Achte auf die typischen Begriffe wie ''Retourenlabel'', ''Rücksendeetikett'' oder ''prepaid return label''.'
)
ON CONFLICT (id) DO UPDATE SET category=EXCLUDED.category, display_name=EXCLUDED.display_name, description=EXCLUDED.description, schema=EXCLUDED.schema, field_descriptions=EXCLUDED.field_descriptions, classify_keywords=EXCLUDED.classify_keywords, typical_senders=EXCLUDED.typical_senders, steuer_relevanz=EXCLUDED.steuer_relevanz, priority=EXCLUDED.priority, enabled=EXCLUDED.enabled, version=EXCLUDED.version, source=EXCLUDED.source, notes=EXCLUDED.notes;

INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'warranty_certificate',
    'K. Handel & Versand',
    'Garantieurkunde',
    'Eine Garantieurkunde ist ein Dokument, das vom Hersteller oder Händler ausgestellt wird und die Garantiebedingungen für ein gekauftes Produkt bestätigt. Sie kommt typischerweise direkt nach dem Kauf eines Produkts vor und enthält Details wie Garantiedauer und -umfang. Im Gegensatz zu einer Rechnung oder einem Lieferschein dient sie nicht der Kaufabwicklung, sondern der Absicherung des Käufers bei Defekten oder Mängeln während der Garantiezeit.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "warranty_certificate", "description": "Garantieurkunde f\u00fcr ein Produkt", "type": "object", "properties": {"produkt": {"type": "object", "properties": {"name": {"type": "string"}, "modell": {"type": "string"}, "hersteller": {"type": "string"}, "kategorie": {"type": "string"}}, "required": ["name"]}, "seriennummer": {"type": "string"}, "kaufdatum": {"type": "string", "format": "date"}, "garantiedauer": {"type": "object", "properties": {"dauer_in_monaten": {"type": "integer"}, "beginn": {"type": "string", "format": "date"}, "ende": {"type": "string", "format": "date"}}, "required": ["dauer_in_monaten", "beginn", "ende"]}, "garantieumfang": {"type": "array", "items": {"type": "object", "properties": {"leistungsbeschreibung": {"type": "string"}, "ausschluesse": {"type": "string"}, "bedingungen": {"type": "string"}}, "required": ["leistungsbeschreibung"]}}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^[0-9]{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$", "nullable": true}, "mwst_satz": {"type": "string", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"], "additionalProperties": false}}, "required": ["produkt", "seriennummer", "kaufdatum", "garantiedauer", "_meta"]}',
    '"{\"produkt\": \"Der Name oder die genaue Bezeichnung des gekauften Produkts, f\u00fcr das die Garantie gilt. Beispiel: ''Bosch Waschmaschine Serie 6''. Wichtig f\u00fcr die Identifikation des Produkts im Garantiefall.\", \"seriennummer\": \"Die eindeutige Seriennummer des Produkts, oft alphanumerisch. Beispiel: ''WAS2023456789''. Wird ben\u00f6tigt, um die Garantieanspr\u00fcche geltend zu machen und das Produkt eindeutig zu identifizieren.\", \"kaufdatum\": \"Das Datum, an dem das Produkt gekauft wurde, meist im Format TT.MM.JJJJ. Beispiel: ''15.05.2023''. Wichtig, um den Beginn der Garantiezeit zu bestimmen.\", \"garantiedauer\": \"Die Dauer der Garantie in Monaten oder Jahren, oft als Zahl mit Einheit angegeben. Beispiel: ''24 Monate'' oder ''2 Jahre''. Bestimmt, wie lange die Garantieanspr\u00fcche g\u00fcltig sind.\", \"garantieumfang\": \"Eine Beschreibung der Leistungen, die im Garantiefall abgedeckt sind. Beispiel: ''Reparatur oder Ersatz bei Material- oder Herstellungsfehlern''. Wichtig, um zu wissen, welche Sch\u00e4den oder Defekte durch die Garantie abgedeckt sind.\"}"',
    'Garantie, Garantieurkunde, Gewährleistung, Warranty Certificate, Herstellergarantie, Garantiedauer, Garantiezeitraum, Seriennummer, Produktgarantie, Kaufdatum, Garantiebedingungen, Garantieumfang, Hersteller, Händler, Defekt, Mangel, Reparatur, Ersatz, warranty period, warranty conditions, product warranty',
    'Hersteller',
    NULL,
    0,
    1,
    1,
    'mistral_batch',
    'Häufig wird die Garantieurkunde mit der gesetzlichen Gewährleistung verwechselt, die unabhängig vom Hersteller gilt. Die Garantie ist eine freiwillige Leistung des Herstellers oder Händlers. Achte auf Formulierungen wie ''Herstellergarantie'' oder ''Garantieerklärung'', um das Dokument von anderen Kaufunterlagen zu unterscheiden. Bei hochpreisigen Produkten (z. B. Elektronik, Haushaltsgeräte) ist die Garantieurkunde besonders relevant und sollte sorgfältig aufbewahrt werden.'
)
