INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'consent_form',
    'L. Rechtliche Dokumente (Beilagen)',
    'Einwilligungserklärung',
    'Eine Einwilligungserklärung ist ein rechtliches Dokument, in dem eine Person (z. B. Kunde, Patient) der Verarbeitung ihrer personenbezogenen Daten für einen bestimmten Zweck zustimmt. Sie kommt häufig im medizinischen Bereich, bei Marketingaktivitäten oder Dienstleistungsverträgen vor. Im Gegensatz zu Verträgen oder AGBs regelt sie ausschließlich die datenschutzrechtliche Einwilligung und ist oft formlos oder standardisiert.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "consent_form", "description": "Einwilligungserkl\u00e4rung zur Verarbeitung personenbezogener Daten", "type": "object", "properties": {"zweck": {"type": "string", "description": "Zweck der Datenerhebung und -verarbeitung"}, "personenbezogene_daten": {"type": "array", "description": "Liste der erhobenen personenbezogenen Daten", "items": {"type": "object", "properties": {"datenart": {"type": "string", "description": "Art der personenbezogenen Daten (z.B. Name, Adresse, E-Mail)"}, "zweckbindung": {"type": "string", "description": "Zweckbindung der jeweiligen Datenart"}}, "required": ["datenart"]}}, "widerrufbar": {"type": "boolean", "description": "Angabe, ob die Einwilligung widerrufbar ist"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^[0-9]{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$", "nullable": true}, "mwst_satz": {"type": "string", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}}, "required": ["zweck", "personenbezogene_daten", "widerrufbar"]}',
    '"{\"zweck\": \"Der genaue Zweck, f\u00fcr den die personenbezogenen Daten verarbeitet werden. Beispiel: ''Zusendung von Werbematerial'', ''Behandlung und Dokumentation im Rahmen der \u00e4rztlichen Versorgung''. Wichtig f\u00fcr die rechtliche Wirksamkeit der Einwilligung nach DSGVO.\", \"personenbezogene_daten\": \"Art der Daten, die verarbeitet werden. Beispiel: ''Name, Adresse, E-Mail, Geburtsdatum, Gesundheitsdaten''. Relevant f\u00fcr die Transparenz und Nachvollziehbarkeit der Datenverarbeitung.\", \"widerrufbar\": \"Angabe, ob die Einwilligung widerrufen werden kann (meist ''ja''). Beispiel: ''Die Einwilligung ist jederzeit widerrufbar''. Wichtig f\u00fcr die rechtliche Absicherung und Information des Einwilligenden.\"}"',
    'Einwilligung, Einwilligungserklärung, Datenschutz, personenbezogene Daten, Datenverarbeitung, Zweck, Widerruf, DSGVO, GDPR, consent, privacy, Verarbeitung, Nutzung, Zustimmung, Patienteneinwilligung, Marketing, Werbung, Kontaktaufnahme',
    'Unternehmen, Ärzte',
    NULL,
    0,
    1,
    1,
    'mistral_batch',
    'Häufige Verwechslungen mit Datenschutzerklärungen (die keine aktive Einwilligung erfordern) oder Verträgen (die weitergehende Regelungen enthalten). Einwilligungserklärungen sind oft kürzer und fokussieren sich auf die Zustimmung zur Datenverarbeitung. Achte auf Formulierungen wie ''Ich willige ein'' oder ''Ich stimme zu''.'
)
