INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'privacy_policy',
    'L. Rechtliche Dokumente (Beilagen)',
    'Datenschutzerklärung',
    'Eine Datenschutzerklärung informiert betroffene Personen gemäß Art. 13, 14 DSGVO über die Verarbeitung ihrer personenbezogenen Daten durch ein Unternehmen. Sie kommt typischerweise bei Websites, Apps oder Vertragsbeziehungen vor und unterscheidet sich von AGB oder Impressum durch den spezifischen Fokus auf Datenverarbeitungsprozesse, Rechtsgrundlagen und Betroffenenrechte.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "Privacy Policy", "description": "Schema f\u00fcr die Extraktion von Datenschutzerkl\u00e4rungen", "type": "object", "properties": {"verantwortlicher": {"type": "object", "properties": {"name": {"type": "string"}, "anschrift": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort", "land"]}, "kontakt": {"type": "object", "properties": {"email": {"type": "string", "format": "email"}, "telefon": {"type": "string"}, "website": {"type": "string", "format": "uri"}}}}, "required": ["name"]}, "datenkategorien": {"type": "array", "items": {"type": "object", "properties": {"kategorie": {"type": "string"}, "beschreibung": {"type": "string"}, "beispiele": {"type": "array", "items": {"type": "string"}}}, "required": ["kategorie"]}}, "zwecke": {"type": "array", "items": {"type": "object", "properties": {"zweck": {"type": "string"}, "beschreibung": {"type": "string"}, "datenkategorien": {"type": "array", "items": {"type": "string"}}}, "required": ["zweck"]}}, "rechtsgrundlage": {"type": "array", "items": {"type": "object", "properties": {"grundlage": {"type": "string"}, "artikel": {"type": "string"}, "beschreibung": {"type": "string"}, "zwecke": {"type": "array", "items": {"type": "string"}}}, "required": ["grundlage"]}}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean", "enum": [false]}, "steuerrelevanz_hinweis": {"type": "string", "enum": [null]}, "steuer_kategorie": {"type": "string", "enum": [null]}, "steuerjahr": {"type": "string", "enum": [null]}, "mwst_ausgewiesen": {"type": "boolean", "enum": [false]}, "mwst_betrag": {"type": "string", "enum": [null]}, "mwst_satz": {"type": "string", "enum": [null]}, "aktenzeichen": {"type": "string", "enum": [null]}, "dokumenten_id": {"type": "string"}}, "required": ["steuerrelevant", "steuerrelevanz_hinweis", "steuer_kategorie", "steuerjahr", "mwst_ausgewiesen", "mwst_betrag", "mwst_satz", "aktenzeichen"]}}, "required": ["_meta"]}',
    '"{\"verantwortlicher\": \"Name und Kontaktdaten der nat\u00fcrlichen oder juristischen Person, Beh\u00f6rde, Einrichtung oder anderen Stelle, die allein oder gemeinsam mit anderen \u00fcber die Zwecke und Mittel der Verarbeitung von personenbezogenen Daten entscheidet. Format: Vollst\u00e4ndiger Name, Adresse, E-Mail, ggf. Telefonnummer. Beispiel: ''Muster GmbH, Musterstra\u00dfe 1, 12345 Berlin, datenschutz@muster.de''. Wichtig f\u00fcr die Identifikation des Datenverarbeiters, aber nicht direkt steuerrelevant.\", \"datenkategorien\": \"Auflistung der Arten personenbezogener Daten, die verarbeitet werden. Format: Aufz\u00e4hlung oder Flie\u00dftext. Beispiel: ''Name, Anschrift, E-Mail-Adresse, IP-Adresse, Cookies, Nutzungsdaten''. Relevant f\u00fcr die Transparenz gegen\u00fcber Betroffenen, aber ohne direkte Steuerrelevanz.\", \"zwecke\": \"Beschreibung der Zwecke, f\u00fcr die die personenbezogenen Daten verarbeitet werden. Format: Aufz\u00e4hlung oder Flie\u00dftext. Beispiel: ''Vertragserf\u00fcllung, Marketing, Verbesserung der Website, Analyse des Nutzerverhaltens''. Wichtig f\u00fcr die Rechtm\u00e4\u00dfigkeit der Datenverarbeitung, aber nicht steuerrelevant.\", \"rechtsgrundlage\": \"Rechtliche Grundlage(n) f\u00fcr die Verarbeitung personenbezogener Daten gem\u00e4\u00df DSGVO. Format: Aufz\u00e4hlung mit Verweis auf Artikel. Beispiel: ''Einwilligung (Art. 6 Abs. 1 lit. a DSGVO), Vertragserf\u00fcllung (Art. 6 Abs. 1 lit. b DSGVO), berechtigtes Interesse (Art. 6 Abs. 1 lit. f DSGVO)''. Relevant f\u00fcr die Compliance, aber ohne Steuerbezug.\"}"',
    'Datenschutzerklärung, Datenschutzhinweise, Privacy Policy, personenbezogene Daten, Datenverarbeitung, DSGVO, Art. 13, Art. 14, Verantwortlicher, Rechtsgrundlage, Einwilligung, berechtigtes Interesse, Datenkategorien, Zwecke, Speicherdauer, Betroffenenrechte, Löschung, Auskunft, Widerspruch, Auftragsverarbeiter, Drittlandtransfer, Cookies, Tracking, Google Analytics, Facebook Pixel',
    'Unternehmen',
    NULL,
    0,
    1,
    1,
    'mistral_batch',
    'Häufige Verwechslungen mit AGB oder Impressum, da alle drei Dokumente oft auf Websites gemeinsam verlinkt werden. Datenschutzerklärungen sind jedoch spezifisch an die DSGVO angelehnt und enthalten typischerweise Abschnitte zu Betroffenenrechten (z. B. Auskunft, Löschung), Datenkategorien und Rechtsgrundlagen. Tipp: Achte auf Formulierungen wie ''Verantwortlicher'', ''Rechtsgrundlage'' oder ''Ihre Rechte gemäß DSGVO''. Sonderfall: Bei Cookies oder Tracking-Technologien wird oft auf eine separate Cookie-Richtlinie verwiesen, die jedoch Teil der Datenschutzerklärung sein kann.'
)
