INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'terms_and_conditions',
    'L. Rechtliche Dokumente (Beilagen)',
    'AGB',
    'Allgemeine Geschäftsbedingungen (AGB) sind vorformulierte Vertragsbedingungen, die ein Unternehmen für eine Vielzahl von Verträgen verwendet. Sie kommen bei fast jedem Vertragsabschluss mit Unternehmen vor, z. B. bei Online-Käufen, Dienstleistungsverträgen oder Mitgliedschaften. AGB unterscheiden sich von individuellen Verträgen durch ihre standardisierte Form und dienen der Vereinfachung und Vereinheitlichung von Vertragsabschlüssen. Im Gegensatz zu Rechnungen oder Lieferscheinen enthalten sie keine konkreten Leistungsdaten, sondern allgemeine Regelungen.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "terms_and_conditions", "description": "Extraktionsschema f\u00fcr Allgemeine Gesch\u00e4ftsbedingungen (AGB)", "type": "object", "properties": {"unternehmen": {"type": "object", "properties": {"name": {"type": "string"}, "rechtsform": {"type": "string"}, "sitz": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort", "land"]}, "kontakt": {"type": "object", "properties": {"telefon": {"type": "string"}, "email": {"type": "string", "format": "email"}, "website": {"type": "string", "format": "uri"}}}, "handelsregister": {"type": "object", "properties": {"registergericht": {"type": "string"}, "registernummer": {"type": "string"}}}}, "required": ["name"]}, "geltungsbereich": {"type": "object", "properties": {"persoenlich": {"type": "string"}, "sachlich": {"type": "string"}, "zeitlich": {"type": "string"}, "ausnahmen": {"type": "array", "items": {"type": "string"}}}}, "zahlungsbedingungen": {"type": "object", "properties": {"zahlungsarten": {"type": "array", "items": {"type": "string"}}, "zahlungsfrist": {"type": "string"}, "verzugszinsen": {"type": "string"}, "skonto": {"type": "object", "properties": {"prozent": {"type": "string"}, "frist": {"type": "string"}}}, "waehrung": {"type": "string"}}}, "kuendigungsbedingungen": {"type": "object", "properties": {"kuendigungsfrist": {"type": "string"}, "kuendigungsform": {"type": "string"}, "kuendigungsgruende": {"type": "array", "items": {"type": "string"}}, "folgen": {"type": "string"}}}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^[0-9]{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$", "nullable": true}, "mwst_satz": {"type": "string", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}}, "required": ["unternehmen", "_meta"]}',
    '"{\"unternehmen\": \"Name und Anschrift des Unternehmens, das die AGB herausgibt. Wichtig f\u00fcr die Identifikation des Vertragspartners, z. B. bei rechtlichen Auseinandersetzungen. Format: Firmenname, Stra\u00dfe, PLZ, Ort. Beispiel: ''Muster GmbH, Musterstra\u00dfe 1, 12345 Musterstadt''.\", \"geltungsbereich\": \"Beschreibung, f\u00fcr welche Vertr\u00e4ge oder Leistungen die AGB gelten. Enth\u00e4lt oft Formulierungen wie ''Diese AGB gelten f\u00fcr alle Vertr\u00e4ge zwischen...''. Wichtig, um den Anwendungsbereich der Bedingungen zu verstehen. Beispiel: ''Diese AGB gelten f\u00fcr alle Kaufvertr\u00e4ge, die \u00fcber unseren Online-Shop abgeschlossen werden''.\", \"zahlungsbedingungen\": \"Regelungen zu Zahlungsmodalit\u00e4ten, F\u00e4lligkeit, Zahlungsmethoden und ggf. Verzugszinsen. Wichtig f\u00fcr die finanzielle Planung und bei Zahlungsstreitigkeiten. Beispiel: ''Die Zahlung ist innerhalb von 14 Tagen nach Rechnungsstellung f\u00e4llig. Bei Zahlungsverzug werden Verzugszinsen in H\u00f6he von 5 % p.a. berechnet''.\", \"kuendigungsbedingungen\": \"Bedingungen und Fristen f\u00fcr die K\u00fcndigung des Vertragsverh\u00e4ltnisses. Enth\u00e4lt oft Angaben zu K\u00fcndigungsfristen, -formen und -gr\u00fcnden. Wichtig f\u00fcr die Beendigung von Vertr\u00e4gen. Beispiel: ''Der Vertrag kann mit einer Frist von 3 Monaten zum Monatsende gek\u00fcndigt werden. Die K\u00fcndigung bedarf der Schriftform''.\"}"',
    'AGB, Allgemeine Geschäftsbedingungen, Terms and Conditions, Nutzungsbedingungen, Vertragsbedingungen, Geltungsbereich, Zahlungsbedingungen, Kündigungsfrist, Haftung, Gewährleistung, Salvatorische Klausel, Gerichtsstand, Widerrufsrecht, Datenschutzhinweis, Vertragspartner, Preisanpassung, Lieferbedingungen, Mängelrüge, Eigentumsvorbehalt, salvatorische Klausel',
    'Unternehmen',
    NULL,
    0,
    1,
    1,
    'mistral_batch',
    'Häufige Verwechslungen: AGB werden oft mit individuellen Verträgen (z. B. Mietverträgen oder Arbeitsverträgen) oder Datenschutzerklärungen verwechselt. AGB sind jedoch standardisiert und gelten für eine Vielzahl von Verträgen. Tipp: AGB enthalten typischerweise Abschnitte wie ''Geltungsbereich'', ''Zahlungsbedingungen'' oder ''Kündigung'' und sind oft als separates Dokument oder als Anhang zu einem Vertrag beigefügt. Bei Online-Shops sind sie meist über einen Link im Footer der Website erreichbar.'
)
