INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'withdrawal_instruction',
    'L. Rechtliche Dokumente (Beilagen)',
    'Widerrufsbelehrung',
    'Eine Widerrufsbelehrung ist ein rechtliches Dokument, das Verbrauchern im Fernabsatz (z. B. Online-Käufe) ihr Recht auf Widerruf eines Vertrags innerhalb einer bestimmten Frist erklärt. Sie unterscheidet sich von allgemeinen AGB oder Rückgabebedingungen durch die spezifische Darstellung der Widerrufsfrist, -modalitäten und Ausnahmen gemäß § 355 BGB. Typischerweise wird sie bei Vertragsabschlüssen oder Lieferungen von Unternehmen an Verbraucher beigelegt.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "withdrawal_instruction", "description": "Schema f\u00fcr Widerrufsbelehrungen", "type": "object", "properties": {"widerrufsfrist": {"type": "string", "description": "Widerrufsfrist in Tagen (z.B. ''14'') oder als Datum im Format ''YYYY-MM-DD''", "oneOf": [{"type": "string", "pattern": "^[0-9]+$"}, {"type": "string", "format": "date"}]}, "kontakt": {"type": "object", "description": "Kontaktdaten f\u00fcr den Widerruf", "properties": {"name": {"type": "string"}, "email": {"type": "string", "format": "email"}, "telefon": {"type": "string", "pattern": "^\\+[0-9]{11,15}$"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string", "pattern": "^[0-9]{5}$"}, "ort": {"type": "string"}, "land": {"type": "string", "pattern": "^[A-Z]{2}$"}}, "required": ["strasse", "plz", "ort", "land"]}}, "required": ["name"]}, "ruecksendeadresse": {"type": "object", "description": "Adresse f\u00fcr die R\u00fccksendung der Ware", "properties": {"name": {"type": "string"}, "strasse": {"type": "string"}, "plz": {"type": "string", "pattern": "^[0-9]{5}$"}, "ort": {"type": "string"}, "land": {"type": "string", "pattern": "^[A-Z]{2}$"}}, "required": ["name", "strasse", "plz", "ort", "land"]}, "ausnahmen": {"type": "array", "description": "Liste der Ausnahmen vom Widerrufsrecht", "items": {"type": "object", "properties": {"grund": {"type": "string"}, "beschreibung": {"type": "string"}}, "required": ["grund"]}}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean", "default": false}, "steuerrelevanz_hinweis": {"type": "string", "default": null}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "default": null}, "steuerjahr": {"type": "string", "pattern": "^[0-9]{4}$", "default": null}, "mwst_ausgewiesen": {"type": "boolean", "default": false}, "mwst_betrag": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$", "default": null}, "mwst_satz": {"type": "string", "pattern": "^[0-9]+(\\.[0-9]{1,2})?$", "default": null}, "aktenzeichen": {"type": "string", "default": null}, "dokumenten_id": {"type": "string", "default": null}}, "required": ["steuerrelevant"]}}, "required": ["_meta"]}',
    '"{\"widerrufsfrist\": \"Die Dauer der Widerrufsfrist in Tagen (z. B. ''14 Tage''). Wichtig f\u00fcr die rechtliche G\u00fcltigkeit des Widerrufs, aber nicht direkt steuerrelevant. Format: Zahl + ''Tage'' oder ''Monate''. Beispiel: ''14 Tage ab Erhalt der Ware''.\", \"kontakt\": \"Kontaktdaten des Unternehmens f\u00fcr die Widerrufserkl\u00e4rung (z. B. E-Mail, Postadresse, Telefonnummer). Wichtig f\u00fcr die korrekte \u00dcbermittlung des Widerrufs. Format: Freitext mit Adresse, E-Mail oder Telefon. Beispiel: ''Muster GmbH, Widerrufsabteilung, Musterstra\u00dfe 1, 12345 Berlin, widerruf@muster.de''.\", \"ruecksendeadresse\": \"Postadresse, an die die Ware im Widerrufsfall zur\u00fcckgesendet werden muss. Kann identisch mit der Unternehmensadresse sein, aber oft eine spezielle Logistikadresse. Format: Freitext mit Stra\u00dfe, PLZ, Ort. Beispiel: ''Muster Logistik GmbH, R\u00fccknahmecenter, Industriestra\u00dfe 10, 54321 K\u00f6ln''.\", \"ausnahmen\": \"Liste von Ausnahmen, bei denen das Widerrufsrecht nicht gilt (z. B. bei versiegelten Hygieneartikeln oder individuell gefertigten Waren). Wichtig f\u00fcr die rechtliche Bewertung, ob ein Widerruf m\u00f6glich ist. Format: Aufz\u00e4hlung oder Flie\u00dftext. Beispiel: ''Das Widerrufsrecht besteht nicht bei: 1. Vertr\u00e4gen zur Lieferung von Waren, die nicht vorgefertigt sind und f\u00fcr deren Herstellung eine individuelle Auswahl oder Bestimmung durch den Verbraucher ma\u00dfgeblich ist.''\"}"',
    'Widerrufsrecht, Widerrufsbelehrung, Widerrufsfrist, 14 Tage, Fernabsatzvertrag, Verbrauchervertrag, Rücksendung, Rückgaberecht, Widerrufserklärung, § 355 BGB, § 312g BGB, cooling-off period, right of withdrawal, return address, Ausnahmen vom Widerrufsrecht, Muster-Widerrufsformular, Vertragswiderruf, Online-Kauf, Haustürgeschäft',
    'Unternehmen',
    NULL,
    0,
    1,
    1,
    'mistral_batch',
    'Häufige Verwechslungen: Widerrufsbelehrungen werden oft mit Rückgabebedingungen (z. B. bei stationärem Handel) oder AGB verwechselt. Eine Widerrufsbelehrung ist jedoch spezifisch für Fernabsatzverträge und enthält immer eine klare Fristangabe (meist 14 Tage) sowie Hinweise auf das Widerrufsrecht. Sonderfälle: Bei digitalen Inhalten (z. B. E-Books, Software) kann die Widerrufsfrist entfallen, sobald der Download beginnt. Tipp: Achte auf Formulierungen wie ''Sie haben das Recht, binnen 14 Tagen ohne Angabe von Gründen diesen Vertrag zu widerrufen.'''
)
ON CONFLICT (id) DO UPDATE SET category=EXCLUDED.category, display_name=EXCLUDED.display_name, description=EXCLUDED.description, schema=EXCLUDED.schema, field_descriptions=EXCLUDED.field_descriptions, classify_keywords=EXCLUDED.classify_keywords, typical_senders=EXCLUDED.typical_senders, steuer_relevanz=EXCLUDED.steuer_relevanz, priority=EXCLUDED.priority, enabled=EXCLUDED.enabled, version=EXCLUDED.version, source=EXCLUDED.source, notes=EXCLUDED.notes;

INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'bafoeg_notice',
    'M. Sonstiges',
    'BAföG-Bescheid',
    'Der BAföG-Bescheid ist ein amtliches Dokument, das Studierende oder Auszubildende vom BAföG-Amt erhalten, nachdem ihr Antrag auf Ausbildungsförderung geprüft wurde. Es enthält die Entscheidung über die Bewilligung, Höhe und Zusammensetzung (Zuschuss- und Darlehensanteil) der Förderung für einen bestimmten Förderzeitraum. Im Gegensatz zu anderen Bescheiden (z. B. Wohngeld oder Kindergeld) bezieht sich der BAföG-Bescheid speziell auf die finanzielle Unterstützung nach dem Bundesausbildungsförderungsgesetz (BAföG) und ist an Ausbildungszwecke gebunden.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "BAf\u00f6G-Bescheid", "description": "Schema f\u00fcr die Extraktion von Daten aus einem BAf\u00f6G-Bescheid", "type": "object", "properties": {"aktenzeichen": {"type": "string", "description": "Aktenzeichen des BAf\u00f6G-Bescheids"}, "antragsteller": {"type": "object", "description": "Angaben zum Antragsteller", "properties": {"name": {"type": "string", "description": "Vollst\u00e4ndiger Name des Antragstellers"}, "geburtsdatum": {"type": "string", "format": "date", "description": "Geburtsdatum des Antragstellers (YYYY-MM-DD)"}, "adresse": {"type": "object", "description": "Adresse des Antragstellers", "properties": {"strasse": {"type": "string", "description": "Stra\u00dfe und Hausnummer"}, "plz": {"type": "string", "description": "Postleitzahl (mit f\u00fchrenden Nullen)"}, "ort": {"type": "string", "description": "Ort"}, "land": {"type": "string", "description": "L\u00e4ndercode (ISO 3166-1 alpha-2)"}}, "required": ["strasse", "plz", "ort", "land"]}}, "required": ["name", "geburtsdatum", "adresse"]}, "foerderzeitraum": {"type": "object", "description": "Zeitraum der F\u00f6rderung", "properties": {"von": {"type": "string", "format": "date", "description": "Beginn des F\u00f6rderzeitraums (YYYY-MM-DD)"}, "bis": {"type": "string", "format": "date", "description": "Ende des F\u00f6rderzeitraums (YYYY-MM-DD)"}}, "required": ["von", "bis"]}, "foerderbetrag": {"type": "string", "description": "Gesamtf\u00f6rderbetrag (z.B. ''450.00'')", "pattern": "^\\d+\\.\\d{2}$"}, "darlehensanteil": {"type": "string", "description": "Darlehensanteil des F\u00f6rderbetrags (z.B. ''225.00'')", "pattern": "^\\d+\\.\\d{2}$"}, "zuschussanteil": {"type": "string", "description": "Zuschussanteil des F\u00f6rderbetrags (z.B. ''225.00'')", "pattern": "^\\d+\\.\\d{2}$"}, "rechtsmittelbelehrung": {"type": "string", "description": "Text der Rechtsmittelbelehrung"}, "_meta": {"type": "object", "description": "Metadaten zum Dokument", "properties": {"steuerrelevant": {"type": "boolean", "description": "Gibt an, ob das Dokument steuerrelevant ist"}, "steuerrelevanz_hinweis": {"type": "string", "description": "Hinweis zur Steuerrelevanz", "nullable": true}, "steuer_kategorie": {"type": "string", "description": "Kategorie der Steuerrelevanz", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "nullable": true}, "steuerjahr": {"type": "string", "description": "Steuerjahr (YYYY)", "pattern": "^\\d{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean", "description": "Gibt an, ob Mehrwertsteuer ausgewiesen ist"}, "mwst_betrag": {"type": "string", "description": "Mehrwertsteuerbetrag (z.B. ''19.00'')", "pattern": "^\\d+\\.\\d{2}$", "nullable": true}, "mwst_satz": {"type": "string", "description": "Mehrwertsteuersatz (z.B. ''19.00'')", "pattern": "^\\d+\\.\\d{2}$", "nullable": true}, "aktenzeichen": {"type": "string", "description": "Aktenzeichen des Dokuments", "nullable": true}, "dokumenten_id": {"type": "string", "description": "Eindeutige ID des Dokuments", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}, "berechnung": {"type": "array", "description": "Einzelne Berechnungspositionen des BAf\u00f6G-Bescheids (Bedarf, Einkommen, Abz\u00fcge, etc.)", "items": {"type": "object", "properties": {"bezeichnung": {"type": "string"}, "betrag": {"type": "string"}}}}}, "required": ["aktenzeichen", "antragsteller", "foerderzeitraum", "foerderbetrag", "darlehensanteil", "zuschussanteil", "_meta"]}',
    '"aktenzeichen, antragsteller, foerderzeitraum, foerderbetrag, darlehensanteil, zuschussanteil, rechtsmittelbelehrung"',
    'BAföG, Bundesausbildungsförderungsgesetz, Ausbildungsförderung, Förderbescheid, Zuschuss, Darlehen, Darlehensanteil, Zuschussanteil, Förderzeitraum, BAföG-Amt, aktenzeichen, Antragsteller, rechtsmittelbelehrung, monatlicher Förderbetrag, Rückzahlung, § 17 BAföG, Ausbildungsstätte, Semester, Auszahlung, Bedarfssatz, Einkommensanrechnung, elternunabhängiges BAföG, BAföG-Antrag, Bewilligung, Ablehnung, Teilablehnung, Förderhöhe, BAföG-Satz',
    'BAföG-Amt',
    '{"einordnung": "nicht steuerrelevant (keine direkte Auswirkung auf Einkommensteuer)"}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
