INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'boarding_pass',
    'M. Sonstiges',
    'Boarding Pass/Fahrkarte',
    'Ein Boarding Pass oder eine Fahrkarte ist ein Dokument, das zur Legitimation und zum Betreten eines Flugzeugs, Zuges oder Busses dient. Es wird typischerweise nach der Buchung und vor der Reise ausgestellt, entweder digital oder in Papierform. Im Gegensatz zu Buchungsbestätigungen enthält es konkrete Reiseinformationen wie Sitzplatz und Abflugzeit, ist aber kein Vertragsdokument wie ein Ticket oder eine Rechnung.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "Boarding Pass/Fahrkarte", "type": "object", "properties": {"passagier": {"type": "object", "properties": {"vorname": {"type": "string"}, "nachname": {"type": "string"}, "titel": {"type": "string", "enum": ["Dr.", "Prof.", "Prof. Dr.", null]}}, "required": ["vorname", "nachname"]}, "flugnummer_zugnummer": {"type": "string"}, "von": {"type": "object", "properties": {"iata_code": {"type": "string"}, "name": {"type": "string"}, "stadt": {"type": "string"}, "land": {"type": "string"}}, "required": ["iata_code", "name"]}, "nach": {"type": "object", "properties": {"iata_code": {"type": "string"}, "name": {"type": "string"}, "stadt": {"type": "string"}, "land": {"type": "string"}}, "required": ["iata_code", "name"]}, "datum": {"type": "string", "format": "date"}, "uhrzeit": {"type": "string", "pattern": "^([01]?[0-9]|2[0-3]):[0-5][0-9]$"}, "sitzplatz": {"type": "string"}, "buchungscode": {"type": "string"}, "fluggesellschaft_bahnunternehmen": {"type": "string"}, "klasse": {"type": "string", "enum": ["Economy", "Premium Economy", "Business", "First", null]}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "enum": [null]}, "steuer_kategorie": {"type": "string", "enum": [null]}, "steuerjahr": {"type": "string", "pattern": "^[0-9]{4}$", "enum": [null]}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$", "enum": [null]}, "mwst_satz": {"type": "string", "enum": [null]}, "aktenzeichen": {"type": "string", "enum": [null]}, "dokumenten_id": {"type": "string"}}, "required": ["steuerrelevant", "mwst_ausgewiesen", "dokumenten_id"]}}, "required": ["passagier", "flugnummer_zugnummer", "von", "nach", "datum", "uhrzeit", "_meta"]}',
    '"{\"passagier\": \"Name des Reisenden, wie im Dokument angegeben (z. B. ''Max Mustermann''). Wichtig f\u00fcr die Identifikation, aber nicht direkt steuerrelevant.\", \"flugnummer_zugnummer\": \"Flugnummer (z. B. ''LH123'') oder Zugnummer (z. B. ''ICE 598''). Format: Kombination aus Buchstaben und Zahlen. Wichtig f\u00fcr die eindeutige Zuordnung der Reise.\", \"von\": \"Abflug- oder Abfahrtsort (z. B. ''Frankfurt (FRA)'', ''Berlin Hbf''). Format: Stadtname mit optionalem IATA-Code oder Bahnhofsk\u00fcrzel.\", \"nach\": \"Ankunftsort (z. B. ''New York (JFK)'', ''M\u00fcnchen Hbf''). Format: Stadtname mit optionalem IATA-Code oder Bahnhofsk\u00fcrzel.\", \"datum\": \"Datum der Abreise im Format TT.MM.JJJJ oder JJJJ-MM-TT (z. B. ''15.12.2023''). Wichtig f\u00fcr die zeitliche Einordnung der Reise.\", \"uhrzeit\": \"Uhrzeit der Abreise im Format HH:MM (z. B. ''14:30''). Kann auch als ''Boarding-Zeit'' oder ''Abfahrt'' angegeben sein.\", \"sitzplatz\": \"Sitzplatznummer (z. B. ''12A'', ''45''). Format: Kombination aus Zahl und optionalem Buchstaben. Wichtig f\u00fcr die Sitzplatzreservierung.\", \"buchungscode\": \"Buchungscode oder PNR (Passenger Name Record), z. B. ''ABC123''. Format: 5-6 alphanumerische Zeichen. Wichtig f\u00fcr die Zuordnung zur Buchung und ggf. f\u00fcr Erstattungen.\", \"fluggesellschaft_bahnunternehmen\": \"Name der Airline (z. B. ''Lufthansa'') oder des Bahnunternehmens (z. B. ''Deutsche Bahn''). Wichtig f\u00fcr die Zuordnung des Dienstleisters.\", \"klasse\": \"Buchungsklasse (z. B. ''Economy'', ''Business'', ''1. Klasse''). Format: Text oder K\u00fcrzel (z. B. ''Y'' f\u00fcr Economy). Kann f\u00fcr steuerliche Zwecke relevant sein, wenn die Reise beruflich veranlasst ist (z. B. \u00a7 4 Abs. 4 EStG).\", \"_meta\": \"Metadaten wie Erstellungsdatum des Dokuments oder digitale Signaturen. Wird nicht extrahiert, da nicht inhaltlich relevant.\"}"',
    'Boarding Pass, Fahrkarte, Flugticket, Zugticket, Busfahrschein, Flugnummer, Zugnummer, Abflug, Ankunft, Departure, Arrival, Gate, Sitzplatz, Seat, Buchungscode, PNR, Fluggesellschaft, Bahnunternehmen, Klasse, Klasse, Klasse, Datum, Uhrzeit, Von, Nach, Passenger, Passagier, E-Ticket, Online-Check-in, Check-in',
    'Airlines, DB, Flixbus',
    NULL,
    0,
    1,
    1,
    'mistral_batch',
    'Häufige Verwechslungen: Boarding Passes werden oft mit Buchungsbestätigungen oder Rechnungen verwechselt. Ein Boarding Pass enthält immer konkrete Reiseinformationen wie Sitzplatz und Abflugzeit, während eine Buchungsbestätigung allgemeiner ist. Bei beruflichen Reisen kann der Boarding Pass als Nachweis für Reisekosten dienen (z. B. für Flugtickets oder Bahnfahrten), ist aber allein nicht ausreichend – hierfür wird zusätzlich eine Rechnung oder ein Ticket benötigt. Digitale Boarding Passes (z. B. als PDF oder in Apps) sind ebenso gültig wie gedruckte Versionen.'
)
ON CONFLICT (id) DO UPDATE SET category=EXCLUDED.category, display_name=EXCLUDED.display_name, description=EXCLUDED.description, schema=EXCLUDED.schema, field_descriptions=EXCLUDED.field_descriptions, classify_keywords=EXCLUDED.classify_keywords, typical_senders=EXCLUDED.typical_senders, steuer_relevanz=EXCLUDED.steuer_relevanz, priority=EXCLUDED.priority, enabled=EXCLUDED.enabled, version=EXCLUDED.version, source=EXCLUDED.source, notes=EXCLUDED.notes;

INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'broadcasting_fee',
    'M. Sonstiges',
    'Rundfunkbeitrag',
    'Der Rundfunkbeitrag ist eine gesetzliche Abgabe in Deutschland, die von jedem Haushalt zur Finanzierung des öffentlich-rechtlichen Rundfunks (ARD, ZDF, Deutschlandradio) erhoben wird. Das Dokument ist der jährliche oder quartalsweise Bescheid über die Beitragspflicht und den zu zahlenden Betrag. Im Gegensatz zu Gebührenbescheiden (z. B. GEZ) handelt es sich um eine pauschale Haushaltsabgabe, die unabhängig von der Nutzung oder Anzahl der Geräte fällig wird.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "Broadcasting Fee", "description": "Schema for extracting broadcasting fee document data", "type": "object", "properties": {"beitragsnummer": {"description": "Unique contribution number", "type": "string"}, "betrag": {"description": "Amount to be paid", "type": "string", "pattern": "^\\d{1,10}\\.\\d{2}$"}, "zeitraum": {"description": "Billing period", "type": "object", "properties": {"von": {"description": "Start date of the period (YYYY-MM-DD)", "type": "string", "format": "date"}, "bis": {"description": "End date of the period (YYYY-MM-DD)", "type": "string", "format": "date"}}, "required": ["von", "bis"]}, "beitragspflichtiger": {"description": "Person liable to pay the contribution", "type": "object", "properties": {"name": {"description": "Full name of the person", "type": "string"}, "adresse": {"description": "Address of the person", "type": "object", "properties": {"strasse": {"description": "Street name and number", "type": "string"}, "plz": {"description": "Postal code", "type": "string"}, "ort": {"description": "City or town", "type": "string"}, "land": {"description": "Country code (ISO 3166-1 alpha-2)", "type": "string", "pattern": "^[A-Z]{2}$"}}, "required": ["strasse", "plz", "ort", "land"]}}, "required": ["name", "adresse"]}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean", "default": false}, "steuerrelevanz_hinweis": {"type": "string", "default": null}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "default": null}, "steuerjahr": {"description": "Tax year (YYYY)", "type": "string", "pattern": "^\\d{4}$", "default": null}, "mwst_ausgewiesen": {"type": "boolean", "default": false}, "mwst_betrag": {"type": "string", "pattern": "^\\d{1,10}\\.\\d{2}$", "default": null}, "mwst_satz": {"type": "string", "default": null}, "aktenzeichen": {"type": "string", "default": null}, "dokumenten_id": {"type": "string", "default": null}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}, "positionen": {"type": "array", "description": "Einzelpositionen des Rundfunkbeitrags (Monatsbeitr\u00e4ge, R\u00fcckst\u00e4nde, etc.)", "items": {"type": "object", "properties": {"beschreibung": {"type": "string"}, "zeitraum": {"type": "string"}, "betrag": {"type": "string"}}}}}, "required": ["beitragsnummer", "betrag", "zeitraum", "beitragspflichtiger"]}',
    '"{\"beitragsnummer\": \"Eindeutige Identifikationsnummer des Beitragskontos, meist 11-stellig (z. B. ''DE123456789''). Wird f\u00fcr R\u00fcckfragen oder \u00c4nderungen beim Beitragsservice ben\u00f6tigt. Format: Alphanumerisch, beginnt oft mit ''DE''.\", \"betrag\": \"Der zu zahlende Betrag pro Monat oder Quartal, typischerweise 18,36 \u20ac (Stand 2024). Wird als Dezimalzahl mit zwei Nachkommastellen angegeben (z. B. ''18.36''). Wichtig f\u00fcr die Dokumentation, falls der Beitrag als haushaltsnahe Dienstleistung geltend gemacht wird (selten, da meist nicht steuerrelevant).\", \"zeitraum\": \"Der Zeitraum, f\u00fcr den der Beitrag f\u00e4llig ist, z. B. ''01.01.2024 \u2013 31.03.2024'' oder ''2024''. Format: Datum im Format TT.MM.JJJJ oder Jahreszahl. Wichtig f\u00fcr die Zuordnung der Zahlung zum richtigen Kalenderjahr.\", \"beitragspflichtiger\": \"Name der Person, die als Beitragspflichtiger im Bescheid genannt wird. Meist der Haushaltsvorstand oder die im Mietvertrag genannte Person. Format: Vor- und Nachname (z. B. ''Max Mustermann''). Relevant f\u00fcr die Identifikation des Zahlungspflichtigen.\"}"',
    'Rundfunkbeitrag, Rundfunkgebühr, Beitragsbescheid, ARD ZDF Deutschlandradio Beitragsservice, Beitragsnummer, Beitragskonto, Haushaltsabgabe, öffentlich-rechtlicher Rundfunk, Beitragspflicht, Zahlungsaufforderung, Bescheid, Beitragszeitraum, Beitragshöhe, 18,36 Euro, Beitragsjahr, Beitragspflichtiger, GEZ, broadcasting fee, license fee, public broadcasting',
    'ARD ZDF Deutschlandradio',
    NULL,
    0,
    1,
    1,
    'mistral_batch',
    'Häufige Verwechslung mit alten GEZ-Bescheiden (vor 2013), die geräteabhängig waren. Der Rundfunkbeitrag ist seit 2013 eine pauschale Haushaltsabgabe. Sonderfälle: Befreiungen oder Ermäßigungen (z. B. für Sozialhilfeempfänger) werden separat bescheinigt. Tipp: Der Bescheid enthält oft einen QR-Code für Online-Zahlungen oder Kontenverwaltung. Nicht mit Rechnungen für private Streaming-Dienste verwechseln.'
)
