INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'church_tax_notice',
    'M. Sonstiges',
    'Kirchensteuerbescheid',
    'Der Kirchensteuerbescheid ist ein amtliches Dokument, das von Finanzämtern oder kirchlichen Steuerstellen an Mitglieder einer steuererhebenden Religionsgemeinschaft versendet wird. Es bestätigt die Höhe der festgesetzten Kirchensteuer für ein bestimmtes Steuerjahr, basierend auf der Einkommensteuer oder Lohnsteuer des Steuerpflichtigen. Im Gegensatz zur regulären Einkommensteuererklärung oder Lohnsteuerbescheinigung bezieht sich dieses Dokument ausschließlich auf die zusätzliche Abgabe an die Kirche und enthält spezifische Angaben zur Konfession und Bemessungsgrundlage.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "church_tax_notice", "description": "Kirchensteuerbescheid", "type": "object", "properties": {"aktenzeichen": {"type": "string", "description": "Aktenzeichen des Kirchensteuerbescheids"}, "steuerpflichtiger": {"type": "object", "description": "Angaben zum Steuerpflichtigen", "properties": {"name": {"type": "string", "description": "Name des Steuerpflichtigen"}, "adresse": {"type": "object", "description": "Adresse des Steuerpflichtigen", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "default": "DE"}}, "required": ["strasse", "plz", "ort"]}}, "required": ["name", "adresse"]}, "steuerjahr": {"type": "string", "description": "Steuerjahr (YYYY)", "pattern": "^[0-9]{4}$"}, "konfession": {"type": "string", "description": "Konfession des Steuerpflichtigen (z.B. ev, rk)"}, "kirchensteuer_betrag": {"type": "string", "description": "Betrag der Kirchensteuer (Format: 49.99)", "pattern": "^[0-9]+\\.[0-9]{2}$"}, "bemessungsgrundlage": {"type": "string", "description": "Bemessungsgrundlage f\u00fcr die Kirchensteuer (Format: 49.99)", "pattern": "^[0-9]+\\.[0-9]{2}$"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean", "default": true}, "steuerrelevanz_hinweis": {"type": "string", "default": "Kirchensteuer ist als Sonderausgabe abziehbar."}, "steuer_kategorie": {"type": "string", "enum": ["sonderausgaben", null], "default": "sonderausgaben"}, "steuerjahr": {"type": "string", "pattern": "^[0-9]{4}$"}, "mwst_ausgewiesen": {"type": "boolean", "default": false}, "mwst_betrag": {"type": "string", "default": null}, "mwst_satz": {"type": "string", "default": null}, "aktenzeichen": {"type": "string"}, "dokumenten_id": {"type": "string", "default": null}}, "required": ["steuerrelevant", "steuerrelevanz_hinweis", "steuer_kategorie", "mwst_ausgewiesen"]}, "positionen": {"type": "array", "description": "Einzelpositionen des Kirchensteuerbescheids", "items": {"type": "object", "properties": {"steuerart": {"type": "string"}, "bemessungsgrundlage": {"type": "string"}, "steuerbetrag": {"type": "string"}}}}}, "required": ["aktenzeichen", "steuerpflichtiger", "steuerjahr", "konfession", "kirchensteuer_betrag", "bemessungsgrundlage", "_meta"]}',
    '"{\"aktenzeichen\": \"Amtliches Aktenzeichen des Finanzamts oder der kirchlichen Steuerstelle, z.B. ''KiSt 2023/4711''. Wichtig f\u00fcr Nachfragen oder Widerspr\u00fcche. Format: alphanumerisch, oft mit Jahreszahl und laufender Nummer.\", \"steuerpflichtiger\": \"Name und Adresse der Person, f\u00fcr die die Kirchensteuer festgesetzt wird. Beispiel: ''Max Mustermann, Musterstra\u00dfe 1, 12345 Musterstadt''. Wichtig zur Identifikation des Steuerpflichtigen.\", \"steuerjahr\": \"Das Jahr, f\u00fcr das die Kirchensteuer festgesetzt wird, z.B. ''2023''. Format: vierstellige Jahreszahl. Relevant f\u00fcr die Zuordnung zur korrekten Steuererkl\u00e4rung.\", \"konfession\": \"Religionsgemeinschaft, der der Steuerpflichtige angeh\u00f6rt, z.B. ''evangelisch'', ''r\u00f6misch-katholisch'', ''israelitische Kultusgemeinde''. Wichtig f\u00fcr die steuerliche Ber\u00fccksichtigung, da nur bestimmte Konfessionen kirchensteuerpflichtig sind.\", \"kirchensteuer_betrag\": \"H\u00f6he der festgesetzten Kirchensteuer in Euro, z.B. ''123,45''. Format: numerisch mit zwei Nachkommastellen. Dieser Betrag ist in der Steuererkl\u00e4rung als Sonderausgabe absetzbar (\u00a710 Abs. 1 Nr. 4 EStG).\", \"bemessungsgrundlage\": \"Grundlage f\u00fcr die Berechnung der Kirchensteuer, meist die festgesetzte Einkommensteuer oder Lohnsteuer, z.B. ''5.000,00''. Format: numerisch mit zwei Nachkommastellen. Wichtig f\u00fcr die \u00dcberpr\u00fcfung der korrekten Berechnung der Kirchensteuer.\"}"',
    'Kirchensteuerbescheid, Kirchensteuer, Konfession, Bemessungsgrundlage, Kirchensteuerbetrag, Steuerjahr, Finanzamt, aktenzeichen, evangelisch, katholisch, israelitisch, Kirchenmitgliedschaft, Kirchensteuerpflicht, Festsetzung, Bescheid, Einkommensteuer, Lohnsteuer, church tax notice, denomination, tax assessment, ecclesiastical tax',
    'Finanzamt',
    '{"paragraphen": "§10 Abs. 1 Nr. 4 EStG (Sonderausgabenabzug für Kirchensteuer)", "anlage": "Anlage Vorsorgeaufwand (Zeile 45-48 für Kirchensteuer)", "absetzbar": "Kirchensteuerbetrag in voller Höhe als Sonderausgabe absetzbar, keine betragliche Begrenzung"}',
    0,
    1,
    1,
    'mistral_batch',
    'Häufige Verwechslungen: Der Kirchensteuerbescheid wird oft mit dem Einkommensteuerbescheid verwechselt, da beide vom Finanzamt stammen können. Der Unterschied liegt darin, dass der Kirchensteuerbescheid ausschließlich die Kirchensteuer betrifft und Angaben zur Konfession enthält. Sonderfälle: In einigen Bundesländern (z.B. Bayern, Baden-Württemberg) wird die Kirchensteuer direkt von der Kirche festgesetzt und erhoben, nicht vom Finanzamt. In diesen Fällen kann der Absender eine kirchliche Steuerstelle sein. Tipp: Kirchensteuerbescheide sind besonders relevant für Steuererklärungen, da die gezahlte Kirchensteuer in voller Höhe als Sonderausgabe absetzbar ist.'
)
