INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'cv',
    'M. Sonstiges',
    'Lebenslauf/CV',
    'Ein Lebenslauf (CV) ist ein Dokument, das von Bewerbern erstellt wird, um ihre beruflichen und akademischen Qualifikationen, Erfahrungen und Fähigkeiten darzustellen. Es wird typischerweise bei Bewerbungen für Jobs, Praktika oder Ausbildungen eingereicht. Im Gegensatz zu einem Anschreiben, das motivationsbezogen ist, listet der Lebenslauf strukturiert Fakten wie Berufserfahrung, Ausbildung und Skills auf.',
    '{"type": "object", "description": "Lebenslauf / Curriculum Vitae \u2014 vollst\u00e4ndige Extraktion aller Abschnitte", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "default": "DE"}}}, "telefon": {"type": "string", "description": "E.164 oder wie im Dokument"}, "email": {"type": "string", "format": "email"}, "website": {"type": "string", "description": "URL falls vorhanden"}, "linkedin": {"type": "string", "description": "LinkedIn-Profil URL"}, "xing": {"type": "string", "description": "Xing-Profil URL"}, "geburtsdatum": {"type": "string", "format": "date"}, "geburtsort": {"type": "string"}, "familienstand": {"type": "string"}, "kinder": {"type": "string", "description": "Angaben zu Kindern falls erw\u00e4hnt"}, "foto_vorhanden": {"type": "boolean"}, "datum_lebenslauf": {"type": "string", "format": "date", "description": "Datum der Erstellung/Unterschrift"}, "berufserfahrung": {"type": "array", "items": {"type": "object", "properties": {"position": {"type": "string"}, "arbeitgeber": {"type": "string"}, "ort": {"type": "string"}, "von": {"type": "string", "description": "MM.YYYY oder YYYY"}, "bis": {"type": "string", "description": "MM.YYYY oder ''heute''/''aktuell''"}, "beschreibung": {"type": "string", "description": "Aufgaben und Verantwortlichkeiten"}, "erfolge": {"type": "array", "items": {"type": "string"}, "description": "Konkrete Erfolge/Ergebnisse"}}}}, "ausbildung": {"type": "array", "items": {"type": "object", "properties": {"institution": {"type": "string"}, "abschluss": {"type": "string"}, "ort": {"type": "string"}, "von": {"type": "string"}, "bis": {"type": "string"}, "note": {"type": "string"}, "schwerpunkte": {"type": "array", "items": {"type": "string"}}}}}, "zertifikate": {"type": "array", "items": {"type": "object", "properties": {"name": {"type": "string"}, "aussteller": {"type": "string"}, "datum": {"type": "string"}}}}, "kenntnisse": {"type": "object", "description": "Kategorisierte Fachkenntnisse", "properties": {"management": {"type": "array", "items": {"type": "object", "properties": {"bereich": {"type": "string"}, "niveau": {"type": "string"}}}}, "it_tools": {"type": "array", "items": {"type": "object", "properties": {"kategorie": {"type": "string"}, "tools": {"type": "array", "items": {"type": "string"}}}}}, "methoden": {"type": "array", "items": {"type": "string"}}, "branchen": {"type": "array", "items": {"type": "string"}}}}, "sprachen": {"type": "array", "items": {"type": "object", "properties": {"sprache": {"type": "string"}, "niveau": {"type": "string", "description": "muttersprache, verhandlungssicher, fliessend, grundkenntnisse, A1-C2"}}}}, "fuehrerschein": {"type": "string"}, "interessen": {"type": "array", "items": {"type": "string"}}, "ehrenamt": {"type": "array", "items": {"type": "object", "properties": {"taetigkeit": {"type": "string"}, "organisation": {"type": "string"}, "zeitraum": {"type": "string"}}}}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean", "default": false}, "dokumenten_id": {"type": "string"}, "aktenzeichen": {"type": "string"}}}}}',
    '"{\"name\": \"Vollst\u00e4ndiger Name des Bewerbers, Format: Vorname Nachname. Beispiel: Max Mustermann.\", \"adresse\": \"Aktuelle Wohnadresse des Bewerbers, inkl. Stra\u00dfe, Hausnummer, Postleitzahl, Ort und optional Land. Beispiel: Musterstra\u00dfe 1, 12345 Musterstadt, Deutschland.\", \"telefon\": \"Kontakttelefonnummer des Bewerbers, oft mit L\u00e4ndervorwahl. Beispiel: +49 123 456789.\", \"email\": \"E-Mail-Adresse des Bewerbers, Format: lokalteil@domain.tld. Beispiel: max.mustermann@example.com.\", \"website\": \"Pers\u00f6nliche Website oder Portfolio des Bewerbers, falls vorhanden. Beispiel: www.mustermann-portfolio.de.\", \"linkedin\": \"LinkedIn-Profil-URL des Bewerbers, falls vorhanden. Beispiel: linkedin.com/in/maxmustermann.\", \"xing\": \"XING-Profil-URL des Bewerbers, falls vorhanden. Beispiel: xing.com/profile/max_mustermann.\", \"geburtsdatum\": \"Geburtsdatum des Bewerbers, Format: TT.MM.JJJJ oder JJJJ-MM-TT. Beispiel: 01.01.1990.\", \"geburtsort\": \"Geburtsort des Bewerbers, oft inkl. Land. Beispiel: Musterstadt, Deutschland.\", \"familienstand\": \"Familienstand des Bewerbers, z. B. ledig, verheiratet, geschieden. Beispiel: ledig.\", \"kinder\": \"Anzahl der Kinder des Bewerbers, falls relevant. Beispiel: 2.\", \"foto_vorhanden\": \"Boolescher Wert (true/false), ob ein Bewerbungsfoto im Lebenslauf enthalten ist. Beispiel: true.\", \"datum_lebenslauf\": \"Datum der Erstellung oder letzten Aktualisierung des Lebenslaufs, Format: TT.MM.JJJJ. Beispiel: 15.05.2023.\", \"berufserfahrung\": \"Liste der beruflichen Stationen mit Arbeitgeber, Position, Zeitraum (von/bis) und optional Beschreibung der T\u00e4tigkeiten. Beispiel: [{''arbeitgeber'': ''Muster GmbH'', ''position'': ''Projektmanager'', ''von'': ''01.2018'', ''bis'': ''12.2022'', ''beschreibung'': ''Verantwortlich f\u00fcr...''}]\", \"ausbildung\": \"Liste der akademischen oder schulischen Ausbildungen mit Institution, Abschluss, Zeitraum (von/bis) und optional Note. Beispiel: [{''institution'': ''Muster-Universit\u00e4t'', ''abschluss'': ''Bachelor of Science'', ''von'': ''10.2014'', ''bis'': ''09.2017'', ''note'': ''1,7''}]\"}"',
    'Lebenslauf, CV, Curriculum Vitae, Berufserfahrung, Ausbildung, Skills, Kenntnisse, Sprachen, Zertifikate, Arbeitgeber, Position, Abschluss, Note, Hobbys, Ehrenamt, Führerschein, Bewerbung, Personalien, Berufsweg, career, work experience, education, certificates, languages, interests, voluntary work',
    'Bewerber',
    NULL,
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
