INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'disability_card',
    'M. Sonstiges',
    'Schwerbehindertenausweis/-bescheid',
    'Der Schwerbehindertenausweis oder -bescheid ist ein amtliches Dokument, das vom Versorgungsamt ausgestellt wird und den Grad der Behinderung (GdB) sowie eventuelle Merkzeichen bestätigt. Er dient als Nachweis für Ansprüche auf Nachteilsausgleiche wie Steuerermäßigungen, Parkerleichterungen oder vergünstigte Fahrkarten. Im Gegensatz zu ärztlichen Attesten oder Reha-Bescheiden ist er der offizielle Nachweis für den Schwerbehindertenstatus nach § 2 SGB IX.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "disability_card", "description": "Schwerbehindertenausweis/-bescheid", "type": "object", "properties": {"aktenzeichen": {"type": "string", "description": "Aktenzeichen des Bescheids"}, "name": {"type": "string", "description": "Name der schwerbehinderten Person"}, "grad_der_behinderung": {"type": "integer", "description": "Grad der Behinderung (GdB) in Prozent", "minimum": 20, "maximum": 100}, "merkzeichen": {"type": "array", "description": "Liste der Merkzeichen", "items": {"type": "string", "enum": ["G", "aG", "B", "H", "Bl", "Gl", "TBl", "VB", "EB", "1.Kl"]}}, "gueltig_ab": {"type": "string", "format": "date", "description": "G\u00fcltigkeitsbeginn (YYYY-MM-DD)"}, "gueltig_bis": {"type": "string", "format": "date", "description": "G\u00fcltigkeitsende (YYYY-MM-DD)"}, "naechste_ueberpruefung": {"type": "string", "format": "date", "description": "Datum der n\u00e4chsten \u00dcberpr\u00fcfung (YYYY-MM-DD)", "nullable": true}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean", "description": "Gibt an, ob das Dokument steuerrelevant ist"}, "steuerrelevanz_hinweis": {"type": "string", "description": "Hinweis zur Steuerrelevanz", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "description": "Steuerkategorie", "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^[0-9]{4}$", "description": "Steuerjahr (YYYY)", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean", "description": "Gibt an, ob Mehrwertsteuer ausgewiesen ist"}, "mwst_betrag": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$", "description": "Mehrwertsteuerbetrag (z.B. 19.00)", "nullable": true}, "mwst_satz": {"type": "string", "description": "Mehrwertsteuersatz (z.B. 19%)", "nullable": true}, "aktenzeichen": {"type": "string", "description": "Aktenzeichen (wiederholt f\u00fcr Meta-Daten)", "nullable": true}, "dokumenten_id": {"type": "string", "description": "Eindeutige Dokumenten-ID", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}}, "required": ["aktenzeichen", "name", "grad_der_behinderung", "gueltig_ab", "gueltig_bis", "_meta"]}',
    '"{\"aktenzeichen\": \"Amtliches Aktenzeichen des Versorgungsamts, z.B. ''L 123456/2023''. Wichtig f\u00fcr Nachweise gegen\u00fcber Beh\u00f6rden und zur Identifikation des Bescheids.\", \"name\": \"Vollst\u00e4ndiger Name der schwerbehinderten Person, wie im Ausweis angegeben, z.B. ''Max Mustermann''. Wird f\u00fcr die Zuordnung in der Steuererkl\u00e4rung ben\u00f6tigt.\", \"grad_der_behinderung\": \"Numerischer Wert des Grades der Behinderung (GdB), z.B. ''50'' oder ''80''. Entscheidend f\u00fcr die H\u00f6he des Behinderten-Pauschbetrags nach \u00a733b EStG.\", \"merkzeichen\": \"Liste der anerkannten Merkzeichen (z.B. [''G'', ''aG'', ''H'', ''Bl'']). Jedes Merkzeichen kann zus\u00e4tzliche steuerliche oder sonstige Nachteilsausgleiche begr\u00fcnden, z.B. ''H'' oder ''Bl'' f\u00fcr den erh\u00f6hten Pauschbetrag von 7.400\u20ac.\", \"gueltig_ab\": \"Datum, ab dem der Ausweis/Bescheid g\u00fcltig ist, im Format ''YYYY-MM-DD'', z.B. ''2023-01-15''. Relevant f\u00fcr die zeitliche Zuordnung in der Steuererkl\u00e4rung.\", \"gueltig_bis\": \"Datum, bis zu dem der Ausweis/Bescheid g\u00fcltig ist, im Format ''YYYY-MM-DD'', z.B. ''2028-01-14''. Wichtig f\u00fcr die Pr\u00fcfung der G\u00fcltigkeit bei Steuererkl\u00e4rung oder Beantragung von Leistungen.\"}"',
    'Schwerbehindertenausweis, Schwerbehindertenbescheid, Versorgungsamt, Grad der Behinderung, GdB, Merkzeichen, G, aG, B, H, Bl, Gl, TBl, Nachteilsausgleich, Parkerleichterung, §2 SGB IX, disability card, degree of disability, validity period, Aktenzeichen, nächste Überprüfung, gültig ab, gültig bis',
    'Versorgungsamt',
    '{"paragraphen": "§33b EStG (Behinderten-Pauschbetrag), §33 EStG (außergewöhnliche Belastungen)", "anlage": "Anlage Behinderten-Pauschbetrag (früher Anlage „Außergewöhnliche Belastungen“)", "absetzbare_betraege": {"pauschbetrag": "Je nach GdB: 384€ (GdB 20-40), 620€ (GdB 50), 1.140€ (GdB 60), 1.440€ (GdB 70), 1.780€ (GdB 80), 2.840€ (GdB 90-100). Bei Merkzeichen H oder Bl: 7.400€ (unabhängig vom GdB).", "hinweis": "Alternativ können tatsächliche behinderungsbedingte Aufwendungen nach §33 EStG geltend gemacht werden, falls höher als der Pauschbetrag."}}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
ON CONFLICT (id) DO UPDATE SET category=EXCLUDED.category, display_name=EXCLUDED.display_name, description=EXCLUDED.description, schema=EXCLUDED.schema, field_descriptions=EXCLUDED.field_descriptions, classify_keywords=EXCLUDED.classify_keywords, typical_senders=EXCLUDED.typical_senders, steuer_relevanz=EXCLUDED.steuer_relevanz, priority=EXCLUDED.priority, enabled=EXCLUDED.enabled, version=EXCLUDED.version, source=EXCLUDED.source, notes=EXCLUDED.notes;

INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'donation_receipt',
    'M. Sonstiges',
    'Spendenquittung',
    'Eine Spendenquittung (auch Spendenbescheinigung genannt) ist ein Dokument, das von gemeinnützigen Organisationen ausgestellt wird, um eine Geld- oder Sachspende zu bestätigen. Sie dient als Nachweis für steuerliche Zwecke und wird typischerweise einmal jährlich oder nach jeder Spende ausgestellt. Im Gegensatz zu einfachen Spendenbestätigungen (z. B. per E-Mail) ist die Spendenquittung ein formelles Dokument mit spezifischen Pflichtangaben nach § 50 EStDV.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "donation_receipt", "description": "Spendenquittung", "type": "object", "properties": {"empfaenger": {"type": "object", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort", "land"]}, "steuernummer": {"type": "string"}, "vr_number": {"type": "string"}}, "required": ["name", "adresse"]}, "spender": {"type": "object", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort", "land"]}}, "required": ["name", "adresse"]}, "betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}, "datum": {"type": "string", "format": "date"}, "zweck": {"type": "string"}, "steuerbeguenstigt": {"type": "boolean"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["spenden", null]}, "steuerjahr": {"type": "string", "pattern": "^\\d{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$", "nullable": true}, "mwst_satz": {"type": "string", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant", "steuerrelevanz_hinweis", "steuer_kategorie", "steuerjahr", "mwst_ausgewiesen", "mwst_betrag", "mwst_satz", "aktenzeichen", "dokumenten_id"]}, "waehrung": {"type": "string", "default": "EUR", "description": "Waehrung ISO 4217 (EUR, USD, etc.)"}}, "required": ["empfaenger", "spender", "betrag", "datum", "zweck", "steuerbeguenstigt", "_meta"]}',
    '"{\"empfaenger\": \"Name und Anschrift der empfangenden Organisation (Verein, Stiftung etc.), die die Spendenquittung ausstellt. Wichtig f\u00fcr die steuerliche Anerkennung, da nur bestimmte Organisationen berechtigt sind, Spendenquittungen auszustellen (z. B. gemeinn\u00fctzige, mildt\u00e4tige oder kirchliche Einrichtungen). Beispiel: ''Deutsches Rotes Kreuz, Ortsverein Berlin, Musterstra\u00dfe 1, 10115 Berlin''.\", \"spender\": \"Name und Anschrift des Spenders (nat\u00fcrliche oder juristische Person). Muss mit dem Kontoinhaber oder dem Einzahler \u00fcbereinstimmen, um die Spende steuerlich geltend machen zu k\u00f6nnen. Beispiel: ''Max Mustermann, Musterweg 2, 12345 Musterstadt''.\", \"betrag\": \"H\u00f6he der Spende in Euro (Bruttobetrag). Bei Sachspenden: gemeiner Wert oder Anschaffungs-/Herstellungskosten. Wichtig f\u00fcr die Berechnung des absetzbaren Betrags in der Steuererkl\u00e4rung. Beispiel: ''50.00'' oder ''100.00''.\", \"datum\": \"Datum der Spende (nicht das Ausstellungsdatum der Quittung!). Muss im Kalenderjahr der Steuererkl\u00e4rung liegen, um abgesetzt werden zu k\u00f6nnen. Format: ISO-8601 (YYYY-MM-DD). Beispiel: ''2023-12-31''.\", \"zweck\": \"Verwendungszweck der Spende (z. B. ''Mitgliedsbeitrag'', ''Projekt XY'', ''allgemeine Spende''). Wichtig f\u00fcr die Zuordnung zu den steuerlichen Kategorien (z. B. mildt\u00e4tig, kirchlich, wissenschaftlich). Beispiel: ''F\u00f6rderung der Jugendhilfe''.\"}"',
    'Spendenquittung, Spendenbescheinigung, Zuwendungsbestätigung, gemeinnützig, steuerbegünstigt, Spende, donation receipt, tax-deductible, § 10b EStG, § 50 EStDV, Empfänger, Spender, Betrag, Zweck, Datum, steuerlich absetzbar, Verein, Stiftung, mildtätig, kirchlich, wissenschaftlich',
    'Vereine, Stiftungen',
    '{"paragraphen": "§ 10b EStG (Sonderausgabenabzug für Spenden), § 50 EStDV (Formvorschriften für Zuwendungsbestätigungen)", "anlage": "Anlage SO (Sonstige Angaben), ggf. auch Anlage Vorsorgeaufwand (wenn Spende an kirchliche Einrichtungen)", "absetzbare_betraege": {"max_betrag": "Bis zu 20% des Gesamtbetrags der Einkünfte oder 4 Promille der Summe der gesamten Umsätze und der im Kalenderjahr aufgewendeten Löhne und Gehälter (für Unternehmen)", "besonderheiten": "Spenden an politische Parteien oder unabhängige Wählervereinigungen unterliegen gesonderten Regelungen (§ 34g EStG). Sachspenden müssen mit dem gemeinen Wert angesetzt werden."}}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
ON CONFLICT (id) DO UPDATE SET category=EXCLUDED.category, display_name=EXCLUDED.display_name, description=EXCLUDED.description, schema=EXCLUDED.schema, field_descriptions=EXCLUDED.field_descriptions, classify_keywords=EXCLUDED.classify_keywords, typical_senders=EXCLUDED.typical_senders, steuer_relevanz=EXCLUDED.steuer_relevanz, priority=EXCLUDED.priority, enabled=EXCLUDED.enabled, version=EXCLUDED.version, source=EXCLUDED.source, notes=EXCLUDED.notes;

INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'fallback',
    'M. Sonstiges',
    'Unbekanntes Dokument',
    'Dieses Template dient als Fallback für Dokumente, die keinem spezifischen Dokumententyp zugeordnet werden können. Es kommt vor, wenn ein Dokument nicht eindeutig klassifiziert werden kann, z.B. aufgrund fehlender oder mehrdeutiger Informationen. Im Gegensatz zu spezifischen Templates enthält es keine vordefinierten Felder für steuerrelevante oder rechtliche Daten, sondern extrahiert allgemeine Metadaten und eine Zusammenfassung des Inhalts.',
    '{"type": "object", "description": "Fallback-Template f\u00fcr unbekannte Dokumenttypen. Extrahiert so viel wie m\u00f6glich.", "properties": {"absender": {"type": "string", "description": "Wer hat das Dokument erstellt/verschickt"}, "empfaenger": {"type": "string", "description": "An wen ist es gerichtet"}, "datum": {"type": "string", "format": "date", "description": "Dokumentdatum YYYY-MM-DD"}, "betreff": {"type": "string", "description": "Worum geht es in einem Satz"}, "dokumenttyp_vermutung": {"type": "string", "description": "Beste Vermutung was f\u00fcr ein Dokumenttyp das ist"}, "zusammenfassung": {"type": "string", "description": "Inhaltszusammenfassung in 2-3 S\u00e4tzen"}, "schluesselwoerter": {"type": "array", "items": {"type": "string"}, "description": "Wichtige Begriffe/Keywords aus dem Dokument"}, "erwaehnter_betrag": {"type": "string", "description": "Geldbetrag falls erw\u00e4hnt (Format: ''49.99'')"}, "erwaehntes_datum": {"type": "string", "description": "Wichtigstes Datum im Dokument (YYYY-MM-DD)"}, "erwaehntes_aktenzeichen": {"type": "string", "description": "Aktenzeichen/Referenznummer falls vorhanden"}, "sprache": {"type": "string", "description": "Sprache des Dokuments (de, en, etc.)"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string"}, "steuer_kategorie": {"type": "string"}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string"}, "aktenzeichen": {"type": "string"}, "dokumenten_id": {"type": "string"}}}}}',
    '"{\"absender\": \"Der Absender des Dokuments, extrahiert aus Kopfzeile oder Signatur. Format: Name/Organisation, Adresse (falls vorhanden). Beispiel: ''Muster GmbH, Musterstra\u00dfe 1, 12345 Musterstadt''. Wichtig f\u00fcr die Zuordnung des Dokuments zu einem bestimmten Kontext oder Absenderkreis.\", \"empfaenger\": \"Der Empf\u00e4nger des Dokuments, extrahiert aus der Empf\u00e4ngerzeile. Format: Name/Organisation, Adresse (falls vorhanden). Beispiel: ''Max Mustermann, Beispielweg 2, 54321 Beispielstadt''. Relevant f\u00fcr die pers\u00f6nliche Zuordnung und Archivierung.\", \"datum\": \"Das Ausstellungs- oder Erstellungsdatum des Dokuments, extrahiert aus dem Dokumententext oder Kopfzeile. Format: ISO-8601 (YYYY-MM-DD). Beispiel: ''2023-10-15''. Wichtig f\u00fcr die zeitliche Einordnung und ggf. Fristen\u00fcberwachung.\", \"betreff\": \"Der Betreff des Dokuments, extrahiert aus der Betreffzeile oder dem einleitenden Satz. Beispiel: ''Ihre Anfrage vom 10.10.2023''. Hilft bei der schnellen inhaltlichen Einordnung.\", \"dokumenttyp_vermutung\": \"Eine automatische Vermutung des Dokumententyps basierend auf Schl\u00fcsselw\u00f6rtern oder Struktur. Beispiel: ''Rechnung'', ''Vertrag'', ''Mitteilung''. Dient als Hinweis f\u00fcr eine manuelle Nachklassifizierung.\", \"zusammenfassung\": \"Eine kurze, automatische Zusammenfassung des Dokumenteninhalts in 1-3 S\u00e4tzen. Beispiel: ''Das Schreiben informiert \u00fcber eine \u00c4nderung der Gesch\u00e4ftsbedingungen zum 01.11.2023.''. Erm\u00f6glicht eine schnelle inhaltliche Erfassung ohne das gesamte Dokument lesen zu m\u00fcssen.\", \"schluesselwoerter\": \"Eine Liste von Schl\u00fcsselw\u00f6rtern, die im Dokument vorkommen und dessen Inhalt charakterisieren. Beispiel: [''Gesch\u00e4ftsbedingungen'', ''\u00c4nderung'', ''K\u00fcndigung'', ''Frist'']. Unterst\u00fctzt die Suche und Klassifizierung.\", \"erwaehnter_betrag\": \"Ein im Dokument erw\u00e4hnter Geldbetrag, extrahiert aus dem Text. Format: Zahl mit W\u00e4hrung (z.B. ''199,99 EUR''). Beispiel: ''Der Rechnungsbetrag bel\u00e4uft sich auf 199,99 EUR.''. Kann Hinweis auf steuerrelevante oder vertragliche Inhalte geben.\", \"erwaehntes_datum\": \"Ein im Dokument erw\u00e4hntes Datum, das nicht das Ausstellungsdatum ist. Format: ISO-8601 (YYYY-MM-DD). Beispiel: ''Die Frist endet am 2023-11-30.''. Wichtig f\u00fcr Fristen\u00fcberwachung oder zeitliche Einordnung von Ereignissen.\", \"erwaehntes_aktenzeichen\": \"Ein im Dokument erw\u00e4hntes Aktenzeichen oder Referenznummer. Beispiel: ''Az.: 2023-4711''. Relevant f\u00fcr die Zuordnung zu Vorg\u00e4ngen oder die Kommunikation mit Beh\u00f6rden/Organisationen.\"}"',
    'unbekannt, nicht klassifizierbar, allgemeines Dokument, diverse Absender, Dokument, Schreiben, Rechnung, Brief, Mitteilung, unknown, unclassified, document, summary, keywords, sender, recipient, date, subject, mentioned amount, mentioned date, file reference',
    'Diverse',
    NULL,
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
ON CONFLICT (id) DO UPDATE SET category=EXCLUDED.category, display_name=EXCLUDED.display_name, description=EXCLUDED.description, schema=EXCLUDED.schema, field_descriptions=EXCLUDED.field_descriptions, classify_keywords=EXCLUDED.classify_keywords, typical_senders=EXCLUDED.typical_senders, steuer_relevanz=EXCLUDED.steuer_relevanz, priority=EXCLUDED.priority, enabled=EXCLUDED.enabled, version=EXCLUDED.version, source=EXCLUDED.source, notes=EXCLUDED.notes;

INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'insurance_card',
    'M. Sonstiges',
    'Versicherungskarte (eVB)',
    'Die elektronische Versicherungsbestätigung (eVB) ist ein Nachweis für die Kfz-Haftpflichtversicherung in Deutschland, der bei der Zulassung oder Ummeldung eines Fahrzeugs benötigt wird. Sie wird von der Versicherung ausgestellt und enthält eine eindeutige eVB-Nummer sowie Details zum Versicherungsnehmer und Fahrzeug. Im Gegensatz zu einer Police oder Beitragsrechnung dient die eVB ausschließlich als temporärer Nachweis für Behörden (z. B. Zulassungsstelle) und ist nicht für den Versicherungsschutz selbst relevant.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "Insurance Card (eVB) Extraction Template", "type": "object", "properties": {"evb_nummer": {"type": "string", "description": "Elektronische Versicherungsbest\u00e4tigungsnummer (eVB-Nummer)"}, "versicherungsnehmer": {"type": "object", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "pattern": "^[A-Z]{2}$"}}, "required": ["strasse", "plz", "ort", "land"]}}, "required": ["name", "adresse"]}, "fahrzeug": {"type": "object", "properties": {"hersteller": {"type": "string"}, "modell": {"type": "string"}, "fin": {"type": "string", "description": "Fahrzeug-Identifizierungsnummer"}, "erstzulassung": {"type": "string", "format": "date", "description": "Datum der Erstzulassung (YYYY-MM-DD)"}}, "required": ["hersteller", "modell", "fin"]}, "kennzeichen": {"type": "string", "description": "Amtliches Kennzeichen des Fahrzeugs"}, "gueltig_ab": {"type": "string", "format": "date", "description": "G\u00fcltigkeitsbeginn der Versicherung (YYYY-MM-DD)"}, "gueltig_bis": {"type": "string", "format": "date", "description": "G\u00fcltigkeitsende der Versicherung (YYYY-MM-DD)"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean", "default": false}, "steuerrelevanz_hinweis": {"type": "string", "default": null}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "default": null}, "steuerjahr": {"type": "string", "pattern": "^[0-9]{4}$", "default": null}, "mwst_ausgewiesen": {"type": "boolean", "default": false}, "mwst_betrag": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$", "default": null}, "mwst_satz": {"type": "string", "default": null}, "aktenzeichen": {"type": "string", "default": null}, "dokumenten_id": {"type": "string", "default": null}}, "required": ["steuerrelevant", "steuerrelevanz_hinweis", "steuer_kategorie", "steuerjahr", "mwst_ausgewiesen", "mwst_betrag", "mwst_satz"]}}, "required": ["evb_nummer", "versicherungsnehmer", "fahrzeug", "kennzeichen", "gueltig_ab", "gueltig_bis", "_meta"]}',
    '"{\"evb_nummer\": \"Die eindeutige 7-stellige Versicherungsbest\u00e4tigungsnummer (eVB-Nummer), z. B. ''X123456''. Wird f\u00fcr die Fahrzeugzulassung ben\u00f6tigt und dient als tempor\u00e4rer Nachweis der Kfz-Haftpflichtversicherung. Nicht steuerrelevant, aber f\u00fcr beh\u00f6rdliche Prozesse essenziell.\", \"versicherungsnehmer\": \"Name und Adresse der Person oder Firma, auf die die Versicherung l\u00e4uft, z. B. ''Max Mustermann, Musterstra\u00dfe 1, 12345 Berlin''. Wichtig f\u00fcr die Identifikation bei der Zulassungsstelle, aber nicht direkt steuerrelevant.\", \"fahrzeug\": \"Details zum versicherten Fahrzeug, meist Marke, Modell und Fahrzeugtyp, z. B. ''VW Golf 1.6 TDI''. Wird f\u00fcr die Zuordnung zur eVB-Nummer ben\u00f6tigt, aber nicht f\u00fcr steuerliche Zwecke.\", \"kennzeichen\": \"Das amtliche Kennzeichen des Fahrzeugs, falls bereits zugeteilt, z. B. ''B-AB 1234''. Bei Neuzulassungen oft noch leer. Relevant f\u00fcr die Zulassung, aber nicht f\u00fcr die Steuererkl\u00e4rung.\", \"gueltig_ab\": \"Startdatum der G\u00fcltigkeit der eVB, z. B. ''01.01.2024''. Die eVB ist typischerweise nur wenige Wochen g\u00fcltig und dient als tempor\u00e4rer Nachweis. Nicht steuerrelevant.\", \"gueltig_bis\": \"Enddatum der G\u00fcltigkeit der eVB, z. B. ''31.01.2024''. Nach diesem Datum verliert die eVB ihre G\u00fcltigkeit f\u00fcr beh\u00f6rdliche Zwecke. Nicht steuerrelevant.\"}"',
    'eVB-Nummer, elektronische Versicherungsbestätigung, Versicherungsbestätigungsnummer, Kfz-Versicherung, Zulassung, Ummeldung, Fahrzeugschein, Kennzeichen, Haftpflichtversicherung, gültig ab, gültig bis, Versicherungsnehmer, Fahrzeugdaten, DEKRA, TÜV, Zulassungsstelle, eVB, insurance confirmation, vehicle registration',
    'Versicherung',
    'Versicherungsbeiträge: Vorsorgeaufwendungen §10 EStG',
    0,
    1,
    1,
    'mistral_batch',
    'Häufige Verwechslung mit der Kfz-Versicherungspolice oder Beitragsrechnung: Die eVB ist *kein* dauerhafter Versicherungsnachweis, sondern nur ein temporäres Dokument für die Zulassung. Sie enthält keine Informationen zu Prämien oder Leistungen. Achte auf die typische 7-stellige eVB-Nummer und die kurze Gültigkeitsdauer (meist 4–6 Wochen). Bei älteren Dokumenten kann die eVB auch als ''Doppelkarte'' bezeichnet werden.'
)
ON CONFLICT (id) DO UPDATE SET category=EXCLUDED.category, display_name=EXCLUDED.display_name, description=EXCLUDED.description, schema=EXCLUDED.schema, field_descriptions=EXCLUDED.field_descriptions, classify_keywords=EXCLUDED.classify_keywords, typical_senders=EXCLUDED.typical_senders, steuer_relevanz=EXCLUDED.steuer_relevanz, priority=EXCLUDED.priority, enabled=EXCLUDED.enabled, version=EXCLUDED.version, source=EXCLUDED.source, notes=EXCLUDED.notes;

INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'kindergeld_notice',
    'M. Sonstiges',
    'Kindergeldbescheid',
    'Der Kindergeldbescheid ist ein amtliches Dokument der Familienkasse, das die Höhe und Dauer des Kindergeldes für berechtigte Eltern oder Erziehungsberechtigte festlegt. Er wird jährlich oder bei Änderungen der familiären Verhältnisse (z. B. Geburt, Schulabschluss) ausgestellt und enthält detaillierte Angaben zu den Kindern, den monatlichen Beträgen und dem Zahlungszeitraum. Im Gegensatz zu anderen Sozialleistungsbescheiden (z. B. Elterngeld) bezieht er sich ausschließlich auf die staatliche Förderung für Kinder nach dem Einkommensteuergesetz (EStG).',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "Kindergeldbescheid", "description": "Extraktionsschema f\u00fcr Kindergeldbescheide", "type": "object", "properties": {"aktenzeichen": {"type": "string", "description": "Aktenzeichen des Bescheids"}, "kindergeldnummer": {"type": "string", "description": "Kindergeldnummer des Berechtigten"}, "berechtigter": {"type": "object", "description": "Angaben zum Kindergeldberechtigten", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "pattern": "^[A-Z]{2}$"}}, "required": ["strasse", "plz", "ort", "land"]}}, "required": ["name", "adresse"]}, "kinder": {"type": "array", "description": "Liste der Kinder, f\u00fcr die Kindergeld bezogen wird", "items": {"type": "object", "properties": {"name": {"type": "string"}, "geburtsdatum": {"type": "string", "format": "date"}, "kindergeldnummer": {"type": "string"}, "betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}}, "required": ["name", "geburtsdatum"]}}, "betrag_pro_kind": {"type": "string", "description": "Betrag pro Kind (falls einheitlich)", "pattern": "^\\d+\\.\\d{2}$"}, "gesamtbetrag": {"type": "string", "description": "Gesamtbetrag des Kindergelds", "pattern": "^\\d+\\.\\d{2}$"}, "zahlungszeitraum": {"type": "object", "description": "Zeitraum, f\u00fcr den das Kindergeld gezahlt wird", "properties": {"von": {"type": "string", "format": "date"}, "bis": {"type": "string", "format": "date"}}, "required": ["von", "bis"]}, "rechtsmittelbelehrung": {"type": "string", "description": "Text der Rechtsmittelbelehrung"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "enum": [null]}, "steuer_kategorie": {"type": "string", "enum": [null]}, "steuerjahr": {"type": "string", "pattern": "^\\d{4}$", "enum": [null]}, "mwst_ausgewiesen": {"type": "boolean", "enum": [false]}, "mwst_betrag": {"type": "string", "enum": [null]}, "mwst_satz": {"type": "string", "enum": [null]}, "aktenzeichen": {"type": "string"}, "dokumenten_id": {"type": "string"}}, "required": ["steuerrelevant", "steuerrelevanz_hinweis", "steuer_kategorie", "steuerjahr", "mwst_ausgewiesen", "mwst_betrag", "mwst_satz", "aktenzeichen"]}, "zahlungen": {"type": "array", "description": "Einzelne Kindergeldzahlungen nach Zeitraum und Kind", "items": {"type": "object", "properties": {"kind": {"type": "string"}, "zeitraum": {"type": "string"}, "betrag_monatlich": {"type": "string"}}}}}, "required": ["aktenzeichen", "kindergeldnummer", "berechtigter", "gesamtbetrag", "zahlungszeitraum", "_meta"]}',
    '"{\"aktenzeichen\": \"Amtliches Aktenzeichen der Familienkasse, z. B. ''KG 123456789''. Wichtig f\u00fcr Nachfragen oder Widerspr\u00fcche. Format: Kombination aus Buchstaben und Ziffern, oft mit Pr\u00e4fix ''KG''.\", \"kindergeldnummer\": \"Eindeutige Nummer zur Identifikation des Kindergeldfalls, z. B. ''12345678901''. Wird f\u00fcr die Kommunikation mit der Familienkasse ben\u00f6tigt. Format: 11-stellige Ziffernfolge.\", \"berechtigter\": \"Name und Adresse der Person, die das Kindergeld erh\u00e4lt (meist ein Elternteil). Wichtig f\u00fcr die Zuordnung in der Steuererkl\u00e4rung (Anlage Kind). Format: Vorname Nachname, Stra\u00dfe, PLZ Ort.\"}"',
    'Kindergeld, Familienkasse, Kindergeldbescheid, Berechtigter, Kinderfreibetrag, Zahlungszeitraum, monatlicher Betrag, Gesamtbetrag, Aktenzeichen, Kindergeldnummer, Rechtsmittelbelehrung, §31 EStG, §62 EStG, §63 EStG, child benefit, payment period, eligible person, children, appeal instructions',
    'Familienkasse',
    '{"paragraphen": "§31 EStG (steuerliche Freistellung des Existenzminimums), §62–§78 EStG (Anspruch und Höhe des Kindergeldes)", "anlage": "Kind (für Kinderfreibetrag oder Kindergeldvergleich), Vorsorgeaufwand (indirekt über §10 EStG bei Schulgeld)", "absetzbare_beträge": "Kindergeld selbst ist steuerfrei, aber relevant für den Vergleich mit dem Kinderfreibetrag (§31 EStG). Bei Schulgeld für Privatschulen können 30% (max. 5.000 € pro Kind/Jahr) als Sonderausgaben abgesetzt werden (§10 Abs. 1 Nr. 9 EStG).", "hinweis": "Das Finanzamt prüft automatisch, ob Kindergeld oder Kinderfreibetrag günstiger ist (Günstigerprüfung). Der Bescheid ist daher für die Steuererklärung zwingend erforderlich."}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
