INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'letter',
    'M. Sonstiges',
    'Brief',
    'Ein allgemeiner Brief ist eine schriftliche Mitteilung zwischen Privatpersonen, Unternehmen oder Behörden. Er kommt in vielfältigen Kontexten vor, z. B. als persönliche Korrespondenz, offizielle Benachrichtigung oder formelle Anfrage. Im Gegensatz zu standardisierten Dokumenten wie Rechnungen oder Verträgen ist der Inhalt frei formuliert und nicht an feste Strukturen gebunden, was die Klassifizierung erschwert.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "letter", "description": "Schema f\u00fcr die Extraktion von Briefen", "type": "object", "properties": {"absender": {"type": "object", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort"]}, "telefon": {"type": "string"}, "email": {"type": "string"}}, "required": ["name"]}, "empfaenger": {"type": "object", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort"]}}, "required": ["name"]}, "datum": {"type": "string", "format": "date"}, "betreff": {"type": "string"}, "inhalt_zusammenfassung": {"type": "string"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^[0-9]{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$", "nullable": true}, "mwst_satz": {"type": "string", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}}, "required": ["absender", "empfaenger", "datum"]}',
    '"{\"absender\": \"Name und Adresse des Absenders, typischerweise im Briefkopf oder am Ende des Dokuments. Format: Freitext, z. B. ''Max Mustermann, Musterstra\u00dfe 1, 12345 Musterstadt''. Wichtig f\u00fcr die Zuordnung des Dokuments zum richtigen Haushaltsmitglied.\", \"empfaenger\": \"Name und Adresse des Empf\u00e4ngers, meist zu Beginn des Briefes. Format: Freitext, z. B. ''Frau Anna Beispiel, Beispielweg 2, 54321 Beispielstadt''. Relevant f\u00fcr die Ablage und ggf. sp\u00e4tere Nachverfolgung.\", \"datum\": \"Datum des Briefes, oft im Format TT.MM.JJJJ oder JJJJ-MM-TT. Beispiel: ''15.03.2024''. Wichtig f\u00fcr die chronologische Sortierung und ggf. Fristen\u00fcberwachung.\", \"betreff\": \"Kurze Zusammenfassung des Briefinhalts, meist fett oder unterstrichen hervorgehoben. Beispiel: ''K\u00fcndigung des Mietvertrags''. Hilft bei der schnellen Identifikation des Themas.\", \"inhalt_zusammenfassung\": \"Kurze, manuell oder automatisch generierte Zusammenfassung des Briefinhalts in 1-2 S\u00e4tzen. Beispiel: ''Der Absender k\u00fcndigt den Mietvertrag f\u00fcr die Wohnung in der Musterstra\u00dfe zum 30.06.2024.'' Wichtig f\u00fcr die schnelle inhaltliche Einordnung ohne vollst\u00e4ndiges Lesen.\"}"',
    'Sehr geehrte, Mit freundlichen Grüßen, Betreff, Anrede, Unterschrift, Briefkopf, Datum, Absender, Empfänger, Korrespondenz, Schreiben, Nachricht, letter, correspondence, subject, sender, recipient, date, signature',
    'Diverse',
    NULL,
    0,
    1,
    1,
    'mistral_batch',
    'Häufige Verwechslungen: Briefe können leicht mit formellen Schreiben wie Mahnungen oder behördlichen Bescheiden verwechselt werden, wenn der Betreff oder Inhalt nicht eindeutig ist. Sonderfälle: Persönliche Briefe ohne formelle Struktur (z. B. handschriftliche Notizen) sind schwer automatisch zu klassifizieren. Tipp: Achte auf typische Briefmerkmale wie Anrede, Grußformel und Unterschrift, um sie von anderen Dokumenten zu unterscheiden.'
)
