INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'membership_card',
    'M. Sonstiges',
    'Mitgliedsausweis/-bestätigung',
    'Eine Mitgliedsausweis oder Mitgliedsbestätigung dient als Nachweis der Mitgliedschaft in einem Verein, Verband oder einer Organisation (z. B. ADAC, Fitnessstudio, Sportverein). Sie wird typischerweise jährlich oder bei Beitrittsbestätigung ausgestellt und enthält Angaben zur Gültigkeit, Mitgliedsnummer und Beitragshöhe. Im Gegensatz zu Rechnungen oder Beitragsbescheiden liegt der Fokus auf der Bestätigung der Mitgliedschaft, nicht auf der Zahlungsaufforderung.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "Mitgliedsausweis/-best\u00e4tigung", "type": "object", "properties": {"verein": {"type": "string", "description": "Name des Vereins"}, "mitgliedsnummer": {"type": "string", "description": "Mitgliedsnummer des Mitglieds"}, "name": {"type": "string", "description": "Name des Mitglieds"}, "gueltig_ab": {"type": "string", "format": "date", "description": "G\u00fcltigkeitsbeginn im Format YYYY-MM-DD"}, "gueltig_bis": {"type": "string", "format": "date", "description": "G\u00fcltigkeitsende im Format YYYY-MM-DD"}, "beitrag": {"type": "object", "properties": {"betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$", "description": "Beitragsbetrag mit 2 Dezimalstellen"}, "waehrung": {"type": "string", "pattern": "^[A-Z]{3}$", "description": "W\u00e4hrung nach ISO 4217"}, "intervall": {"type": "string", "enum": ["monatlich", "viertelj\u00e4hrlich", "halbj\u00e4hrlich", "j\u00e4hrlich", "einmalig"], "description": "Zahlungsintervall des Beitrags"}}, "required": ["betrag", "waehrung"]}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^\\d{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$", "nullable": true}, "mwst_satz": {"type": "string", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}}, "required": ["verein", "name"]}',
    '"{\"verein\": \"Name des Vereins oder der Organisation, die den Ausweis ausstellt. Beispiel: ''ADAC e.V.'', ''TSV M\u00fcnchen 1860''. Wichtig f\u00fcr die steuerliche Zuordnung (gemeinn\u00fctzig vs. kommerziell).\", \"mitgliedsnummer\": \"Eindeutige Identifikationsnummer des Mitglieds beim Verein. Beispiel: ''12345678''. Dient als Nachweis der Mitgliedschaft und kann f\u00fcr steuerliche Zwecke relevant sein (z. B. bei Spendenbescheinigungen).\", \"name\": \"Name des Mitglieds, auf den der Ausweis ausgestellt ist. Beispiel: ''Max Mustermann''. Wichtig f\u00fcr die pers\u00f6nliche Zuordnung in der Steuererkl\u00e4rung.\", \"gueltig_ab\": \"Datum, ab dem die Mitgliedschaft g\u00fcltig ist. Format: YYYY-MM-DD. Beispiel: ''2023-01-01''. Relevant f\u00fcr die zeitliche Zuordnung der Beitragszahlungen in der Steuererkl\u00e4rung.\", \"gueltig_bis\": \"Datum, bis zu dem die Mitgliedschaft g\u00fcltig ist. Format: YYYY-MM-DD. Beispiel: ''2023-12-31''. Wichtig f\u00fcr die Pr\u00fcfung, ob Beitr\u00e4ge im Veranlagungszeitraum angefallen sind.\"}"',
    'Mitgliedsausweis, Mitgliedskarte, Mitgliedsbestätigung, Mitgliedschaftsnachweis, Mitgliedsnummer, gültig ab, gültig bis, Beitrag, Jahresbeitrag, Verein, Club, Organisation, ADAC, Fitnessstudio, Sportverein, member card, membership confirmation, valid from, valid until, membership fee',
    'Vereine, ADAC, Fitnessstudios',
    '{"paragraphen": ["§10 Abs. 1 Nr. 4 EStG (Vereinsbeiträge als Sonderausgaben)", "§35a EStG (haushaltsnahe Dienstleistungen bei bestimmten Vereinen)"], "anlage": "V (Vorsorgeaufwand) oder N (Sonstige Aufwendungen), je nach Art des Vereins", "hinweise": "Beiträge zu gemeinnützigen Vereinen (z. B. Sport-, Kultur-, Umweltvereine) können als Sonderausgaben bis zu 1.900 € (Alleinstehende) bzw. 3.800 € (Verheiratete) abgesetzt werden. Bei Fitnessstudios oder ähnlichen kommerziellen Anbietern ist eine Absetzbarkeit nur in Ausnahmefällen (z. B. medizinische Notwendigkeit) möglich. §35a EStG greift nur bei bestimmten haushaltsnahen Dienstleistungen (z. B. Mitgliedsbeitrag für einen Haus- und Grundbesitzerverein)."}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
