INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'moving_confirmation',
    'M. Sonstiges',
    'Meldebestätigung/Ummeldung',
    'Die Meldebestätigung oder Ummeldung ist ein offizielles Dokument des Einwohnermeldeamts, das den Wohnsitzwechsel einer Person bestätigt. Es wird nach einer An- oder Ummeldung ausgestellt und dient als Nachweis für den neuen Wohnsitz, z.B. für Behörden, Arbeitgeber oder Banken. Im Gegensatz zu einem Mietvertrag oder einer Wohnungsgeberbestätigung ist es der behördliche Nachweis des tatsächlichen Umzugs und der neuen Meldeadresse.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "moving_confirmation", "description": "Schema f\u00fcr Meldebest\u00e4tigung/Ummeldung", "type": "object", "properties": {"name": {"type": "string", "description": "Vollst\u00e4ndiger Name der umgemeldeten Person"}, "alte_adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "default": "DE"}}, "required": ["strasse", "plz", "ort"]}, "neue_adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "default": "DE"}}, "required": ["strasse", "plz", "ort"]}, "umzugsdatum": {"type": "string", "format": "date", "description": "Datum des Umzugs im Format YYYY-MM-DD"}, "meldedatum": {"type": "string", "format": "date", "description": "Datum der Ummeldung im Format YYYY-MM-DD"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean", "default": false}, "steuerrelevanz_hinweis": {"type": "string", "default": null}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "default": null}, "steuerjahr": {"type": "string", "pattern": "^[0-9]{4}$", "default": null}, "mwst_ausgewiesen": {"type": "boolean", "default": false}, "mwst_betrag": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$", "default": null}, "mwst_satz": {"type": "string", "default": null}, "aktenzeichen": {"type": "string", "default": null}, "dokumenten_id": {"type": "string", "default": null}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}}, "required": ["name", "alte_adresse", "neue_adresse", "umzugsdatum", "meldedatum", "_meta"]}',
    '"{\"name\": \"Vollst\u00e4ndiger Name der umgemeldeten Person, wie im Dokument angegeben (Vor- und Nachname). Wichtig f\u00fcr die Identifikation und Zuordnung zu anderen Dokumenten (z.B. Steuererkl\u00e4rung). Beispiel: ''Max Mustermann''.\", \"alte_adresse\": \"Vollst\u00e4ndige vorherige Wohnadresse inkl. Stra\u00dfe, Hausnummer, Postleitzahl und Ort. Wichtig f\u00fcr den Nachweis des Wohnsitzwechsels und ggf. f\u00fcr die Berechnung von Umzugskosten. Beispiel: ''Musterstra\u00dfe 1, 12345 Musterstadt''.\", \"neue_adresse\": \"Vollst\u00e4ndige neue Wohnadresse inkl. Stra\u00dfe, Hausnummer, Postleitzahl und Ort. Dient als Nachweis des neuen Wohnsitzes und ist relevant f\u00fcr die Steuererkl\u00e4rung (z.B. bei doppelter Haushaltsf\u00fchrung). Beispiel: ''Neue Stra\u00dfe 2, 67890 Neustadt''.\", \"umzugsdatum\": \"Datum des tats\u00e4chlichen Umzugs (Format: YYYY-MM-DD). Wichtig f\u00fcr die zeitliche Zuordnung und ggf. f\u00fcr die Berechnung von Umzugskosten oder doppelter Haushaltsf\u00fchrung. Beispiel: ''2023-10-15''.\"}"',
    'Meldebestätigung, Ummeldung, Anmeldung, Wohnsitz, Einwohnermeldeamt, Meldebehörde, Adressänderung, Umzugsdatum, neue Adresse, alte Adresse, registration confirmation, change of address, resident registration, citizen office, moving confirmation, Wohnungswechsel, Hauptwohnsitz, Nebenwohnsitz',
    'Einwohnermeldeamt',
    '{"relevanz": "mittel", "paragraphen": "§9 EStG (Werbungskosten bei doppelter Haushaltsführung), §10 FVG (Kosten für Umzug aus beruflichen Gründen)", "anlage": "Anlage N (bei beruflich veranlasstem Umzug), Anlage Vorsorgeaufwand (bei Umzugskosten als außergewöhnliche Belastung)", "hinweise": "Umzugskosten können als Werbungskosten abgesetzt werden, wenn der Umzug beruflich veranlasst ist (z.B. Arbeitsplatzwechsel). Die Meldebestätigung dient als Nachweis für das Finanzamt. Bei privaten Umzügen können Kosten unter bestimmten Bedingungen als außergewöhnliche Belastungen (§33 EStG) geltend gemacht werden, z.B. bei Krankheit oder Behinderung."}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
ON CONFLICT (id) DO UPDATE SET category=EXCLUDED.category, display_name=EXCLUDED.display_name, description=EXCLUDED.description, schema=EXCLUDED.schema, field_descriptions=EXCLUDED.field_descriptions, classify_keywords=EXCLUDED.classify_keywords, typical_senders=EXCLUDED.typical_senders, steuer_relevanz=EXCLUDED.steuer_relevanz, priority=EXCLUDED.priority, enabled=EXCLUDED.enabled, version=EXCLUDED.version, source=EXCLUDED.source, notes=EXCLUDED.notes;

INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'newsletter',
    'M. Sonstiges',
    'Newsletter/Werbung',
    'Ein Newsletter ist eine regelmäßig versendete E-Mail oder digitale Mitteilung von Unternehmen oder Organisationen, die über Neuigkeiten, Angebote, Veranstaltungen oder allgemeine Informationen informiert. Im Gegensatz zu Rechnungen, Verträgen oder offiziellen Schreiben dient ein Newsletter primär Marketingzwecken und enthält keine rechtlich bindenden oder steuerrelevanten Inhalte. Er unterscheidet sich von persönlichen E-Mails durch standardisierte Inhalte und häufige Werbeelemente wie Rabattcodes oder Produktvorstellungen.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "Newsletter", "description": "Extraktionsschema f\u00fcr Newsletter/Werbung", "type": "object", "properties": {"absender": {"type": "string", "description": "Name oder E-Mail-Adresse des Absenders"}, "betreff": {"type": "string", "description": "Betreffzeile des Newsletters"}, "angebote": {"type": "array", "description": "Liste der enthaltenen Angebote", "items": {"type": "object", "properties": {"produktname": {"type": "string", "description": "Name des angebotenen Produkts"}, "beschreibung": {"type": "string", "description": "Beschreibung des Angebots"}, "preis": {"type": "string", "description": "Preis des Angebots (Format: ''49.99'')", "pattern": "^\\d+\\.\\d{2}$"}, "w\u00e4hrung": {"type": "string", "description": "W\u00e4hrung des Preises (ISO 4217)", "pattern": "^[A-Z]{3}$"}, "rabatt": {"type": "string", "description": "Rabattbetrag oder -prozentsatz (Format: ''10.00'' oder ''10%'')"}, "g\u00fcltig_bis": {"type": "string", "description": "G\u00fcltigkeitsdatum des Angebots (Format: ''YYYY-MM-DD'')", "format": "date"}, "link": {"type": "string", "description": "URL zum Angebot", "format": "uri"}}, "required": ["produktname"]}}, "abmelde_link": {"type": "string", "description": "URL zum Abmelden vom Newsletter", "format": "uri"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean", "description": "Gibt an, ob das Dokument steuerrelevant ist"}, "steuerrelevanz_hinweis": {"type": "string", "description": "Hinweis zur Steuerrelevanz", "nullable": true}, "steuer_kategorie": {"type": "string", "description": "Kategorie der Steuerrelevanz", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "nullable": true}, "steuerjahr": {"type": "string", "description": "Steuerjahr (Format: ''YYYY'')", "pattern": "^\\d{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean", "description": "Gibt an, ob Mehrwertsteuer ausgewiesen ist"}, "mwst_betrag": {"type": "string", "description": "Mehrwertsteuerbetrag (Format: ''49.99'')", "pattern": "^\\d+\\.\\d{2}$", "nullable": true}, "mwst_satz": {"type": "string", "description": "Mehrwertsteuersatz (Format: ''19.00'')", "pattern": "^\\d+\\.\\d{2}$", "nullable": true}, "aktenzeichen": {"type": "string", "description": "Aktenzeichen f\u00fcr das Dokument", "nullable": true}, "dokumenten_id": {"type": "string", "description": "Eindeutige ID des Dokuments", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}}, "required": ["absender", "betreff"]}',
    '"{\"absender\": \"Name oder Firma des Absenders des Newsletters, z. B. ''Amazon.de'' oder ''Zalando SE''. Wird extrahiert, um den Ursprung der Werbung zu identifizieren. Format: String, Beispiel: ''MediaMarkt Saturn''\", \"betreff\": \"Betreffzeile des Newsletters, oft mit werblichen Formulierungen oder Hinweisen auf Angebote. Format: String, Beispiel: ''Exklusiv f\u00fcr Sie: 20% Rabatt auf alle Schuhe diese Woche!''\", \"angebote[]\": \"Liste der im Newsletter beworbenen Angebote, Produkte oder Dienstleistungen. Jedes Angebot kann Felder wie Produktname, Preis, Rabatt, G\u00fcltigkeitsdatum oder Link enthalten. Format: Array von Objekten, Beispiel: [{''produkt'': ''Laufschuhe'', ''preis'': ''79,99 \u20ac'', ''rabatt'': ''20%'', ''gueltig_bis'': ''31.12.2023''}]\", \"abmelde_link\": \"URL oder Link, \u00fcber den der Empf\u00e4nger den Newsletter abbestellen kann. Wird oft mit Formulierungen wie ''Hier abmelden'' oder ''Unsubscribe'' gekennzeichnet. Format: String (URL), Beispiel: ''https://newsletter.beispiel.de/unsubscribe?email=nutzer@example.com''\"}"',
    'Newsletter, Werbung, Angebot, Rabattcode, exklusiv, Mitgliedervorteile, Neuigkeiten, Update, Produktvorstellung, Sale, Aktion, Abbestellen, Unsubscribe, Newsletter abmelden, Marketing, Promotion, Limited Offer, Jetzt kaufen, Hier anmelden, Ihre Vorteile, wöchentlich, monatlich, Infomail',
    'Unternehmen',
    NULL,
    0,
    1,
    1,
    'mistral_batch',
    'Häufige Verwechslungen: Newsletter können mit Rechnungen oder Bestellbestätigungen verwechselt werden, wenn sie ähnliche Betreffzeilen verwenden (z. B. ''Ihre Bestellung bei uns''). Typische Erkennungsmerkmale sind jedoch das Fehlen von Rechnungsnummern, Bestelldetails oder Zahlungsaufforderungen. Newsletter enthalten oft auffällige Grafiken, Call-to-Action-Buttons und wiederholte Werbeinhalte. Sonderfall: Manche Newsletter enthalten personalisierte Angebote (z. B. Geburtstagsrabatte), die jedoch keine steuerliche Relevanz haben.'
)
ON CONFLICT (id) DO UPDATE SET category=EXCLUDED.category, display_name=EXCLUDED.display_name, description=EXCLUDED.description, schema=EXCLUDED.schema, field_descriptions=EXCLUDED.field_descriptions, classify_keywords=EXCLUDED.classify_keywords, typical_senders=EXCLUDED.typical_senders, steuer_relevanz=EXCLUDED.steuer_relevanz, priority=EXCLUDED.priority, enabled=EXCLUDED.enabled, version=EXCLUDED.version, source=EXCLUDED.source, notes=EXCLUDED.notes;

INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'parental_allowance',
    'M. Sonstiges',
    'Elterngeldbescheid',
    'Der Elterngeldbescheid ist ein amtliches Dokument, das von der Elterngeldstelle ausgestellt wird und die Höhe sowie den Bezugszeitraum des Elterngeldes für ein neugeborenes Kind festlegt. Es unterscheidet sich von ähnlichen Dokumenten wie Kindergeldbescheid oder Mutterschaftsgeld durch die spezifische Berechnung des Elterngeldes (Basiselterngeld, ElterngeldPlus oder Partnerschaftsbonus) und die Angabe der Bemessungsgrundlage, die sich auf das Einkommen vor der Geburt bezieht.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "parental_allowance", "description": "Elterngeldbescheid", "type": "object", "properties": {"aktenzeichen": {"type": "string"}, "antragsteller": {"type": "object", "properties": {"name": {"type": "string"}, "vorname": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort", "land"]}, "steuer_id": {"type": "string"}}, "required": ["name", "vorname", "adresse"]}, "kind": {"type": "object", "properties": {"name": {"type": "string"}, "vorname": {"type": "string"}}, "required": ["name", "vorname"]}, "geburtsdatum_kind": {"type": "string", "format": "date"}, "bezugszeitraum": {"type": "object", "properties": {"von": {"type": "string", "format": "date"}, "bis": {"type": "string", "format": "date"}}, "required": ["von", "bis"]}, "monatlicher_betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}, "elterngeld_art": {"type": "string", "enum": ["basis", "plus", "partnerschaftsbonus"]}, "bemessungsgrundlage": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}, "rechtsmittelbelehrung": {"type": "string"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^\\d{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$", "nullable": true}, "mwst_satz": {"type": "string", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}, "berechnungsmonate": {"type": "array", "description": "Einzelne Elterngeld-Monate mit Berechnung", "items": {"type": "object", "properties": {"monat": {"type": "string"}, "art": {"type": "string", "description": "Basiselterngeld, ElterngeldPlus, Partnerschaftsbonus"}, "betrag": {"type": "string"}}}}}, "required": ["aktenzeichen", "antragsteller", "kind", "geburtsdatum_kind", "bezugszeitraum", "monatlicher_betrag", "elterngeld_art", "_meta"]}',
    '"{\"aktenzeichen\": \"Amtliches Aktenzeichen der Elterngeldstelle, z. B. ''EG 12345/2023''. Wichtig f\u00fcr Nachfragen oder Widerspr\u00fcche.\", \"antragsteller\": \"Name und Anschrift der Person, die den Elterngeldantrag gestellt hat, z. B. ''Max Mustermann, Musterstra\u00dfe 1, 12345 Berlin''. Relevant f\u00fcr die Zuordnung in der Steuererkl\u00e4rung.\", \"kind\": \"Name des Kindes, f\u00fcr das Elterngeld bezogen wird, z. B. ''Lisa Mustermann''. Wichtig f\u00fcr die Anlage Kind in der Steuererkl\u00e4rung.\", \"geburtsdatum_kind\": \"Geburtsdatum des Kindes im Format TT.MM.JJJJ, z. B. ''15.05.2023''. Relevant f\u00fcr die zeitliche Zuordnung des Bezugszeitraums und die steuerliche Ber\u00fccksichtigung.\", \"bezugszeitraum\": \"Zeitraum, f\u00fcr den Elterngeld gezahlt wird, z. B. ''01.06.2023 - 31.05.2024''. Wichtig f\u00fcr die korrekte Angabe in der Steuererkl\u00e4rung (Progressionsvorbehalt).\", \"monatlicher_betrag\": \"H\u00f6he des monatlich ausgezahlten Elterngeldes in Euro, z. B. ''1.200,00 \u20ac''. Muss in der Steuererkl\u00e4rung als steuerfreier, aber progressionsrelevanter Betrag angegeben werden.\", \"elterngeld_art\": \"Art des Elterngeldes, z. B. ''Basiselterngeld'', ''ElterngeldPlus'' oder ''Partnerschaftsbonus''. Relevant f\u00fcr die steuerliche Einordnung und m\u00f6gliche Kombinationen mit anderen Leistungen.\", \"bemessungsgrundlage\": \"Das f\u00fcr die Berechnung des Elterngeldes zugrunde gelegte Nettoeinkommen vor der Geburt des Kindes, z. B. ''2.500,00 \u20ac''. Wichtig f\u00fcr die Berechnung des Progressionsvorbehalts in der Steuererkl\u00e4rung.\"}"',
    'Elterngeldbescheid, Elterngeldstelle, Bezugszeitraum, Basiselterngeld, ElterngeldPlus, Partnerschaftsbonus, Bemessungsgrundlage, Nettoeinkommen vor Geburt, aktenzeichen, Antragsteller, Geburtsdatum Kind, monatlicher Betrag, Rechtsmittelbelehrung, Elternzeit, parental allowance, income before birth, reference period',
    'Elterngeldstelle',
    '{"einordnung": "Elterngeld ist steuerfrei nach § 3 Nr. 67 EStG, unterliegt jedoch dem Progressionsvorbehalt (§ 32b EStG).", "anlage": "Anlage N (für Progressionsvorbehalt), ggf. Anlage Kind (für Kinderfreibetrag)", "hinweise": "Der erhaltene Betrag muss in der Steuererklärung angegeben werden, da er den Steuersatz für das übrige Einkommen beeinflusst. Die Bemessungsgrundlage ist nicht direkt absetzbar, aber relevant für die Berechnung des Progressionsvorbehalts."}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
ON CONFLICT (id) DO UPDATE SET category=EXCLUDED.category, display_name=EXCLUDED.display_name, description=EXCLUDED.description, schema=EXCLUDED.schema, field_descriptions=EXCLUDED.field_descriptions, classify_keywords=EXCLUDED.classify_keywords, typical_senders=EXCLUDED.typical_senders, steuer_relevanz=EXCLUDED.steuer_relevanz, priority=EXCLUDED.priority, enabled=EXCLUDED.enabled, version=EXCLUDED.version, source=EXCLUDED.source, notes=EXCLUDED.notes;

INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'parking_ticket',
    'M. Sonstiges',
    'Parkschein/-quittung',
    'Eine Parkschein- oder Parkquittung dokumentiert die bezahlte Parkzeit in einem Parkhaus, auf einem Parkplatz oder an einem Parkautomaten. Sie dient als Nachweis für die Entrichtung der Parkgebühr und enthält typischerweise Angaben zu Standort, Datum, Uhrzeit, Betrag und Kennzeichen. Im Gegensatz zu Strafzetteln oder Mahnungen handelt es sich um eine reguläre Zahlungsbestätigung für eine in Anspruch genommene Dienstleistung.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "Parking Ticket", "description": "Schema f\u00fcr die Extraktion von Parkscheinen und Parkquittungen", "type": "object", "properties": {"standort": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "default": "DE"}}, "required": ["strasse", "plz", "ort"]}, "datum": {"type": "string", "format": "date"}, "uhrzeit_von": {"type": "string", "pattern": "^([01]?[0-9]|2[0-3]):[0-5][0-9]$"}, "uhrzeit_bis": {"type": "string", "pattern": "^([01]?[0-9]|2[0-3]):[0-5][0-9]$"}, "betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}, "kennzeichen": {"type": "string"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean", "default": false}, "steuerrelevanz_hinweis": {"type": "string", "default": null}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "default": null}, "steuerjahr": {"type": "string", "pattern": "^\\d{4}$", "default": null}, "mwst_ausgewiesen": {"type": "boolean", "default": false}, "mwst_betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$", "default": null}, "mwst_satz": {"type": "string", "default": null}, "aktenzeichen": {"type": "string", "default": null}, "dokumenten_id": {"type": "string", "default": null}}, "required": ["steuerrelevant"]}}, "required": ["standort", "datum", "uhrzeit_von", "uhrzeit_bis", "betrag", "kennzeichen", "_meta"]}',
    '"{\"standort\": \"Der genaue Standort des Parkplatzes oder Parkhauses, z. B. ''Parkhaus Hauptbahnhof, Ebene 3''. Wichtig f\u00fcr die Zuordnung, falls mehrere Parkvorg\u00e4nge dokumentiert werden m\u00fcssen.\", \"datum\": \"Das Datum des Parkvorgangs im Format TT.MM.JJJJ oder JJJJ-MM-TT, z. B. ''15.05.2024''. Wichtig f\u00fcr die zeitliche Einordnung des Dokuments.\", \"uhrzeit_von\": \"Die Startzeit des Parkvorgangs im Format HH:MM, z. B. ''14:30''. Wichtig f\u00fcr die Berechnung der Parkdauer.\", \"uhrzeit_bis\": \"Die Endzeit des Parkvorgangs im Format HH:MM, z. B. ''16:45''. Wichtig f\u00fcr die Berechnung der Parkdauer und ggf. f\u00fcr die \u00dcberpr\u00fcfung von \u00dcberschreitungen.\", \"betrag\": \"Der gezahlte Betrag f\u00fcr den Parkvorgang, z. B. ''3,50 \u20ac'' oder ''3.50''. Wichtig f\u00fcr die Dokumentation der Ausgaben, falls diese f\u00fcr berufliche Zwecke absetzbar sind (z. B. bei Dienstreisen).\", \"kennzeichen\": \"Das Kennzeichen des geparkten Fahrzeugs, z. B. ''B-AB 1234''. Wichtig f\u00fcr die eindeutige Zuordnung des Parkvorgangs zum Fahrzeug, besonders bei mehreren Fahrzeugen im Haushalt.\"}"',
    'Parkschein, Parkquittung, Parkticket, Parkhaus, Parkplatz, Parkautomat, Parkgebühr, Parkzeit, Kennzeichen, Standort, Datum, Uhrzeit, Betrag, parking ticket, parking receipt, parking fee, license plate, location, date, time, amount',
    'Parkhausbetreiber, Automaten',
    'MwSt ausgewiesen: Vorsteuer ggf. absetzbar',
    0,
    1,
    1,
    'mistral_batch',
    'Häufige Verwechslungen können mit Strafzetteln (z. B. ''Knöllchen'') oder Mahnungen für nicht bezahlte Parkgebühren auftreten. Parkscheine sind jedoch reguläre Zahlungsbestätigungen ohne Sanktionscharakter. Bei beruflicher Nutzung (z. B. Dienstreisen) können Parkgebühren unter Umständen als Werbungskosten (§9 EStG) oder Betriebsausgaben abgesetzt werden, sofern sie nicht vom Arbeitgeber erstattet werden. In solchen Fällen sollte das Dokument zusammen mit anderen Reisekostenbelegen aufbewahrt werden.'
)
