INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'photo_id_copy',
    'M. Sonstiges',
    'Ausweiskopie',
    'Eine Kopie eines amtlichen Lichtbildausweises wie Personalausweis oder Reisepass, die häufig für Identitätsnachweise bei Behörden, Banken, Vermietern oder Dienstleistern angefordert wird. Unterscheidet sich von anderen Dokumenten durch die Kombination aus persönlichen Daten, Ausweisnummer und Gültigkeitsdatum, oft mit sichtbarem Foto und behördlichen Sicherheitsmerkmalen.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "Photo ID Copy", "description": "Schema f\u00fcr die Extraktion von Daten aus einer Ausweiskopie", "type": "object", "properties": {"name": {"type": "string", "description": "Vollst\u00e4ndiger Name der Person"}, "geburtsdatum": {"type": "string", "format": "date", "description": "Geburtsdatum im Format YYYY-MM-DD"}, "nationalitaet": {"type": "string", "description": "Nationalit\u00e4t der Person (ISO 3166-1 alpha-2)"}, "ausweisnummer": {"type": "string", "description": "Ausweisnummer"}, "gueltig_bis": {"type": "string", "format": "date", "description": "G\u00fcltigkeitsdatum des Ausweises im Format YYYY-MM-DD"}, "ausstellende_behoerde": {"type": "string", "description": "Name der ausstellenden Beh\u00f6rde"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean", "description": "Gibt an, ob das Dokument steuerrelevant ist"}, "steuerrelevanz_hinweis": {"type": "string", "description": "Hinweis zur Steuerrelevanz", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "description": "Kategorie der Steuerrelevanz", "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^[0-9]{4}$", "description": "Steuerjahr im Format YYYY", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean", "description": "Gibt an, ob Mehrwertsteuer ausgewiesen ist"}, "mwst_betrag": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$", "description": "Mehrwertsteuerbetrag als String mit zwei Dezimalstellen", "nullable": true}, "mwst_satz": {"type": "string", "description": "Mehrwertsteuersatz", "nullable": true}, "aktenzeichen": {"type": "string", "description": "Aktenzeichen", "nullable": true}, "dokumenten_id": {"type": "string", "description": "Eindeutige Dokumenten-ID", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}}, "required": ["name", "geburtsdatum", "nationalitaet", "ausweisnummer", "gueltig_bis", "_meta"]}',
    '"{\"name\": \"Vollst\u00e4ndiger Name der Person, wie im Ausweis angegeben (Vor- und Nachname). Format: Text, Beispiel: ''Max Mustermann''. Wichtig f\u00fcr Identit\u00e4tspr\u00fcfungen, aber nicht direkt steuerrelevant.\", \"geburtsdatum\": \"Geburtsdatum der Person im Format TT.MM.JJJJ. Beispiel: ''15.08.1985''. Wird f\u00fcr Altersverifikationen genutzt, aber nicht f\u00fcr die Steuererkl\u00e4rung ben\u00f6tigt.\", \"nationalitaet\": \"Staatsangeh\u00f6rigkeit der Person, oft als L\u00e4nderk\u00fcrzel (z. B. ''DE'' f\u00fcr Deutschland) oder ausgeschrieben. Beispiel: ''Deutsch''. Relevant f\u00fcr internationale Identit\u00e4tspr\u00fcfungen, nicht steuerrelevant.\", \"ausweisnummer\": \"Eindeutige Nummer des Ausweisdokuments, oft alphanumerisch. Beispiel: ''1234567890'' oder ''T220001293''. Wird f\u00fcr beh\u00f6rdliche oder vertragliche Zwecke genutzt, nicht f\u00fcr Steuern.\", \"gueltig_bis\": \"Ablaufdatum des Ausweises im Format TT.MM.JJJJ. Beispiel: ''31.12.2030''. Wichtig f\u00fcr die Pr\u00fcfung der G\u00fcltigkeit des Dokuments, nicht steuerrelevant.\", \"ausstellende_behoerde\": \"Name der Beh\u00f6rde, die den Ausweis ausgestellt hat (z. B. ''Bundesdruckerei'', ''Stadt K\u00f6ln''). Format: Text, Beispiel: ''Landratsamt M\u00fcnchen''. Wird f\u00fcr Authentizit\u00e4tspr\u00fcfungen genutzt, nicht f\u00fcr Steuern.\"}"',
    'Personalausweis, Reisepass, Ausweiskopie, Identitätsnachweis, Lichtbildausweis, ID card copy, passport copy, Name, Geburtsdatum, Nationalität, Ausweisnummer, gültig bis, ausstellende Behörde, Passbild, MRZ, Machine Readable Zone, Dokumentennummer, Ablaufdatum, identity verification',
    'Personalausweis, Reisepass',
    NULL,
    0,
    1,
    1,
    'mistral_batch',
    'Häufige Verwechslungen: Wird oft mit Führerscheinkopien oder Aufenthaltstiteln verwechselt, die jedoch andere Felder (z. B. Führerscheinklassen oder Aufenthaltstitel-Nummer) enthalten. Ausweiskopien enthalten typischerweise eine MRZ (Machine Readable Zone) und behördliche Sicherheitsmerkmale wie Hologramme. Tipp: Achte auf das Vorhandensein eines Fotos und der typischen Felder wie Ausweisnummer und Gültigkeitsdatum. Bei digitalen Kopien (z. B. Scans) können Wasserzeichen oder Stempel der anfordernden Stelle (z. B. Bank) vorhanden sein.'
)
