INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'school_report',
    'M. Sonstiges',
    'Schulzeugnis',
    'Ein Schulzeugnis ist ein offizielles Dokument einer Bildungseinrichtung, das die schulischen Leistungen eines Schülers in einem bestimmten Schuljahr oder Halbjahr zusammenfasst. Es enthält Noten für einzelne Fächer sowie einen Versetzungsvermerk und wird typischerweise am Ende eines Schuljahres oder Halbjahres ausgestellt. Im Gegensatz zu reinen Leistungsübersichten (z. B. Zwischenberichte) ist es ein rechtsverbindliches Dokument mit Unterschrift und Stempel der Schule.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "school_report", "description": "Schulzeugnis", "type": "object", "properties": {"schueler": {"type": "object", "properties": {"vorname": {"type": "string"}, "nachname": {"type": "string"}, "geburtsdatum": {"type": "string", "format": "date"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort", "land"]}}, "required": ["vorname", "nachname", "geburtsdatum"]}, "schule": {"type": "object", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort", "land"]}}, "required": ["name"]}, "klasse": {"type": "string"}, "schuljahr": {"type": "string"}, "faecher_noten": {"type": "array", "items": {"type": "object", "properties": {"fach": {"type": "string"}, "note": {"type": "string"}, "bemerkung": {"type": "string"}}, "required": ["fach", "note"]}}, "versetzungsvermerk": {"type": "string"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^[0-9]{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "pattern": "^[0-9]+\\.[0-9]{2}$", "nullable": true}, "mwst_satz": {"type": "string", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"], "additionalProperties": false}}, "required": ["schueler", "schule", "klasse", "schuljahr", "faecher_noten", "_meta"]}',
    '"{\"schueler\": \"Vollst\u00e4ndiger Name des Sch\u00fclers/der Sch\u00fclerin, wie im Dokument angegeben. Format: Vorname Nachname. Beispiel: ''Max Mustermann''. Wichtig f\u00fcr die eindeutige Zuordnung des Zeugnisses zu einer Person, insbesondere bei mehreren Kindern im Haushalt.\", \"schule\": \"Name und ggf. Adresse der ausstellenden Schule. Format: Schulname, [Stra\u00dfe, PLZ Ort]. Beispiel: ''Goethe-Gymnasium, Musterstra\u00dfe 1, 12345 Berlin''. Wichtig zur Identifikation der Bildungseinrichtung, z. B. f\u00fcr Schulwechsel oder Nachweise.\", \"klasse\": \"Klassenstufe und ggf. Klassenbezeichnung des Sch\u00fclers. Format: Jahrgangsstufe + Klassenbuchstabe (z. B. ''5a'', ''10c''). Beispiel: ''7b''. Relevant f\u00fcr die Einordnung des schulischen Fortschritts.\", \"schuljahr\": \"Zeitraum des Schuljahres, auf das sich das Zeugnis bezieht. Format: ''YYYY/YYYY'' oder ''1. Halbjahr YYYY/YYYY'' bzw. ''2. Halbjahr YYYY/YYYY''. Beispiel: ''2022/2023'' oder ''1. Halbjahr 2023/2024''. Wichtig f\u00fcr die chronologische Einordnung der schulischen Leistungen.\", \"faecher_noten\": \"Liste der unterrichteten F\u00e4cher mit den jeweiligen Noten oder Bewertungen. Format: Array von Objekten mit den Keys ''fach'' (String) und ''note'' (String oder Number). Beispiel: [{''fach'': ''Mathematik'', ''note'': ''2''}, {''fach'': ''Deutsch'', ''note'': ''1-2''}]. Enth\u00e4lt ggf. auch Kopfnoten (z. B. ''Soziales Verhalten''). Wichtig f\u00fcr die Dokumentation der schulischen Entwicklung.\", \"versetzungsvermerk\": \"Aussage zur Versetzung in die n\u00e4chste Klassenstufe. Format: String mit Werten wie ''versetzt'', ''nicht versetzt'', ''mit Auflage versetzt'' oder ''Wechsel in die Qualifikationsphase''. Beispiel: ''versetzt''. Entscheidend f\u00fcr den weiteren schulischen Werdegang des Sch\u00fclers.\"}"',
    'Zeugnis, Schulzeugnis, Halbjahreszeugnis, Jahreszeugnis, Versetzung, versetzt, nicht versetzt, Fach, Note, Noten, schulische Leistungen, Schuljahr, Klasse, Schüler, Schule, Durchschnittsnote, Kopfnote, Bemerkungen, Unterschrift, Stempel, Leistungsbewertung, Grundschule, weiterführende Schule, Gymnasium, Realschule, Gesamtschule, report card, grades, promotion, school year',
    'Schulen',
    NULL,
    0,
    1,
    1,
    'mistral_batch',
    'Häufige Verwechslungen: Schulzeugnisse werden oft mit Zwischenberichten oder reinen Notenübersichten verwechselt, die jedoch keine rechtsverbindliche Versetzungsentscheidung enthalten. Sonderfälle: Zeugnisse von Grundschulen enthalten oft verbale Bewertungen statt Noten; internationale Schulen verwenden ggf. andere Notenskalen (z. B. A-F). Bei Zeugnissen mit ''nicht versetzt'' oder ''Wiederholung der Klasse'' sollte das Folgezeugnis besonders beachtet werden. Tipp: Achte auf Unterschrift und Stempel der Schule – diese sind für die Gültigkeit essenziell.'
)
ON CONFLICT (id) DO UPDATE SET category=EXCLUDED.category, display_name=EXCLUDED.display_name, description=EXCLUDED.description, schema=EXCLUDED.schema, field_descriptions=EXCLUDED.field_descriptions, classify_keywords=EXCLUDED.classify_keywords, typical_senders=EXCLUDED.typical_senders, steuer_relevanz=EXCLUDED.steuer_relevanz, priority=EXCLUDED.priority, enabled=EXCLUDED.enabled, version=EXCLUDED.version, source=EXCLUDED.source, notes=EXCLUDED.notes;

INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'social_security_notice',
    'M. Sonstiges',
    'Sozialversicherungsnachweis',
    'Der Sozialversicherungsnachweis ist ein Dokument der Deutschen Rentenversicherung (DRV) oder einer Krankenkasse, das die erfassten Versicherungs- und Beitragszeiten eines Versicherten auflistet. Es wird jährlich oder auf Anfrage verschickt und dient als Nachweis für die Rentenberechnung oder bei Anträgen auf Leistungen. Im Gegensatz zu Rentenbescheiden oder Beitragsnachweisen enthält es keine finanziellen Bewertungen, sondern lediglich zeitliche Daten.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "Social Security Notice", "description": "Schema for extracting data from social security notices", "type": "object", "properties": {"versicherungsnummer": {"type": "string", "description": "Social security number of the insured person"}, "versicherter": {"type": "object", "properties": {"name": {"type": "string", "description": "Full name of the insured person"}, "geburtsdatum": {"type": "string", "format": "date", "description": "Date of birth in YYYY-MM-DD format"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "pattern": "^[A-Z]{2}$"}}, "required": ["strasse", "plz", "ort", "land"]}}, "required": ["name", "geburtsdatum", "adresse"]}, "versicherungszeiten": {"type": "array", "items": {"type": "object", "properties": {"von": {"type": "string", "format": "date", "description": "Start date in YYYY-MM-DD format"}, "bis": {"type": "string", "format": "date", "description": "End date in YYYY-MM-DD format"}, "art": {"type": "string", "description": "Type of insurance period (e.g., Beitragszeit, Anrechnungszeit)"}, "beitragsgrundlage": {"type": "string", "description": "Contribution basis amount (e.g., 3000.00)"}, "beitragssatz": {"type": "string", "description": "Contribution rate (e.g., 18.6%)"}}, "required": ["von", "bis", "art"]}}, "beitragszeiten": {"type": "object", "properties": {"gesamt": {"type": "integer", "description": "Total number of contribution months"}, "detailliert": {"type": "array", "items": {"type": "object", "properties": {"jahr": {"type": "string", "description": "Year (YYYY)"}, "monate": {"type": "integer", "description": "Number of contribution months in the year"}, "beitrag": {"type": "string", "description": "Total contribution amount for the year (e.g., 5400.00)"}}, "required": ["jahr", "monate", "beitrag"]}}}, "required": ["gesamt"]}, "anrechnungszeiten": {"type": "object", "properties": {"gesamt": {"type": "integer", "description": "Total number of creditable months"}, "detailliert": {"type": "array", "items": {"type": "object", "properties": {"art": {"type": "string", "description": "Type of creditable period (e.g., Schulzeit, Krankheit)"}, "von": {"type": "string", "format": "date", "description": "Start date in YYYY-MM-DD format"}, "bis": {"type": "string", "format": "date", "description": "End date in YYYY-MM-DD format"}, "monate": {"type": "integer", "description": "Number of months credited"}}, "required": ["art", "von", "bis", "monate"]}}}, "required": ["gesamt"]}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^[0-9]{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "nullable": true}, "mwst_satz": {"type": "string", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}, "beitraege": {"type": "array", "description": "Einzelne Sozialversicherungsbeitr\u00e4ge nach Art", "items": {"type": "object", "properties": {"bezeichnung": {"type": "string"}, "betrag_monatlich": {"type": "string"}, "betrag_jaehrlich": {"type": "string"}}}}}, "required": ["versicherungsnummer", "versicherter", "_meta"]}',
    '"{\"versicherungsnummer\": \"Eindeutige Identifikationsnummer des Versicherten im deutschen Sozialversicherungssystem, bestehend aus 12 Ziffern (Format: XX XXXXX XXXXX). Wichtig f\u00fcr die Zuordnung zu Rentenanspr\u00fcchen, aber nicht direkt steuerrelevant.\", \"versicherter\": \"Name und ggf. Geburtsdatum der versicherten Person. Wird zur Identifikation ben\u00f6tigt, z. B. bei Namens\u00e4nderungen oder zur Pr\u00fcfung der Richtigkeit der Daten.\", \"versicherungszeiten\": \"Array von Zeitr\u00e4umen (Start- und Enddatum), in denen der Versicherte sozialversicherungspflichtig besch\u00e4ftigt war oder gleichgestellte Zeiten (z. B. Kindererziehung) vorlagen. Format: ISO-8601 (YYYY-MM-DD). Relevant f\u00fcr die Rentenberechnung, aber nicht direkt f\u00fcr die Steuererkl\u00e4rung.\", \"beitragszeiten\": \"Spezifische Zeitr\u00e4ume, in denen Beitr\u00e4ge zur Rentenversicherung gezahlt wurden (z. B. durch Besch\u00e4ftigung oder freiwillige Zahlungen). Format: ISO-8601 (YYYY-MM-DD). Wichtig f\u00fcr die sp\u00e4tere Rentenh\u00f6he, aber nicht steuerrelevant.\", \"anrechnungszeiten\": \"Zeiten, die f\u00fcr die Rente angerechnet werden, aber keine Beitragszahlungen erfordern (z. B. Schulausbildung, Arbeitslosigkeit, Krankheit). Format: ISO-8601 (YYYY-MM-DD). Dienen der Vervollst\u00e4ndigung des Versicherungsverlaufs, aber ohne direkte Steuerwirkung.\"}"',
    'Sozialversicherungsnachweis, Versicherungsverlauf, Rentenkonto, Beitragszeiten, Anrechnungszeiten, rentenrechtliche Zeiten, Deutsche Rentenversicherung, DRV, Krankenkasse, Versicherungsnummer, Versicherter, rentenversicherungspflichtige Beschäftigung, rentenrechtliche Bewertung, Sozialversicherungsdaten, insurance record, contribution periods, credited periods, pension insurance',
    'DRV, Krankenkasse',
    'Versicherungsbeiträge: Vorsorgeaufwendungen §10 EStG',
    0,
    1,
    1,
    'mistral_batch',
    'Häufig wird der Sozialversicherungsnachweis mit dem Rentenbescheid verwechselt, der jedoch konkrete Rentenansprüche und -höhen ausweist. Der Nachweis enthält keine finanziellen Bewertungen, sondern nur zeitliche Daten. Bei Unstimmigkeiten (z. B. fehlende Zeiten) sollte umgehend die DRV kontaktiert werden, da dies später die Rentenhöhe beeinflussen kann. Für die Steuererklärung ist das Dokument in der Regel nicht relevant, kann aber bei Nachfragen des Finanzamts zu Versicherungszeiten als Nachweis dienen.'
)
ON CONFLICT (id) DO UPDATE SET category=EXCLUDED.category, display_name=EXCLUDED.display_name, description=EXCLUDED.description, schema=EXCLUDED.schema, field_descriptions=EXCLUDED.field_descriptions, classify_keywords=EXCLUDED.classify_keywords, typical_senders=EXCLUDED.typical_senders, steuer_relevanz=EXCLUDED.steuer_relevanz, priority=EXCLUDED.priority, enabled=EXCLUDED.enabled, version=EXCLUDED.version, source=EXCLUDED.source, notes=EXCLUDED.notes;

INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'trade_registration',
    'M. Sonstiges',
    'Gewerbeanmeldung/-abmeldung',
    'Die Gewerbeanmeldung oder -abmeldung ist ein behördliches Dokument, das die Aufnahme oder Beendigung einer selbstständigen gewerblichen Tätigkeit in Deutschland bestätigt. Es wird vom Gewerbeamt ausgestellt und ist Voraussetzung für die legale Ausübung eines Gewerbes. Im Gegensatz zur Handelsregistereintragung (für Kaufleute) oder Freiberufler-Bescheinigung (für freie Berufe) betrifft es klassische Gewerbetreibende wie Handwerker, Händler oder Gastwirte.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "trade_registration", "description": "Gewerbeanmeldung/-abmeldung", "type": "object", "properties": {"anmelder": {"type": "object", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort", "land"]}, "telefon": {"type": "string"}, "email": {"type": "string", "format": "email"}}, "required": ["name", "adresse"]}, "gewerbe": {"type": "object", "properties": {"bezeichnung": {"type": "string"}, "branche": {"type": "string"}}, "required": ["bezeichnung"]}, "rechtsform": {"type": "string"}, "betriebsstaette": {"type": "object", "properties": {"adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort", "land"]}, "zusaetzliche_standorte": {"type": "array", "items": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string"}}, "required": ["strasse", "plz", "ort", "land"]}}}, "required": ["adresse"]}, "taetigkeitsbeschreibung": {"type": "string"}, "anmeldedatum": {"type": "string", "format": "date"}, "abmeldedatum": {"type": "string", "format": "date", "nullable": true}, "_meta": {"type": "object", "description": "Globale Meta-Felder: Steuerrelevanz, MwSt, Aktenzeichen", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string"}, "steuer_kategorie": {"type": "string"}, "steuerjahr": {"type": "string"}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string"}, "mwst_satz": {"type": "string"}, "aktenzeichen": {"type": "string"}, "dokumenten_id": {"type": "string"}}}}, "required": ["anmelder", "gewerbe", "rechtsform", "betriebsstaette", "taetigkeitsbeschreibung", "anmeldedatum"], "_meta": {"steuerrelevant": true, "steuerrelevanz_hinweis": "Gewerbeanmeldungen können steuerrelevante Auswirkungen auf Betriebsausgaben und Vorsteuerabzug haben.", "steuer_kategorie": null, "steuerjahr": null, "mwst_ausgewiesen": false, "mwst_betrag": null, "mwst_satz": null, "aktenzeichen": null, "dokumenten_id": null}}',
    '"anmelder, gewerbe, rechtsform, betriebsstaette, taetigkeitsbeschreibung, anmeldedatum, abmeldedatum"',
    'Gewerbeanmeldung, Gewerbeabmeldung, Gewerbeschein, Gewerbeamt, selbstständige Tätigkeit, gewerbliche Tätigkeit, Anmeldung eines Gewerbes, Abmeldung eines Gewerbes, Betriebsstätte, Rechtsform, Einzelunternehmen, GbR, GmbH, UG, Handelsgewerbe, trade registration, business registration, deregistration, activity description, Anmeldebestätigung',
    'Gewerbeamt',
    '{"einkommensteuer": {"paragraph": "§15 EStG (Einkünfte aus Gewerbebetrieb)", "anlage": "S (Einkünfte aus selbstständiger Arbeit) oder G (Einkünfte aus Gewerbebetrieb), je nach Tätigkeit", "hinweis": "Das Anmeldedatum ist relevant für den Beginn der steuerlichen Erfassung. Gewerbliche Einkünfte müssen in der Steuererklärung angegeben werden. Bei Abmeldung: Ende der gewerblichen Tätigkeit für die Steuererklärung."}, "umsatzsteuer": {"paragraph": "§2 UStG (Unternehmer), §19 UStG (Kleinunternehmerregelung)", "anlage": "USt-Erklärung (Anlage UR)", "hinweis": "Abmeldedatum relevant für Ende der Umsatzsteuerpflicht. Bei Anmeldung: Prüfung der Kleinunternehmerregelung (§19 UStG) möglich."}, "gewerbesteuer": {"paragraph": "§2 GewStG (Steuergegenstand), §11 GewStG (Freibetrag)", "anlage": "Gewerbesteuererklärung (Anlage G)"}}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
ON CONFLICT (id) DO UPDATE SET category=EXCLUDED.category, display_name=EXCLUDED.display_name, description=EXCLUDED.description, schema=EXCLUDED.schema, field_descriptions=EXCLUDED.field_descriptions, classify_keywords=EXCLUDED.classify_keywords, typical_senders=EXCLUDED.typical_senders, steuer_relevanz=EXCLUDED.steuer_relevanz, priority=EXCLUDED.priority, enabled=EXCLUDED.enabled, version=EXCLUDED.version, source=EXCLUDED.source, notes=EXCLUDED.notes;

INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'travel_booking',
    'M. Sonstiges',
    'Reisebuchung/-bestätigung',
    'Eine Reisebuchung oder -bestätigung dokumentiert die Reservierung von Flügen, Hotels, Bahnfahrten oder Pauschalreisen. Sie wird nach der Buchung vom Anbieter (z. B. Airline, Hotelportal, Bahn) per E-Mail oder Post versendet und enthält alle relevanten Buchungsdetails. Im Gegensatz zu Rechnungen oder Tickets liegt der Fokus hier auf der Bestätigung der Buchung, nicht auf der Zahlungsaufforderung oder dem Check-in-Prozess.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "travel_booking", "description": "Reisebuchung/-best\u00e4tigung", "type": "object", "properties": {"anbieter": {"type": "string", "description": "Name des Reiseanbieters"}, "buchungsnummer": {"type": "string", "description": "Eindeutige Buchungsnummer"}, "reisende": {"type": "array", "description": "Liste der Reisenden", "items": {"type": "object", "properties": {"name": {"type": "string", "description": "Vollst\u00e4ndiger Name des Reisenden"}, "geburtsdatum": {"type": "string", "format": "date", "description": "Geburtsdatum des Reisenden (YYYY-MM-DD)"}, "reisepassnummer": {"type": "string", "description": "Reisepassnummer des Reisenden"}, "nationalitaet": {"type": "string", "description": "Nationalit\u00e4t des Reisenden (ISO 3166-1 alpha-2)"}}, "required": ["name"]}}, "reisezeitraum": {"type": "object", "description": "Zeitraum der Reise", "properties": {"start": {"type": "string", "format": "date", "description": "Startdatum der Reise (YYYY-MM-DD)"}, "ende": {"type": "string", "format": "date", "description": "Enddatum der Reise (YYYY-MM-DD)"}}, "required": ["start", "ende"]}, "strecke_hotel": {"type": "object", "description": "Informationen zur Reise und Unterkunft", "properties": {"strecke": {"type": "array", "description": "Liste der Reisestrecken", "items": {"type": "object", "properties": {"startort": {"type": "string", "description": "Startort der Strecke"}, "zielort": {"type": "string", "description": "Zielort der Strecke"}, "verkehrsmittel": {"type": "string", "description": "Verkehrsmittel (z.B. Flug, Zug, Bus)"}, "hinfahrt": {"type": "string", "format": "date-time", "description": "Datum und Uhrzeit der Hinfahrt (YYYY-MM-DDTHH:MM:SS)"}, "rueckfahrt": {"type": "string", "format": "date-time", "description": "Datum und Uhrzeit der R\u00fcckfahrt (YYYY-MM-DDTHH:MM:SS)"}}, "required": ["zielort"]}}, "hotel": {"type": "object", "description": "Informationen zur Unterkunft", "properties": {"name": {"type": "string", "description": "Name des Hotels"}, "adresse": {"type": "object", "description": "Adresse des Hotels", "properties": {"strasse": {"type": "string", "description": "Stra\u00dfe und Hausnummer"}, "plz": {"type": "string", "description": "Postleitzahl"}, "ort": {"type": "string", "description": "Ort"}, "land": {"type": "string", "description": "Land (ISO 3166-1 alpha-2)"}}, "required": ["strasse", "plz", "ort", "land"]}, "zimmer": {"type": "string", "description": "Zimmertyp"}}, "required": ["name"]}}}, "preis": {"type": "object", "description": "Preisinformationen", "properties": {"gesamtpreis": {"type": "string", "description": "Gesamtpreis der Buchung (z.B. 499.99)"}, "waehrung": {"type": "string", "description": "W\u00e4hrung des Preises (ISO 4217)"}, "zahlungsbedingungen": {"type": "string", "description": "Zahlungsbedingungen"}}, "required": ["gesamtpreis", "waehrung"]}, "stornobedingungen": {"type": "string", "description": "Bedingungen f\u00fcr eine Stornierung"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean"}, "steuerrelevanz_hinweis": {"type": "string", "nullable": true}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "nullable": true}, "steuerjahr": {"type": "string", "pattern": "^[0-9]{4}$", "nullable": true}, "mwst_ausgewiesen": {"type": "boolean"}, "mwst_betrag": {"type": "string", "nullable": true}, "mwst_satz": {"type": "string", "nullable": true}, "aktenzeichen": {"type": "string", "nullable": true}, "dokumenten_id": {"type": "string", "nullable": true}}, "required": ["steuerrelevant", "mwst_ausgewiesen"]}, "positionen": {"type": "array", "description": "Einzelpositionen der Reisebuchung (Fl\u00fcge, Hotels, Mietwagen, Versicherung, etc.)", "items": {"type": "object", "properties": {"beschreibung": {"type": "string"}, "datum": {"type": "string"}, "betrag": {"type": "string"}}}}}, "required": ["anbieter", "buchungsnummer", "preis"]}',
    '"anbieter, buchungsnummer, reisende[], reisezeitraum, strecke_hotel, preis, stornobedingungen"',
    'Buchungsbestätigung, Reisebestätigung, booking confirmation, Flugreservierung, Hotelreservierung, Bahnbuchung, Buchungsnummer, Reisezeitraum, Reisende, Strecke, Preis, Stornobedingungen, Anbieter, e-ticket, Reservierungsdetails, Confirmation, Check-in, Reiseunterlagen, Reiseplan, Reisebuchung, Reisekosten',
    'Airlines, Hotels, Booking, DB',
    '{"privat": {"beschreibung": "Reisekosten können unter bestimmten Bedingungen als außergewöhnliche Belastungen (§33 EStG) oder Werbungskosten (§9 EStG) geltend gemacht werden, wenn sie beruflich veranlasst sind. Für Privatreisen ist keine steuerliche Absetzbarkeit gegeben.", "anlage": null, "hinweise": "Nur relevant, wenn die Reise beruflich veranlasst ist (z. B. Dienstreise). Dann können Kosten für Transport, Unterkunft und Verpflegung abgesetzt werden. Belege müssen als Nachweis aufbewahrt werden. Bei gemischten Reisen (privat/beruflich) ist eine Aufteilung erforderlich."}, "beruflich": {"beschreibung": "Beruflich veranlasste Reisekosten können als Werbungskosten (§9 EStG) in der Anlage N oder als Betriebsausgaben in der Einnahmen-Überschuss-Rechnung (Anlage EÜR) geltend gemacht werden. Dazu zählen Fahrtkosten, Übernachtungskosten und Verpflegungsmehraufwand.", "anlage": "N, EÜR", "absetzbare_beträge": {"fahrtkosten": "Tatsächliche Kosten oder Kilometerpauschale (0,30 €/km für PKW, §9 Abs. 1 Satz 3 Nr. 4a EStG)", "übernachtungskosten": "Tatsächliche Kosten (ohne Frühstück, §9 Abs. 1 Satz 3 Nr. 5a EStG)"}}}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
ON CONFLICT (id) DO UPDATE SET category=EXCLUDED.category, display_name=EXCLUDED.display_name, description=EXCLUDED.description, schema=EXCLUDED.schema, field_descriptions=EXCLUDED.field_descriptions, classify_keywords=EXCLUDED.classify_keywords, typical_senders=EXCLUDED.typical_senders, steuer_relevanz=EXCLUDED.steuer_relevanz, priority=EXCLUDED.priority, enabled=EXCLUDED.enabled, version=EXCLUDED.version, source=EXCLUDED.source, notes=EXCLUDED.notes;

INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'unemployment_notice',
    'M. Sonstiges',
    'Arbeitslosengeldbescheid',
    'Der Arbeitslosengeldbescheid ist ein amtliches Dokument der Agentur für Arbeit oder des Jobcenters, das die Bewilligung, Höhe und Dauer von Arbeitslosengeld I (ALG I), Arbeitslosengeld II (ALG II) oder Bürgergeld bestätigt. Es wird nach Antragstellung und Prüfung der Anspruchsvoraussetzungen ausgestellt und dient als Nachweis für den Leistungsbezug, z. B. für Behörden, Vermieter oder die Steuererklärung. Im Gegensatz zu ähnlichen Dokumenten wie dem Bewilligungsbescheid für Wohngeld oder Kindergeld enthält es spezifische Angaben zur Arbeitslosigkeit und den daraus resultierenden finanziellen Leistungen.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "unemployment_notice", "description": "Arbeitslosengeldbescheid", "type": "object", "properties": {"aktenzeichen": {"type": "string"}, "kundennummer": {"type": "string"}, "leistungsempfaenger": {"type": "object", "properties": {"name": {"type": "string"}, "adresse": {"type": "object", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "default": "DE"}}, "required": ["strasse", "plz", "ort"]}}, "required": ["name", "adresse"]}, "leistungsart": {"type": "string", "enum": ["ALG_I", "ALG_II", "Buergergeld"]}, "bewilligungszeitraum": {"type": "object", "properties": {"von": {"type": "string", "format": "date"}, "bis": {"type": "string", "format": "date"}}, "required": ["von", "bis"]}, "monatlicher_betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}, "bemessungsgrundlage": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}, "leistungssatz_prozent": {"type": "string", "pattern": "^\\d+(\\.\\d{1,2})?$"}, "anrechnungen": {"type": "array", "items": {"type": "object", "properties": {"art": {"type": "string"}, "betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$"}, "begruendung": {"type": "string"}}, "required": ["art", "betrag"]}}, "rechtsmittelbelehrung": {"type": "string"}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean", "default": true}, "steuerrelevanz_hinweis": {"type": "string", "default": "Arbeitslosengeld I ist steuerfrei, unterliegt aber dem Progressionsvorbehalt. Arbeitslosengeld II/B\u00fcrgergeld ist steuerfrei."}, "steuer_kategorie": {"type": "string", "enum": [null, "sonderausgaben"], "default": null}, "steuerjahr": {"type": "string", "pattern": "^\\d{4}$"}, "mwst_ausgewiesen": {"type": "boolean", "default": false}, "mwst_betrag": {"type": "string", "default": null}, "mwst_satz": {"type": "string", "default": null}, "aktenzeichen": {"type": "string"}, "dokumenten_id": {"type": "string"}}, "required": ["steuerrelevant", "steuerrelevanz_hinweis", "mwst_ausgewiesen"]}}, "required": ["aktenzeichen", "leistungsempfaenger", "leistungsart", "bewilligungszeitraum", "monatlicher_betrag", "_meta"]}',
    '"aktenzeichen, kundennummer, leistungsempfaenger, leistungsart (ALG_I/ALG_II/Buergergeld), bewilligungszeitraum, monatlicher_betrag, bemessungsgrundlage, leistungssatz_prozent, anrechnungen[], rechtsmittelbelehrung"',
    'Arbeitslosengeldbescheid, ALG I, ALG II, Bürgergeld, Agentur für Arbeit, Jobcenter, Leistungsbescheid, Bewilligungszeitraum, monatlicher Betrag, Bemessungsgrundlage, Leistungssatz, Anrechnungen, Rechtsmittelbelehrung, Kundennummer, Aktenzeichen, Leistungsempfänger, Arbeitslosengeld, unemployment benefit, notice of decision, benefit period, monthly amount, assessment basis, deductions',
    'Agentur für Arbeit, Jobcenter',
    '{"einkommensteuer": {"paragraphen": "§ 32b EStG (Progressionsvorbehalt für ALG I), § 22 Nr. 1 EStG (sonstige Einkünfte für ALG II/Bürgergeld, sofern steuerpflichtig)", "anlage": "Anlage N (für ALG I unter Progressionsvorbehalt), ggf. Anlage SO (für ALG II/Bürgergeld als sonstige Einkünfte)"}}',
    0,
    1,
    1,
    'mistral_batch',
    NULL
)
ON CONFLICT (id) DO UPDATE SET category=EXCLUDED.category, display_name=EXCLUDED.display_name, description=EXCLUDED.description, schema=EXCLUDED.schema, field_descriptions=EXCLUDED.field_descriptions, classify_keywords=EXCLUDED.classify_keywords, typical_senders=EXCLUDED.typical_senders, steuer_relevanz=EXCLUDED.steuer_relevanz, priority=EXCLUDED.priority, enabled=EXCLUDED.enabled, version=EXCLUDED.version, source=EXCLUDED.source, notes=EXCLUDED.notes;

INSERT INTO template (id, category, display_name, description, schema, field_descriptions, classify_keywords, typical_senders, steuer_relevanz, priority, enabled, version, source, notes) VALUES (
    'wohngeld_notice',
    'M. Sonstiges',
    'Wohngeldbescheid',
    'Ein Wohngeldbescheid ist ein amtliches Dokument, das die Bewilligung oder Ablehnung von Wohngeld für einkommensschwache Haushalte bestätigt. Es wird von der zuständigen Wohngeldstelle ausgestellt und enthält Details zum bewilligten Zuschuss, dem Bewilligungszeitraum sowie den Haushaltsmitgliedern. Im Gegensatz zu Mietverträgen oder Nebenkostenabrechnungen regelt es staatliche Leistungen zur Wohnkostenentlastung und ist an spezifische Einkommensgrenzen gebunden.',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "Wohngeldbescheid", "description": "Schema f\u00fcr die Extraktion von Daten aus einem Wohngeldbescheid", "type": "object", "properties": {"aktenzeichen": {"type": "string", "description": "Aktenzeichen des Wohngeldbescheids"}, "antragsteller": {"type": "object", "description": "Angaben zum Antragsteller", "properties": {"name": {"type": "string", "description": "Vollst\u00e4ndiger Name des Antragstellers"}, "adresse": {"type": "object", "description": "Adresse des Antragstellers", "properties": {"strasse": {"type": "string"}, "plz": {"type": "string"}, "ort": {"type": "string"}, "land": {"type": "string", "default": "DE"}}, "required": ["strasse", "plz", "ort"]}, "geburtsdatum": {"type": "string", "format": "date", "description": "Geburtsdatum des Antragstellers (YYYY-MM-DD)"}, "steuer_id": {"type": "string", "description": "Steueridentifikationsnummer des Antragstellers"}}, "required": ["name", "adresse"]}, "bewilligungszeitraum": {"type": "object", "description": "Zeitraum, f\u00fcr den das Wohngeld bewilligt wurde", "properties": {"von": {"type": "string", "format": "date", "description": "Beginn des Bewilligungszeitraums (YYYY-MM-DD)"}, "bis": {"type": "string", "format": "date", "description": "Ende des Bewilligungszeitraums (YYYY-MM-DD)"}}, "required": ["von", "bis"]}, "monatlicher_zuschuss": {"type": "object", "description": "Monatlicher Wohngeldzuschuss", "properties": {"betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$", "description": "Betrag des monatlichen Zuschusses (z.B. 49.99)"}, "waehrung": {"type": "string", "default": "EUR", "description": "W\u00e4hrung des Zuschusses (ISO 4217)"}}, "required": ["betrag"]}, "haushaltsmitglieder": {"type": "array", "description": "Liste der Haushaltsmitglieder", "items": {"type": "object", "properties": {"name": {"type": "string", "description": "Vollst\u00e4ndiger Name des Haushaltsmitglieds"}, "geburtsdatum": {"type": "string", "format": "date", "description": "Geburtsdatum des Haushaltsmitglieds (YYYY-MM-DD)"}, "verwandtschaftsverhaeltnis": {"type": "string", "description": "Verwandtschaftsverh\u00e4ltnis zum Antragsteller (z.B. Ehepartner, Kind)"}, "einkommen": {"type": "object", "description": "Einkommen des Haushaltsmitglieds", "properties": {"betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$", "description": "J\u00e4hrliches Bruttoeinkommen (z.B. 25000.00)"}, "waehrung": {"type": "string", "default": "EUR", "description": "W\u00e4hrung des Einkommens (ISO 4217)"}}}}, "required": ["name"]}}, "rechtsmittelbelehrung": {"type": "object", "description": "Angaben zur Rechtsmittelbelehrung", "properties": {"frist": {"type": "string", "description": "Frist f\u00fcr die Einlegung eines Rechtsmittels (z.B. 1 Monat)"}, "zustaendige_behoerde": {"type": "string", "description": "Zust\u00e4ndige Beh\u00f6rde f\u00fcr Rechtsmittel"}, "hinweis": {"type": "string", "description": "Zus\u00e4tzliche Hinweise zur Rechtsmittelbelehrung"}}}, "_meta": {"type": "object", "properties": {"steuerrelevant": {"type": "boolean", "default": false}, "steuerrelevanz_hinweis": {"type": "string", "default": null}, "steuer_kategorie": {"type": "string", "enum": ["werbungskosten", "sonderausgaben", "aussergewoehnliche_belastungen", "haushaltsnahe_dienstleistungen", "handwerkerleistungen", "vorsorgeaufwendungen", "kapitalertraege", "vermietung", "spenden", null], "default": null}, "steuerjahr": {"type": "string", "pattern": "^\\d{4}$", "default": null}, "mwst_ausgewiesen": {"type": "boolean", "default": false}, "mwst_betrag": {"type": "string", "pattern": "^\\d+\\.\\d{2}$", "default": null}, "mwst_satz": {"type": "string", "default": null}, "aktenzeichen": {"type": "string", "default": null}, "dokumenten_id": {"type": "string", "default": null}}, "required": ["steuerrelevant"]}, "berechnung": {"type": "array", "description": "Einzelne Berechnungspositionen des Wohngeldbescheids", "items": {"type": "object", "properties": {"bezeichnung": {"type": "string"}, "betrag": {"type": "string"}}}}}, "required": ["aktenzeichen", "antragsteller", "bewilligungszeitraum", "monatlicher_zuschuss"]}',
    '"{\"aktenzeichen\": \"Amtliches Aktenzeichen der Wohngeldstelle, z. B. ''WG-2023-4711''. Wichtig f\u00fcr Nachfragen oder Rechtsmittel, aber nicht direkt steuerrelevant.\", \"antragsteller\": \"Name und Adresse der Person, die den Wohngeldantrag gestellt hat. Format: ''Max Mustermann, Musterstra\u00dfe 1, 12345 Musterstadt''. Dient der Identifikation des Leistungsempf\u00e4ngers.\", \"bewilligungszeitraum\": \"Zeitraum, f\u00fcr den das Wohngeld bewilligt wird, z. B. ''01.01.2024 \u2013 31.12.2024''. Wichtig f\u00fcr die Dokumentation der Leistungsdauer, aber nicht steuerrelevant.\", \"monatlicher_zuschuss\": \"H\u00f6he des bewilligten monatlichen Wohngelds in Euro, z. B. ''250,00 \u20ac''. Wird als staatliche Transferleistung nicht versteuert, muss aber bei anderen Sozialleistungen (z. B. B\u00fcrgergeld) angegeben werden.\", \"haushaltsmitglieder\": \"Liste der im Haushalt lebenden Personen, die bei der Berechnung des Wohngelds ber\u00fccksichtigt wurden. Format: ''Max Mustermann, Erika Mustermann, Kind (geb. 2015)''. Relevant f\u00fcr die Pr\u00fcfung der Anspruchsvoraussetzungen.\", \"rechtsmittelbelehrung\": \"Hinweis zu Fristen und M\u00f6glichkeiten, gegen den Bescheid Widerspruch einzulegen, z. B. ''Innerhalb eines Monats nach Erhalt des Bescheids''. Wichtig f\u00fcr rechtliche Schritte, aber nicht steuerrelevant.\"}"',
    'Wohngeldbescheid, Wohngeldstelle, Bewilligung, Ablehnung, monatlicher Zuschuss, Bewilligungszeitraum, Haushaltsmitglieder, Rechtsbehelfsbelehrung, Wohngeldantrag, Einkommensgrenze, Mietzuschuss, Lastenzuschuss, Aktenzeichen, Antragsteller, Wohnkostenentlastung, § 27 Wohngeldgesetz, WoGG, Wohngeldnummer, Leistungsbescheid, Sozialleistung',
    'Wohngeldstelle',
    NULL,
    0,
    1,
    1,
    'mistral_batch',
    'Häufige Verwechslung mit anderen Sozialleistungsbescheiden wie Bürgergeld oder Grundsicherung. Wohngeldbescheide beziehen sich explizit auf Wohnkosten (Miete oder Lasten) und enthalten immer einen Bewilligungszeitraum sowie einen monatlichen Zuschussbetrag. Tipp: Achten auf den Absender (Wohngeldstelle) und die Nennung des Wohngeldgesetzes (WoGG). Bei Ablehnungen ist der Bescheid oft kürzer, enthält aber dieselben Felder (außer ''monatlicher_zuschuss'').'
)
